    [Fact]
    public void catalog_is_semantic_and_supported_for_flash_and_unity()
    {
        using var fixture = new SurfaceFixture();

        string[] declared_member_ids = typeof(ApplicationMemberIds)
            .GetFields(BindingFlags.Public | BindingFlags.Static)
            .Where(field => field.IsLiteral && field.FieldType == typeof(string))
            .Select(field => (string)field.GetRawConstantValue()!)
            .Order(StringComparer.Ordinal)
            .ToArray();
        Assert.Equal(
            declared_member_ids,
            fixture.Application.Members.Select(member => member.Id).ToArray());

        ApplicationExposure[] exposures =
        [
            ApplicationExposure.Ui,
            ApplicationExposure.Cli,
            ApplicationExposure.Scripting,
            ApplicationExposure.Mcp
        ];
        Assert.All(fixture.Application.Members, member =>
        {
            ApplicationExposure expected_exposure = member.Kind is ApplicationMemberKind.Event
                ? ApplicationExposure.Ui | ApplicationExposure.Cli | ApplicationExposure.Scripting
                : ApplicationExposure.All;
            Assert.Equal(expected_exposure, member.Exposure);
            Assert.All(exposures, exposure => Assert.Equal(
                expected_exposure.HasFlag(exposure),
                member.Exposure.HasFlag(exposure)));
            if (member.Messages.Count == 0)
                Assert.Equal(ApplicationMemberKind.Query, member.Kind);
            Assert.All(member.Messages, requirement =>
            {
                Assert.False(requirement.Key.IsEmpty);
                Assert.True(fixture.Messages.Registry.TryGet(
                    requirement.Key,
                    out MessageDescriptor registry_descriptor));
                Assert.True(registry_descriptor.HasExplicitKey);
                Assert.Equal(requirement.Direction, registry_descriptor.Direction);
            });

            ApplicationClientAvailability[] clients = fixture.Application
                .Describe(member.Id)
                .Availability
                .Clients
                .ToArray();
            Assert.Equal(
                [ClientType.Flash, ClientType.Unity],
                clients.Select(client => client.Client).ToArray());
            Assert.All(clients, client =>
            {
                Assert.Equal(member.Messages.Count, client.Messages.Count);
                Assert.Equal(
                    client.Messages
                        .Where(message => message.Required)
                        .All(message => message.Supported),
                    client.Supported);
            });
        });

        (string member_id, ApplicationMemberKind kind, Type? request_type, Type result_type, bool available)[]
            catalog_members =
            [
                (ApplicationMemberIds.CatalogState, ApplicationMemberKind.Query,
                    typeof(CatalogStateRequest), typeof(CatalogStateView), true),
                (ApplicationMemberIds.CatalogIndexGet, ApplicationMemberKind.Operation,
                    typeof(CatalogIndexGetRequest), typeof(CatalogIndexView), false),
                (ApplicationMemberIds.CatalogPageGet, ApplicationMemberKind.Operation,
                    typeof(CatalogPageGetRequest), typeof(CatalogPageView), false),
                (ApplicationMemberIds.CatalogPagesLoad, ApplicationMemberKind.Operation,
                    typeof(CatalogLoadRequest), typeof(CatalogLoadView), false),
                (ApplicationMemberIds.CatalogPagesList, ApplicationMemberKind.Query,
                    typeof(CatalogPagesRequest), typeof(CatalogPageListView), true),
                (ApplicationMemberIds.CatalogOffersSearch, ApplicationMemberKind.Query,
                    typeof(CatalogOfferSearchRequest), typeof(CatalogOfferSearchPage), true),
                (ApplicationMemberIds.CatalogCacheClear, ApplicationMemberKind.Operation,
                    typeof(CatalogCacheClearRequest), typeof(CatalogCacheClearView), true),
                (ApplicationMemberIds.CatalogPurchaseState, ApplicationMemberKind.Query,
                    typeof(CatalogPurchaseStateRequest), typeof(CatalogPurchaseStateView), true),
                (ApplicationMemberIds.CatalogPurchaseSend, ApplicationMemberKind.Operation,
                    typeof(CatalogPurchaseSendRequest), typeof(CatalogPurchaseDispatchReceipt), false),
                (ApplicationMemberIds.CatalogPurchaseOutcome, ApplicationMemberKind.Event,
                    null, typeof(CatalogPurchaseOutcomeEvent), false),
                (ApplicationMemberIds.CatalogPublished, ApplicationMemberKind.Event,
                    null, typeof(CatalogPublishedEvent), false)
            ];
        Assert.All(catalog_members, member =>
        {
            ApplicationDescriptor descriptor = fixture.Application.Members
                .Single(candidate => candidate.Id == member.member_id);
            Assert.Equal(member.kind, descriptor.Kind);
            Assert.Equal(member.request_type, descriptor.RequestType);
            Assert.Equal(member.result_type, descriptor.ResultType);
            Assert.Equal(member.available, fixture.Application
                .Describe(member.member_id)
                .Availability
                .Available);
        });

        string[] flash_only =
        [
            ApplicationMemberIds.MarketplaceHistoryClear,
            ApplicationMemberIds.MarketplaceHistoryClearResult,
            ApplicationMemberIds.MarketplaceOfferCancel,
            ApplicationMemberIds.MarketplaceOfferCancelResult
        ];
        foreach (string member_id in flash_only)
        {
            ApplicationClientAvailability[] clients = fixture.Application
                .Describe(member_id)
                .Availability
                .Clients
                .ToArray();
            Assert.True(Assert.Single(clients, value => value.Client is ClientType.Flash).Supported);
            Assert.False(Assert.Single(clients, value => value.Client is ClientType.Unity).Supported);
        }
    }

    [Fact]
    public async Task profile_state_is_bounded_and_offline_readable_but_refresh_is_not()
    {
        using var fixture = new SurfaceFixture();

        Assert.True(fixture.Application
            .Describe(ApplicationMemberIds.ProfileState)
            .Availability
            .Available);
        ProfileStateView state = await fixture.Application
            .InvokeAsync<ProfileStateRequest, ProfileStateView>(
                ApplicationMemberIds.ProfileState,
                new ProfileStateRequest());
        Assert.False(state.Connected);
        Assert.Null(state.Client);
        Assert.Null(state.Identity);
        Assert.False(state.BlockListLoaded);
        Assert.Equal(0, state.BlockedUserCount);
        Assert.False(state.IgnoreListLoaded);
        Assert.Equal(0, state.IgnoredUserCount);
        Assert.False(state.FigureSetsLoaded);
        Assert.Equal(0, state.FigureSetCount);
        Assert.Equal(0, state.BoundFurnitureNameCount);
        Assert.False(state.SanctionsLoaded);
        Assert.Null(state.SanctionsKind);

        ProfileIdPage blocks = await fixture.Application
            .InvokeAsync<ProfileIdPageRequest, ProfileIdPage>(
                ApplicationMemberIds.ProfileBlocksList,
                new ProfileIdPageRequest(Limit: 1));
        Assert.Empty(blocks.UserIds);
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => fixture.Application
            .InvokeAsync<ProfileIdPageRequest, ProfileIdPage>(
                ApplicationMemberIds.ProfileBlocksList,
                new ProfileIdPageRequest(Limit: 501))
            .AsTask());

        Assert.False(fixture.Application
            .Describe(ApplicationMemberIds.ProfileRefresh)
            .Availability
            .Available);
        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<ProfileRefreshRequest, ProfileStateView>(
                ApplicationMemberIds.ProfileRefresh,
                new ProfileRefreshRequest())
            .AsTask());
    }

    [Fact]
    public void unity_unignore_is_resolved_but_wire_unavailable_without_a_verified_schema()
    {
        using var fixture = new SurfaceFixture(ClientType.Unity, include_unignore: true);

        ApplicationMemberDescription description = fixture.Application.Describe(
            ApplicationMemberIds.ProfileIgnoreRemove);
        ApplicationMessageAvailability message = Assert.Single(
            description.Availability.ActiveMessages);
        Assert.True(message.Registered);
        Assert.True(message.Supported);
        Assert.True(message.Resolved);
        Assert.Equal([6], message.Headers);
        Assert.Equal("unityUnignoreSchema", message.WireCapability);
        Assert.False(message.WireAvailable);
        Assert.False(string.IsNullOrWhiteSpace(message.WireReason));
        ApplicationMessageHeaderCapability header = Assert.Single(message.HeaderCapabilities);
        Assert.Equal(6, header.Header);
        Assert.Equal("unityUnignoreSchema", header.Capability);
        Assert.False(header.Available);
        Assert.Equal(message.WireReason, header.Reason);
        Assert.False(description.Availability.Available);
    }

    [Theory]
    [InlineData(OutgoingWireType.Int64, "unityUnignoreIdSchema")]
    [InlineData(OutgoingWireType.String, "unityUnignoreNameSchema")]
    public void unity_unignore_reports_the_exact_verified_identity_schema(
        OutgoingWireType wire_type,
        string capability)
    {
        using var fixture = new SurfaceFixture(
            ClientType.Unity,
            include_unignore: true,
            unity_unignore_schema: wire_type);

        ApplicationMemberDescription description = fixture.Application.Describe(
            ApplicationMemberIds.ProfileIgnoreRemove);
        ApplicationMessageAvailability message = Assert.Single(
            description.Availability.ActiveMessages);
        Assert.True(message.Resolved);
        Assert.True(message.WireAvailable);
        Assert.Equal(capability, message.WireCapability);
        ApplicationMessageHeaderCapability header = Assert.Single(message.HeaderCapabilities);
        Assert.Equal(6, header.Header);
        Assert.Equal(capability, header.Capability);
        Assert.True(header.Available);
        Assert.Null(header.Reason);
        Assert.True(description.Availability.Available);
    }

    [Fact]
