        Assert.False(state.Connected);
        Assert.Null(state.Client);
        Assert.False(state.CreditsLoaded);
        Assert.Null(state.Credits);
        Assert.False(state.PointsLoaded);
        Assert.Equal(0, state.ActivityPoints.SnapshotRevision);
        Assert.Equal(0, state.ActivityPoints.TotalPoints);
        Assert.Empty(state.ActivityPoints.Points);

        WalletStateView complete = WalletApplicationPages.Read(fixture.Application);
        Assert.Equal(state, complete);
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => fixture.Application
            .InvokeAsync<WalletStateRequest, WalletStateView>(
                ApplicationMemberIds.WalletState,
                new WalletStateRequest(PointLimit: 501))
            .AsTask());

        Assert.False(fixture.Application
            .Describe(ApplicationMemberIds.WalletRefresh)
            .Availability
            .Available);
        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<WalletRefreshRequest, WalletStateView>(
                ApplicationMemberIds.WalletRefresh,
                new WalletRefreshRequest())
            .AsTask());
    }

    [Theory]
    [InlineData(ClientType.Flash, "00000002000000050000007B000000000000002D")]
    [InlineData(ClientType.Unity, "0002000000050000007B000000000000002D")]
    public void wallet_activity_points_keep_explicit_flash_and_unity_count_widths(
        ClientType client,
        string expected_hex)
    {
        var value = new ActivityPoints(
        [
            new ActivityPoint(WalletPointTypes.Diamonds, 123),
            new ActivityPoint(WalletPointTypes.Duckets, 45)
        ]);
        using var packet = new Packet(new Header(Direction.In, 1), client);

        packet.Writer().Compose(value);

        Assert.Equal(Convert.FromHexString(expected_hex), packet.Buffer.Span.ToArray());
        packet.Position = 0;
        ActivityPoints parsed = packet.Reader().Parse<ActivityPoints>();
        Assert.Equal(value.Points, parsed.Points);
        Assert.Equal(0, packet.Available);
    }

    [Fact]
    public async Task wallet_refresh_correlates_both_responses_across_single_flight_waiters()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);

        Task<WalletStateView> first = fixture.Application
            .InvokeAsync<WalletRefreshRequest, WalletStateView>(
                ApplicationMemberIds.WalletRefresh,
                new WalletRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();
        await fixture.WalletRequestSent.WaitAsync(test_synchronization_timeout);
        Task<WalletStateView> second = fixture.Application
            .InvokeAsync<WalletRefreshRequest, WalletStateView>(
                ApplicationMemberIds.WalletRefresh,
                new WalletRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();

        Assert.Equal(1, fixture.WalletRequestCount);
        fixture.Receive(
            MessageContracts.Wallet.CreditsBalance,
            new CreditBalance("321.0"));
        Assert.False(first.IsCompleted);
        Assert.False(second.IsCompleted);

        fixture.Receive(
            MessageContracts.Wallet.ActivityPoints,
            new ActivityPoints(
            [
                new ActivityPoint(WalletPointTypes.Diamonds, 12),
                new ActivityPoint(WalletPointTypes.Duckets, 8)
            ]));

        WalletStateView[] states = await Task.WhenAll(first, second)
            .WaitAsync(test_synchronization_timeout);
        Assert.Equal(1, fixture.WalletRequestCount);
        Assert.All(states, state =>
        {
            Assert.True(state.Connected);
            Assert.Equal(ClientType.Flash, state.Client);
            Assert.True(state.CreditsLoaded);
            Assert.Equal(321, state.Credits);
            Assert.True(state.PointsLoaded);
            Assert.Equal(
                [
                    new WalletPointBalance(WalletPointTypes.Duckets, 8),
                    new WalletPointBalance(WalletPointTypes.Diamonds, 12)
                ],
                state.ActivityPoints.Points);
        });
    }

    [Fact]
    public async Task wallet_refresh_waiters_end_when_runtime_is_disposed()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);

        Task<WalletStateView> first = fixture.Application
            .InvokeAsync<WalletRefreshRequest, WalletStateView>(
                ApplicationMemberIds.WalletRefresh,
                new WalletRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();
        await fixture.WalletRequestSent.WaitAsync(test_synchronization_timeout);
        Task<WalletStateView> second = fixture.Application
            .InvokeAsync<WalletRefreshRequest, WalletStateView>(
                ApplicationMemberIds.WalletRefresh,
                new WalletRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();

        Assert.Equal(1, fixture.WalletRequestCount);
        fixture.Application.Dispose();

        await Assert.ThrowsAsync<ObjectDisposedException>(() =>
            first.WaitAsync(test_synchronization_timeout));
        await Assert.ThrowsAsync<ObjectDisposedException>(() =>
            second.WaitAsync(test_synchronization_timeout));
        Assert.Equal(1, fixture.WalletRequestCount);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task wallet_load_reuses_received_credits_and_waits_for_points(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        fixture.Receive(MessageContracts.Wallet.CreditsBalance, new CreditBalance("0.0"));

        Task first = EnsureWalletLoaded(fixture.Application);
        Task second = EnsureWalletLoaded(fixture.Application);
        Assert.Equal(0, fixture.WalletRequestCount);
        Assert.False(first.IsCompleted);
        fixture.Receive(MessageContracts.Wallet.ActivityPoints, new ActivityPoints([]));
        await Task.WhenAll(first, second).WaitAsync(test_synchronization_timeout);
        await EnsureWalletLoaded(fixture.Application).WaitAsync(test_synchronization_timeout);

        WalletStateView state = WalletApplicationPages.Read(fixture.Application);
        Assert.True(state.CreditsLoaded);
        Assert.Equal(0, state.Credits);
        Assert.True(state.PointsLoaded);
        Assert.Equal(0, fixture.WalletRequestCount);
    }

