    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public void catalog_wire_roundtrips_strict_client_shapes_and_freezes_collections(
        ClientType client)
    {
        int[] offer_ids = [301];
        CatalogNode[] children =
        [
            new CatalogNode(true, 2, 201, "chairs", "catalog.page.chairs", offer_ids, [])
        ];
        var root = new CatalogNode(true, 1, -1, "root", "catalog.root", [], children);
        offer_ids[0] = 999;
        children[0] = root;
        Assert.Equal(301, Assert.Single(Assert.Single(root.Children).OfferIds));
        Assert.True(Assert.IsAssignableFrom<IList<int>>(root.Children[0].OfferIds).IsReadOnly);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogNode>>(root.Children).IsReadOnly);

        CatalogIndex index = RoundtripCatalog(
            MessageContracts.Catalog.IndexSnapshot,
            new CatalogIndex(root, true, "NORMAL"),
            client,
            Direction.In);
        Assert.Equal("NORMAL", index.CatalogType);
        Assert.Equal(201, Assert.Single(index.Root.Children).PageId);

        var product = new CatalogProduct(
            CatalogProduct.TypeStuff,
            501,
            "chair_basic",
            2,
            false,
            0,
            0,
            client is ClientType.Unity ? (short)1 : null);
        CatalogProduct[] products = [product];
        IReadOnlyList<CatalogPageProductReference>? references = client is ClientType.Unity
            ? [new CatalogPageProductReference(1, "chair_basic")]
            : null;
        IReadOnlyList<CatalogPageProduct>? unity_products = client is ClientType.Unity
            ? [new CatalogPageProduct(1, 501, "chair_basic", 2, false, 0, 0)]
            : null;
        var offer = new CatalogPageOffer(
            301,
            "chair_offer",
            false,
            3,
            4,
            5,
            6,
            true,
            products,
            0,
            true,
            false,
            "chair.png",
            references,
            unity_products);
        products[0] = product with { FurniClassId = 999 };
        Assert.Equal(501, Assert.Single(offer.Products).FurniClassId);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogProduct>>(offer.Products).IsReadOnly);

        var page = new CatalogPage(
            201,
            "NORMAL",
            "default_3x3",
            new CatalogPageLocalization(["chair.png"], ["Chairs"]),
            [offer],
            301,
            false,
            [new CatalogFrontPageItem(1, "chair", "promo.png", 1, "", 301, "", 60)]);
        CatalogPage parsed_page = RoundtripCatalog(
            MessageContracts.Catalog.PageSnapshot,
            page,
            client,
            Direction.In);
        Assert.Equal(201, parsed_page.PageId);
        Assert.Equal(501, Assert.Single(Assert.Single(parsed_page.Offers).Products).FurniClassId);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogPageOffer>>(parsed_page.Offers).IsReadOnly);

        Assert.Equal(
            "NORMAL",
            RoundtripCatalog(
                MessageContracts.Catalog.IndexRequest,
                new CatalogIndexRequest("NORMAL"),
                client,
                Direction.Out).CatalogType);
        CatalogPageRequest page_request = RoundtripCatalog(
            MessageContracts.Catalog.PageRequest,
            new CatalogPageRequest(201, 301, "NORMAL"),
            client,
            Direction.Out);
        Assert.Equal((201, 301, "NORMAL"),
            (page_request.PageId, page_request.OfferId, page_request.CatalogType));
        CatalogPublished published = RoundtripCatalog(
            MessageContracts.Catalog.Published,
            new CatalogPublished(true, "furni-hash"),
            client,
            Direction.In);
        Assert.True(published.InstantlyRefreshCatalogue);
        Assert.Equal("furni-hash", published.NewFurniDataHash);

        PurchaseFromCatalogRequest purchase_request = RoundtripCatalog(
            MessageContracts.Catalog.Purchase,
            new PurchaseFromCatalogRequest(201, 301, "chair_basic", 2),
            client,
            Direction.Out);
        Assert.Equal((201, 301, "chair_basic", 2),
            (purchase_request.PageId, purchase_request.OfferId,
                purchase_request.ExtraData, purchase_request.Quantity));

        var purchase_offer = new PurchaseOffer(
            301,
            "chair_offer",
            false,
            3,
            4,
            5,
            true,
            [product],
            0,
            true,
            client is ClientType.Unity ? 9_000_000_001 : null,
            client is ClientType.Unity ? [9_000_000_002] : null,
            client is ClientType.Unity ? [9_000_000_003] : null);
        PurchaseOK accepted = RoundtripCatalog(
            MessageContracts.Catalog.Accepted,
            new PurchaseOK(purchase_offer),
            client,
            Direction.In);
        Assert.Equal(301, accepted.Offer.OfferId);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogProduct>>(
            accepted.Offer.Products).IsReadOnly);
        if (client is ClientType.Unity)
        {
            Assert.Equal((Id)9_000_000_001, accepted.Offer.GiftTo);
            Assert.True(Assert.IsAssignableFrom<IList<Id>>(accepted.Offer.RoomItems!).IsReadOnly);
            Assert.True(Assert.IsAssignableFrom<IList<Id>>(accepted.Offer.WallItems!).IsReadOnly);
        }
        else
        {
            Assert.Null(accepted.Offer.GiftTo);
            Assert.Null(accepted.Offer.RoomItems);
            Assert.Null(accepted.Offer.WallItems);
        }
        Assert.Equal(17, RoundtripCatalog(
            MessageContracts.Catalog.Failed,
            new PurchaseError(17),
            client,
            Direction.In).ErrorCode);
        Assert.Equal(19, RoundtripCatalog(
            MessageContracts.Catalog.Forbidden,
            new PurchaseNotAllowed(19),
            client,
            Direction.In).ErrorCode);

        Assert.Throws<InvalidDataException>(() => new CatalogNode(
            true,
            0,
            1,
            "oversized",
            "oversized",
            Enumerable.Range(0, ushort.MaxValue + 1).ToArray(),
            []));
        Assert.Throws<InvalidDataException>(() => new PurchaseOffer(
            1,
            "oversized",
            false,
            0,
            0,
            0,
            false,
            Enumerable.Repeat(product, ushort.MaxValue + 1).ToArray(),
            0,
            false));
    }

    [Fact]
    public void flash_purchase_ok_stops_at_the_client_boundary_before_the_server_extension()
    {
        var product = new CatalogProduct(
            CatalogProduct.TypeStuff,
            5001,
            "",
            1,
            false,
            0,
            0);
        var offer = new PurchaseOffer(
            700,
            "offer_700",
            false,
            0,
            25,
            0,
            true,
            [product],
            0,
            false);
        using var packet = new Packet(new Header(Direction.In, 1), ClientType.Flash);
        packet.Writer().Compose(new PurchaseOK(offer));
        packet.Writer().WriteInt(0);
        packet.Writer().WriteInt(-1);
        packet.Writer().WriteInt(0);
        packet.Position = 0;

        PurchaseOK parsed = MessageContracts.Catalog.Accepted.Parse(packet.Reader());

        Assert.Equal(700, parsed.Offer.OfferId);
        Assert.Single(parsed.Offer.Products);
        Assert.Equal(12, packet.Available);

        using var invalid = new Packet(new Header(Direction.In, 1), ClientType.Flash);
        invalid.Writer().Compose(new PurchaseOK(offer));
        invalid.Writer().WriteInt(0);
        invalid.Position = 0;
        Assert.Throws<InvalidDataException>(() =>
            MessageContracts.Catalog.Accepted.Parse(invalid.Reader()));

        packet.Position = 0;
        Assert.Throws<InvalidDataException>(() => packet.Reader().Parse<PurchaseOffer>());
    }

    [Fact]
    public async Task catalog_state_and_bounded_queries_are_offline_but_network_reads_are_not()
    {
        using var fixture = new SurfaceFixture();

        string[] persistent_members =
        [
            ApplicationMemberIds.CatalogState,
            ApplicationMemberIds.CatalogPagesList,
            ApplicationMemberIds.CatalogOffersSearch,
            ApplicationMemberIds.CatalogCacheClear,
            ApplicationMemberIds.CatalogPurchaseState
        ];
        Assert.All(persistent_members, member_id => Assert.True(fixture.Application
            .Describe(member_id)
            .Availability
            .Available));
        string[] connected_members =
        [
            ApplicationMemberIds.CatalogIndexGet,
            ApplicationMemberIds.CatalogPageGet,
            ApplicationMemberIds.CatalogPagesLoad,
            ApplicationMemberIds.CatalogPurchaseSend
        ];
        Assert.All(connected_members, member_id => Assert.False(fixture.Application
            .Describe(member_id)
            .Availability
            .Available));

        CatalogStateView state = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());
        Assert.False(state.Connected);
        Assert.Null(state.Client);
        Assert.Equal("NORMAL", state.CatalogType);
        Assert.False(state.IndexLoaded);
        Assert.Null(state.IndexReceivedAtUtc);
        Assert.Null(state.IndexAgeMilliseconds);
        Assert.Equal(0, state.CachedPages);
        Assert.Equal(0, state.CachedOffers);

        CatalogPurchaseStateView purchase_state = fixture.Application
            .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                ApplicationMemberIds.CatalogPurchaseState,
                new CatalogPurchaseStateRequest());
        Assert.False(purchase_state.Connected);
        Assert.Null(purchase_state.Client);
        Assert.Null(purchase_state.LastOutcome);
        Assert.Null(purchase_state.LastOutcomeAtUtc);

        CatalogPageListView pages = fixture.Application.Invoke<CatalogPagesRequest, CatalogPageListView>(
            ApplicationMemberIds.CatalogPagesList,
            new CatalogPagesRequest(Limit: 500));
        Assert.False(pages.Connected);
        Assert.Empty(pages.Pages);
        Assert.Null(pages.NextOffset);
        Assert.True(pages.SnapshotRevision > 0);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogPageSummaryView>>(pages.Pages).IsReadOnly);

        CatalogOfferSearchPage offers = fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(Limit: 500));
        Assert.False(offers.Connected);
        Assert.Empty(offers.Offers);
        Assert.Null(offers.NextOffset);
        Assert.True(offers.SnapshotRevision > 0);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogOfferSearchMatchView>>(offers.Offers).IsReadOnly);

        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<CatalogIndexGetRequest, CatalogIndexView>(
                ApplicationMemberIds.CatalogIndexGet,
                new CatalogIndexGetRequest())
            .AsTask());
        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(1, 1))
            .AsTask());
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogPagesRequest, CatalogPageListView>(
                ApplicationMemberIds.CatalogPagesList,
                new CatalogPagesRequest(Limit: 501)));
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(Offset: -1)));
        Assert.Equal("NORMAL", fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest("normal")).CatalogType);
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest("OTHER")));

        CatalogCacheClearView cleared = fixture.Application
            .Invoke<CatalogCacheClearRequest, CatalogCacheClearView>(
                ApplicationMemberIds.CatalogCacheClear,
                new CatalogCacheClearRequest());
        Assert.Null(cleared.Client);
        Assert.Null(cleared.CatalogType);
        Assert.True(cleared.Revision > state.Revision);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task catalog_application_and_legacy_bridge_share_fresh_cache_and_nonblocking_matchers(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        CatalogIndex first_index = CreateCatalogIndex(
            "NORMAL",
            (201, true, [2_010_001]));

        Task<CatalogIndex> first_request = globals.GetCatalogIndex(timeoutMs: test_request_timeout_ms);
        await fixture.WaitForCatalogIndexRequestCount(1).WaitAsync(test_synchronization_timeout);
        Assert.Equal("NORMAL", Assert.IsType<CatalogIndexRequest>(
            fixture.LastCatalogIndexRequest).CatalogType);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.IndexSnapshot,
            CreateCatalogIndex("BUILDERS_CLUB", (901, true, [9_010_001]))));
        Assert.False(first_request.IsCompleted);
        Assert.False(fixture.Receive(MessageContracts.Catalog.IndexSnapshot, first_index));
        CatalogIndex received_index = await first_request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(201, Assert.Single(received_index.Root.Children).PageId);

        CatalogStateView indexed_state = fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
        Assert.True(indexed_state.Connected);
        Assert.Equal(client, indexed_state.Client);
        Assert.True(indexed_state.IndexLoaded);
        Assert.Equal(0, indexed_state.CachedPages);

        CatalogIndexView cached_index = await fixture.Application
            .InvokeAsync<CatalogIndexGetRequest, CatalogIndexView>(
                ApplicationMemberIds.CatalogIndexGet,
                new CatalogIndexGetRequest(
                    MaxAgeMilliseconds: -1,
                    ExpectedSessionGeneration: indexed_state.SessionGeneration,
                    ExpectedCatalogGeneration: indexed_state.CatalogGeneration));
        Assert.True(cached_index.FromCache);
        Assert.Equal(2, cached_index.TotalNodes);
        Assert.False(cached_index.NodesTruncated);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogNodeView>>(cached_index.Nodes).IsReadOnly);
        Assert.Equal(1, fixture.CatalogIndexRequestCount);

        CatalogIndex default_cached = await globals.GetCatalogIndex(timeoutMs: test_request_timeout_ms);
        CatalogIndex infinite_cached = await globals.GetCatalogIndex(
            timeoutMs: test_request_timeout_ms,
            maxAge: Timeout.InfiniteTimeSpan);
        Assert.Same(received_index, default_cached);
        Assert.Same(received_index, infinite_cached);
        Assert.Equal(1, fixture.CatalogIndexRequestCount);

        CatalogIndex refreshed_index = CreateCatalogIndex(
            "NORMAL",
            (201, true, [2_010_001]),
            (202, true, [2_020_001]));
        Task<CatalogIndex> forced_index = globals.GetCatalogIndex(
            timeoutMs: test_request_timeout_ms,
            maxAge: TimeSpan.Zero);
        await fixture.WaitForCatalogIndexRequestCount(2).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(MessageContracts.Catalog.IndexSnapshot, refreshed_index));
        Assert.Equal(
            [201, 202],
            (await forced_index.WaitAsync(test_synchronization_timeout)).Root.Children
                .Select(node => node.PageId));

        CatalogStateView refreshed_state = fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
        Assert.True(refreshed_state.CatalogGeneration > indexed_state.CatalogGeneration);

        CatalogPage page = CreateCatalogPage(client, 201);
        Task<CatalogPage> page_request = globals.GetCatalogPage(
            201,
            page.Offers[0].OfferId,
            timeoutMs: test_request_timeout_ms,
            maxAge: TimeSpan.Zero);
        await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
        CatalogPageRequest sent_page = Assert.IsType<CatalogPageRequest>(fixture.LastCatalogPageRequest);
        Assert.Equal((201, page.Offers[0].OfferId, "NORMAL"),
            (sent_page.PageId, sent_page.OfferId, sent_page.CatalogType));
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.PageSnapshot,
            CreateCatalogPage(client, 202)));
        Assert.False(page_request.IsCompleted);
        Assert.False(fixture.Receive(MessageContracts.Catalog.PageSnapshot, page));
        CatalogPage received_page = await page_request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(page.Offers[0].OfferId, Assert.Single(received_page.Offers).OfferId);

        CatalogStateView paged_state = fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
        CatalogPageView cached_page = await fixture.Application
            .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                ApplicationMemberIds.CatalogPageGet,
                new CatalogPageGetRequest(
                    201,
                    page.Offers[0].OfferId,
                    MaxAgeMilliseconds: -1,
                    ExpectedSessionGeneration: paged_state.SessionGeneration,
                    ExpectedCatalogGeneration: paged_state.CatalogGeneration));
        Assert.True(cached_page.FromCache);
        Assert.Equal(page.Offers[0].OfferId, Assert.Single(cached_page.Offers).OfferId);
        Assert.Equal(1, fixture.CatalogPageRequestCount);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public void catalog_publication_commits_before_application_and_script_observers(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        CatalogPublished? script_publication = null;
        CatalogPublishedEvent? application_publication = null;
        CatalogStateView? state_seen_by_observer = null;
        using IDisposable script_subscription = globals.OnCatalogPublished(
            publication => script_publication = publication);
        using IDisposable application_subscription = fixture.Application.Subscribe<CatalogPublishedEvent>(
            ApplicationMemberIds.CatalogPublished,
            publication =>
            {
                application_publication = publication;
                state_seen_by_observer = fixture.Application
                    .Invoke<CatalogStateRequest, CatalogStateView>(
                        ApplicationMemberIds.CatalogState,
                        new CatalogStateRequest());
            });
        CatalogStateView before = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());

        var published = new CatalogPublished(true, "next-furni-hash");
        Assert.False(fixture.Receive(MessageContracts.Catalog.Published, published));
        Assert.Equal(published, script_publication);
        CatalogPublishedEvent observed = Assert.IsType<CatalogPublishedEvent>(application_publication);
        Assert.Equal(published, observed.Publication);
        Assert.Equal(client, observed.Client);
        Assert.True(observed.CatalogGeneration > before.CatalogGeneration);
        CatalogStateView observed_state = Assert.IsType<CatalogStateView>(state_seen_by_observer);
        Assert.Equal(observed.CatalogGeneration, observed_state.CatalogGeneration);
        Assert.Equal(observed.Revision, observed_state.Revision);
        Assert.Equal(published, observed_state.LastPublication);
        Assert.Equal(observed.ReceivedAtUtc, observed_state.LastPublishedAtUtc);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task catalog_page_projection_preserves_selected_bundle_and_queries_use_stable_leases(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        CatalogStateView initial = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());
        CatalogPage bundle_page = CreateCatalogBundlePage(client, 301);
        int selected_offer_id = bundle_page.Offers[^1].OfferId;

        Task<CatalogPageView> bundle_request = fixture.Application
            .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                ApplicationMemberIds.CatalogPageGet,
                new CatalogPageGetRequest(
                    301,
                    selected_offer_id,
                    MaxAgeMilliseconds: 0,
                    TimeoutMilliseconds: test_request_timeout_ms,
                    ExpectedSessionGeneration: initial.SessionGeneration,
                    ExpectedCatalogGeneration: initial.CatalogGeneration))
            .AsTask();
        await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(MessageContracts.Catalog.PageSnapshot, bundle_page));
        CatalogPageView bundle_view = await bundle_request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(501, bundle_view.TotalOffers);
        CatalogOfferView selected_offer = Assert.Single(
            bundle_view.Offers,
            offer => offer.OfferId == selected_offer_id);
        Assert.Equal(256, selected_offer.TotalProducts);
        Assert.Equal(256, selected_offer.Products.Count);
        Assert.False(selected_offer.ProductsTruncated);
        Assert.Equal("bundle-product-255", selected_offer.Products[^1].ExtraParam);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogOfferView>>(bundle_view.Offers).IsReadOnly);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogProductView>>(selected_offer.Products).IsReadOnly);

        CatalogStateView one_page = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());
        Task<CatalogPageView> second_request = fixture.Application
            .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                ApplicationMemberIds.CatalogPageGet,
                new CatalogPageGetRequest(
                    302,
                    MaxAgeMilliseconds: 0,
                    TimeoutMilliseconds: test_request_timeout_ms,
                    ExpectedSessionGeneration: one_page.SessionGeneration,
                    ExpectedCatalogGeneration: one_page.CatalogGeneration))
            .AsTask();
        await fixture.WaitForCatalogPageRequestCount(2).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.PageSnapshot,
            CreateCatalogPage(client, 302)));
        _ = await second_request.WaitAsync(test_synchronization_timeout);

        CatalogPageListView first_pages = fixture.Application
            .Invoke<CatalogPagesRequest, CatalogPageListView>(
                ApplicationMemberIds.CatalogPagesList,
                new CatalogPagesRequest(Limit: 1));
        Assert.Equal(2, first_pages.TotalPages);
        Assert.Single(first_pages.Pages);
        Assert.Equal(1, first_pages.NextOffset);
        CatalogPageListView second_pages = fixture.Application
            .Invoke<CatalogPagesRequest, CatalogPageListView>(
                ApplicationMemberIds.CatalogPagesList,
                new CatalogPagesRequest(
                    Offset: 1,
                    Limit: 1,
                    SnapshotRevision: first_pages.SnapshotRevision,
                    ExpectedSessionGeneration: first_pages.SessionGeneration,
                    ExpectedCatalogGeneration: first_pages.CatalogGeneration));
        Assert.Single(second_pages.Pages);
        Assert.Null(second_pages.NextOffset);
        Assert.Equal(302, second_pages.Pages[0].PageId);

        CatalogOfferSearchPage first_offers = fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(Limit: 500));
        Assert.Equal(502, first_offers.TotalOffers);
        Assert.Equal(500, first_offers.Offers.Count);
        Assert.Equal(500, first_offers.NextOffset);
        CatalogOfferSearchPage second_offers = fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(
                    Offset: 500,
                    Limit: 500,
                    SnapshotRevision: first_offers.SnapshotRevision,
                    ExpectedSessionGeneration: first_offers.SessionGeneration,
                    ExpectedCatalogGeneration: first_offers.CatalogGeneration));
        Assert.Equal(2, second_offers.Offers.Count);
        Assert.Null(second_offers.NextOffset);
        CatalogOfferSearchMatchView selected_match = Assert.Single(
            second_offers.Offers,
            offer => offer.OfferId == selected_offer_id);
        Assert.Equal(256, selected_match.ProductCount);
        Assert.Equal(bundle_page.Offers[^1].Products[0].FurniClassId, selected_match.FirstFurniClassId);

        CatalogProduct second_product = bundle_page.Offers[^1].Products[1];
        CatalogOfferSearchPage deep_extra_match = fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(second_product.ExtraParam, Limit: 500));
        Assert.Equal(
            selected_offer_id,
            Assert.Single(deep_extra_match.Offers).OfferId);
        CatalogOfferSearchPage deep_class_match = fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(
                    second_product.FurniClassId.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    Limit: 500));
        Assert.Equal(
            selected_offer_id,
            Assert.Single(deep_class_match.Offers).OfferId);

        IReadOnlyList<CatalogPage> legacy_pages = globals.CachedCatalogPages();
        CatalogPage legacy_bundle = Assert.Single(legacy_pages, page => page.PageId == 301);
        Assert.Equal(501, legacy_bundle.Offers.Count);
        Assert.Equal(256, legacy_bundle.Offers[^1].Products.Count);
        CatalogOfferMatch legacy_match = Assert.Single(globals.FindCatalogOffers(second_product.ExtraParam));
        Assert.Equal(selected_offer_id, legacy_match.Offer.OfferId);
        CatalogCacheState legacy_state = globals.CatalogCache();
        Assert.Equal(2, legacy_state.PageCount);
        Assert.Equal(502, legacy_state.OfferCount);

        CatalogStateView before_clear = fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
        int sent_before_guard = fixture.CatalogPageRequestCount;
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                ApplicationMemberIds.CatalogPageGet,
                new CatalogPageGetRequest(
                    301,
                    MaxAgeMilliseconds: -1,
                    ExpectedSessionGeneration: before_clear.SessionGeneration,
                    ExpectedCatalogGeneration: before_clear.CatalogGeneration + 1))
            .AsTask());
        Assert.Equal(sent_before_guard, fixture.CatalogPageRequestCount);

        CatalogCacheClearView cleared = fixture.Application
            .Invoke<CatalogCacheClearRequest, CatalogCacheClearView>(
                ApplicationMemberIds.CatalogCacheClear,
                new CatalogCacheClearRequest(
                    ExpectedSessionGeneration: before_clear.SessionGeneration,
                    ExpectedCatalogGeneration: before_clear.CatalogGeneration));
        Assert.True(cleared.CatalogGeneration > before_clear.CatalogGeneration);
        Assert.Empty(globals.CachedCatalogPages());
        Assert.Throws<InvalidOperationException>(() => fixture.Application
            .Invoke<CatalogPagesRequest, CatalogPageListView>(
                ApplicationMemberIds.CatalogPagesList,
                new CatalogPagesRequest(
                    Offset: 1,
                    Limit: 1,
                    SnapshotRevision: first_pages.SnapshotRevision)));
        Assert.Throws<InvalidOperationException>(() => fixture.Application
            .Invoke<CatalogOfferSearchRequest, CatalogOfferSearchPage>(
                ApplicationMemberIds.CatalogOffersSearch,
                new CatalogOfferSearchRequest(
                    Offset: 500,
                    Limit: 500,
                    SnapshotRevision: first_offers.SnapshotRevision)));
    }

    [Fact]
    public async Task catalog_cas_races_are_terminal_for_two_forced_reads_refresh_publish_and_disconnect()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            CatalogStateView state = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
            CatalogPage response = CreateCatalogPage(ClientType.Flash, 401, 2);
            Task<CatalogPageView> first = fixture.Application
                .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                    ApplicationMemberIds.CatalogPageGet,
                    new CatalogPageGetRequest(
                        401,
                        response.Offers[0].OfferId,
                        MaxAgeMilliseconds: 0,
                        TimeoutMilliseconds: test_request_timeout_ms,
                        ExpectedSessionGeneration: state.SessionGeneration,
                        ExpectedCatalogGeneration: state.CatalogGeneration))
                .AsTask();
            Task<CatalogPageView> second = fixture.Application
                .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                    ApplicationMemberIds.CatalogPageGet,
                    new CatalogPageGetRequest(
                        401,
                        response.Offers[1].OfferId,
                        MaxAgeMilliseconds: 0,
                        TimeoutMilliseconds: test_request_timeout_ms,
                        ExpectedSessionGeneration: state.SessionGeneration,
                        ExpectedCatalogGeneration: state.CatalogGeneration))
                .AsTask();
            await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
            Assert.False(fixture.Receive(MessageContracts.Catalog.PageSnapshot, response));
            await fixture.WaitForCatalogPageRequestCount(2).WaitAsync(test_synchronization_timeout);
            Assert.False(fixture.Receive(MessageContracts.Catalog.PageSnapshot, response));
            CatalogPageView[] results = await Task.WhenAll(first, second).WaitAsync(test_synchronization_timeout);
            Assert.All(results, result => Assert.Equal(401, result.PageId));
            Assert.Equal(results[0].Revision, results[1].Revision);
            Assert.Single(results, result => !result.FromCache);
            Assert.Single(results, result => result.FromCache);
            CatalogStateView committed = fixture.Application
                .Invoke<CatalogStateRequest, CatalogStateView>(
                    ApplicationMemberIds.CatalogState,
                    new CatalogStateRequest());
            Assert.Equal(1, committed.CachedPages);
            Assert.Equal(2, committed.CachedOffers);
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            CatalogStateView state = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
            Task<CatalogPageView> pending_page = fixture.Application
                .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                    ApplicationMemberIds.CatalogPageGet,
                    new CatalogPageGetRequest(
                        402,
                        MaxAgeMilliseconds: 0,
                        TimeoutMilliseconds: test_request_timeout_ms,
                        ExpectedSessionGeneration: state.SessionGeneration,
                        ExpectedCatalogGeneration: state.CatalogGeneration))
                .AsTask();
            await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
            Task<CatalogIndexView> index_refresh = fixture.Application
                .InvokeAsync<CatalogIndexGetRequest, CatalogIndexView>(
                    ApplicationMemberIds.CatalogIndexGet,
                    new CatalogIndexGetRequest(
                        MaxAgeMilliseconds: 0,
                        TimeoutMilliseconds: test_request_timeout_ms,
                        ExpectedSessionGeneration: state.SessionGeneration,
                        ExpectedCatalogGeneration: state.CatalogGeneration))
                .AsTask();
            await fixture.WaitForCatalogIndexRequestCount(1).WaitAsync(test_synchronization_timeout);
            Assert.False(fixture.Receive(
                MessageContracts.Catalog.IndexSnapshot,
                CreateCatalogIndex("NORMAL", (402, true, [4_020_001]))));
            _ = await index_refresh.WaitAsync(test_synchronization_timeout);
            await Assert.ThrowsAsync<CatalogInvalidatedException>(() =>
                pending_page.WaitAsync(test_synchronization_timeout));
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            CatalogStateView state = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
            Task<CatalogPageView> pending_page = fixture.Application
                .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                    ApplicationMemberIds.CatalogPageGet,
                    new CatalogPageGetRequest(
                        403,
                        MaxAgeMilliseconds: 0,
                        TimeoutMilliseconds: test_request_timeout_ms,
                        ExpectedSessionGeneration: state.SessionGeneration,
                        ExpectedCatalogGeneration: state.CatalogGeneration))
                .AsTask();
            await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
            Assert.False(fixture.Receive(
                MessageContracts.Catalog.Published,
                new CatalogPublished(true, "published-race")));
            await Assert.ThrowsAsync<CatalogInvalidatedException>(() =>
                pending_page.WaitAsync(test_synchronization_timeout));
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            Task<CatalogIndexView> pending_index = fixture.Application
                .InvokeAsync<CatalogIndexGetRequest, CatalogIndexView>(
                    ApplicationMemberIds.CatalogIndexGet,
                    new CatalogIndexGetRequest(
                        MaxAgeMilliseconds: 0,
                        TimeoutMilliseconds: test_request_timeout_ms))
                .AsTask();
            await fixture.WaitForCatalogIndexRequestCount(1).WaitAsync(test_synchronization_timeout);
            fixture.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() =>
                pending_index.WaitAsync(test_synchronization_timeout));
        }
    }

    [Fact]
    public async Task catalog_load_counts_only_page_timeouts_as_refused()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        CatalogStateView initial = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());
        Task<CatalogLoadView> load = fixture.Application
            .InvokeAsync<CatalogLoadRequest, CatalogLoadView>(
                ApplicationMemberIds.CatalogPagesLoad,
                new CatalogLoadRequest(
                    OnlyVisible: false,
                    MaxAgeMilliseconds: 0,
                    TimeoutMilliseconds: test_refusal_timeout_ms,
                    ExpectedSessionGeneration: initial.SessionGeneration,
                    ExpectedCatalogGeneration: initial.CatalogGeneration))
            .AsTask();
        await fixture.WaitForCatalogIndexRequestCount(1).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.IndexSnapshot,
            CreateCatalogIndex(
                "NORMAL",
                (501, true, [5_010_001]),
                (502, true, [5_020_001]),
                (503, true, [5_030_001]))));
        await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
        Assert.Equal(501, Assert.IsType<CatalogPageRequest>(fixture.LastCatalogPageRequest).PageId);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.PageSnapshot,
            CreateCatalogPage(ClientType.Flash, 501)));
        await fixture.WaitForCatalogPageRequestCount(2).WaitAsync(test_synchronization_timeout);
        Assert.Equal(502, Assert.IsType<CatalogPageRequest>(fixture.LastCatalogPageRequest).PageId);
        await fixture.WaitForCatalogPageRequestCount(3).WaitAsync(test_synchronization_timeout);
        Assert.Equal(503, Assert.IsType<CatalogPageRequest>(fixture.LastCatalogPageRequest).PageId);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.PageSnapshot,
            CreateCatalogPage(ClientType.Flash, 503)));
        CatalogLoadView report = await load.WaitAsync(test_synchronization_timeout);
        Assert.Equal(2, report.Loaded);
        Assert.Equal(0, report.AlreadyCached);
        Assert.Equal(1, report.Refused);
        Assert.Equal(3, report.Total);
        Assert.Equal(2, report.Available);

        CatalogStateView loaded = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());
        Assert.Equal(2, loaded.CachedPages);
        Assert.Equal(2, loaded.CachedOffers);
        _ = fixture.Application.Invoke<CatalogCacheClearRequest, CatalogCacheClearView>(
            ApplicationMemberIds.CatalogCacheClear,
            new CatalogCacheClearRequest(
                ExpectedSessionGeneration: loaded.SessionGeneration,
                ExpectedCatalogGeneration: loaded.CatalogGeneration));
        CatalogStateView cleared = fixture.Application.Invoke<CatalogStateRequest, CatalogStateView>(
            ApplicationMemberIds.CatalogState,
            new CatalogStateRequest());

        Task<CatalogLoadView> invalidated_load = fixture.Application
            .InvokeAsync<CatalogLoadRequest, CatalogLoadView>(
                ApplicationMemberIds.CatalogPagesLoad,
                new CatalogLoadRequest(
                    OnlyVisible: false,
                    MaxAgeMilliseconds: 0,
                    TimeoutMilliseconds: test_request_timeout_ms,
                    ExpectedSessionGeneration: cleared.SessionGeneration,
                    ExpectedCatalogGeneration: cleared.CatalogGeneration))
            .AsTask();
        await fixture.WaitForCatalogIndexRequestCount(2).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.IndexSnapshot,
            CreateCatalogIndex("NORMAL", (504, true, [5_040_001]))));
        await fixture.WaitForCatalogPageRequestCount(4).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.Published,
            new CatalogPublished(true, "load-invalidated")));
        await Assert.ThrowsAsync<CatalogInvalidatedException>(() =>
            invalidated_load.WaitAsync(test_synchronization_timeout));
    }

    [Fact]
    public async Task catalog_waiter_cancellation_and_runtime_disposal_are_terminal()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        using ScriptGlobals globals = fixture.CreateGlobals();
        using var cancellation = new CancellationTokenSource();
        Task<CatalogIndexView> cancelled = fixture.Application
            .InvokeAsync<CatalogIndexGetRequest, CatalogIndexView>(
                ApplicationMemberIds.CatalogIndexGet,
                new CatalogIndexGetRequest(MaxAgeMilliseconds: 0, TimeoutMilliseconds: test_request_timeout_ms),
                cancellation.Token)
            .AsTask();
        Task<CatalogIndexView> retained = fixture.Application
            .InvokeAsync<CatalogIndexGetRequest, CatalogIndexView>(
                ApplicationMemberIds.CatalogIndexGet,
                new CatalogIndexGetRequest(MaxAgeMilliseconds: 0, TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForCatalogIndexRequestCount(1).WaitAsync(test_synchronization_timeout);
        cancellation.Cancel();
        OperationCanceledException cancelled_error = await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
            cancelled.WaitAsync(test_synchronization_timeout));
        Assert.Equal(cancellation.Token, cancelled_error.CancellationToken);
        Assert.False(retained.IsCompleted);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.IndexSnapshot,
            CreateCatalogIndex("NORMAL", (601, true, [6_010_001]))));
        Assert.Equal(601, Assert.Single(
            (await retained.WaitAsync(test_synchronization_timeout)).Nodes,
            node => node.PageId >= 0).PageId);
        Assert.Equal(1, fixture.CatalogIndexRequestCount);

        Task<CatalogPageView> pending = fixture.Application
            .InvokeAsync<CatalogPageGetRequest, CatalogPageView>(
                ApplicationMemberIds.CatalogPageGet,
                new CatalogPageGetRequest(601, MaxAgeMilliseconds: 0, TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForCatalogPageRequestCount(1).WaitAsync(test_synchronization_timeout);
        fixture.Application.Dispose();
        await Assert.ThrowsAsync<ObjectDisposedException>(() =>
            pending.WaitAsync(test_synchronization_timeout));
        Assert.Throws<ObjectDisposedException>(() => fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest()));
        Assert.Throws<InvalidOperationException>(() =>
        {
            _ = globals.GetCatalogIndex();
        });
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task catalog_purchase_dispatch_is_immediate_and_outcomes_remain_passive(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        CatalogStateView catalog_state = fixture.Application
            .Invoke<CatalogStateRequest, CatalogStateView>(
                ApplicationMemberIds.CatalogState,
                new CatalogStateRequest());
        CatalogPurchaseStateView initial = fixture.Application
            .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                ApplicationMemberIds.CatalogPurchaseState,
                new CatalogPurchaseStateRequest());
        Assert.True(initial.Connected);
        Assert.Equal(client, initial.Client);
        Assert.Null(initial.LastOutcome);

        ApplicationDescriptor send_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.CatalogPurchaseSend);
        Assert.Equal(ApplicationExposure.All, send_descriptor.Exposure);
        Assert.Equal(new ApplicationToolHints(false, true, false, true), send_descriptor.ToolHints);
        Assert.Equal(ApplicationInvocationScope.Transient, send_descriptor.InvocationScope);
        Assert.Equal(
            ["page_id", "offer_id", "extra_data", "quantity",
                "expected_session_generation", "expected_catalog_generation"],
            send_descriptor.Parameters.Select(parameter => parameter.Name).ToArray());
        Assert.Equal(string.Empty, send_descriptor.Parameters[2].DefaultValue);
        Assert.Equal((int)ushort.MaxValue, send_descriptor.Parameters[2].Constraints!.MaxUtf8Bytes);
        Assert.Equal(1, send_descriptor.Parameters[3].DefaultValue);
        Assert.Equal(1L, send_descriptor.Parameters[3].Constraints!.Minimum);
        Assert.Equal(
            [MessageKeys.Catalog.Purchase],
            send_descriptor.Messages.Select(message => message.Key).ToArray());
        Assert.Equal([ApplicationStateKey.HotelConnected], send_descriptor.RequiredStates);

        ApplicationDescriptor state_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.CatalogPurchaseState);
        Assert.Equal(ApplicationExposure.All, state_descriptor.Exposure);
        Assert.Equal(ApplicationInvocationScope.Persistent, state_descriptor.InvocationScope);
        Assert.Empty(state_descriptor.Parameters);
        Assert.Empty(state_descriptor.RequiredStates);
        Assert.Equal(
            [new ApplicationStateEffect(
                ApplicationStateKey.CatalogPurchase,
                ApplicationStateEffectKind.Reads)],
            state_descriptor.StateEffects);
        Assert.Equal(
            [MessageKeys.Catalog.PurchaseAccepted,
                MessageKeys.Catalog.PurchaseFailed,
                MessageKeys.Catalog.PurchaseForbidden],
            state_descriptor.Messages.Select(message => message.Key).ToArray());
        Assert.All(state_descriptor.Messages, message =>
        {
            Assert.False(message.Required);
            Assert.Equal(Direction.In, message.Direction);
            Assert.Equal(ApplicationMessageRole.Observe, message.Role);
        });

        ApplicationDescriptor outcome_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.CatalogPurchaseOutcome);
        Assert.Equal(
            ApplicationExposure.Ui | ApplicationExposure.Cli | ApplicationExposure.Scripting,
            outcome_descriptor.Exposure);
        Assert.Equal(ApplicationInvocationScope.Persistent, outcome_descriptor.InvocationScope);
        Assert.Empty(outcome_descriptor.RequiredStates);
        Assert.Equal(
            [new ApplicationStateEffect(
                ApplicationStateKey.CatalogPurchase,
                ApplicationStateEffectKind.Changes)],
            outcome_descriptor.StateEffects);
        Assert.Equal(
            state_descriptor.Messages.Select(message => message.Key).ToArray(),
            outcome_descriptor.Messages.Select(message => message.Key).ToArray());
        Assert.All(outcome_descriptor.Messages, message =>
        {
            Assert.True(message.Required);
            Assert.Equal(Direction.In, message.Direction);
            Assert.Equal(ApplicationMessageRole.Observe, message.Role);
        });

        CatalogPurchaseDispatchReceipt receipt = fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(
                    201,
                    301,
                    "chair_basic",
                    2,
                    catalog_state.SessionGeneration,
                    catalog_state.CatalogGeneration));
        Assert.Equal(client, receipt.Client);
        Assert.Equal(catalog_state.SessionGeneration, receipt.SessionGeneration);
        Assert.Equal(catalog_state.CatalogGeneration, receipt.CatalogGeneration);
        Assert.Equal((201, 301, 2, 1),
            (receipt.PageId, receipt.OfferId, receipt.Quantity, receipt.MessagesDispatched));
        Assert.Equal((201, 301, "chair_basic", 2),
            (fixture.LastCatalogPurchase!.PageId,
                fixture.LastCatalogPurchase.OfferId,
                fixture.LastCatalogPurchase.ExtraData,
                fixture.LastCatalogPurchase.Quantity));

        CatalogPurchaseOutcome scripted = await globals
            .BuyFromCatalog(202, 302, "script", 3, timeoutMs: -1)
            .WaitAsync(test_synchronization_timeout);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, scripted.Status);
        Assert.False(scripted.Succeeded);
        Assert.Null(scripted.Offer);
        Assert.Equal(0, scripted.ErrorCode);

        globals.PurchaseFromCatalog(203, 303, "action", 4);
        CatalogPurchaseOutcome bridged = await fixture.Catalog
            .PurchaseAsync(new PurchaseFromCatalogRequest(204, 304, "bridge", 5), -1)
            .WaitAsync(test_synchronization_timeout);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, bridged.Status);

        Task<CatalogPurchaseOutcome> first = globals.BuyFromCatalog(205, 305);
        Task<CatalogPurchaseOutcome> second = globals.BuyFromCatalog(206, 306);
        CatalogPurchaseOutcome[] overlap = await Task.WhenAll(first, second)
            .WaitAsync(test_synchronization_timeout);
        Assert.All(overlap, outcome => Assert.Equal(CatalogPurchaseStatus.Dispatched, outcome.Status));
        Assert.Equal(6, fixture.CatalogPurchaseSendCount);
        Assert.Null(globals.LastPurchase);

        int sends_before_validation = fixture.CatalogPurchaseSendCount;
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(-1, 1)));
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(1, -1)));
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(1, 1, new string('x', ushort.MaxValue + 1))));
        Assert.Throws<ArgumentOutOfRangeException>(() => fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(1, 1, Quantity: 0)));
        Assert.Throws<InvalidOperationException>(() => fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(
                    1,
                    1,
                    ExpectedSessionGeneration: catalog_state.SessionGeneration + 1)));
        Assert.Throws<InvalidOperationException>(() => fixture.Application
            .Invoke<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(
                    1,
                    1,
                    ExpectedCatalogGeneration: catalog_state.CatalogGeneration + 1)));
        using (var cancellation = new CancellationTokenSource())
        {
            cancellation.Cancel();
            Task<CatalogPurchaseOutcome> cancelled = fixture.Catalog.PurchaseAsync(
                new PurchaseFromCatalogRequest(207, 307, "", 1),
                cancellation_token: cancellation.Token);
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => cancelled);
            Assert.Equal(cancellation.Token, error.CancellationToken);
        }
        Assert.Equal(sends_before_validation, fixture.CatalogPurchaseSendCount);

        var outcomes = new List<CatalogPurchaseOutcomeEvent>();
        CatalogPurchaseStateView? state_seen_by_event = null;
        CatalogPurchaseOutcome? legacy_outcome = null;
        using IDisposable application_subscription = fixture.Application
            .Subscribe<CatalogPurchaseOutcomeEvent>(
                ApplicationMemberIds.CatalogPurchaseOutcome,
                outcome =>
                {
                    outcomes.Add(outcome);
                    state_seen_by_event = fixture.Application
                        .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                            ApplicationMemberIds.CatalogPurchaseState,
                            new CatalogPurchaseStateRequest());
                });
        using IDisposable script_subscription = globals.OnPurchase(outcome => legacy_outcome = outcome);
        PurchaseOffer accepted_offer = CreatePurchaseOffer(client, 257, 123);
        Assert.False(fixture.Receive(
            MessageContracts.Catalog.Accepted,
            new PurchaseOK(accepted_offer)));

        CatalogPurchaseOutcomeEvent accepted = Assert.Single(outcomes);
        Assert.Equal(CatalogPurchaseOutcomeKind.Accepted, accepted.Outcome.Kind);
        Assert.Equal(accepted.Revision, Assert.IsType<CatalogPurchaseStateView>(
            state_seen_by_event).Revision);
        CatalogPurchaseOfferView accepted_view = Assert.IsType<CatalogPurchaseOfferView>(
            accepted.Outcome.Offer);
        Assert.Equal(257, accepted_view.TotalProducts);
        Assert.True(accepted_view.ProductsTruncated);
        Assert.Equal(256, accepted_view.Products.Count);
        Assert.True(Assert.IsAssignableFrom<IList<CatalogProductView>>(
            accepted_view.Products).IsReadOnly);
        if (client is ClientType.Unity)
        {
            Assert.Equal(123, accepted_view.TotalRoomItems);
            Assert.Equal(122, accepted_view.RoomItems.Count);
            Assert.True(accepted_view.RoomItemsTruncated);
            Assert.Equal(123, accepted_view.TotalWallItems);
            Assert.Equal(122, accepted_view.WallItems.Count);
            Assert.True(accepted_view.WallItemsTruncated);
        }
        else
        {
            Assert.Equal(0, accepted_view.TotalRoomItems);
            Assert.Equal(0, accepted_view.TotalWallItems);
        }
        CatalogPurchaseOutcome legacy_accepted = Assert.IsType<CatalogPurchaseOutcome>(legacy_outcome);
        Assert.Equal(CatalogPurchaseStatus.Completed, legacy_accepted.Status);
        Assert.Equal(257, legacy_accepted.Offer!.Products.Count);
        Assert.Equal(257, globals.LastPurchase!.Offer!.Products.Count);

        Assert.False(fixture.Receive(MessageContracts.Catalog.Failed, new PurchaseError(17)));
        Assert.False(fixture.Receive(MessageContracts.Catalog.Forbidden, new PurchaseNotAllowed(19)));
        Assert.Equal(
            [CatalogPurchaseOutcomeKind.Accepted,
                CatalogPurchaseOutcomeKind.Failed,
                CatalogPurchaseOutcomeKind.Forbidden],
            outcomes.Select(outcome => outcome.Outcome.Kind).ToArray());
        Assert.Equal(CatalogPurchaseStatus.NotAllowed, globals.LastPurchase!.Status);
        Assert.Equal(19, globals.LastPurchase.ErrorCode);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, scripted.Status);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, bridged.Status);

        fixture.Disconnect();
        CatalogPurchaseStateView disconnected = fixture.Application
            .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                ApplicationMemberIds.CatalogPurchaseState,
                new CatalogPurchaseStateRequest());
        Assert.False(disconnected.Connected);
        Assert.Null(disconnected.LastOutcome);
        Assert.Null(globals.LastPurchase);
        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<CatalogPurchaseSendRequest, CatalogPurchaseDispatchReceipt>(
                ApplicationMemberIds.CatalogPurchaseSend,
                new CatalogPurchaseSendRequest(1, 1))
            .AsTask());
        fixture.Application.Dispose();
        Assert.Throws<InvalidOperationException>(() =>
        {
            _ = fixture.Catalog.PurchaseAsync(new PurchaseFromCatalogRequest(1, 1, "", 1));
        });

        using var unsolicited = new SurfaceFixture(client);
        CatalogPurchaseOutcomeEvent? unsolicited_event = null;
        using IDisposable unsolicited_subscription = unsolicited.Application
            .Subscribe<CatalogPurchaseOutcomeEvent>(
                ApplicationMemberIds.CatalogPurchaseOutcome,
                outcome => unsolicited_event = outcome);
        Assert.False(unsolicited.Receive(MessageContracts.Catalog.Failed, new PurchaseError(41)));
        Assert.Equal(0, unsolicited.CatalogPurchaseSendCount);
        Assert.Equal(CatalogPurchaseOutcomeKind.Failed,
            Assert.IsType<CatalogPurchaseOutcomeEvent>(unsolicited_event).Outcome.Kind);
        CatalogPurchaseStateView unsolicited_state = unsolicited.Application
            .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                ApplicationMemberIds.CatalogPurchaseState,
                new CatalogPurchaseStateRequest());
        Assert.Equal(41, unsolicited_state.LastOutcome!.ErrorCode);
        unsolicited.Disconnect();
        Assert.Null(unsolicited.Application
            .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                ApplicationMemberIds.CatalogPurchaseState,
                new CatalogPurchaseStateRequest()).LastOutcome);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task catalog_purchase_gift_and_room_ad_use_dispatch_only_compatibility(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();

        CatalogPurchaseOutcome gift = await globals.BuyGiftFromCatalog(
            201,
            301,
            "receiver",
            "message",
            timeoutMs: -1).WaitAsync(test_synchronization_timeout);
        CatalogPurchaseOutcome room_ad = await globals.BuyRoomEvent(
            202,
            302,
            client is ClientType.Unity ? 9_000_000_001 : 101,
            "event",
            timeoutMs: -1).WaitAsync(test_synchronization_timeout);

        Assert.Equal(CatalogPurchaseStatus.Dispatched, gift.Status);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, room_ad.Status);
        Assert.Equal(1, fixture.GiftPurchaseSendCount);
        Assert.Equal(1, fixture.RoomAdPurchaseSendCount);
        Assert.Equal(0, fixture.CatalogPurchaseSendCount);
        Assert.Null(globals.LastPurchase);

        Assert.False(fixture.Receive(MessageContracts.Catalog.Failed, new PurchaseError(27)));
        Assert.Equal(CatalogPurchaseStatus.Failed, globals.LastPurchase!.Status);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, gift.Status);
        Assert.Equal(CatalogPurchaseStatus.Dispatched, room_ad.Status);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task catalog_purchase_reentrant_reset_drops_queued_outcomes(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        var application_outcomes = new List<CatalogPurchaseOutcomeEvent>();
        var legacy_outcomes = new List<CatalogPurchaseOutcome>();
        using IDisposable legacy_subscription = globals.OnPurchase(legacy_outcomes.Add);
        using IDisposable application_subscription = fixture.Application
            .Subscribe<CatalogPurchaseOutcomeEvent>(
                ApplicationMemberIds.CatalogPurchaseOutcome,
                outcome =>
                {
                    application_outcomes.Add(outcome);
                    if (application_outcomes.Count != 1)
                        return;
                    Assert.False(fixture.Receive(
                        MessageContracts.Catalog.Failed,
                        new PurchaseError(71)));
                    fixture.Disconnect();
                });

        bool blocked = await Task.Run(() => fixture.Receive(
                MessageContracts.Catalog.Accepted,
                new PurchaseOK(CreatePurchaseOffer(client, 1, 0))))
            .WaitAsync(test_synchronization_timeout);

        Assert.False(blocked);
        Assert.Equal(CatalogPurchaseOutcomeKind.Accepted,
            Assert.Single(application_outcomes).Outcome.Kind);
        Assert.Empty(legacy_outcomes);
        Assert.Null(globals.LastPurchase);
        CatalogPurchaseStateView state = fixture.Application
            .Invoke<CatalogPurchaseStateRequest, CatalogPurchaseStateView>(
                ApplicationMemberIds.CatalogPurchaseState,
                new CatalogPurchaseStateRequest());
        Assert.False(state.Connected);
        Assert.Null(state.LastOutcome);
        Assert.Equal(0, fixture.CatalogPurchaseSendCount);
    }

    [Fact]
    public void catalog_purchase_legacy_abi_keeps_signatures_defaults_and_numeric_values()
    {
        Assert.Equal(0, (int)CatalogPurchaseStatus.Completed);
        Assert.Equal(1, (int)CatalogPurchaseStatus.Failed);
        Assert.Equal(2, (int)CatalogPurchaseStatus.NotAllowed);
        Assert.Equal(3, (int)CatalogPurchaseStatus.Dispatched);
        Assert.False(new CatalogPurchaseOutcome(CatalogPurchaseStatus.Dispatched, null, 0).Succeeded);

        ConstructorInfo constructor = Assert.Single(typeof(CatalogPurchaseOutcome).GetConstructors());
        Assert.Equal(
            [typeof(CatalogPurchaseStatus), typeof(PurchaseOffer), typeof(int)],
            constructor.GetParameters().Select(parameter => parameter.ParameterType).ToArray());

        MethodInfo[] overloads = typeof(CatalogManager)
            .GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
            .Where(method => method.Name == nameof(CatalogManager.PurchaseAsync))
            .ToArray();
        Assert.Equal(3, overloads.Length);
        MethodInfo typed = Assert.Single(overloads, method => !method.IsGenericMethodDefinition);
        Assert.Equal(typeof(Task<CatalogPurchaseOutcome>), typed.ReturnType);
        Assert.Equal(
            [typeof(PurchaseFromCatalogRequest), typeof(int), typeof(CancellationToken)],
            typed.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal("timeout_ms", typed.GetParameters()[1].Name);
        Assert.Equal(10000, typed.GetParameters()[1].DefaultValue);
        Assert.True(typed.GetParameters()[2].HasDefaultValue);

        MethodInfo[] generic = overloads.Where(method => method.IsGenericMethodDefinition).ToArray();
        Assert.Equal(2, generic.Length);
        Assert.Equal(
            [typeof(MessageKey), typeof(string)],
            generic.Select(method => method.GetParameters()[0].ParameterType)
                .OrderBy(type => type.FullName, StringComparer.Ordinal)
                .ToArray());
        Assert.All(generic, method =>
        {
            Assert.Equal(typeof(Task<CatalogPurchaseOutcome>), method.ReturnType);
            Assert.Equal([typeof(Qx.Messages.IComposer)],
                method.GetGenericArguments()[0].GetGenericParameterConstraints());
            Assert.Equal("timeout_ms", method.GetParameters()[2].Name);
            Assert.Equal(10000, method.GetParameters()[2].DefaultValue);
            Assert.True(method.GetParameters()[3].HasDefaultValue);
        });
    }

