    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public void poll_wire_roundtrips_client_shapes_and_rejects_trailing_payload(ClientType client)
    {
        Id poll_id = 101;
        Id outgoing_id = client is ClientType.Unity ? 9_000_000_101 : poll_id;
        PollContents contents = CreatePollContents(client, poll_id);

        PollOffer offer = RoundtripPoll(
            MessageContracts.Polls.Offer,
            new PollOffer(poll_id, "hotel", "headline", "summary"),
            client,
            Direction.In);
        Assert.Equal(poll_id, offer.PollId);
        Assert.Equal("headline", offer.Headline);

        PollContents parsed_contents = RoundtripPoll(
            MessageContracts.Polls.Contents,
            contents,
            client,
            Direction.In);
        PollQuestionGroup group = Assert.Single(parsed_contents.Questions);
        Assert.Single(group.Question.Choices);
        Assert.Single(group.Children);
        Assert.Equal(contents.PollId, parsed_contents.PollId);

        _ = RoundtripPoll(
            MessageContracts.Polls.Error,
            new PollError(),
            client,
            Direction.In);
        Assert.Equal(
            outgoing_id,
            RoundtripPoll(
                MessageContracts.Polls.Start,
                new StartPoll(outgoing_id),
                client,
                Direction.Out).PollId);
        Assert.Equal(
            outgoing_id,
            RoundtripPoll(
                MessageContracts.Polls.Reject,
                new RejectPoll(outgoing_id),
                client,
                Direction.Out).PollId);

        PollResponse[] responses = client is ClientType.Flash
            ? [new PollResponse(201, ["yes", "later"])]
            :
            [
                new PollResponse(9_000_000_201, ["yes", "later"]),
                new PollResponse(9_000_000_202, ["free text"])
            ];
        PollAnswer answer = RoundtripPoll(
            MessageContracts.Polls.Answer,
            new PollAnswer(outgoing_id, Array.AsReadOnly(responses)),
            client,
            Direction.Out);
        Assert.Equal(outgoing_id, answer.PollId);
        Assert.Equal(responses.Length, answer.Responses.Count);
        Assert.Equal(responses[0].QuestionId, answer.Responses[0].QuestionId);
        Assert.Equal(responses[0].Answers, answer.Responses[0].Answers);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task poll_application_and_script_surface_preserve_state_correlation_and_dispatch(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        PollContents initial_contents = CreatePollContents(client, 201);
        fixture.Receive(
            MessageContracts.Polls.Offer,
            new PollOffer(201, "hotel", "initial", "summary"));
        fixture.Receive(MessageContracts.Polls.Contents, initial_contents);

        using ScriptGlobals globals = fixture.CreateGlobals();
        Assert.Equal("initial", globals.LatestPollOffer?.Headline);
        Assert.Equal(initial_contents.PollId, globals.LatestPollId);
        IReadOnlyList<PollQuestion> initial_questions = globals.LatestPollQuestions;
        PollQuestionGroup initial_group = Assert.Single(initial_contents.Questions);
        Assert.Equal(
            [initial_group.Question.QuestionId, initial_group.Children[0].QuestionId],
            initial_questions.Select(question => question.QuestionId));
        IList<PollQuestion> question_list = Assert.IsAssignableFrom<IList<PollQuestion>>(
            initial_questions);
        Assert.True(question_list.IsReadOnly);
        Assert.Throws<NotSupportedException>(() => question_list.Add(initial_group.Question));

        PollOffer? observed_offer = null;
        PollContents? observed_contents = null;
        int errors = 0;
        using IDisposable offer_subscription = globals.OnPollOffer(offer => observed_offer = offer);
        using IDisposable contents_subscription = globals.OnPollContents(
            contents => observed_contents = contents);
        using IDisposable error_subscription = globals.OnPollError(() => errors++);

        fixture.Receive(
            MessageContracts.Polls.Offer,
            new PollOffer(202, "hotel", "updated", "summary"));
        Assert.Equal("updated", observed_offer?.Headline);
        fixture.Receive(MessageContracts.Polls.Error, new PollError());
        Assert.Equal(1, errors);
        Assert.True(globals.LastPollFailed);
        fixture.Receive(MessageContracts.Polls.Contents, initial_contents);
        Assert.Equal(initial_contents.PollId, observed_contents?.PollId);
        Assert.False(globals.LastPollFailed);

        Id outgoing_id = client is ClientType.Unity ? 9_000_000_101 : 101;
        globals.AcceptPoll(outgoing_id);
        globals.RejectPoll(outgoing_id);
        Assert.Equal(outgoing_id, fixture.LastPollStart?.PollId);
        Assert.Equal(outgoing_id, fixture.LastPollReject?.PollId);

        PollResponseInput[] application_responses =
        [
            new PollResponseInput(client is ClientType.Unity ? 9_000_000_201 : 201, ["one"]),
            new PollResponseInput(client is ClientType.Unity ? 9_000_000_202 : 202, [])
        ];
        int answer_count = fixture.PollAnswerSendCount;
        PollDispatchReceipt receipt = fixture.Application
            .Invoke<PollAnswerRequest, PollDispatchReceipt>(
                ApplicationMemberIds.PollsAnswer,
                new PollAnswerRequest(outgoing_id, application_responses));
        int expected_dispatches = client is ClientType.Flash ? 2 : 1;
        Assert.Equal(expected_dispatches, receipt.MessagesDispatched);
        Assert.Equal(answer_count + expected_dispatches, fixture.PollAnswerSendCount);
        PollAnswer dispatched_answer = Assert.IsType<PollAnswer>(fixture.LastPollAnswer);
        Assert.Equal(outgoing_id, dispatched_answer.PollId);
        Assert.Empty(dispatched_answer.Responses[^1].Answers);
        if (client is ClientType.Flash)
        {
            int empty_count = fixture.PollAnswerSendCount;
            Assert.Throws<InvalidDataException>(() => fixture.Application
                .Invoke<PollAnswerRequest, PollDispatchReceipt>(
                    ApplicationMemberIds.PollsAnswer,
                    new PollAnswerRequest(outgoing_id, [])));
            Assert.Equal(empty_count, fixture.PollAnswerSendCount);
        }

        globals.AnswerPoll(201, initial_group.Question.QuestionId, "one");
        globals.AnswerPoll(initial_group.Question, "two");
        int consumer_count = fixture.PollAnswerSendCount;
        var prepared_answer = new PollAnswer(
            outgoing_id,
            [
                new PollResponse(application_responses[0].QuestionId, ["one"]),
                new PollResponse(application_responses[1].QuestionId, ["two"])
            ]);
        if (client is ClientType.Flash)
        {
            Assert.Throws<InvalidDataException>(() => globals.AnswerPoll(prepared_answer));
            Assert.Equal(consumer_count, fixture.PollAnswerSendCount);
        }
        else
        {
            globals.AnswerPoll(prepared_answer);
            Assert.Equal(consumer_count + 1, fixture.PollAnswerSendCount);
            Assert.Equal(2, fixture.LastPollAnswer?.Responses.Count);
        }

        Task<PollContents> request = globals.RequestPollContents(301, test_request_timeout_ms);
        await fixture.WaitForPollStartCount(2).WaitAsync(test_synchronization_timeout);
        fixture.Receive(MessageContracts.Polls.Contents, CreatePollContents(client, 302));
        Assert.False(request.IsCompleted);
        fixture.Receive(MessageContracts.Polls.Contents, CreatePollContents(client, 301));
        PollContents result = await request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(301, result.PollId);

        List<PollChangeKind> changes = [];
        using IDisposable changed = fixture.Application.Subscribe<PollChanged>(
            ApplicationMemberIds.PollsChanged,
            change => changes.Add(change.Kind));
        fixture.Disconnect();
        Assert.Contains(PollChangeKind.Reset, changes);
        PollStateView reset = fixture.Application.Invoke<PollStateRequest, PollStateView>(
            ApplicationMemberIds.PollsState,
            new PollStateRequest());
        Assert.False(reset.Connected);
        Assert.Null(reset.Offer);
        Assert.Null(reset.Contents);
        Assert.False(reset.LastRequestFailed);
        Assert.Null(globals.LatestPollOffer);
        Assert.Null(globals.LatestPoll);
        Assert.Empty(globals.LatestPollQuestions);
    }

