    [Fact]
    public async Task poll_pending_requests_and_unity_empty_answer_are_terminal_and_guarded()
    {
        using (var disconnected = new SurfaceFixture(ClientType.Flash))
        {
            Task<PollStateView> pending = disconnected.Application
                .InvokeAsync<PollContentsGetRequest, PollStateView>(
                    ApplicationMemberIds.PollsContentsGet,
                    new PollContentsGetRequest(401, test_request_timeout_ms))
                .AsTask();
            await disconnected.WaitForPollStartCount(1).WaitAsync(test_synchronization_timeout);
            disconnected.Receive(MessageContracts.Polls.Error, new PollError());
            Assert.False(pending.IsCompleted);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() =>
                pending.WaitAsync(test_synchronization_timeout));
        }

        using (var timeout = new SurfaceFixture(ClientType.Flash))
        {
            await Assert.ThrowsAsync<RequestTimeoutException>(() => timeout.Application
                .InvokeAsync<PollContentsGetRequest, PollStateView>(
                    ApplicationMemberIds.PollsContentsGet,
                    new PollContentsGetRequest(402, 50))
                .AsTask()
                .WaitAsync(test_synchronization_timeout));
        }

        using (var disposed = new SurfaceFixture(ClientType.Flash))
        {
            Task<PollStateView> pending = disposed.Application
                .InvokeAsync<PollContentsGetRequest, PollStateView>(
                    ApplicationMemberIds.PollsContentsGet,
                    new PollContentsGetRequest(403, test_request_timeout_ms))
                .AsTask();
            await disposed.WaitForPollStartCount(1).WaitAsync(test_synchronization_timeout);
            disposed.Application.Dispose();
            await Assert.ThrowsAsync<ObjectDisposedException>(() =>
                pending.WaitAsync(test_synchronization_timeout));
        }

        using (var unity = new SurfaceFixture(ClientType.Unity))
        {
            int start_count = unity.PollStartSendCount;
            await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => unity.Application
                .InvokeAsync<PollContentsGetRequest, PollStateView>(
                    ApplicationMemberIds.PollsContentsGet,
                    new PollContentsGetRequest((long)int.MaxValue + 1, test_request_timeout_ms))
                .AsTask());
            Assert.Equal(start_count, unity.PollStartSendCount);

            int answer_count = unity.PollAnswerSendCount;
            PollDispatchReceipt receipt = unity.Application
                .Invoke<PollAnswerRequest, PollDispatchReceipt>(
                    ApplicationMemberIds.PollsAnswer,
                    new PollAnswerRequest(9_000_000_001, []));
            Assert.Equal(1, receipt.MessagesDispatched);
            Assert.Equal(answer_count + 1, unity.PollAnswerSendCount);
            Assert.Empty(Assert.IsType<PollAnswer>(unity.LastPollAnswer).Responses);
        }
    }

