                [
                    new RelationshipEntry(1, 2, nested_id, "friend", "figure")
                ])),
            client,
            Direction.In);
        Assert.Equal(nested_id, Assert.Single(relationship.Entries).RandomFriendId);

        Assert.Equal(
            id,
            RoundtripPeopleGroup(
                MessageContracts.Badges.SelectedRequest,
                new SelectedBadgesRequest(id),
                client,
                Direction.Out).UserId);
        UserBadges badges = RoundtripPeopleGroup(
            MessageContracts.Badges.Selected,
            new UserBadges(
                id,
                Array.AsReadOnly(
                [
                    new SelectedBadge(1, "ACH", 4, 2, client is ClientType.Flash)
                ])),
            client,
            Direction.In);
        Assert.Equal("ACH", Assert.Single(badges.Badges).Code);

        Assert.Equal(
            id,
            RoundtripPeopleGroup(
                MessageContracts.Groups.Details.Request,
                new GroupDetailsRequest(id, false),
                client,
                Direction.Out).GroupId);
        GroupData details = RoundtripPeopleGroup(
            MessageContracts.Groups.Details.Snapshot,
            CreateGroupDetails(client, id),
            client,
            Direction.In);
        Assert.Equal(id, details.Id);
        Assert.Equal(client is ClientType.Unity ? extension_id : null, details.UnityExtensionId);

        GetGuildMembersRequest members_request = RoundtripPeopleGroup(
            MessageContracts.Groups.Members.Request,
            new GetGuildMembersRequest(id, 0, "", GuildMemberSearchType.All),
            client,
            Direction.Out);
        Assert.Equal(id, members_request.GroupId);
        GuildMembers members = RoundtripPeopleGroup(
            MessageContracts.Groups.Members.Snapshot,
            CreateGuildMembers(client, id, 0, 1, 50, nested_id),
            client,
            Direction.In);
        Assert.Equal(nested_id, Assert.Single(members.Entries).Id);
        Assert.Equal(client is ClientType.Flash ? GuildMemberSearchType.All : null, members.SearchType);

        _ = RoundtripPeopleGroup(
            MessageContracts.Groups.Memberships.Request,
            new GuildMembershipsRequest(),
            client,
            Direction.Out);
        GuildMemberships memberships = RoundtripPeopleGroup(
            MessageContracts.Groups.Memberships.Snapshot,
            new GuildMemberships(
                Array.AsReadOnly(
                [
                    CreateGuildMembership(id)
                ])),
            client,
            Direction.In);
        Assert.Equal(id, Assert.Single(memberships.Items).Id);
    }

