        fixture.Receive(
            MessageContracts.Groups.Details.Snapshot,
            CreateGroupDetails(client, wrong_id));
        Assert.False(group_request.IsCompleted);
        fixture.Receive(
            MessageContracts.Groups.Details.Snapshot,
            CreateGroupDetails(client, id) with { OpenDetails = true });
        Assert.False(group_request.IsCompleted);
        fixture.Receive(
            MessageContracts.Groups.Details.Snapshot,
