            new UserBadges(wrong_id, Array.AsReadOnly(Array.Empty<SelectedBadge>())));
        Assert.False(badges_request.IsCompleted);
        fixture.Receive(
            MessageContracts.Badges.Selected,
            new UserBadges(id, Array.AsReadOnly(Array.Empty<SelectedBadge>())));
