        Assert.Equal(0, sent_members.PageIndex);
        fixture.Receive(
            MessageContracts.Groups.Members.Snapshot,
            CreateGuildMembers(client, id, 1, 2, 1, wrong_id));
        Assert.False(members_request.IsCompleted);
        fixture.Receive(
            MessageContracts.Groups.Members.Snapshot,
