            profile_sends + 1,
            fixture.PeopleGroupRequestCount(MessageKeys.Users.ExtendedProfileRequest));
        Assert.True(Assert.IsType<ExtendedProfileRequest>(fixture.LastProfileRequest).OpenInClient);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task room_reads_are_session_bound_lossless_and_application_only(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        Id room_id = client is ClientType.Unity ? 9_000_000_401 : 401;
        Id owner_id = client is ClientType.Unity ? 9_000_000_402 : 402;
        Id wrong_id = (long)room_id + 1;
        var source = new RoomData
        {
            Id = room_id,
            Name = "Room",
            OwnerId = owner_id,
            OwnerName = "Owner",
            DoorMode = RoomDoorMode.Password,
            UserCount = 17,
            MaxUserCount = 42,
            Description = "Description",
            TradeMode = RoomTradeMode.Everyone,
            Score = 81,
            Ranking = 7,
            Category = 9,
            Tags = Array.AsReadOnly(["one", "two"]),
            OfficialRoomPicRef = "picture",
            HasGroup = true,
            GroupId = owner_id,
            GroupName = "Group",
            GroupBadge = "BADGE",
            HasEvent = true,
            EventName = "Event",
            EventDescription = "Event description",
            EventMinutesRemaining = 31,
            ShowOwner = true,
            AllowPets = true,
            DisplayRoomEntryAd = true
        };

        Task<RoomData> room_request = globals.GetRoomData(room_id, test_request_timeout_ms);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.SnapshotRequest,
            1).WaitAsync(test_synchronization_timeout);
        GetGuestRoomRequest sent_room = Assert.IsType<GetGuestRoomRequest>(
            fixture.LastRoomDataRequest);
        Assert.Equal(room_id, sent_room.RoomId);
        Assert.False(sent_room.EnterRoom);
        Assert.False(sent_room.RoomForward);
        fixture.Receive(
            MessageContracts.Room.Snapshot,
            new GuestRoomResult(false, new RoomData { Id = wrong_id }));
        Assert.False(room_request.IsCompleted);
        fixture.Receive(MessageContracts.Room.Snapshot, new GuestRoomResult(false, source));
        RoomData room = await room_request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(source.Id, room.Id);
        Assert.Equal(source.Name, room.Name);
        Assert.Equal(source.OwnerId, room.OwnerId);
        Assert.Equal(source.OwnerName, room.OwnerName);
        Assert.Equal(source.DoorMode, room.DoorMode);
        Assert.Equal(source.UserCount, room.UserCount);
        Assert.Equal(source.MaxUserCount, room.MaxUserCount);
        Assert.Equal(source.Description, room.Description);
        Assert.Equal(source.TradeMode, room.TradeMode);
        Assert.Equal(source.Score, room.Score);
        Assert.Equal(source.Ranking, room.Ranking);
        Assert.Equal(source.Category, room.Category);
        Assert.Equal(source.Tags, room.Tags);
        Assert.Equal(source.OfficialRoomPicRef, room.OfficialRoomPicRef);
        Assert.Equal(source.HasGroup, room.HasGroup);
        Assert.Equal(source.GroupId, room.GroupId);
        Assert.Equal(source.GroupName, room.GroupName);
        Assert.Equal(source.GroupBadge, room.GroupBadge);
        Assert.Equal(source.HasEvent, room.HasEvent);
        Assert.Equal(source.EventName, room.EventName);
        Assert.Equal(source.EventDescription, room.EventDescription);
        Assert.Equal(source.EventMinutesRemaining, room.EventMinutesRemaining);
        Assert.Equal(source.ShowOwner, room.ShowOwner);
        Assert.Equal(source.AllowPets, room.AllowPets);
        Assert.Equal(source.DisplayRoomEntryAd, room.DisplayRoomEntryAd);
        Assert.True(Assert.IsAssignableFrom<IList<string>>(room.Tags).IsReadOnly);

        var expected_users = new[]
        {
            new IdName(owner_id, "First"),
            new IdName((long)owner_id + 1, "Second")
        };
        Task<IReadOnlyList<IdName>> rights_request = globals.GetRightsFor(room_id, test_request_timeout_ms);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.Authority.ControllersRequest,
            1).WaitAsync(test_synchronization_timeout);
        Assert.Equal(
            room_id,
            Assert.IsType<GetFlatControllersRequest>(fixture.LastRoomRightsRequest).RoomId);
        fixture.Receive(
            MessageContracts.Room.Authority.ControllersSnapshot,
            new RightsList(wrong_id, Array.AsReadOnly(expected_users)));
        Assert.False(rights_request.IsCompleted);
        fixture.Receive(
            MessageContracts.Room.Authority.ControllersSnapshot,
            new RightsList(room_id, Array.AsReadOnly(expected_users)));
        IReadOnlyList<IdName> rights = await rights_request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(expected_users, rights);
        Assert.True(Assert.IsAssignableFrom<IList<IdName>>(rights).IsReadOnly);

        RoomRightsReadResult direct = new(
            client,
            DateTimeOffset.UtcNow,
            1,
            room_id,
            1,
            expected_users);
        expected_users[0] = new IdName(1, "mutated");
        Assert.Equal("First", direct.Users[0].Name);

        ApplicationDescriptor data_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.RoomDataGet);
        ApplicationDescriptor rights_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.RoomRightsList);
        Assert.Equal(typeof(RoomDataReadRequest), data_descriptor.RequestType);
        Assert.Equal(typeof(RoomDataReadResult), data_descriptor.ResultType);
        Assert.Equal(typeof(RoomRightsReadRequest), rights_descriptor.RequestType);
        Assert.Equal(typeof(RoomRightsReadResult), rights_descriptor.ResultType);
        Assert.True(fixture.Application.Describe(ApplicationMemberIds.RoomDataGet).Availability.Available);
        Assert.True(fixture.Application.Describe(ApplicationMemberIds.RoomRightsList).Availability.Available);

        string source_text = File.ReadAllText(Path.Combine(
            FindRepositoryRoot(),
            "src",
            "QX.Scripting",
            "ScriptGlobals.Requests.cs"));
        string room_method = MethodSource(source_text, "public async Task<RoomData> GetRoomData");
        string rights_method = MethodSource(
            source_text,
            "public async Task<IReadOnlyList<IdName>> GetRightsFor");
        Assert.Contains("ApplicationMemberIds.RoomDataGet", room_method, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.RoomRightsList", rights_method, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.Requests", room_method, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.Requests", rights_method, StringComparison.Ordinal);
    }

    [Fact]
    public async Task room_reads_enforce_generation_disconnect_and_caller_cancellation()
    {
        using (var offline = new SurfaceFixture())
        {
            Assert.False(offline.Application.Describe(ApplicationMemberIds.RoomDataGet).Availability.Available);
            Assert.False(offline.Application.Describe(ApplicationMemberIds.RoomRightsList).Availability.Available);
        }

        using (var generation = new SurfaceFixture(ClientType.Flash))
        {
            await Assert.ThrowsAsync<InvalidOperationException>(() => generation.Application
                .InvokeAsync<RoomDataReadRequest, RoomDataReadResult>(
                    ApplicationMemberIds.RoomDataGet,
                    new RoomDataReadRequest(1, test_request_timeout_ms, long.MaxValue))
                .AsTask());
            Assert.Equal(0, generation.PeopleGroupRequestCount(MessageKeys.Room.SnapshotRequest));
        }

        using (var disconnected = new SurfaceFixture(ClientType.Flash))
        {
            Task<RoomRightsReadResult> pending = disconnected.Application
                .InvokeAsync<RoomRightsReadRequest, RoomRightsReadResult>(
                    ApplicationMemberIds.RoomRightsList,
                    new RoomRightsReadRequest(1, test_request_timeout_ms))
                .AsTask();
            await disconnected.WaitForPeopleGroupRequestCount(
                MessageKeys.Room.Authority.ControllersRequest,
                1).WaitAsync(test_synchronization_timeout);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => pending.WaitAsync(
                test_synchronization_timeout));
        }

        using (var cancelled = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<RoomDataReadResult> pending = cancelled.Application
                .InvokeAsync<RoomDataReadRequest, RoomDataReadResult>(
                    ApplicationMemberIds.RoomDataGet,
                    new RoomDataReadRequest(1, test_request_timeout_ms),
                    cancellation.Token)
                .AsTask();
            await cancelled.WaitForPeopleGroupRequestCount(
                MessageKeys.Room.SnapshotRequest,
                1).WaitAsync(test_synchronization_timeout);
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => pending.WaitAsync(test_synchronization_timeout));
            Assert.Equal(cancellation.Token, error.CancellationToken);
        }

        using (var before_dispatch = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            before_dispatch.BeforeRoomReadDispatch = _ => cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => before_dispatch.Application
                    .InvokeAsync<RoomDataReadRequest, RoomDataReadResult>(
                        ApplicationMemberIds.RoomDataGet,
                        new RoomDataReadRequest(1, test_request_timeout_ms),
                        cancellation.Token)
                    .AsTask());
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(
                0,
                before_dispatch.PeopleGroupRequestCount(MessageKeys.Room.SnapshotRequest));
        }

        using (var unity = new SurfaceFixture(ClientType.Unity))
        {
            Id room_id = 9_000_000_501;
            Task<RoomDataReadResult> pending = unity.Application
                .InvokeAsync<RoomDataReadRequest, RoomDataReadResult>(
                    ApplicationMemberIds.RoomDataGet,
                    new RoomDataReadRequest(room_id, test_request_timeout_ms))
                .AsTask();
            await unity.WaitForPeopleGroupRequestCount(
                MessageKeys.Room.SnapshotRequest,
                1).WaitAsync(test_synchronization_timeout);
            unity.Disconnect();
            unity.Connect(new Session("localhost", 0, "next", "next", ClientType.Unity));
            unity.Receive(
                MessageContracts.Room.Snapshot,
                new GuestRoomResult(false, new RoomData { Id = room_id }));
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => pending.WaitAsync(
                test_synchronization_timeout));
        }
    }

