        fixture.RoomActions.DropHandItem();
        fixture.RoomActions.PassHandItem(user_id);

        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.Occupants.Action.ExpressionRequest,
            2).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.HandItem.Drop,
            1).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.HandItem.Pass,
            1).WaitAsync(test_synchronization_timeout);

        string root = FindRepositoryRoot();
        string scripting = File.ReadAllText(Path.Combine(root, "src", "QX.Scripting", "ScriptGlobals.cs"));
        string mimic = File.ReadAllText(Path.Combine(root, "src", "QX.Game", "MimicService.cs"));
        string rules = File.ReadAllText(Path.Combine(root, "src", "QX.Game", "Rules", "SessionRules.cs"));
        string mcp = File.ReadAllText(Path.Combine(root, "src", "QX.Hosting", "Mcp", "McpHost.cs"));
        Assert.DoesNotContain("Game.Requests.SendComposer", scripting, StringComparison.Ordinal);
        Assert.DoesNotContain("_game.Requests.SendComposer", mimic, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.Requests.SendComposer", rules, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEventAsync", mcp, StringComparison.Ordinal);
    }

    [Fact]
    public async Task group_membership_leases_and_legacy_aggregation_are_complete_and_single_send()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        GuildMembership[] expected = Enumerable.Range(1, 501)
            .Select(id => CreateGuildMembership(id))
            .ToArray();

        Task<GroupMembershipsPage> first_request = fixture.Application
            .InvokeAsync<GroupMembershipsGetRequest, GroupMembershipsPage>(
                ApplicationMemberIds.GroupsMembershipsGet,
                new GroupMembershipsGetRequest(0, 500, test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Groups.Memberships.Request,
            1).WaitAsync(test_synchronization_timeout);
        fixture.Receive(
            MessageContracts.Groups.Memberships.Snapshot,
            new GuildMemberships(Array.AsReadOnly(expected)));
        GroupMembershipsPage first = await first_request.WaitAsync(test_synchronization_timeout);
        Assert.Equal(501, first.TotalMemberships);
        Assert.Equal(500, first.Memberships.Count);
        Assert.Equal(500, first.NextOffset);
        Assert.True(first.SnapshotRevision > 0);
        Assert.True(Assert.IsAssignableFrom<IList<GuildMembership>>(first.Memberships).IsReadOnly);

        GroupMembershipsPage second = await fixture.Application
            .InvokeAsync<GroupMembershipsGetRequest, GroupMembershipsPage>(
                ApplicationMemberIds.GroupsMembershipsGet,
                new GroupMembershipsGetRequest(
                    500,
                    500,
                    test_request_timeout_ms,
                    first.SnapshotRevision,
                    first.SessionGeneration));
        Assert.Single(second.Memberships);
        Assert.Null(second.NextOffset);
        GroupMembershipsPage end = await fixture.Application
            .InvokeAsync<GroupMembershipsGetRequest, GroupMembershipsPage>(
                ApplicationMemberIds.GroupsMembershipsGet,
                new GroupMembershipsGetRequest(
                    501,
                    500,
                    test_request_timeout_ms,
                    first.SnapshotRevision,
                    first.SessionGeneration));
        Assert.Empty(end.Memberships);
        Assert.Null(end.NextOffset);
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => fixture.Application
            .InvokeAsync<GroupMembershipsGetRequest, GroupMembershipsPage>(
                ApplicationMemberIds.GroupsMembershipsGet,
                new GroupMembershipsGetRequest(
                    502,
                    500,
                    test_request_timeout_ms,
                    first.SnapshotRevision,
                    first.SessionGeneration))
            .AsTask());
        Assert.Equal(
            1,
            fixture.PeopleGroupRequestCount(MessageKeys.Groups.Memberships.Request));
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<GroupMembershipsGetRequest, GroupMembershipsPage>(
                ApplicationMemberIds.GroupsMembershipsGet,
                new GroupMembershipsGetRequest(
                    500,
                    500,
                    test_request_timeout_ms,
                    first.SnapshotRevision + 1,
                    first.SessionGeneration))
            .AsTask());
        Assert.Equal(
            1,
            fixture.PeopleGroupRequestCount(MessageKeys.Groups.Memberships.Request));

        using ScriptGlobals globals = fixture.CreateGlobals();
        Task<IReadOnlyList<GuildMembership>> legacy_request = globals.GetGuildMemberships(test_request_timeout_ms);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Groups.Memberships.Request,
            2).WaitAsync(test_synchronization_timeout);
        fixture.Receive(
            MessageContracts.Groups.Memberships.Snapshot,
            new GuildMemberships(Array.AsReadOnly(expected)));
        IReadOnlyList<GuildMembership> memberships = await legacy_request.WaitAsync(
            test_synchronization_timeout);
        Assert.Equal(501, memberships.Count);
        Assert.Equal(expected.Select(value => value.Id), memberships.Select(value => value.Id));
        Assert.True(Assert.IsAssignableFrom<IList<GuildMembership>>(memberships).IsReadOnly);
        Assert.Equal(
            2,
            fixture.PeopleGroupRequestCount(MessageKeys.Groups.Memberships.Request));

        using var oversized = new SurfaceFixture(ClientType.Flash);
        Task<GroupMembershipsPage> oversized_request = oversized.Application
            .InvokeAsync<GroupMembershipsGetRequest, GroupMembershipsPage>(
                ApplicationMemberIds.GroupsMembershipsGet,
                new GroupMembershipsGetRequest(0, 500, test_request_timeout_ms))
            .AsTask();
        await oversized.WaitForPeopleGroupRequestCount(
            MessageKeys.Groups.Memberships.Request,
            1).WaitAsync(test_synchronization_timeout);
        oversized.Receive(
            MessageContracts.Groups.Memberships.Snapshot,
            new GuildMemberships(
                Array.AsReadOnly(
                    Enumerable.Repeat(
                        CreateGuildMembership(1),
                        ushort.MaxValue + 1)
                    .ToArray())));
        await Assert.ThrowsAsync<InvalidDataException>(() => oversized_request.WaitAsync(
            test_synchronization_timeout));
        Assert.Equal(
            1,
            oversized.PeopleGroupRequestCount(MessageKeys.Groups.Memberships.Request));
    }

    [Fact]
    public async Task legacy_all_group_members_rejects_metadata_overlap_and_final_count_drift()
    {
        foreach (string scenario in new[] { "success", "metadata", "overlap", "count" })
        {
            using var fixture = new SurfaceFixture(ClientType.Flash);
            using ScriptGlobals globals = fixture.CreateGlobals();
            Task<GuildMemberQuery> request = globals.GetAllGuildMembers(501, timeoutMs: test_request_timeout_ms);
            await fixture.WaitForPeopleGroupRequestCount(
                MessageKeys.Groups.Members.Request,
                1).WaitAsync(test_synchronization_timeout);
            fixture.Receive(
                MessageContracts.Groups.Members.Snapshot,
                CreateGuildMembers(ClientType.Flash, 501, 0, 4, 2, 1, 2));
            await fixture.WaitForPeopleGroupRequestCount(
                MessageKeys.Groups.Members.Request,
                2).WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, fixture.LastGroupMembersRequest?.PageIndex);

            GuildMembers second = scenario switch
            {
                "metadata" => CreateGuildMembers(
                    ClientType.Flash,
                    501,
                    1,
                    4,
                    2,
                    3,
                    4) with
                { IsAllowedToManage = false },
                "overlap" => CreateGuildMembers(ClientType.Flash, 501, 1, 4, 2, 2, 3),
                "count" => CreateGuildMembers(ClientType.Flash, 501, 1, 4, 2, 3),
                _ => CreateGuildMembers(ClientType.Flash, 501, 1, 4, 2, 3, 4)
            };
            fixture.Receive(MessageContracts.Groups.Members.Snapshot, second);

            if (scenario == "success")
            {
                GuildMemberQuery members = await request.WaitAsync(test_synchronization_timeout);
                Assert.Equal([1L, 2L, 3L, 4L], members.Select(member => (long)member.Id));
            }
            else
            {
                await Assert.ThrowsAsync<InvalidDataException>(() => request.WaitAsync(
                    test_synchronization_timeout));
            }
        }
    }

