    [Fact]
    public async Task people_group_operations_are_offline_guarded_and_terminal()
    {
        using (var offline = new SurfaceFixture())
        {
            string[] operations =
            [
                ApplicationMemberIds.PeopleProfileGet,
                ApplicationMemberIds.PeopleRelationshipGet,
                ApplicationMemberIds.PeopleBadgesGet,
                ApplicationMemberIds.PeopleProfileOpen,
                ApplicationMemberIds.GroupsDetailsGet,
                ApplicationMemberIds.GroupsMembersPage,
                ApplicationMemberIds.GroupsMembershipsGet
            ];
            Assert.All(operations, id => Assert.False(offline.Application
                .Describe(id)
                .Availability
                .Available));
            await Assert.ThrowsAsync<ApplicationUnavailableException>(() => offline.Application
                .InvokeAsync<RemoteProfileGetRequest, RemoteProfileResult>(
                    ApplicationMemberIds.PeopleProfileGet,
                    new RemoteProfileGetRequest(1, 50))
                .AsTask());
        }

        using (var generation = new SurfaceFixture(ClientType.Flash))
        {
            int sends = generation.PeopleGroupRequestCount(
                MessageKeys.Users.ExtendedProfileRequest);
            await Assert.ThrowsAsync<InvalidOperationException>(() => generation.Application
                .InvokeAsync<RemoteProfileGetRequest, RemoteProfileResult>(
                    ApplicationMemberIds.PeopleProfileGet,
                    new RemoteProfileGetRequest(1, test_request_timeout_ms, long.MaxValue))
                .AsTask());
            Assert.Equal(
                sends,
                generation.PeopleGroupRequestCount(MessageKeys.Users.ExtendedProfileRequest));
        }

        using (var disconnected = new SurfaceFixture(ClientType.Flash))
        {
            Task<RemoteProfileResult> pending = disconnected.Application
                .InvokeAsync<RemoteProfileGetRequest, RemoteProfileResult>(
                    ApplicationMemberIds.PeopleProfileGet,
                    new RemoteProfileGetRequest(1, test_request_timeout_ms))
                .AsTask();
            await disconnected.WaitForPeopleGroupRequestCount(
                MessageKeys.Users.ExtendedProfileRequest,
                1).WaitAsync(test_synchronization_timeout);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => pending.WaitAsync(
                test_synchronization_timeout));
        }

        using (var timeout = new SurfaceFixture(ClientType.Flash))
        {
            await Assert.ThrowsAsync<RequestTimeoutException>(() => timeout.Application
                .InvokeAsync<RemoteBadgesGetRequest, RemoteBadgesResult>(
                    ApplicationMemberIds.PeopleBadgesGet,
                    new RemoteBadgesGetRequest(1, 50))
                .AsTask()
                .WaitAsync(test_synchronization_timeout));
        }

        using (var disposed = new SurfaceFixture(ClientType.Flash))
        {
            Task<GroupDetailsResult> first = disposed.Application
                .InvokeAsync<GroupDetailsGetRequest, GroupDetailsResult>(
                    ApplicationMemberIds.GroupsDetailsGet,
                    new GroupDetailsGetRequest(1, test_request_timeout_ms))
                .AsTask();
            await disposed.WaitForPeopleGroupRequestCount(
                MessageKeys.Groups.Details.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task<GroupDetailsResult> second = disposed.Application
                .InvokeAsync<GroupDetailsGetRequest, GroupDetailsResult>(
                    ApplicationMemberIds.GroupsDetailsGet,
                    new GroupDetailsGetRequest(2, test_request_timeout_ms))
                .AsTask();
            disposed.Application.Dispose();
            await Assert.ThrowsAsync<ObjectDisposedException>(() => first.WaitAsync(
                test_synchronization_timeout));
            await Assert.ThrowsAsync<ObjectDisposedException>(() => second.WaitAsync(
                test_synchronization_timeout));
            Assert.Equal(
                1,
                disposed.PeopleGroupRequestCount(MessageKeys.Groups.Details.Request));
        }

        using (var cancelled = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<RemoteRelationshipResult> pending = cancelled.Application
                .InvokeAsync<RemoteRelationshipGetRequest, RemoteRelationshipResult>(
                    ApplicationMemberIds.PeopleRelationshipGet,
                    new RemoteRelationshipGetRequest(1, test_request_timeout_ms),
                    cancellation.Token)
                .AsTask();
            await cancelled.WaitForPeopleGroupRequestCount(
                MessageKeys.Users.Relationship.Request,
                1).WaitAsync(test_synchronization_timeout);
            cancellation.Cancel();
            Task disposal = Task.Run(cancelled.Application.Dispose);
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => pending.WaitAsync(
                test_synchronization_timeout));
            await disposal.WaitAsync(test_synchronization_timeout);
        }

        using (var unity = new SurfaceFixture(ClientType.Unity))
        {
            int sends = unity.PeopleGroupRequestCount(MessageKeys.Groups.Members.Request);
            await Assert.ThrowsAsync<NotSupportedException>(() => unity.Application
                .InvokeAsync<GroupMembersPageRequest, GroupMembersPage>(
                    ApplicationMemberIds.GroupsMembersPage,
                    new GroupMembersPageRequest(
                        9_000_000_001,
                        SearchType: GuildMemberSearchType.Administrators))
                .AsTask());
            Assert.Equal(
                sends,
                unity.PeopleGroupRequestCount(MessageKeys.Groups.Members.Request));
        }
    }

