    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public void placement_wire_roundtrips_and_rejects_trailing_payload(ClientType client)
    {
        Id item_id = client is ClientType.Unity ? -9_000_000_001 : 101;
        var wall = new WallLocation(1, 2, 3, 4, WallOrientation.Left);
        using (Packet floor_place = CreatePlacementPacket(
                   client,
                   Direction.Out,
                   client is ClientType.Unity ? "PlaceRoomItem" : "PlaceObject",
                   client is ClientType.Unity ? CreateFloorPlacementSchema("PlaceRoomItem") : null))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.ItemPlace,
                PlaceRoomItemRequest.Floor(item_id, 5, 6, 2),
                floor_place);
        }
        using (Packet wall_place = CreatePlacementPacket(
                   client,
                   Direction.Out,
                   client is ClientType.Unity ? "PlaceWallItem" : "PlaceObject",
                   client is ClientType.Unity ? CreateWallLocationSchema("PlaceWallItem") : null))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.ItemPlace,
                PlaceRoomItemRequest.Wall(item_id, wall),
                wall_place);
        }
        using (Packet floor_move = CreatePlacementPacket(
                   client,
                   Direction.Out,
                   client is ClientType.Unity ? "MoveRoomItem" : "MoveObject"))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.FloorItemMove,
                new MoveFloorItemRequest(item_id, 7, 8, 4),
                floor_move);
        }
        using (Packet wall_move = CreatePlacementPacket(
                   client,
                   Direction.Out,
                   "MoveWallItem",
                   client is ClientType.Unity ? CreateWallLocationSchema("MoveWallItem") : null))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.WallItemMove,
                new MoveWallItemRequest(item_id, wall),
                wall_move);
        }
        using (Packet pickup = CreatePlacementPacket(
                   client,
                   Direction.Out,
                   client is ClientType.Unity ? "PickItemUpFromRoom" : "PickupObject"))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.ItemPickup,
                new PickupRoomItemRequest(2, item_id, client is ClientType.Flash),
                pickup);
        }

        if (client is ClientType.Flash)
        {
            using Packet confirmation = CreatePlacementPacket(
                client,
                Direction.In,
                "ObjectRemoveConfirm");
            AssertPlacementRoundtrip(
                MessageContracts.Room.ItemPickupConfirmation,
                new PickupConfirmation(2, item_id, "title", "body"),
                confirmation);
        }
        else
        {
            Assert.False(MessageContracts.Room.ItemPickupConfirmation.Supports(client));
        }
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public void placement_incoming_ids_preserve_client_width_and_reject_flash_overflow(
        ClientType client)
    {
        Id item_id = client is ClientType.Flash ? int.MinValue : long.MinValue;
        using (Packet floor_remove = CreatePlacementPacket(
                   client,
                   Direction.In,
                   client is ClientType.Flash ? "ObjectRemove" : "ActiveObjectRemove"))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.FloorItem.Removed,
                new FloorItemRemove(item_id, false, -1, 0),
                floor_remove);
        }
        using (Packet wall_remove = CreatePlacementPacket(
                   client,
                   Direction.In,
                   client is ClientType.Flash ? "ItemRemove" : "RemoveItem"))
        {
            AssertPlacementRoundtrip(
                MessageContracts.Room.WallItem.Removed,
                new WallItemRemove(item_id, -1),
                wall_remove);
        }
        using (var wall_item = new Packet(new Header(Direction.In, 92), client))
        {
            wall_item.Writer().Compose(CreateWallItem(item_id, 21, 1, 2, 3, 4));
            wall_item.Position = 0;
            Assert.Equal(item_id, wall_item.Reader().Parse<WallItem>().Id);
            Assert.Equal(0, wall_item.Available);
        }

        if (client is ClientType.Unity)
            return;

        using (var floor_overflow = new Packet(new Header(Direction.In, 93), client))
        {
            floor_overflow.Writer().WriteString("2147483648");
            floor_overflow.Position = 0;
            Assert.Throws<InvalidDataException>(() =>
                MessageContracts.Room.FloorItem.Removed.Parse(floor_overflow.Reader()));
        }
        using (var wall_overflow = new Packet(new Header(Direction.In, 94), client))
        {
            wall_overflow.Writer().WriteString("-2147483649");
            wall_overflow.Position = 0;
            Assert.Throws<InvalidDataException>(() =>
                MessageContracts.Room.WallItem.Removed.Parse(wall_overflow.Reader()));
        }
        using (var wall_item_overflow = new Packet(new Header(Direction.In, 95), client))
        {
            wall_item_overflow.Writer().WriteString("2147483648");
            wall_item_overflow.Position = 0;
            Assert.Throws<InvalidDataException>(() => wall_item_overflow.Reader().Parse<WallItem>());
        }
        using (var compose_overflow = new Packet(new Header(Direction.In, 96), client))
        {
            Assert.Throws<InvalidDataException>(() => compose_overflow.Writer().Compose(
                CreateWallItem((long)int.MaxValue + 1, 21, 1, 2, 3, 4)));
        }
    }

