        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorPlaceRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorPlace,
                new RoomPlacementFloorPlaceRequest(
                    -7,
                    new RoomPlacementFloorPosition(3, 4, 2),
                    ExpectedInventoryRevision: inventory.Furni.SnapshotRevision + 1))
            .AsTask());
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorPlaceRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorPlace,
                new RoomPlacementFloorPlaceRequest(
                    -7,
                    new RoomPlacementFloorPosition(3, 4, 2),
                    ExpectedSessionGeneration: inventory.SessionGeneration + 1))
            .AsTask());

        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorPlaceRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorPlace,
                new RoomPlacementFloorPlaceRequest(
                    -7,
                    new RoomPlacementFloorPosition(3, 4, 2),
                    ExpectedRoomItemId: -100))
            .AsTask());
        Assert.Equal(0, fixture.PlacementSendCount);

        RoomPlacementDispatchReceipt receipt = await fixture.Application
            .InvokeAsync<RoomPlacementFloorPlaceRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorPlace,
                new RoomPlacementFloorPlaceRequest(
                    -7,
                    new RoomPlacementFloorPosition(3, 4, 2),
                    ExpectedRoomItemId: -99,
                    ExpectedInventoryRevision: inventory.Furni.SnapshotRevision,
                    ExpectedSessionGeneration: inventory.SessionGeneration,
                    ExpectedRoomGeneration: fixture.RoomGeneration));
        Assert.Equal(RoomPlacementOperationKind.PlaceFloor, receipt.Operation);
        Assert.Equal((Id)(-7), receipt.InventoryItemId);
        Assert.Equal((Id)(-99), receipt.RoomItemId);
        Assert.Equal(1, fixture.PlacementSendCount);
        Assert.Equal((Id)(-7), fixture.LastPlacement?.ItemId);

        fixture.AddFloorItem(CreateFloorItem(-99, 123, 3, 4, 2));
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorMoveRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorMove,
                new RoomPlacementFloorMoveRequest(
                    -99,
                    new RoomPlacementFloorPosition(5, 5, 4),
                    ExpectedSource: new RoomPlacementFloorPosition(9, 9, 0)))
            .AsTask());
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<RoomPlacementPickupRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementPickup,
                new RoomPlacementPickupRequest(-99, RoomPlacementItemKind.Wall))
            .AsTask());
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorMoveRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorMove,
                new RoomPlacementFloorMoveRequest(
                    -99,
                    new RoomPlacementFloorPosition(5, 5, 4),
                    ExpectedRoomGeneration: fixture.RoomGeneration + 1))
            .AsTask());
        Assert.Equal(1, fixture.PlacementSendCount);

        fixture.Receive(
            MessageContracts.Inventory.Furni.Snapshot,
            new FurniList(2, 0, [inventory_item]));
        InventoryStateView stale = await fixture.Application
            .InvokeAsync<InventoryStateRequest, InventoryStateView>(
                ApplicationMemberIds.InventoryState,
                new InventoryStateRequest());
        Assert.False(stale.Furni.Loaded);
        Assert.True(stale.Furni.Stale);
        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorPlaceRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorPlace,
                new RoomPlacementFloorPlaceRequest(-7, new RoomPlacementFloorPosition(3, 4, 2)))
            .AsTask());
        Assert.Equal(1, fixture.PlacementSendCount);
    }

    [Fact]
    public async Task placement_availability_is_variant_specific_and_fails_closed()
    {
        using var fixture = new SurfaceFixture(
            ClientType.Unity,
            invalid_floor_place_schema: true,
            unity_inventory_extended_metadata: false);
        fixture.EnterRoom(42);
        fixture.LoadFurni(new InventoryItem
        {
            ItemId = -7,
            Id = -99,
            Type = ItemType.Floor,
            Kind = 123,
            Category = 1,
            Data = new EmptyItemData(),
            SlotId = "slot"
        });

        ApplicationMemberDescription floor = fixture.Application.Describe(
            ApplicationMemberIds.RoomPlacementFloorPlace);
        ApplicationMessageAvailability floor_route = Assert.Single(floor.Availability.ActiveMessages);
        Assert.False(floor.Availability.Available);
        Assert.False(floor_route.Resolved);
        Assert.Empty(floor_route.Headers);
        Assert.Equal("unityFloorItemPlacementSchema", floor_route.WireCapability);
        Assert.False(floor_route.WireAvailable);
        ApplicationMemberDescription wall = fixture.Application.Describe(
            ApplicationMemberIds.RoomPlacementWallPlace);
        ApplicationMessageAvailability wall_route = Assert.Single(wall.Availability.ActiveMessages);
        Assert.True(wall.Availability.Available);
        Assert.True(wall_route.Resolved);
        Assert.Equal([34], wall_route.Headers);
        Assert.Equal("unityWallItemPlacementSchema", wall_route.WireCapability);
        Assert.True(wall_route.WireAvailable);

        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => fixture.Application
            .InvokeAsync<RoomPlacementFloorPlaceRequest, RoomPlacementDispatchReceipt>(
                ApplicationMemberIds.RoomPlacementFloorPlace,
                new RoomPlacementFloorPlaceRequest(-7, new RoomPlacementFloorPosition(3, 4, 2)))
            .AsTask());
        Assert.Equal(0, fixture.PlacementSendCount);

        using var flash = new SurfaceFixture(ClientType.Flash);
        foreach (string member_id in new[]
                 {
                     ApplicationMemberIds.RoomPlacementFloorPlace,
                     ApplicationMemberIds.RoomPlacementWallPlace
                 })
        {
            ApplicationMessageAvailability route = Assert.Single(
                flash.Application.Describe(member_id).Availability.ActiveMessages);
            Assert.True(route.Resolved);
            Assert.Equal([33], route.Headers);
            Assert.Null(route.WireCapability);
            Assert.Null(route.WireAvailable);
        }
    }

