    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task room_furni_batches_route_post_its_by_special_type(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        await fixture.LoadRoomGameDataAsync(RoomFurniData);
        fixture.EnterRoom(42);
        fixture.RoomActions.OwnUserId = () => 1;
        Id post_it_id = client is ClientType.Unity ? 9_000_000_021 : 201;
        Id normal_id = client is ClientType.Unity ? 9_000_000_022 : 202;
        Id foreign_post_it_id = client is ClientType.Unity ? 9_000_000_023 : 203;
        WallItem post_it = CreateWallItem(post_it_id, 21, 0, 0, 0, 0);
        WallItem normal = CreateWallItem(normal_id, 22, 1, 0, 0, 0);
        WallItem foreign_post_it = CreateWallItem(foreign_post_it_id, 21, 2, 0, 0, 0);
        foreign_post_it.OwnerId = 2;
        fixture.AddWallItem(post_it);
        fixture.AddWallItem(normal);
        fixture.AddWallItem(foreign_post_it);
        fixture.RoomActions.ToggleInterval = TimeSpan.Zero;
        fixture.RoomActions.TogglePostItInterval = TimeSpan.Zero;
        fixture.RoomActions.PickupInterval = TimeSpan.Zero;
        fixture.RoomActions.PickupPostItInterval = TimeSpan.Zero;

        await fixture.RoomActions.ToggleAsync([normal]);
        Assert.Equal(normal_id, fixture.LastWallItemUseRequest?.ItemId);
        Assert.Equal(1, fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.Use));
        Assert.Equal(0, fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.StickyDataRequest));
        await fixture.RoomActions.ToggleAsync([post_it]);
        Assert.Equal(post_it_id, fixture.LastStickyRequest?.ItemId);
        Assert.Equal(1, fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.Use));
        Assert.Equal(1, fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.StickyDataRequest));

        int placement_count = fixture.PlacementSendCount;
        await fixture.RoomActions.PickupAsync([normal]);
        Assert.Equal(placement_count + 1, fixture.PlacementSendCount);
        await fixture.RoomActions.PickupAsync([post_it]);
        Assert.Equal(placement_count + 1, fixture.PlacementSendCount);
        Assert.Equal(post_it_id, fixture.LastWallItemRemoveRequest?.ItemId);
        Assert.Equal(1, fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.Remove));

        int remove_count = fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.Remove);
        InvalidOperationException error = await Assert.ThrowsAsync<InvalidOperationException>(
            () => fixture.RoomActions.EjectAsync([foreign_post_it]));
        Assert.Contains("cannot be ejected", error.Message, StringComparison.Ordinal);
        Assert.Equal(
            remove_count,
            fixture.PeopleGroupRequestCount(MessageKeys.Room.WallItem.Remove));
    }

