    [Fact]
    public void placement_events_are_bounded_and_include_reset_and_flash_confirmation()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        var changes = new List<RoomPlacementChanged>();
        var confirmations = new List<RoomPlacementPickupConfirmation>();
        Assert.Equal(
            [
                new ApplicationStateEffect(
                    ApplicationStateKey.RoomActive,
                    ApplicationStateEffectKind.Changes),
                new ApplicationStateEffect(
                    ApplicationStateKey.RoomActive,
                    ApplicationStateEffectKind.Invalidates)
            ],
            fixture.Application
                .Describe(ApplicationMemberIds.RoomPlacementChanged)
                .Descriptor
                .StateEffects);
        Assert.Empty(fixture.Application
            .Describe(ApplicationMemberIds.RoomPlacementPickupConfirmation)
            .Descriptor
            .StateEffects);
        using IDisposable changed = fixture.Application.Subscribe<RoomPlacementChanged>(
            ApplicationMemberIds.RoomPlacementChanged,
            changes.Add);
        using IDisposable confirmed = fixture.Application.Subscribe<RoomPlacementPickupConfirmation>(
            ApplicationMemberIds.RoomPlacementPickupConfirmation,
            confirmations.Add);
        fixture.EnterRoom(42);

        fixture.AddFloorItem(CreateFloorItem(101, 11, 1, 1, 0));
        fixture.UpdateFloorItem(CreateFloorItem(101, 11, 2, 2, 2));
        fixture.RemoveFloorItem(101);
        fixture.AddWallItem(CreateWallItem(201, 21, 1, 2, 3, 4));
        fixture.UpdateWallItem(CreateWallItem(201, 21, 2, 3, 4, 5));
        fixture.RemoveWallItem(201);
        fixture.Receive(
            MessageContracts.Room.ItemPickupConfirmation,
            new PickupConfirmation(2, 101, "title", "body"));
        fixture.Disconnect();

        Assert.Equal(
            [
                RoomPlacementChangeKind.FloorAdded,
                RoomPlacementChangeKind.FloorUpdated,
                RoomPlacementChangeKind.FloorRemoved,
                RoomPlacementChangeKind.WallAdded,
                RoomPlacementChangeKind.WallUpdated,
                RoomPlacementChangeKind.WallRemoved,
                RoomPlacementChangeKind.RoomReset
            ],
            changes.Select(change => change.Kind).ToArray());
        Assert.Null(changes[0].Previous);
        Assert.NotNull(changes[0].Current);
        Assert.NotNull(changes[1].Previous);
        Assert.NotNull(changes[1].Current);
        Assert.NotNull(changes[2].Previous);
        Assert.Null(changes[2].Current);
        Assert.Null(changes[^1].Previous);
        Assert.Null(changes[^1].Current);
        long active_session_generation = changes[0].SessionGeneration;
        Assert.All(
            changes.Take(6),
            change => Assert.Equal(active_session_generation, change.SessionGeneration));
        Assert.Equal(active_session_generation + 1, changes[^1].SessionGeneration);
        RoomPlacementPickupConfirmation confirmation = Assert.Single(confirmations);
        Assert.Equal(active_session_generation, confirmation.SessionGeneration);
        Assert.Equal(2, confirmation.Category);
        Assert.Equal((Id)101, confirmation.RoomItemId);
        Assert.Equal("title", confirmation.Title);
        Assert.Equal("body", confirmation.Body);
    }

