    [Fact]
    public void room_settings_wire_shapes_are_exact_and_unity_save_fails_closed()
    {
        RoomSettings flash_value = CreateRoomSettings(42);
        using (var flash = new Packet(new Header(Direction.In, 1), ClientType.Flash))
        {
            MessageContracts.Room.Settings.Snapshot.Compose(flash_value, flash.Writer());
            Assert.Equal([0, 0, 0, 42], flash.Buffer.Span[..4].ToArray());
            flash.Position = 0;
            RoomSettings parsed = MessageContracts.Room.Settings.Snapshot.Parse(flash.Reader());
            Assert.Equal(flash_value.Tags, parsed.Tags);
            Assert.Equal(flash_value.TradeMode, parsed.TradeMode);
            Assert.Equal(0, flash.Available);
        }

        for (int visitor_fields = 0; visitor_fields <= 4; visitor_fields++)
        {
            using Packet legacy = CreateUnityRoomSettingsPacket(
                UnityRoomSettingsWireLayout.Legacy,
                visitor_fields,
                0);
            byte[] encoded = legacy.Buffer.Span.ToArray();
            legacy.Position = 0;
            RoomSettings parsed = MessageContracts.Room.Settings.Snapshot.Parse(legacy.Reader());
            Assert.Equal(visitor_fields >= 1, parsed.IsHabboXDemoRoom);
            Assert.Equal(visitor_fields >= 2 ? 33 : 0, parsed.MaximumVisitors);
            Assert.Equal(visitor_fields >= 3 ? 44 : 0, parsed.MaximumVisitorsLimit);
            Assert.Equal(visitor_fields >= 4 ? 11 : 0, parsed.MaximumVisitorsLowerLimit);
            using var roundtrip = new Packet(new Header(Direction.In, 1), ClientType.Unity)
            {
                Context = legacy.Context
            };
            MessageContracts.Room.Settings.Snapshot.Compose(parsed, roundtrip.Writer());
            Assert.Equal(encoded, roundtrip.Buffer.Span.ToArray());
        }

        using (Packet modern = CreateUnityRoomSettingsPacket(
                   UnityRoomSettingsWireLayout.Modern,
                   4,
                   3))
        {
            modern.Position = 0;
            RoomSettings parsed = MessageContracts.Room.Settings.Snapshot.Parse(modern.Reader());
            Assert.Equal(RoomTradeMode.Everyone, parsed.TradeMode);
            Assert.True(parsed.AllowFoodConsume);
            Assert.False(parsed.AllowWalkThrough);
        }
        using (Packet truncated = CreateUnityRoomSettingsPacket(
                   UnityRoomSettingsWireLayout.Modern,
                   4,
                   2))
        {
            truncated.Position = 0;
            Assert.Throws<InvalidDataException>(() =>
                MessageContracts.Room.Settings.Snapshot.Parse(truncated.Reader()));
        }

        SaveRoomSettingsRequest save_value = CreateRoomSettingsSave();
        foreach (bool modern in new[] { false, true })
        {
            (MessageManager messages, Header header) = CreateUnityRoomSettingsSaveMessages(
                [CreateUnityRoomSettingsSaveSchema(modern)]);
            using var packet = new Packet(header, ClientType.Unity)
            {
                Context = new ParserContext(messages)
            };
            SaveRoomSettingsRequest selected = save_value with
            {
                TradeMode = modern ? RoomTradeMode.Everyone : RoomTradeMode.Disabled,
                AllowFoodConsume = modern
            };
            MessageContracts.Room.Settings.Save.Compose(selected, packet.Writer());
            Assert.Equal(modern ? 90 : 78, packet.Buffer.Length);
            packet.Position = 0;
            SaveRoomSettingsRequest parsed = MessageContracts.Room.Settings.Save.Parse(packet.Reader());
            Assert.Equal(selected.TradeMode, parsed.TradeMode);
            Assert.Equal(selected.NftGroupIds, parsed.NftGroupIds);
        }

        foreach (IReadOnlyList<OutgoingMessageSchema> schemas in new IReadOnlyList<OutgoingMessageSchema>[]
                 {
                     [],
                     [CreateUnityRoomSettingsSaveSchema(false, invalid_array: true)]
                 })
        {
            (MessageManager messages, Header header) = CreateUnityRoomSettingsSaveMessages(schemas);
            using var packet = new Packet(header, ClientType.Unity)
            {
                Context = new ParserContext(messages)
            };
            Assert.Throws<NotSupportedException>(() =>
                MessageContracts.Room.Settings.Save.Compose(save_value, packet.Writer()));
        }
    }

    [Fact]
    public async Task room_settings_get_and_save_correlate_terminal_messages()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        Task<RoomSettingsStateView> loaded = fixture.GetRoomSettings(42, test_request_timeout_ms);
        await fixture.WaitForRoomSettingsRequestCount(1).WaitAsync(test_synchronization_timeout);
        fixture.Receive(MessageContracts.Room.Settings.Snapshot, CreateRoomSettings(42));
        RoomSettingsStateView state = await loaded.WaitAsync(test_synchronization_timeout);
        Assert.True(state.Loaded);

        Task<RoomSettingsStateView> rejected_get = fixture.GetRoomSettings(43, test_request_timeout_ms);
        await fixture.WaitForRoomSettingsRequestCount(2).WaitAsync(test_synchronization_timeout);
        fixture.Receive(MessageContracts.Room.Settings.RequestFailed, new RoomSettingsError(43, 17));
        RoomSettingsRejectedException get_error = await Assert.ThrowsAsync<RoomSettingsRejectedException>(
            () => rejected_get.WaitAsync(test_synchronization_timeout));
        Assert.Equal(RoomSettingsOperationKind.Get, get_error.Operation);
        Assert.Equal(17, get_error.ErrorCode);

        fixture.AfterRoomSettingsDispatch = _ =>
        {
            if (fixture.RoomSettingsRequestCount == 4)
                fixture.Receive(MessageContracts.Room.Settings.Snapshot, CreateRoomSettings(44));
        };
        Task<RoomSettingsStateView> retried = fixture.GetRoomSettings(44, 1600);
        await fixture.WaitForRoomSettingsRequestCount(3).WaitAsync(test_synchronization_timeout);
        fixture.Receive(MessageContracts.Room.Settings.Snapshot, CreateRoomSettings(45));
        Assert.Equal(44, (await retried.WaitAsync(test_synchronization_timeout)).RoomId);
        fixture.AfterRoomSettingsDispatch = null;

        RoomSettingsValues values = state.Settings! with { RoomId = 51, Name = "room-51" };
        Task<RoomSettingsSaveReceipt> saved = fixture.SaveRoomSettings(values, "secret", test_request_timeout_ms);
        await fixture.WaitForRoomSettingsSaveCount(1).WaitAsync(test_synchronization_timeout);
        fixture.Receive(MessageContracts.Room.Settings.SaveSucceeded, new RoomSettingsSaved(51));
        Assert.Equal(51, (await saved.WaitAsync(test_synchronization_timeout)).RoomId);

        Task<RoomSettingsSaveReceipt> rejected_save = fixture.SaveRoomSettings(
            values with { RoomId = 52 },
            "",
            test_request_timeout_ms);
        await fixture.WaitForRoomSettingsSaveCount(2).WaitAsync(test_synchronization_timeout);
        fixture.Receive(
            MessageContracts.Room.Settings.SaveFailed,
            new RoomSettingsSaveError(52, 23, "denied"));
        RoomSettingsRejectedException save_error = await Assert.ThrowsAsync<RoomSettingsRejectedException>(
            () => rejected_save.WaitAsync(test_synchronization_timeout));
        Assert.Equal(RoomSettingsOperationKind.Save, save_error.Operation);
        Assert.Equal(23, save_error.ErrorCode);
        Assert.Equal(4, fixture.RoomSettingsRequestCount);
        Assert.Equal(2, fixture.RoomSettingsSaveCount);
    }

    [Fact]
    public async Task room_settings_terminal_received_during_dispatch_wins_at_timeout_boundary()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.AfterRoomSettingsDispatch = key =>
        {
            if (key == MessageKeys.Room.Settings.Request)
                fixture.Receive(MessageContracts.Room.Settings.Snapshot, CreateRoomSettings(61));
            else if (key == MessageKeys.Room.Settings.Save)
                fixture.Receive(MessageContracts.Room.Settings.SaveSucceeded, new RoomSettingsSaved(61));
            Thread.Sleep(150);
        };

        RoomSettingsStateView loaded = await fixture.GetRoomSettings(61, 100);
