        Assert.Equal(1, fixture.RoomSettingsRequestCount);
        Assert.Equal(1, fixture.RoomSettingsSaveCount);
    }

    [Fact]
    public async Task room_settings_state_bounds_and_stale_guards_are_fail_closed()
    {
        using (var offline = new SurfaceFixture())
        {
            RoomSettingsStateView state = await offline.ReadRoomSettings(1);
            Assert.False(state.Connected);
            Assert.False(state.Loaded);
        }

        using var fixture = new SurfaceFixture(ClientType.Flash);
        var changes = new List<RoomSettingsChanged>();
        using IDisposable subscription = fixture.Application.Subscribe<RoomSettingsChanged>(
            ApplicationMemberIds.RoomSettingsChanged,
            changes.Add);
        for (int room_id = 1; room_id <= 65; room_id++)
            fixture.Receive(MessageContracts.Room.Settings.Snapshot, CreateRoomSettings(room_id));
        Assert.False((await fixture.ReadRoomSettings(1)).Loaded);
        RoomSettingsStateView retained = await fixture.ReadRoomSettings(65);
        Assert.True(retained.Loaded);

        fixture.Receive(
            MessageContracts.Room.Settings.Snapshot,
            CreateRoomSettings(66) with { Tags = Enumerable.Repeat("tag", 501).ToArray() });
        Assert.False((await fixture.ReadRoomSettings(66)).Loaded);
        Assert.Equal(66, changes.Count);
        Assert.DoesNotContain(
            typeof(RoomSettingsChanged).GetProperties(),
            property => property.PropertyType != typeof(string) &&
                typeof(System.Collections.IEnumerable).IsAssignableFrom(property.PropertyType));

        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.GetRoomSettings(
            65,
            1000,
            retained.SessionGeneration + 1));
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.GetRoomSettings(
            65,
            1000,
            retained.SessionGeneration,
            1));
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.SaveRoomSettings(
            retained.Settings!,
            "",
            1000,
            expected_operation_revision: retained.OperationRevision + 1));
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.SaveRoomSettings(
            retained.Settings!,
            "",
            1000,
            expected_snapshot_revision: retained.SnapshotRevision + 1));
        Assert.Equal(0, fixture.RoomSettingsRequestCount);
        Assert.Equal(0, fixture.RoomSettingsSaveCount);
    }

    [Fact]
    public async Task room_settings_timeout_quarantines_its_lane_without_blocking_another_room()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        Task<RoomSettingsStateView> timed_out = fixture.GetRoomSettings(71, 600);
        await fixture.WaitForRoomSettingsRequestCount(2).WaitAsync(test_synchronization_timeout);
