            timed_out.WaitAsync(test_synchronization_timeout));

        Task<RoomSettingsStateView> quarantined = fixture.GetRoomSettings(71, 250);
        Task<RoomSettingsStateView> parallel = fixture.GetRoomSettings(72, 1500);
        await fixture.WaitForRoomSettingsRequestCount(3).WaitAsync(test_synchronization_timeout);
        fixture.Receive(MessageContracts.Room.Settings.Snapshot, CreateRoomSettings(72));
        RoomSettingsStateView parallel_state = await parallel.WaitAsync(test_synchronization_timeout);
        await Assert.ThrowsAsync<RequestTimeoutException>(() =>
            quarantined.WaitAsync(test_synchronization_timeout));

        Assert.Equal(72, parallel_state.RoomId);
        Assert.Equal(3, fixture.RoomSettingsRequestCount);
    }

