            Convert.FromHexString("0001000000000000019000057175657279000473686F7000106E6176696761746F722E736561726368"),
            unity_saved.Buffer.Span.ToArray());
        unity_saved.Position = 0;
        Assert.Equal(link, Assert.Single(unity_saved.Reader().Parse<NavigatorSavedSearches>().Searches));
        Assert.Equal(0, unity_saved.Available);
