    [Fact]
    public void unity_private_messages_require_build_bound_wire_evidence()
    {
        using var fixture = new SurfaceFixture(ClientType.Unity);

        ApplicationMemberDescription send = fixture.Application.Describe(
            ApplicationMemberIds.FriendMessageSend);
        ApplicationMessageAvailability outgoing = Assert.Single(send.Availability.ActiveMessages);
        Assert.True(outgoing.Supported);
        Assert.NotEmpty(outgoing.Headers);
        Assert.True(outgoing.Resolved);
        Assert.Equal("unity_private_message_schema", outgoing.WireCapability);
        Assert.False(outgoing.WireAvailable);
        Assert.False(string.IsNullOrWhiteSpace(outgoing.WireReason));
        Assert.False(send.Availability.Available);

        ApplicationMemberDescription received = fixture.Application.Describe(
            ApplicationMemberIds.FriendMessageReceived);
        ApplicationMessageAvailability incoming = Assert.Single(received.Availability.ActiveMessages);
        Assert.True(incoming.Supported);
        Assert.NotEmpty(incoming.Headers);
        Assert.True(incoming.Resolved);
        Assert.Equal("unity_console_message_layout", incoming.WireCapability);
        Assert.False(incoming.WireAvailable);
        Assert.False(string.IsNullOrWhiteSpace(incoming.WireReason));
        Assert.False(received.Availability.Available);

        using JsonDocument availability = JsonDocument.Parse(ApplicationJson.Serialize(
            ApplicationJson.DescribeAvailability(send.Availability),
            indented: false));
        JsonElement wire = Assert.Single(
            availability.RootElement
                .GetProperty("unavailable_wire_capabilities")
                .EnumerateArray()
                .ToArray());
        Assert.Equal(MessageKeys.Friends.PrivateMessageSend.Value, wire.GetProperty("key").GetString());
        Assert.Equal("unity_private_message_schema", wire.GetProperty("capability").GetString());
        Assert.False(string.IsNullOrWhiteSpace(wire.GetProperty("reason").GetString()));
    }

    [Fact]
    public async Task history_is_available_offline_and_validates_paging_bounds()
    {
        using var fixture = new SurfaceFixture();

        Assert.True(fixture.Application
            .Describe(ApplicationMemberIds.RoomChatHistory)
            .Availability
            .Available);
        object? value = await fixture.Application.InvokeAsync(
            ApplicationMemberIds.RoomChatHistory,
            new RoomChatHistoryRequest());
        RoomChatHistoryPage page = Assert.IsType<RoomChatHistoryPage>(value);
        Assert.Empty(page.Entries);
        Assert.Equal(0, page.After);
        Assert.Equal(0, page.Next);
        Assert.Equal(0, page.Oldest);
        Assert.Equal(0, page.Latest);
        Assert.False(page.HasMore);
        Assert.False(page.Gap);

        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => fixture.Application
            .InvokeAsync(
                ApplicationMemberIds.RoomChatHistory,
                new RoomChatHistoryRequest(-1, 1))
            .AsTask());
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => fixture.Application
            .InvokeAsync(
                ApplicationMemberIds.RoomChatHistory,
                new RoomChatHistoryRequest(0, 0))
            .AsTask());
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => fixture.Application
            .InvokeAsync(
                ApplicationMemberIds.RoomChatHistory,
                new RoomChatHistoryRequest(0, 501))
            .AsTask());

        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => fixture.Application
            .InvokeAsync(
                ApplicationMemberIds.RoomChatHistory,
                new RoomChatHistoryRequest(),
                cancelled.Token)
            .AsTask());
        Assert.ThrowsAny<OperationCanceledException>(() => fixture.Application
            .Invoke<RoomChatHistoryRequest, RoomChatHistoryPage>(
                ApplicationMemberIds.RoomChatHistory,
                new RoomChatHistoryRequest(),
                cancelled.Token));
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task room_chat_talk_and_shout_use_application_dispatch(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();

        Assert.False(fixture.Application.Describe(ApplicationMemberIds.RoomChatTalk)
            .Availability.Available);
        Assert.False(fixture.Application.Describe(ApplicationMemberIds.RoomChatShout)
            .Availability.Available);

        fixture.EnterRoom(42);
        globals.Talk("hello", 3);
        globals.Shout("loud", 4);

        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.Chat.TalkSend,
            1).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.Chat.ShoutSend,
            1).WaitAsync(test_synchronization_timeout);
        TalkRequest talk = Assert.IsType<TalkRequest>(fixture.LastTalkRequest);
        ShoutRequest shout = Assert.IsType<ShoutRequest>(fixture.LastShoutRequest);
        Assert.Equal(("hello", 3, -1), (talk.Text, talk.BubbleStyle, talk.TrackingId));
        Assert.Equal(("loud", 4), (shout.Text, shout.BubbleStyle));
        Assert.True(fixture.Game.Mimic.Say("copied", ChatType.Talk, 5));
        Assert.True(fixture.Game.Mimic.Say("copied loudly", ChatType.Shout, 6));
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.Chat.TalkSend,
            2).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForPeopleGroupRequestCount(
            MessageKeys.Room.Chat.ShoutSend,
            2).WaitAsync(test_synchronization_timeout);
        talk = Assert.IsType<TalkRequest>(fixture.LastTalkRequest);
        shout = Assert.IsType<ShoutRequest>(fixture.LastShoutRequest);
        Assert.Equal(("copied", 5, -1), (talk.Text, talk.BubbleStyle, talk.TrackingId));
        Assert.Equal(("copied loudly", 6), (shout.Text, shout.BubbleStyle));
        Assert.True(fixture.Application.Describe(ApplicationMemberIds.RoomChatTalk)
            .Availability.Available);
        Assert.True(fixture.Application.Describe(ApplicationMemberIds.RoomChatShout)
            .Availability.Available);

        string source = File.ReadAllText(Path.Combine(
            FindRepositoryRoot(),
            "src",
            "QX.Scripting",
            "ScriptGlobals.cs"));
        Assert.Contains("ApplicationMemberIds.RoomChatTalk", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.RoomChatShout", source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.Talk(", source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.Shout(", source, StringComparison.Ordinal);
        string mimic = File.ReadAllText(Path.Combine(
            FindRepositoryRoot(),
            "src",
            "QX.Game",
            "MimicService.cs"));
        Assert.DoesNotContain("_game.RoomActions.Talk(", mimic, StringComparison.Ordinal);
        Assert.DoesNotContain("_game.RoomActions.Shout(", mimic, StringComparison.Ordinal);
    }

