        Assert.DoesNotContain("Game.RoomActions.CancelTyping(", actions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.SelectEffect(", actions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("_game.RoomActions.", mimic_source, StringComparison.Ordinal);
        Assert.DoesNotContain("RoomActions.LookTo(", rules_source, StringComparison.Ordinal);
        Assert.DoesNotContain("RoomActions.Expression(", rules_source, StringComparison.Ordinal);
    }

