    public async Task room_item_interactions_use_application_dispatch(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        using ScriptGlobals globals = fixture.CreateGlobals();
        (string Id, Type Request)[] descriptors =
        [
            (ApplicationMemberIds.RoomItemFloorUse, typeof(RoomFloorItemUseRequest)),
            (ApplicationMemberIds.RoomItemWallUse, typeof(RoomWallItemUseRequest)),
            (ApplicationMemberIds.RoomItemOneWayDoorEnter, typeof(RoomOneWayDoorEnterRequest)),
            (ApplicationMemberIds.RoomItemDiceThrow, typeof(RoomDiceRequest)),
            (ApplicationMemberIds.RoomItemDiceClear, typeof(RoomDiceRequest)),
            (ApplicationMemberIds.RoomItemWallRemove, typeof(RoomWallItemRemoveRequest)),
            (ApplicationMemberIds.RoomItemStickySet, typeof(RoomStickySetRequest)),
            (ApplicationMemberIds.RoomItemPostItPlace, typeof(RoomPostItPlaceRequest)),
            (ApplicationMemberIds.RoomItemPostItAdd, typeof(RoomPostItAddRequest))
        ];
        foreach ((string id, Type request) in descriptors)
        {
            ApplicationMemberDescription member = fixture.Application.Describe(id);
            Assert.Equal(ApplicationMemberKind.Operation, member.Descriptor.Kind);
            Assert.Equal(request, member.Descriptor.RequestType);
            Assert.Equal(typeof(RoomItemDispatchResult), member.Descriptor.ResultType);
            Assert.Single(member.Descriptor.Messages);
            Assert.True(member.Availability.Available);
        }

        fixture.EnterRoom(77);
        globals.UseFloorItem(1001, 2);
        int wall_state = client is ClientType.Flash ? 3 : 0;
        globals.UseWallItem(1002, wall_state);
        globals.EnterOneWayDoor(1003);
        globals.ThrowDice(1004);
        globals.DiceOff(1005);
        globals.RemoveItem(1006);
        globals.SetStickyData(1007, "FFFF33", "note");
        globals.PlacePostIt(1008, ":w=2,3 l=5,20 l");
        globals.AddPostIt(1009, ":w=3,4 l=6,21 r", "FF00FF", "spam");

        MessageKey[] keys =
        [
            MessageKeys.Room.FloorItem.Use,
            MessageKeys.Room.WallItem.Use,
            MessageKeys.Room.FloorItem.OneWayDoorEnter,
            MessageKeys.Room.FloorItem.ThrowDice,
            MessageKeys.Room.FloorItem.DiceOff,
            MessageKeys.Room.WallItem.Remove,
            MessageKeys.Room.WallItem.StickyDataSet,
            MessageKeys.Room.WallItem.PostItPlace,
            MessageKeys.Room.WallItem.SpamPostItAdd
        ];
        foreach (MessageKey key in keys)
        {
            await fixture.WaitForPeopleGroupRequestCount(key, 1)
                .WaitAsync(test_synchronization_timeout);
        }

        Assert.Equal(new UseFloorItemRequest(1001, 2), fixture.LastFloorItemUseRequest);
        Assert.Equal(new UseWallItemRequest(1002, wall_state), fixture.LastWallItemUseRequest);
        Assert.Equal(new EnterOneWayDoorRequest(1003), fixture.LastOneWayDoorRequest);
        Assert.Equal(new ThrowDiceRequest(1004), fixture.LastThrowDiceRequest);
        Assert.Equal(new DiceOffRequest(1005), fixture.LastDiceOffRequest);
        Assert.Equal(new RemoveWallItemRequest(1006), fixture.LastWallItemRemoveRequest);
        Assert.Equal(
            new SetStickyDataRequest(1007, "FFFF33", "note"),
            fixture.LastStickySetRequest);
        Assert.Equal(
            new PlacePostItRequest(1008, ":w=2,3 l=5,20 l"),
            fixture.LastPostItPlaceRequest);
        Assert.Equal(
            new AddSpamWallPostItRequest(1009, ":w=3,4 l=6,21 r", "FF00FF", "spam"),
            fixture.LastPostItAddRequest);

        string root = FindRepositoryRoot();
        string globals_source = File.ReadAllText(Path.Combine(root, "src", "QX.Scripting", "ScriptGlobals.cs"));
        string actions_source = File.ReadAllText(Path.Combine(root, "src", "QX.Scripting", "ScriptGlobals.Actions.cs"));
        string interactions_source = File.ReadAllText(Path.Combine(root, "src", "QX.Scripting", "ScriptGlobals.Interactions.cs"));
        Assert.DoesNotContain("Game.RoomActions.UseFloorItem(", globals_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.UseWallItem(", globals_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.ThrowDice(", actions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.DiceOff(", actions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.PlacePostIt(", actions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.AddSpamWallPostIt(", actions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.EnterOneWayDoor(", interactions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.SetStickyData(", interactions_source, StringComparison.Ordinal);
        Assert.DoesNotContain("Game.RoomActions.RemoveWallItem(", interactions_source, StringComparison.Ordinal);
    }

