    [Fact]
    public void application_json_is_strict_and_preserves_decimal_identifiers()
    {
        using JsonDocument request_json = JsonDocument.Parse(
            """{"after_sequence":"9007199254740993","limit":50}""");
        RoomChatHistoryRequest request = Assert.IsType<RoomChatHistoryRequest>(
            ApplicationJson.Deserialize(
                request_json.RootElement,
                typeof(RoomChatHistoryRequest)));
        Assert.Equal(9007199254740993L, request.AfterSequence);
        Assert.Equal(50, request.Limit);

        using JsonDocument invalid_json = JsonDocument.Parse(
            """{"after_sequence":"1","limit":1,"unknown":true}""");
        Assert.Throws<JsonException>(() => ApplicationJson.Deserialize(
            invalid_json.RootElement,
            typeof(RoomChatHistoryRequest)));

        string result_json = ApplicationJson.Serialize(
            new RoomChatWhisperResult(
                ClientType.Flash,
                (Id)9223372036854775806L,
                9007199254740993L,
                true,
                false,
                DateTimeOffset.UnixEpoch),
            false);
        using JsonDocument result = JsonDocument.Parse(result_json);
        Assert.Equal(
            "9223372036854775806",
            result.RootElement.GetProperty("room_id").GetString());
        Assert.Equal(
            "9007199254740993",
            result.RootElement.GetProperty("room_generation").GetString());
        Assert.Equal(JsonValueKind.String, result.RootElement.GetProperty("room_id").ValueKind);
        Assert.Equal(JsonValueKind.String, result.RootElement.GetProperty("room_generation").ValueKind);

        string dictionary_json = ApplicationJson.Serialize(
            new Dictionary<Id, string> { [(Id)9223372036854775806L] = "value" },
            false);
        using JsonDocument dictionary = JsonDocument.Parse(dictionary_json);
        Assert.Equal(
            "value",
            dictionary.RootElement.GetProperty("9223372036854775806").GetString());
    }

    [Fact]
    public void marketplace_item_data_schema_matches_serialized_optional_fields()
    {
        using JsonDocument document = JsonDocument.Parse(ApplicationJson.Serialize(
            ApplicationJson.OutputSchema(typeof(ItemDataSnapshot)),
            indented: false));
        JsonElement schema = document.RootElement;
        JsonElement properties = schema.GetProperty("properties");
        string[] required = schema.GetProperty("required")
            .EnumerateArray()
            .Select(value => value.GetString()!)
            .ToArray();

        Assert.Contains("type", required);
        Assert.DoesNotContain("map_entries", required);
        Assert.DoesNotContain("string_values", required);
        JsonElement map = properties.GetProperty("map_entries")
            .GetProperty("anyOf")[0];
        Assert.Equal("object", map.GetProperty("type").GetString());
        Assert.Equal(
            "string",
            map.GetProperty("additionalProperties").GetProperty("type").GetString());
    }

