    [Fact]
    public async Task mcp_tools_cover_calls_and_keep_events_subscription_only()
    {
        using var fixture = new SurfaceFixture();

        IReadOnlyList<McpTool> tools = ApplicationMcpTools.Create(fixture.Application);
        string[] expected_tools =
        [
            .. fixture.Application.Members
                .Where(member => member.Kind is not ApplicationMemberKind.Event &&
                    member.Exposure.HasFlag(ApplicationExposure.Mcp))
                .Select(member => "application_" + member.Id.Replace('.', '_')),
            "describe_application_member",
            "list_application_members"
        ];
        Assert.Equal(
            expected_tools.Order(StringComparer.Ordinal).ToArray(),
            tools.Select(tool => tool.Name).ToArray());
        Assert.DoesNotContain(tools, tool => tool.Name == "application_room_chat_received");
        Assert.DoesNotContain(tools, tool => tool.Name == "application_friends_changed");
        Assert.DoesNotContain(tools, tool => tool.Name == "application_friends_message_received");
        Assert.DoesNotContain(tools, tool => tool.Name == "application_trade_changed");
        Assert.All(tools, tool =>
        {
            Assert.NotNull(tool.OutputSchema);
            Assert.NotNull(tool.Metadata);
            Assert.NotEmpty(tool.Metadata!);
        });

        McpTool history = Assert.Single(tools, tool =>
            tool.Name == "application_room_chat_history");
        McpTool talk = Assert.Single(tools, tool =>
            tool.Name == "application_room_chat_talk");
        McpTool shout = Assert.Single(tools, tool =>
            tool.Name == "application_room_chat_shout");
        McpTool whisper = Assert.Single(tools, tool =>
            tool.Name == "application_room_chat_whisper");
        McpTool request_accept = Assert.Single(tools, tool =>
            tool.Name == "application_friends_request_accept");
        McpTool requests_decline_all = Assert.Single(tools, tool =>
            tool.Name == "application_friends_requests_decline_all");
        McpTool catalog_purchase = Assert.Single(tools, tool =>
            tool.Name == "application_catalog_purchase_send");
        Assert.Equal(ApplicationMemberIds.RoomChatHistory, history.Metadata!["qx.id"]);
        Assert.Equal(ApplicationMemberIds.RoomChatTalk, talk.Metadata!["qx.id"]);
        Assert.Equal(ApplicationMemberIds.RoomChatShout, shout.Metadata!["qx.id"]);
        Assert.Equal(ApplicationMemberIds.RoomChatWhisper, whisper.Metadata!["qx.id"]);
        Assert.Equal("application", history.Metadata["qx.surface"]);
        Assert.Equal("application", whisper.Metadata["qx.surface"]);
        Assert.Equal(ApplicationMemberIds.CatalogPurchaseSend, catalog_purchase.Metadata!["qx.id"]);
        Assert.Contains("qx.messages", history.Metadata.Keys);
        Assert.Contains("qx.messages", whisper.Metadata.Keys);
        Assert.True(history.Annotations.ReadOnlyHint);
        Assert.False(history.Annotations.DestructiveHint);
        Assert.True(history.Annotations.IdempotentHint);
        Assert.False(history.Annotations.OpenWorldHint);
        Assert.False(whisper.Annotations.ReadOnlyHint);
        Assert.True(whisper.Annotations.DestructiveHint);
        Assert.False(whisper.Annotations.IdempotentHint);
        Assert.True(whisper.Annotations.OpenWorldHint);
        Assert.False(talk.Annotations.ReadOnlyHint);
        Assert.True(talk.Annotations.DestructiveHint);
        Assert.False(talk.Annotations.IdempotentHint);
        Assert.True(talk.Annotations.OpenWorldHint);
        Assert.False(shout.Annotations.ReadOnlyHint);
        Assert.True(shout.Annotations.DestructiveHint);
        Assert.False(shout.Annotations.IdempotentHint);
        Assert.True(shout.Annotations.OpenWorldHint);
        Assert.False(catalog_purchase.Annotations.ReadOnlyHint);
        Assert.True(catalog_purchase.Annotations.DestructiveHint);
        Assert.False(catalog_purchase.Annotations.IdempotentHint);
        Assert.True(catalog_purchase.Annotations.OpenWorldHint);

        using JsonDocument history_schema = JsonDocument.Parse(
            ApplicationJson.Serialize(history.InputSchema, indented: false));
        JsonElement history_properties = history_schema.RootElement.GetProperty("properties");
        JsonElement after_sequence = history_properties.GetProperty("after_sequence");
        Assert.Equal("string", after_sequence.GetProperty("type").GetString());
        Assert.Equal("0", after_sequence.GetProperty("default").GetString());
        Assert.Equal("^[0-9]+$", after_sequence.GetProperty("pattern").GetString());
        JsonElement limit = history_properties.GetProperty("limit");
        Assert.Equal(1, limit.GetProperty("minimum").GetInt32());
        Assert.Equal(500, limit.GetProperty("maximum").GetInt32());

        using JsonDocument accept_schema = JsonDocument.Parse(
            ApplicationJson.Serialize(request_accept.InputSchema, indented: false));
        JsonElement request_ids = accept_schema.RootElement
            .GetProperty("properties")
            .GetProperty("request_ids");
        Assert.Equal(1, request_ids.GetProperty("minItems").GetInt32());
        Assert.Equal(ushort.MaxValue, request_ids.GetProperty("maxItems").GetInt32());
        using JsonDocument decline_all_schema = JsonDocument.Parse(
            ApplicationJson.Serialize(requests_decline_all.InputSchema, indented: false));
        Assert.Empty(decline_all_schema.RootElement.GetProperty("properties").EnumerateObject());
        Assert.Empty(decline_all_schema.RootElement.GetProperty("required").EnumerateArray());

        using JsonDocument whisper_args = JsonDocument.Parse(
            """{"recipient":"bob","message":"hello","bubble":0}""");
        McpToolException unavailable = await Assert.ThrowsAsync<McpToolException>(() =>
            whisper.Handler(whisper_args.RootElement, CancellationToken.None));
        Assert.Equal("application_unavailable", unavailable.Metadata["qx.error"]);
        Assert.Equal(ApplicationMemberIds.RoomChatWhisper, unavailable.Metadata["qx.id"]);
        Assert.Contains("qx.availability", unavailable.Metadata.Keys);
    }

