                typeof(SubscriptionBuildersClubFurniCountRefreshResult),
                2),
            (ApplicationMemberIds.SubscriptionsBuildersClubFloorOfferPlace,
                ApplicationMemberKind.Operation,
                typeof(SubscriptionBuildersClubFloorPlaceRequest),
                typeof(SubscriptionBuildersClubPlacementDispatchReceipt),
                1),
            (ApplicationMemberIds.SubscriptionsBuildersClubWallOfferPlace,
                ApplicationMemberKind.Operation,
                typeof(SubscriptionBuildersClubWallPlaceRequest),
                typeof(SubscriptionBuildersClubPlacementDispatchReceipt),
                1),
            (ApplicationMemberIds.SubscriptionsChanged,
                ApplicationMemberKind.Event,
                null,
                typeof(SubscriptionChanged),
                6)
        ];
        Assert.Equal(9, offline.Application.Members.Count(
            member => member.Id.StartsWith("subscriptions.", StringComparison.Ordinal)));
        Assert.All(members, expected =>
        {
            ApplicationDescriptor descriptor = offline.Application.Members.Single(
                member => member.Id == expected.id);
            Assert.Equal(expected.kind, descriptor.Kind);
            Assert.Equal(expected.request, descriptor.RequestType);
            Assert.Equal(expected.result, descriptor.ResultType);
            Assert.Equal(expected.messages, descriptor.Messages.Count);
            Assert.Equal(
                expected.kind is ApplicationMemberKind.Event
                    ? ApplicationExposure.Ui |
                        ApplicationExposure.Cli |
                        ApplicationExposure.Scripting
                    : ApplicationExposure.All,
                descriptor.Exposure);
        });
        Assert.True(offline.Application
            .Describe(ApplicationMemberIds.SubscriptionsState)
            .Availability
            .Available);
        Assert.True(offline.Application
            .Describe(ApplicationMemberIds.SubscriptionsClubOffersList)
            .Availability
            .Available);
        Assert.All(
            members.Where(member => member.kind is not ApplicationMemberKind.Query),
            member => Assert.False(offline.Application.Describe(member.id).Availability.Available));

        string[] tool_names = ApplicationMcpTools.Create(offline.Application)
            .Select(tool => tool.Name)
            .ToArray();
        Assert.Contains("application_subscriptions_state", tool_names);
        Assert.Contains("application_subscriptions_club_offers_list", tool_names);
        Assert.Contains("application_subscriptions_club_offers_refresh", tool_names);
        Assert.Contains("application_subscriptions_user_info_refresh", tool_names);
        Assert.Contains("application_subscriptions_kickback_refresh", tool_names);
        Assert.Contains("application_subscriptions_builders_club_furni_count_refresh", tool_names);
        Assert.Contains(
            "application_subscriptions_builders_club_floor_offer_place",
            tool_names);
        Assert.Contains(
            "application_subscriptions_builders_club_wall_offer_place",
            tool_names);
        Assert.DoesNotContain("application_subscriptions_changed", tool_names);

        ApplicationDescriptor club_offers_refresh = offline.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.SubscriptionsClubOffersRefresh);
        ApplicationParameterDescriptor club_offers_timeout = club_offers_refresh.Parameters.Single(
            parameter => parameter.Name == "timeout_milliseconds");
        Assert.Equal(1, club_offers_timeout.Constraints?.Minimum);
        Assert.Null(club_offers_timeout.Constraints?.Maximum);

        foreach (ClientType client in new[] { ClientType.Flash, ClientType.Unity })
        {
            using var connected = new SurfaceFixture(client);
            connected.EnterRoom(101);
            Assert.All(members, member => Assert.True(
                connected.Application.Describe(member.id).Availability.Available));
            ApplicationDescriptor state = connected.Application.Members.Single(
                member => member.Id == ApplicationMemberIds.SubscriptionsState);
            ApplicationMessageRequirement[] optional = state.Messages
                .Where(message => !message.Required)
                .ToArray();
            Assert.Equal(2, optional.Length);
            Assert.Equal(
                [
                    MessageKeys.Subscriptions.BuildersClubMembershipStatus,
                    MessageKeys.Subscriptions.BuildersClubPlacementWarning
                ],
                optional.Select(message => message.Key).ToArray());
        }
    }

    [Fact]
    public void subscription_state_is_capped_leased_and_reset_safe()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        var kickback = new ScrSendKickbackInfo(1, "2020-01-01", 0.25, 2, 3, 4, 5, 6, 7);
        var membership = new BuildersClubMembershipStatus(10, 20, 30, 40);
        var warning = new BuildersClubPlacementWarning(
            11,
            12,
            "floor",
            new BuildersClubFloorPlacement(13, 14, 2));
        Assert.False(fixture.Receive(MessageContracts.Subscriptions.KickbackInfo, kickback));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.BuildersClubFurniCount,
            new BuildersClubFurniCount(55)));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.BuildersClubMembershipStatus,
            membership));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.BuildersClubPlacementWarning,
            warning));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.ClubOffersSnapshot,
            new HabboClubOffers([ClubOffer(1)], 19)));
        for (int index = 0; index < 501; index++)
        {
            Assert.False(fixture.Receive(
                MessageContracts.Subscriptions.UserInfo,
                SubscriptionInfo($"product-{index:000}", index)));
        }

        SubscriptionStateView state = fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(Limit: 500));
        Assert.True(state.Connected);
        Assert.Equal(ClientType.Flash, state.Client);
        Assert.Equal(500, state.TotalProducts);
        Assert.Equal(500, state.MatchedProducts);
        Assert.Equal(500, state.Products.Count);
        Assert.Null(state.NextOffset);
        Assert.DoesNotContain(state.Products, product => product.ProductName == "product-000");
        Assert.Equal(kickback.CurrentHcStreak, state.Kickback?.CurrentHcStreak);
        Assert.Equal(55, state.BuildersClubFurniCount);
        Assert.Equal(membership.SecondsLeftWithGrace,
            state.BuildersClubMembership?.SecondsLeftWithGrace);
        Assert.Equal(SubscriptionPlacementKind.Floor,
            state.LastPlacementWarning?.PlacementKind);
        Assert.Equal(13, state.LastPlacementWarning?.X);
        Assert.Equal(19, state.ClubOffers?.DaysLeft);
        Assert.Equal(1, state.ClubOffers?.TotalOffers);
        Assert.True(state.ClubOffersRevision > 0);

        SubscriptionStateView first = fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(Limit: 2));
        Assert.Equal(2, first.NextOffset);
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.UserInfo,
            SubscriptionInfo("product-501", 501)));
        SubscriptionStateView continuation = fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(
                    Offset: 2,
                    Limit: 2,
                    SnapshotRevision: first.SnapshotRevision));
        Assert.Equal(
            state.Products.Skip(2).Take(2).Select(product => product.ProductName),
            continuation.Products.Select(product => product.ProductName));

        for (int index = 0; index < 16; index++)
        {
            _ = fixture.Application.Invoke<SubscriptionStateRequest, SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(Limit: 1));
        }
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(
                    Offset: 2,
                    Limit: 1,
                    SnapshotRevision: first.SnapshotRevision)));

        SubscriptionStateView active = fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(Limit: 2));
        long active_lease = active.SnapshotRevision;
        fixture.Disconnect();
        SubscriptionStateView reset = fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(Limit: 500));
        Assert.False(reset.Connected);
        Assert.Null(reset.Client);
        Assert.Empty(reset.Products);
        Assert.Null(reset.Kickback);
        Assert.Null(reset.BuildersClubFurniCount);
        Assert.Null(reset.BuildersClubMembership);
        Assert.Null(reset.LastPlacementWarning);
        Assert.Null(reset.ClubOffers);
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest(
                    Offset: 2,
                    Limit: 1,
                    SnapshotRevision: active_lease)));
    }

    [Fact]
    public async Task subscription_refreshes_ignore_presend_and_retry_then_first_response_wins()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        ScrSendUserInfo presend = SubscriptionInfo("habbo_club", 1);
        fixture.BeforeSubscriptionDispatch = key =>
        {
            if (key != MessageKeys.Subscriptions.UserInfoRequest)
                return;
            fixture.BeforeSubscriptionDispatch = null;
            Assert.False(fixture.Receive(MessageContracts.Subscriptions.UserInfo, presend));
        };
        Task<SubscriptionUserInfoRefreshResult> user_info = fixture.Application
            .InvokeAsync<SubscriptionUserInfoRefreshRequest, SubscriptionUserInfoRefreshResult>(
                ApplicationMemberIds.SubscriptionsUserInfoRefresh,
                new SubscriptionUserInfoRefreshRequest("habbo_club", test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForSubscriptionRequestCount(
            MessageKeys.Subscriptions.UserInfoRequest,
            1).WaitAsync(test_synchronization_timeout);
        Assert.False(user_info.IsCompleted);
        ScrSendUserInfo fresh = SubscriptionInfo("habbo_club", 2);
        Assert.False(fixture.Receive(MessageContracts.Subscriptions.UserInfo, fresh));
        SubscriptionUserInfoRefreshResult user_result = await user_info.WaitAsync(
            test_synchronization_timeout);
        Assert.Equal(2, user_result.Product.DaysToPeriodEnd);
        Assert.Equal("habbo_club", fixture.LastSubscriptionUserInfoRequest?.ProductName);
        Assert.Equal(1, fixture.SubscriptionUserInfoRequestCount);

        var first = new ScrSendKickbackInfo(3, "first", 0.3, 1, 2, 3, 4, 5, 6);
        var second = new ScrSendKickbackInfo(4, "second", 0.4, 2, 3, 4, 5, 6, 7);
        fixture.AfterSubscriptionDispatch = key =>
        {
            if (key != MessageKeys.Subscriptions.KickbackInfoRequest)
                return;
            fixture.AfterSubscriptionDispatch = null;
            Assert.False(fixture.Receive(MessageContracts.Subscriptions.KickbackInfo, first));
            Assert.False(fixture.Receive(MessageContracts.Subscriptions.KickbackInfo, second));
        };
        Task<SubscriptionKickbackRefreshResult> kickback = fixture.Application
            .InvokeAsync<SubscriptionKickbackRefreshRequest, SubscriptionKickbackRefreshResult>(
                ApplicationMemberIds.SubscriptionsKickbackRefresh,
                new SubscriptionKickbackRefreshRequest(test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForSubscriptionRequestCount(
            MessageKeys.Subscriptions.KickbackInfoRequest,
            1).WaitAsync(test_synchronization_timeout);
        SubscriptionKickbackRefreshResult kickback_result = await kickback.WaitAsync(
            test_synchronization_timeout);
        Assert.Equal("first", kickback_result.Kickback.FirstSubscriptionDate);
        SubscriptionStateView latest = fixture.Application.Invoke<
            SubscriptionStateRequest,
            SubscriptionStateView>(
                ApplicationMemberIds.SubscriptionsState,
                new SubscriptionStateRequest());
        Assert.Equal("second", latest.Kickback?.FirstSubscriptionDate);

        fixture.BeforeSubscriptionDispatch = key =>
        {
            if (key == MessageKeys.Subscriptions.BuildersClubFurniCountRequest &&
                fixture.SubscriptionFurniCountRequestCount == 1)
            {
                Assert.False(fixture.Receive(
                    MessageContracts.Subscriptions.BuildersClubFurniCount,
                    new BuildersClubFurniCount(66)));
            }
        };
        fixture.AfterSubscriptionDispatch = key =>
        {
            if (key == MessageKeys.Subscriptions.BuildersClubFurniCountRequest &&
                fixture.SubscriptionFurniCountRequestCount == 1)
            {
                fixture.BeforeSubscriptionDispatch = null;
                fixture.AfterSubscriptionDispatch = null;
                Assert.False(fixture.Receive(
                    MessageContracts.Subscriptions.BuildersClubFurniCount,
                    new BuildersClubFurniCount(77)));
            }
        };
        Task<SubscriptionBuildersClubFurniCountRefreshResult> furni = fixture.Application
            .InvokeAsync<
                SubscriptionBuildersClubFurniCountRefreshRequest,
                SubscriptionBuildersClubFurniCountRefreshResult>(
                    ApplicationMemberIds.SubscriptionsBuildersClubFurniCountRefresh,
                    new SubscriptionBuildersClubFurniCountRefreshRequest(1000))
            .AsTask();
        await fixture.WaitForSubscriptionRequestCount(
            MessageKeys.Subscriptions.BuildersClubFurniCountRequest,
            2).WaitAsync(test_synchronization_timeout);
        SubscriptionBuildersClubFurniCountRefreshResult furni_result = await furni.WaitAsync(
            test_synchronization_timeout);
        Assert.Equal(77, furni_result.FurniCount);
        Assert.Equal(2, fixture.SubscriptionFurniCountRequestCount);
    }

