    [Fact]
    public async Task subscription_club_offer_refresh_terminal_paths_send_at_most_once()
    {
        using (var timeout = new SurfaceFixture(ClientType.Flash))
        {
            await Assert.ThrowsAsync<RequestTimeoutException>(() => timeout.Application
                .InvokeAsync<SubscriptionClubOffersRefreshRequest, SubscriptionClubOffersPage>(
                    ApplicationMemberIds.SubscriptionsClubOffersRefresh,
                    new SubscriptionClubOffersRefreshRequest(TimeoutMilliseconds: 400))
                .AsTask()
                .WaitAsync(test_synchronization_timeout));
            Assert.Equal(1, timeout.ClubOffersRequestCount);
        }

        using (var cancelled = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<SubscriptionClubOffersPage> pending = cancelled.Application
                .InvokeAsync<SubscriptionClubOffersRefreshRequest, SubscriptionClubOffersPage>(
                    ApplicationMemberIds.SubscriptionsClubOffersRefresh,
                    new SubscriptionClubOffersRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms),
                    cancellation.Token)
                .AsTask();
            await cancelled.WaitForSubscriptionRequestCount(
                MessageKeys.Subscriptions.ClubOffersRequest,
                1).WaitAsync(test_synchronization_timeout);
            cancellation.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => pending.WaitAsync(
                test_synchronization_timeout));
            Assert.Equal(1, cancelled.ClubOffersRequestCount);
        }

        using (var disconnected = new SurfaceFixture(ClientType.Flash))
        {
            Task<SubscriptionClubOffersPage> pending = disconnected.Application
                .InvokeAsync<SubscriptionClubOffersRefreshRequest, SubscriptionClubOffersPage>(
                    ApplicationMemberIds.SubscriptionsClubOffersRefresh,
                    new SubscriptionClubOffersRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
                .AsTask();
            await disconnected.WaitForSubscriptionRequestCount(
                MessageKeys.Subscriptions.ClubOffersRequest,
                1).WaitAsync(test_synchronization_timeout);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => pending.WaitAsync(
                test_synchronization_timeout));
            Assert.Equal(1, disconnected.ClubOffersRequestCount);
        }

        using (var disposed = new SurfaceFixture(ClientType.Flash))
        {
            Task<SubscriptionClubOffersPage> first = disposed.Application
                .InvokeAsync<SubscriptionClubOffersRefreshRequest, SubscriptionClubOffersPage>(
                    ApplicationMemberIds.SubscriptionsClubOffersRefresh,
                    new SubscriptionClubOffersRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
                .AsTask();
            await disposed.WaitForSubscriptionRequestCount(
                MessageKeys.Subscriptions.ClubOffersRequest,
                1).WaitAsync(test_synchronization_timeout);
            Task<SubscriptionClubOffersPage> queued = disposed.Application
                .InvokeAsync<SubscriptionClubOffersRefreshRequest, SubscriptionClubOffersPage>(
                    ApplicationMemberIds.SubscriptionsClubOffersRefresh,
                    new SubscriptionClubOffersRefreshRequest(TimeoutMilliseconds: test_request_timeout_ms))
                .AsTask();
            disposed.Application.Dispose();
            await Assert.ThrowsAsync<ObjectDisposedException>(() => first.WaitAsync(
                test_synchronization_timeout));
            await Assert.ThrowsAsync<ObjectDisposedException>(() => queued.WaitAsync(
                test_synchronization_timeout));
            Assert.Equal(1, disposed.ClubOffersRequestCount);
        }
    }

