    [Fact]
    public void subscription_club_offer_memory_is_capped_and_nonclub_state_is_sanitized()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        for (int index = 0; index < 3; index++)
        {
            Assert.False(fixture.Receive(
                MessageContracts.Subscriptions.ClubOffersSnapshot,
                new HabboClubOffers(
                    Enumerable.Range(0, 501).Select(ClubOffer).ToArray(),
                    index)));
        }
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.UserInfo,
            SubscriptionInfo("habbo_club", 1)));
        _ = fixture.Application.Invoke<SubscriptionStateRequest, SubscriptionStateView>(
            ApplicationMemberIds.SubscriptionsState,
            new SubscriptionStateRequest(Limit: 1));

        object feature = SubscriptionFeature(fixture.Application);
        var club_commits = (System.Collections.ICollection)feature.GetType()
            .GetField("club_offer_commits", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(feature)!;
        Assert.Equal(2, club_commits.Count);
        var user_commits = (System.Collections.IEnumerable)feature.GetType()
            .GetField("user_info_commits", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(feature)!;
        Assert.All(user_commits.Cast<object>(), commit =>
        {
            object update = commit.GetType().GetProperty("Update")!.GetValue(commit)!;
            object state = update.GetType().GetProperty("State")!.GetValue(update)!;
            Assert.Null(state.GetType().GetProperty("ClubOffers")!.GetValue(state));
        });
        var leases = (System.Collections.IDictionary)feature.GetType()
            .GetField("leases", BindingFlags.Instance | BindingFlags.NonPublic)!
            .GetValue(feature)!;
        Assert.All(leases.Values.Cast<object>(), lease =>
        {
            object state = lease.GetType().GetProperty("State")!.GetValue(lease)!;
            Assert.Null(state.GetType().GetProperty("ClubOffers")!.GetValue(state));
            Assert.NotNull(lease.GetType().GetProperty("ClubOffers")!.GetValue(lease));
        });
    }

