    [Fact]
    public async Task subscription_club_offer_script_is_lossless_across_the_wire_maximum()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        using ScriptGlobals globals = fixture.CreateGlobals();
        var expected = new HabboClubOffer[ushort.MaxValue];
        for (int index = 0; index < expected.Length; index++)
            expected[index] = ClubOffer(index % 257);
        SetReservedWireFlag(expected[500], true);

        Task<HabboClubOffers> pending = globals.GetClubOffers(7, 120001);
        await fixture.WaitForSubscriptionRequestCount(
            MessageKeys.Subscriptions.ClubOffersRequest,
            1).WaitAsync(test_synchronization_timeout);
        Assert.Equal(7, fixture.LastClubOffersRequest?.OfferType);
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.ClubOffersSnapshot,
            new HabboClubOffers(expected, 31)));

        HabboClubOffers result = await pending.WaitAsync(TimeSpan.FromSeconds(10));
        Assert.Equal(1, fixture.ClubOffersRequestCount);
        Assert.Equal(31, result.DaysLeft);
        Assert.Equal(expected.Length, result.Offers.Count);
        for (int index = 0; index < expected.Length; index++)
            Assert.Equal(expected[index], result.Offers[index]);
        Assert.True(ReadReservedWireFlag(result.Offers[500]));
        Assert.Equal(result.Offers[1], result.Offers[258]);
        Assert.NotSame(result.Offers[1], result.Offers[258]);
    }

    [Theory]
    [InlineData("connected")]
    [InlineData("client")]
    [InlineData("session")]
    [InlineData("revision")]
    [InlineData("club_revision")]
    [InlineData("snapshot")]
    [InlineData("loaded")]
    [InlineData("days_left")]
    [InlineData("total")]
    [InlineData("offset")]
    [InlineData("gap")]
    [InlineData("final_count")]
    public async Task subscription_club_offer_script_rejects_paging_drift(string fault)
    {
        SubscriptionClubOffersPage first = ClubOffersPage(
            0,
            2,
            [ClubOfferView(1)],
            1);
        SubscriptionClubOffersPage second = ClubOffersPage(
            1,
            2,
            [ClubOfferView(2)],
            null);
        second = fault switch
        {
            "connected" => second with { Connected = false },
            "client" => second with { Client = ClientType.Unity },
            "session" => second with { SessionGeneration = 12 },
            "revision" => second with { Revision = 22 },
            "club_revision" => second with { ClubOffersRevision = 32 },
            "snapshot" => second with { SnapshotRevision = 42 },
            "loaded" => second with { Loaded = false },
            "days_left" => second with { DaysLeft = 52 },
            "total" => second with { TotalOffers = 3 },
            "offset" => second with { Offset = 2 },
            "gap" => second with { NextOffset = 3 },
            "final_count" => second with { Offers = Array.Empty<SubscriptionClubOfferView>() },
            _ => throw new ArgumentOutOfRangeException(nameof(fault))
        };
        var runtime = new ClubOffersScriptRuntime(first, second);
        using var fixture = new SurfaceFixture(ClientType.Flash);
        using ScriptGlobals globals = fixture.CreateGlobals(runtime);

        await Assert.ThrowsAsync<InvalidDataException>(() => globals.GetClubOffers());
    }

