    [Fact]
    public void subscription_builders_club_script_placements_are_exact_once_and_room_guarded()
    {
        foreach (ClientType client in new[] { ClientType.Flash, ClientType.Unity })
        {
            using var fixture = new SurfaceFixture(client);
            fixture.EnterRoom(101);
            using ScriptGlobals globals = fixture.CreateGlobals();

            globals.PlaceBuildersClubFurni(2, 3, 4, 5, 6, "floor");
            Assert.Equal(1, fixture.BuildersClubFloorPlacementCount);
            Assert.Equal(
                new BuildersClubPlaceRoomItem(2, 3, "floor", 4, 5, 6),
                fixture.LastBuildersClubFloorPlacement);

            globals.PlaceBuildersClubWallItem(7, 8, ":w=1,2 l=3,4 r", "wall");
            Assert.Equal(1, fixture.BuildersClubWallPlacementCount);
            Assert.Equal(
                new BuildersClubPlaceWallItem(7, 8, "wall", ":w=1,2 l=3,4 r"),
                fixture.LastBuildersClubWallPlacement);
        }

        using (var offline = new SurfaceFixture())
        using (ScriptGlobals globals = offline.CreateGlobals())
        {
            Assert.Throws<ApplicationUnavailableException>(() =>
                globals.PlaceBuildersClubFurni(1, 2, 3, 4));
            Assert.Equal(0, offline.BuildersClubFloorPlacementCount);
        }

        using (var no_room = new SurfaceFixture(ClientType.Flash))
        using (ScriptGlobals globals = no_room.CreateGlobals())
        {
            Assert.Throws<ApplicationUnavailableException>(() =>
                globals.PlaceBuildersClubWallItem(1, 2, ":w=1,2 l=3,4 l"));
            Assert.Equal(0, no_room.BuildersClubWallPlacementCount);
        }

        using (var unsupported = new SurfaceFixture(
            ClientType.Unity,
            invalid_builders_club_wall_schema: true))
        {
            unsupported.EnterRoom(101);
            using ScriptGlobals globals = unsupported.CreateGlobals();
            Assert.Throws<ApplicationUnavailableException>(() =>
                globals.PlaceBuildersClubWallItem(1, 2, ":w=1,2 l=3,4 l"));
            Assert.Equal(0, unsupported.BuildersClubWallPlacementCount);
        }
    }

