    [Fact]
    public void subscription_legacy_script_and_mcp_abi_have_no_state_bypass()
    {
        PropertyInfo subscription_info = typeof(ScriptGlobals).GetProperty(
            nameof(ScriptGlobals.SubscriptionInfo))!;
        Assert.Equal(
            typeof(IReadOnlyDictionary<string, ScrSendUserInfo>),
            subscription_info.PropertyType);
        Assert.Equal(typeof(ScrSendKickbackInfo), Nullable.GetUnderlyingType(
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.SubscriptionKickback))!
                .PropertyType) ?? typeof(ScrSendKickbackInfo));
        MethodInfo request_info = typeof(ScriptGlobals).GetMethod(
            nameof(ScriptGlobals.RequestSubscriptionInfo))!;
        ParameterInfo product_parameter = Assert.Single(request_info.GetParameters());
        Assert.Equal(typeof(string), product_parameter.ParameterType);
        Assert.Equal("habbo_club", product_parameter.DefaultValue);
        Assert.Equal(typeof(void), request_info.ReturnType);
        MethodInfo find = typeof(ScriptGlobals).GetMethod(
            nameof(ScriptGlobals.FindSubscription))!;
        Assert.Equal(typeof(ScrSendUserInfo), find.ReturnType);

        MethodInfo get_club_offers = typeof(ScriptGlobals).GetMethod(
            nameof(ScriptGlobals.GetClubOffers))!;
        Assert.Equal(typeof(Task<HabboClubOffers>), get_club_offers.ReturnType);
        Assert.Equal(
            [typeof(int), typeof(int)],
            get_club_offers.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [1, 10000],
            get_club_offers.GetParameters().Select(parameter => parameter.DefaultValue).ToArray());

        MethodInfo place_floor = typeof(ScriptGlobals).GetMethod(
            nameof(ScriptGlobals.PlaceBuildersClubFurni))!;
        Assert.Equal(typeof(void), place_floor.ReturnType);
        Assert.Equal(
            [typeof(int), typeof(int), typeof(int), typeof(int), typeof(int), typeof(string)],
            place_floor.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [DBNull.Value, DBNull.Value, DBNull.Value, DBNull.Value, 0, ""],
            place_floor.GetParameters().Select(parameter => parameter.DefaultValue).ToArray());

        MethodInfo place_wall = typeof(ScriptGlobals).GetMethod(
            nameof(ScriptGlobals.PlaceBuildersClubWallItem))!;
        Assert.Equal(typeof(void), place_wall.ReturnType);
        Assert.Equal(
            [typeof(int), typeof(int), typeof(string), typeof(string)],
            place_wall.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [DBNull.Value, DBNull.Value, DBNull.Value, ""],
            place_wall.GetParameters().Select(parameter => parameter.DefaultValue).ToArray());

        MethodInfo mcp = typeof(IMcpHost).GetMethod(nameof(IMcpHost.GetSubscriptionsAsync))!;
        Assert.Equal(typeof(Task<string>), mcp.ReturnType);
        Assert.Equal(
            [
                typeof(bool),
                typeof(string),
                typeof(int),
                typeof(int),
                typeof(int),
                typeof(CancellationToken)
            ],
            mcp.GetParameters().Select(parameter => parameter.ParameterType).ToArray());

        using var fixture = new SurfaceFixture(ClientType.Flash);
        using ScriptGlobals globals = fixture.CreateGlobals();
        var user_events = new List<ScrSendUserInfo>();
        var kickback_events = new List<ScrSendKickbackInfo>();
        var count_events = new List<BuildersClubFurniCount>();
        var membership_events = new List<BuildersClubMembershipStatus>();
        var warning_events = new List<BuildersClubPlacementWarning>();
        int resets = 0;
        _ = globals.OnSubscriptionInfoChanged(user_events.Add);
        _ = globals.OnSubscriptionKickbackChanged(kickback_events.Add);
        _ = globals.OnBuildersClubFurniCountChanged(count_events.Add);
        _ = globals.OnBuildersClubStatusChanged(membership_events.Add);
        _ = globals.OnBuildersClubPlacementWarning(warning_events.Add);
        _ = globals.OnSubscriptionsReset(() => resets++);

        ScrSendUserInfo user = SubscriptionInfo("habbo_club", 9);
        var kickback = new ScrSendKickbackInfo(1, "legacy", 0.5, 2, 3, 4, 5, 6, 7);
        var count = new BuildersClubFurniCount(88);
        var membership = new BuildersClubMembershipStatus(10, 20, 30, null);
        var warning = new BuildersClubPlacementWarning(
            1,
            2,
            "wall",
            new BuildersClubWallPlacement(":w=1,2 l=3,4"));
        Assert.False(fixture.Receive(MessageContracts.Subscriptions.UserInfo, user));
        Assert.False(fixture.Receive(MessageContracts.Subscriptions.KickbackInfo, kickback));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.BuildersClubFurniCount,
            count));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.BuildersClubMembershipStatus,
            membership));
        Assert.False(fixture.Receive(
            MessageContracts.Subscriptions.BuildersClubPlacementWarning,
            warning));
        Assert.Equal(user, Assert.Single(user_events));
        Assert.Equal(kickback, Assert.Single(kickback_events));
        Assert.Equal(count, Assert.Single(count_events));
        Assert.Equal(membership, Assert.Single(membership_events));
        Assert.Equal(warning, Assert.Single(warning_events));
        Assert.Equal(user, globals.SubscriptionInfo["HABBO_CLUB"]);
        Assert.Equal(user, globals.FindSubscription("HABBO_CLUB"));
        Assert.NotSame(
            globals.SubscriptionInfo["habbo_club"],
            globals.SubscriptionInfo["habbo_club"]);
        Assert.NotSame(
            globals.FindSubscription("habbo_club"),
            globals.FindSubscription("habbo_club"));
        Assert.Null(globals.FindSubscription(""));
        Assert.Null(globals.FindSubscription("   "));
        Assert.Null(globals.FindSubscription(new string('x', ushort.MaxValue + 1)));
        Assert.Throws<ArgumentNullException>(() => globals.FindSubscription(null!));
        Assert.Equal(kickback, globals.SubscriptionKickback);
        Assert.Equal(count, globals.BuildersClubFurnitureCount);
        Assert.Equal(membership, globals.BuildersClubMembership);
        Assert.Equal(warning, globals.LastBuildersClubPlacementWarning);

        globals.RequestSubscriptionInfo();
        globals.RequestSubscriptionKickback();
        globals.RequestBuildersClubFurniCount();
        Assert.Equal(1, fixture.SubscriptionUserInfoRequestCount);
        Assert.Equal(1, fixture.SubscriptionKickbackRequestCount);
        Assert.Equal(1, fixture.SubscriptionFurniCountRequestCount);
        Assert.Equal("habbo_club", fixture.LastSubscriptionUserInfoRequest?.ProductName);
        fixture.Disconnect();
        Assert.Equal(1, resets);

        string root = FindRepositoryRoot();
        string scripting = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.Subscriptions.cs"));
        Assert.Contains("ApplicationMemberIds.SubscriptionsState", scripting, StringComparison.Ordinal);
        Assert.DoesNotContain("Subscriptions.UserInfo", scripting, StringComparison.Ordinal);
        Assert.DoesNotContain("Subscriptions.KickbackInfo", scripting, StringComparison.Ordinal);
        Assert.DoesNotContain("Subscriptions.BuildersClubStatus", scripting, StringComparison.Ordinal);
        Assert.DoesNotContain("Subscriptions.LastPlacementWarning", scripting, StringComparison.Ordinal);
        string events = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.SubscriptionEvents.cs"));
        Assert.Contains("Application.Subscribe<SubscriptionChanged>", events, StringComparison.Ordinal);
        Assert.DoesNotContain("Subscriptions.", events, StringComparison.Ordinal);
        string shop = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.Shop.cs"));
        Assert.Contains(
            "ApplicationMemberIds.SubscriptionsClubOffersRefresh",
            shop,
            StringComparison.Ordinal);
        Assert.Contains(
            "ApplicationMemberIds.SubscriptionsClubOffersList",
            shop,
            StringComparison.Ordinal);
        Assert.DoesNotContain("Msg.Out.GetClubOffers", shop, StringComparison.Ordinal);
        Assert.DoesNotContain(
            "new Qx.Model.Messages.Incoming.GetClubOffers",
            shop,
            StringComparison.Ordinal);
        string special_shop = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.ShopSpecial.cs"));
        Assert.Contains(
            "ApplicationMemberIds.SubscriptionsBuildersClubFloorOfferPlace",
            special_shop,
            StringComparison.Ordinal);
        Assert.Contains(
            "ApplicationMemberIds.SubscriptionsBuildersClubWallOfferPlace",
            special_shop,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "Msg.Out.BuildersClubPlaceRoomItem",
            special_shop,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "Msg.Out.BuildersClubPlaceWallItem",
            special_shop,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "new BuildersClubPlaceRoomItem",
            special_shop,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            "new BuildersClubPlaceWallItem",
            special_shop,
            StringComparison.Ordinal);
        string hosting = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Hosting",
            "Mcp",
            "McpHost.cs"));
        Assert.Contains("SubscriptionUserInfoRefreshRequest", hosting, StringComparison.Ordinal);
        Assert.Contains("refreshed_generation = result.SessionGeneration", hosting, StringComparison.Ordinal);
        Assert.Contains("SubscriptionStateRequest(Limit: 500)", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("game.Subscriptions", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEventAsync<ScrSendUserInfo>", hosting, StringComparison.Ordinal);
    }

    [Fact]
    public async Task subscription_mcp_executes_refresh_errors_generation_and_legacy_json()
    {
        var runtime = new SubscriptionMcpRuntime
        {
            State = SubscriptionMcpState(
                1,
                SubscriptionProduct("a", 1),
                SubscriptionProduct("B", 2),
                SubscriptionProduct("A", 3)),
            Refresh = (request, _) => ValueTask.FromResult(
                new SubscriptionUserInfoRefreshResult(
                    ClientType.Flash,
                    1,
                    4,
                    4,
                    DateTimeOffset.UnixEpoch,
                    SubscriptionProduct(request.ProductName, 4)))
        };
        int readiness = 0;
        string paged = await ReadSubscriptionMcp(
            runtime,
            () => true,
            _ =>
            {
                readiness++;
                return Task.CompletedTask;
            },
            true,
            "  builders_club  ",
            1,
            1,
            10000);
        Assert.Equal(1, runtime.RefreshCount);
        Assert.Equal(1, readiness);
        Assert.Equal("builders_club", runtime.LastProductName);
        Assert.InRange(runtime.LastTimeoutMilliseconds, 1, 10000);
        using (JsonDocument document = JsonDocument.Parse(paged))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            Assert.Equal(2, root.GetProperty("metadata").GetProperty("nextOffset").GetInt32());
            JsonElement data = root.GetProperty("data");
            Assert.Equal(
                [
                    "total",
                    "returned",
                    "offset",
                    "maxItems",
                    "truncated",
                    "buildersClubFurniCount",
                    "products"
                ],
                data.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(3, data.GetProperty("total").GetInt32());
            Assert.Equal(1, data.GetProperty("returned").GetInt32());
            Assert.Equal(1, data.GetProperty("offset").GetInt32());
            Assert.Equal(1, data.GetProperty("maxItems").GetInt32());
            Assert.True(data.GetProperty("truncated").GetBoolean());
            Assert.Equal(42, data.GetProperty("buildersClubFurniCount").GetInt32());
            Assert.Equal(
                "B",
                data.GetProperty("products")[0].GetProperty("productName").GetString());
        }

        _ = await ReadSubscriptionMcp(
            runtime,
            () => true,
            _ => Task.CompletedTask,
            true,
            "   ",
            20,
            0,
            10000);
        Assert.Equal(2, runtime.RefreshCount);
        Assert.Equal("habbo_club", runtime.LastProductName);
        Assert.InRange(runtime.LastTimeoutMilliseconds, 1, 10000);

        _ = await ReadSubscriptionMcp(
            runtime,
            () => true,
            _ => Task.CompletedTask,
            false,
            "habbo_club",
            20,
            0,
            10000);
        Assert.Equal(2, runtime.RefreshCount);

        runtime.Refresh = (_, _) => ValueTask.FromException<SubscriptionUserInfoRefreshResult>(
            new TimeoutException("subscription timeout"));
        string timeout = await ReadSubscriptionMcp(
            runtime,
            () => true,
            _ => Task.CompletedTask,
            true,
            "habbo_club",
            20,
            0,
            10000);
        using (JsonDocument document = JsonDocument.Parse(timeout))
        {
            Assert.Equal(
                "timeout",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
            Assert.Equal(3,
                document.RootElement.GetProperty("data").GetProperty("total").GetInt32());
        }

        runtime.Refresh = (request, _) =>
        {
            runtime.State = SubscriptionMcpState(
                2,
                SubscriptionProduct("current", 5));
            return ValueTask.FromResult(new SubscriptionUserInfoRefreshResult(
                ClientType.Flash,
                1,
                5,
                5,
                DateTimeOffset.UnixEpoch,
                SubscriptionProduct(request.ProductName, 5)));
        };
        string drift = await ReadSubscriptionMcp(
            runtime,
            () => true,
            _ => Task.CompletedTask,
            true,
            "habbo_club",
            20,
            0,
            10000);
        using (JsonDocument document = JsonDocument.Parse(drift))
        {
            JsonElement root = document.RootElement;
            Assert.Equal("unavailable", root.GetProperty("error").GetProperty("code").GetString());
            Assert.Equal(
                "current",
                root.GetProperty("data")
                    .GetProperty("products")[0]
                    .GetProperty("productName")
                    .GetString());
        }

        IMcpHost host = DispatchProxy.Create<IMcpHost, EmptyMcpHostProxy>();
        var server = new McpServer(
            host,
            9390,
            new McpConfig
            {
                Token = new string('a', 32),
                AllowEditor = false
            });
        FieldInfo tools_field = typeof(McpServer).GetField(
            "_tools",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        McpTool subscriptions = Assert.Single(
            (IReadOnlyList<McpTool>)tools_field.GetValue(server)!,
            tool => tool.Name == "get_subscriptions");
        using JsonDocument schema = JsonDocument.Parse(
            JsonSerializer.Serialize(subscriptions.InputSchema));
        JsonElement properties = schema.RootElement.GetProperty("properties");
        Assert.True(properties.GetProperty("fetch").GetProperty("default").GetBoolean());
        Assert.Equal("habbo_club",
            properties.GetProperty("product").GetProperty("default").GetString());
        Assert.Equal(20, properties.GetProperty("limit").GetProperty("default").GetInt32());
        Assert.Equal(1, properties.GetProperty("limit").GetProperty("minimum").GetInt32());
        Assert.Equal(100, properties.GetProperty("limit").GetProperty("maximum").GetInt32());
        Assert.Equal(0, properties.GetProperty("offset").GetProperty("default").GetInt32());
        Assert.Equal(10000,
            properties.GetProperty("timeout_ms").GetProperty("default").GetInt32());
        Assert.Equal(1,
            properties.GetProperty("timeout_ms").GetProperty("minimum").GetInt32());
        Assert.Equal(120000,
            properties.GetProperty("timeout_ms").GetProperty("maximum").GetInt32());
    }

    [Fact]
    public void gifts_descriptors_state_pages_leases_and_reset_are_exact()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        string[] member_ids =
        [
            ApplicationMemberIds.GiftsState,
            ApplicationMemberIds.GiftsWrappingList,
            ApplicationMemberIds.GiftsClubInfoList,
