            ApplicationMemberIds.GiftsNewUserAdvance,
            ApplicationMemberIds.GiftsChanged
        ];
        Assert.All(member_ids, id => Assert.Contains(
            fixture.Application.Members,
            descriptor => descriptor.Id == id));
        Assert.All(
            member_ids.Where(id => id != ApplicationMemberIds.GiftsChanged),
