        Assert.True(state.Connected);
        Assert.Equal(ClientType.Flash, state.Client);
        Assert.Equal(4, state.Wrapping!.StuffTypeCount);
        Assert.Equal(5, state.ClubInfo!.OfferCount);
        Assert.Equal(10, state.ClubInfo.ProductCount);
        Assert.True(state.OfferGiftability[101]);
        Assert.True(Assert.IsAssignableFrom<IDictionary<int, bool>>(
            state.OfferGiftability).IsReadOnly);

        GiftClubInfoPage first = fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(Limit: 2));
        Assert.True(first.Loaded);
        Assert.Equal(5, first.Total);
        Assert.Equal([0, 1], first.Offers.Select(offer => offer.OfferOrdinal).ToArray());
        Assert.Equal(2, first.NextOffset);
        Assert.True(first.SnapshotRevision > 0);

        GiftClubInfoPage second = fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(
                    GiftClubInfoCollection.Offers,
                    2,
                    2,
                    first.SnapshotRevision));
        Assert.Equal([2, 3], second.Offers.Select(offer => offer.OfferOrdinal).ToArray());
        Assert.Equal(4, second.NextOffset);
        GiftClubInfoPage products = fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(
                    GiftClubInfoCollection.Products,
                    0,
                    3,
                    first.SnapshotRevision));
        Assert.Equal(10, products.Total);
        Assert.Equal([(0, 0), (0, 1), (1, 0)], products.Products
            .Select(product => (product.OfferOrdinal, product.ProductOrdinal)).ToArray());

        foreach ((GiftWrappingCollection collection, int total) in new[]
        {
            (GiftWrappingCollection.StuffTypes, 4),
            (GiftWrappingCollection.BoxTypes, 3),
            (GiftWrappingCollection.RibbonTypes, 2),
            (GiftWrappingCollection.DefaultStuffTypes, 1)
        })
        {
            GiftWrappingPage page = fixture.Application.Invoke<
                GiftWrappingPageRequest,
                GiftWrappingPage>(
                    ApplicationMemberIds.GiftsWrappingList,
                    new GiftWrappingPageRequest(collection, 0, 500, first.SnapshotRevision));
            Assert.Equal(first.SnapshotRevision, page.SnapshotRevision);
            Assert.Equal(total, page.Total);
            Assert.Equal(total, page.Values.Count);
        }

        Assert.False(fixture.Receive(
            MessageContracts.Gifts.PresentOpened,
            new PresentOpened("s", 7, "gift", 8, "s", true, "")));
        GiftClubInfoPage after_scalar = fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(Limit: 2));
        Assert.Equal(first.SnapshotRevision, after_scalar.SnapshotRevision);

        GiftClubInfoPage newest = after_scalar;
        for (int revision = 2; revision <= 5; revision++)
        {
            Assert.False(fixture.Receive(
                MessageContracts.Gifts.ClubInfo,
                GiftClubInfo(revision, 1)));
            newest = fixture.Application.Invoke<GiftClubInfoPageRequest, GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(Limit: 1));
        }
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(
                    GiftClubInfoCollection.Offers,
                    0,
                    1,
                    first.SnapshotRevision)));
        Assert.Single(fixture.Application.Invoke<GiftClubInfoPageRequest, GiftClubInfoPage>(
            ApplicationMemberIds.GiftsClubInfoList,
            new GiftClubInfoPageRequest(
                GiftClubInfoCollection.Offers,
                0,
                1,
                newest.SnapshotRevision)).Offers);

        fixture.Disconnect();
        GiftStateView disconnected = fixture.Application.Invoke<GiftStateRequest, GiftStateView>(
            ApplicationMemberIds.GiftsState,
            new GiftStateRequest());
        Assert.False(disconnected.Connected);
        Assert.Null(disconnected.Wrapping);
        Assert.Null(disconnected.ClubInfo);
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(
                    GiftClubInfoCollection.Offers,
                    0,
                    1,
                    newest.SnapshotRevision)));
    }

    [Fact]
    public async Task gifts_refresh_pairs_first_responses_and_serializes_both_routes()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.WrappingConfiguration,
            GiftWrapping(1)));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, GiftClubInfo(1, 1)));
        GiftWrappingConfiguration presend_wrapping = GiftWrapping(2);
        ClubGiftInfo presend_club = GiftClubInfo(2, 1);
        fixture.BeforeGiftDispatch = key =>
        {
            if (key == MessageKeys.Gifts.WrappingConfigurationRequest)
                Assert.False(fixture.Receive(
                    MessageContracts.Gifts.WrappingConfiguration,
                    presend_wrapping));
            if (key == MessageKeys.Gifts.ClubInfoRequest)
                Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, presend_club));
        };

        Task<GiftRefreshResult> refresh = fixture.Application.InvokeAsync<
            GiftRefreshRequest,
            GiftRefreshResult>(
                ApplicationMemberIds.GiftsRefresh,
                new GiftRefreshRequest(1, test_request_timeout_ms)).AsTask();
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.WrappingConfigurationRequest,
            1).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.ClubInfoRequest,
            1).WaitAsync(test_synchronization_timeout);
        Assert.False(refresh.IsCompleted);
        fixture.BeforeGiftDispatch = null;

        GiftWrappingConfiguration first_wrapping = GiftWrapping(3);
        GiftWrappingConfiguration late_wrapping = GiftWrapping(4);
        ClubGiftInfo first_club = GiftClubInfo(3, 3);
        ClubGiftInfo late_club = GiftClubInfo(4, 4);
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.WrappingConfiguration,
            first_wrapping));
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.WrappingConfiguration,
            late_wrapping));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, first_club));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, late_club));
        GiftRefreshResult result = await refresh.WaitAsync(test_synchronization_timeout);
        Assert.Equal(first_wrapping.WrappingPrice, result.Wrapping.WrappingPrice);
        Assert.Equal(first_club.Offers.Count, result.ClubInfo.OfferCount);
        Assert.Equal(result.SnapshotRevision, result.ClubInfoPage.SnapshotRevision);
        Assert.Single(result.ClubInfoPage.Offers);
        GiftWrappingPage paired_wrapping = fixture.Application.Invoke<
            GiftWrappingPageRequest,
            GiftWrappingPage>(
                ApplicationMemberIds.GiftsWrappingList,
                new GiftWrappingPageRequest(
                    GiftWrappingCollection.StuffTypes,
                    0,
                    500,
                    result.SnapshotRevision));
        Assert.Equal(first_wrapping.WrappingPrice, paired_wrapping.WrappingPrice);
        GiftClubInfoPage paired_club = fixture.Application.Invoke<
            GiftClubInfoPageRequest,
            GiftClubInfoPage>(
                ApplicationMemberIds.GiftsClubInfoList,
                new GiftClubInfoPageRequest(
                    GiftClubInfoCollection.Offers,
                    0,
                    500,
                    result.SnapshotRevision));
        Assert.Equal(first_club.Offers.Count, paired_club.TotalOffers);

        Task<GiftRefreshResult> first_serial = fixture.Application.InvokeAsync<
            GiftRefreshRequest,
            GiftRefreshResult>(
                ApplicationMemberIds.GiftsRefresh,
                new GiftRefreshRequest(2, test_request_timeout_ms)).AsTask();
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.WrappingConfigurationRequest,
            2).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.ClubInfoRequest,
            2).WaitAsync(test_synchronization_timeout);
        Task<GiftRefreshResult> second_serial = fixture.Application.InvokeAsync<
            GiftRefreshRequest,
            GiftRefreshResult>(
                ApplicationMemberIds.GiftsRefresh,
                new GiftRefreshRequest(2, test_request_timeout_ms)).AsTask();
        await Task.Yield();
        Assert.Equal(2, fixture.GiftRequestCount(
            MessageKeys.Gifts.WrappingConfigurationRequest));
        Assert.Equal(2, fixture.GiftRequestCount(MessageKeys.Gifts.ClubInfoRequest));
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.WrappingConfiguration,
            GiftWrapping(5)));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, GiftClubInfo(5, 2)));
        _ = await first_serial.WaitAsync(test_synchronization_timeout);
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.WrappingConfigurationRequest,
            3).WaitAsync(test_synchronization_timeout);
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.ClubInfoRequest,
            3).WaitAsync(test_synchronization_timeout);
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.WrappingConfiguration,
            GiftWrapping(6)));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, GiftClubInfo(6, 2)));
        _ = await second_serial.WaitAsync(test_synchronization_timeout);
        Assert.Equal(3, fixture.GiftRequestCount(
            MessageKeys.Gifts.WrappingConfigurationRequest));
        Assert.Equal(3, fixture.GiftRequestCount(MessageKeys.Gifts.ClubInfoRequest));
    }

