    [Fact]
    public async Task gifts_refresh_timeout_reset_and_offer_correlation_fail_closed()
    {
        using (var timeout_fixture = new SurfaceFixture(ClientType.Flash))
        {
            Task<GiftRefreshResult> timeout = timeout_fixture.Application.InvokeAsync<
                GiftRefreshRequest,
                GiftRefreshResult>(
                    ApplicationMemberIds.GiftsRefresh,
                    new GiftRefreshRequest(1, 1_000)).AsTask();
            await timeout_fixture.WaitForGiftRequestCount(
                MessageKeys.Gifts.WrappingConfigurationRequest,
                1).WaitAsync(test_synchronization_timeout);
            await timeout_fixture.WaitForGiftRequestCount(
                MessageKeys.Gifts.ClubInfoRequest,
                1).WaitAsync(test_synchronization_timeout);
            await Assert.ThrowsAnyAsync<TimeoutException>(() => timeout);
        }

        using (var reset_fixture = new SurfaceFixture(ClientType.Flash))
        {
            Task<GiftRefreshResult> reset = reset_fixture.Application.InvokeAsync<
                GiftRefreshRequest,
                GiftRefreshResult>(
                    ApplicationMemberIds.GiftsRefresh,
                    new GiftRefreshRequest(1, test_request_timeout_ms)).AsTask();
            await reset_fixture.WaitForGiftRequestCount(
                MessageKeys.Gifts.WrappingConfigurationRequest,
                1).WaitAsync(test_synchronization_timeout);
            await reset_fixture.WaitForGiftRequestCount(
                MessageKeys.Gifts.ClubInfoRequest,
                1).WaitAsync(test_synchronization_timeout);
            reset_fixture.Disconnect();
            await Assert.ThrowsAnyAsync<Exception>(() => reset);
            GiftStateView state = reset_fixture.Application.Invoke<
                GiftStateRequest,
                GiftStateView>(
                    ApplicationMemberIds.GiftsState,
                    new GiftStateRequest());
            Assert.False(state.Connected);
            Assert.Null(state.Wrapping);
            Assert.Null(state.ClubInfo);
        }

        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.BeforeGiftDispatch = key =>
        {
            if (key != MessageKeys.Gifts.OfferGiftabilityRequest)
                return;
            fixture.BeforeGiftDispatch = null;
            Assert.False(fixture.Receive(
                MessageContracts.Gifts.OfferGiftability,
                new IsOfferGiftable(100, false)));
        };
        Task<GiftOfferGiftabilityRefreshResult> refresh = fixture.Application.InvokeAsync<
            GiftOfferGiftabilityRefreshRequest,
            GiftOfferGiftabilityRefreshResult>(
                ApplicationMemberIds.GiftsOfferGiftabilityRefresh,
                new GiftOfferGiftabilityRefreshRequest(100, test_request_timeout_ms)).AsTask();
        await fixture.WaitForGiftRequestCount(
            MessageKeys.Gifts.OfferGiftabilityRequest,
            1).WaitAsync(test_synchronization_timeout);
        Assert.False(refresh.IsCompleted);
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.OfferGiftability,
            new IsOfferGiftable(101, true)));
        Assert.False(refresh.IsCompleted);
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.OfferGiftability,
            new IsOfferGiftable(100, true)));
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.OfferGiftability,
            new IsOfferGiftable(100, false)));
        GiftOfferGiftabilityRefreshResult result = await refresh.WaitAsync(
            test_synchronization_timeout);
        Assert.True(result.IsGiftable);
        GiftStateView latest = fixture.Application.Invoke<GiftStateRequest, GiftStateView>(
            ApplicationMemberIds.GiftsState,
            new GiftStateRequest());
        Assert.False(latest.OfferGiftability[100]);
        Assert.True(latest.OfferGiftability[101]);

        for (int offer_id = 1000; offer_id <= 1500; offer_id++)
        {
            Assert.False(fixture.Receive(
                MessageContracts.Gifts.OfferGiftability,
                new IsOfferGiftable(offer_id, offer_id % 2 == 0)));
        }
        GiftStateView bounded = fixture.Application.Invoke<GiftStateRequest, GiftStateView>(
            ApplicationMemberIds.GiftsState,
            new GiftStateRequest());
        Assert.Equal(500, bounded.OfferGiftability.Count);
        Assert.DoesNotContain(1000, bounded.OfferGiftability.Keys);
        Assert.Contains(1500, bounded.OfferGiftability.Keys);
    }

    [Fact]
    public void gifts_application_events_are_bounded_reset_ordered_and_disposal_safe()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var changes = new List<GiftChanged>();
            using IDisposable subscription = fixture.Application.Subscribe<GiftChanged>(
                ApplicationMemberIds.GiftsChanged,
                changes.Add);
            Assert.False(fixture.Receive(
                MessageContracts.Gifts.WrappingConfiguration,
                GiftWrapping(20)));
            Assert.False(fixture.Receive(
                MessageContracts.Gifts.ClubInfo,
                GiftClubInfo(20, 4)));
            Assert.False(fixture.Receive(
                MessageContracts.Gifts.PresentOpened,
                new PresentOpened("s", 20, "opened", 21, "s", true, "")));
            Assert.Equal(
                [GiftChangeKind.Wrapping, GiftChangeKind.ClubInfo, GiftChangeKind.PresentOpened],
                changes.Select(change => change.Kind).ToArray());
            Assert.True(changes[0].SnapshotRevision > 0);
            Assert.Equal(4, changes[0].Wrapping!.StuffTypeCount);
            Assert.True(changes[1].SnapshotRevision > 0);
            Assert.Equal(4, changes[1].ClubInfo!.OfferCount);
            Assert.Null(changes[2].SnapshotRevision);
            Assert.Equal("opened", changes[2].PresentOpened!.ProductCode);
            Assert.True(changes[0].Revision < changes[1].Revision);
            Assert.True(changes[1].Revision < changes[2].Revision);
            fixture.Disconnect();
            GiftChanged reset = changes[^1];
            Assert.Equal(GiftChangeKind.Reset, reset.Kind);
            Assert.Null(reset.Client);
            Assert.Null(reset.SnapshotRevision);
            Assert.Null(reset.Wrapping);
            Assert.Null(reset.ClubInfo);
        }

        using var disposed = new SurfaceFixture(ClientType.Flash);
        using ScriptGlobals globals = disposed.CreateGlobals();
        var disposed_changes = new List<GiftChanged>();
        using IDisposable disposed_subscription = disposed.Application.Subscribe<GiftChanged>(
            ApplicationMemberIds.GiftsChanged,
            disposed_changes.Add);
        disposed.Application.Dispose();
        Assert.False(disposed.Receive(
            MessageContracts.Gifts.WrappingConfiguration,
            GiftWrapping(21)));
        Assert.Empty(disposed_changes);
        Assert.NotNull(globals.GiftWrapping);
        Assert.Throws<InvalidOperationException>(() =>
            globals.RequestGiftWrappingConfiguration());
        Assert.Throws<ObjectDisposedException>(() => disposed.Application.Invoke<
            GiftStateRequest,
            GiftStateView>(
                ApplicationMemberIds.GiftsState,
                new GiftStateRequest()));
    }

    [Fact]
    public void gifts_legacy_script_reads_events_and_new_user_selection_stay_lossless()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.EnterRoom(1000);
        using ScriptGlobals globals = fixture.CreateGlobals();
        var wrapping_events = new List<GiftWrappingConfiguration>();
        var club_events = new List<ClubGiftInfo>();
        var selected_events = new List<ClubGiftSelected>();
        var opened_events = new List<PresentOpened>();
        var notification_events = new List<ClubGiftNotification>();
        var giftability_events = new List<IsOfferGiftable>();
        var offer_events = new List<NuxGiftOffer>();
        int receiver_not_found = 0;
        int incomplete = 0;
        int resets = 0;
        _ = globals.OnGiftWrappingChanged(wrapping_events.Add);
        _ = globals.OnClubGiftsChanged(club_events.Add);
        _ = globals.OnClubGiftSelected(selected_events.Add);
        _ = globals.OnPresentOpened(opened_events.Add);
        _ = globals.OnGiftReceiverNotFound(() => receiver_not_found++);
        _ = globals.OnClubGiftNotification(notification_events.Add);
        _ = globals.OnOfferGiftabilityChanged(giftability_events.Add);
        _ = globals.OnNewUserGiftOfferChanged(offer_events.Add);
        _ = globals.OnNewUserFlowIncomplete(() => incomplete++);
        _ = globals.OnGiftsReset(() => resets++);

        GiftWrappingConfiguration wrapping = GiftWrapping(10);
        ClubGiftInfo club = GiftClubInfo(10, 2);
        var selected = new ClubGiftSelected(
            "selected-product",
            [GiftCatalogProduct(10, 0, 0)]);
        var opened = new PresentOpened("s", 10, "opened", 11, "s", true, "");
        var notification = new ClubGiftNotification(3);
        var giftability = new IsOfferGiftable(10, true);
        List<NuxGiftStep> new_user_steps =
        [
            new NuxGiftStep(
                1,
                2,
                [new NuxGiftOption("first", [new NuxGiftProduct("a", "a-key")])]),
            new NuxGiftStep(3, 4, []),
            new NuxGiftStep(
                5,
                6,
                [
                    new NuxGiftOption("second", [new NuxGiftProduct("b", null)]),
                    new NuxGiftOption("third", [new NuxGiftProduct("c", "c-key")])
                ])
        ];
        for (int step = new_user_steps.Count; step < 501; step++)
            new_user_steps.Add(new NuxGiftStep(step + 1, step + 1, []));
        var new_user_offer = new NuxGiftOffer(new_user_steps);
        Assert.False(fixture.Receive(MessageContracts.Gifts.WrappingConfiguration, wrapping));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubInfo, club));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubSelected, selected));
        Assert.False(fixture.Receive(MessageContracts.Gifts.PresentOpened, opened));
        Assert.False(fixture.Receive(
            MessageContracts.Gifts.ReceiverNotFound,
            new GiftReceiverNotFound()));
        Assert.False(fixture.Receive(MessageContracts.Gifts.ClubNotification, notification));
        Assert.False(fixture.Receive(MessageContracts.Gifts.OfferGiftability, giftability));
        Assert.False(fixture.Receive(MessageContracts.Gifts.NewUserOffer, new_user_offer));
        Assert.False(fixture.Receive(MessageContracts.Gifts.NewUserIncomplete, new NuxNotComplete()));

        AssertLegacyGiftPayload(wrapping, Assert.Single(wrapping_events));
        AssertLegacyGiftPayload(club, Assert.Single(club_events));
        AssertLegacyGiftPayload(selected, Assert.Single(selected_events));
        AssertLegacyGiftPayload(opened, Assert.Single(opened_events));
        Assert.Equal(1, receiver_not_found);
        AssertLegacyGiftPayload(notification, Assert.Single(notification_events));
        AssertLegacyGiftPayload(giftability, Assert.Single(giftability_events));
        AssertLegacyGiftPayload(new_user_offer, Assert.Single(offer_events));
        Assert.Equal(1, incomplete);
        AssertLegacyGiftPayload(wrapping, globals.GiftWrapping!);
        AssertLegacyGiftPayload(club, globals.ClubGifts!);
        AssertLegacyGiftPayload(selected, globals.LastSelectedClubGift!);
        AssertLegacyGiftPayload(opened, globals.LastOpenedPresent!);
        AssertLegacyGiftPayload(notification, globals.LatestClubGiftNotification!);
        AssertLegacyGiftPayload(new_user_offer, globals.NewUserGiftOffer!);
        Assert.True(globals.NewUserFlowIsIncomplete);
        Assert.True(globals.OfferGiftability[10]);

        Assert.Equal(2, globals.SelectFirstNewUserGifts());
        Assert.Equal(
            [new NuxGiftSelection(1, 2, 0), new NuxGiftSelection(5, 6, 0)],
            fixture.LastNewUserGiftSelect!.Selections);
        Assert.Equal(1, fixture.GiftRequestCount(MessageKeys.Gifts.NewUserSelect));
        fixture.Disconnect();
        Assert.Equal(1, resets);
        Assert.Null(globals.GiftWrapping);
        Assert.Null(globals.ClubGifts);
        Assert.Empty(globals.OfferGiftability);

        using var unity = new SurfaceFixture(ClientType.Unity);
        using ScriptGlobals unity_globals = unity.CreateGlobals();
        Assert.Equal(0, unity_globals.SelectFirstNewUserGifts());
        Assert.Equal(0, unity.GiftRequestCount(MessageKeys.Gifts.NewUserSelect));
    }

    [Fact]
    public async Task gifts_script_and_mcp_abi_schema_and_dispatch_are_compatible()
    {
        MethodInfo record_purchase = Assert.Single(
            typeof(ScriptGlobals).GetMethods(),
            method => method.Name == nameof(ScriptGlobals.PurchaseFromCatalogAsGift) &&
                method.GetParameters().Length == 1);
