            typeof(PurchaseFromCatalogAsGift),
            Assert.Single(record_purchase.GetParameters()).ParameterType);
        MethodInfo actions_purchase = Assert.Single(
            typeof(ScriptGlobals).GetMethods(),
            method => method.Name == nameof(ScriptGlobals.PurchaseFromCatalogAsGift) &&
                method.GetParameters().Length == 10);
        Assert.Equal(typeof(void), actions_purchase.ReturnType);
        Assert.Equal(
            [
                typeof(int),
                typeof(int),
                typeof(string),
                typeof(string),
                typeof(string),
                typeof(int),
                typeof(int),
                typeof(int),
                typeof(bool),
                typeof(int)
            ],
            actions_purchase.GetParameters()
                .Select(parameter => parameter.ParameterType)
                .ToArray());
        Assert.Equal(
            [
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                false,
                1
            ],
            actions_purchase.GetParameters()
                .Select(parameter => parameter.DefaultValue)
                .ToArray());

        MethodInfo buy = typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.BuyGiftFromCatalog))!;
        Assert.Equal(typeof(Task<CatalogPurchaseOutcome>), buy.ReturnType);
        Assert.Equal(
            [
                typeof(int),
                typeof(int),
                typeof(string),
                typeof(string),
                typeof(string),
                typeof(int),
                typeof(int),
                typeof(int),
                typeof(bool),
                typeof(int)
            ],
            buy.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [
                DBNull.Value,
                DBNull.Value,
                DBNull.Value,
                "",
                "",
                0,
                0,
                0,
                false,
                10000
            ],
            buy.GetParameters().Select(parameter => parameter.DefaultValue).ToArray());
        MethodInfo open = typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.OpenPresent))!;
        Assert.Equal(typeof(void), open.ReturnType);
        Assert.Equal(typeof(Id), Assert.Single(open.GetParameters()).ParameterType);
        MethodInfo select_first = typeof(ScriptGlobals).GetMethod(
            nameof(ScriptGlobals.SelectFirstNewUserGifts))!;
        Assert.Equal(typeof(int), select_first.ReturnType);
        Assert.Empty(select_first.GetParameters());
        Assert.Equal(
            typeof(IReadOnlyDictionary<int, bool>),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.OfferGiftability))!.PropertyType);
        Assert.Equal(
            typeof(IDisposable),
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.OnGiftWrappingChanged))!
                .ReturnType);
        Assert.Equal(
            typeof(Action<GiftWrappingConfiguration>),
            Assert.Single(typeof(ScriptGlobals)
                .GetMethod(nameof(ScriptGlobals.OnGiftWrappingChanged))!
                .GetParameters()).ParameterType);

        MethodInfo[] mcp_methods = typeof(IMcpHost).GetMethods()
            .Where(method => method.Name == nameof(IMcpHost.GetGiftsAsync))
            .OrderBy(method => method.GetParameters().Length)
            .ToArray();
        Assert.Equal(2, mcp_methods.Length);
        Assert.Equal(
            [
                typeof(bool),
                typeof(bool),
                typeof(int),
                typeof(int),
                typeof(int),
                typeof(CancellationToken)
            ],
            mcp_methods[0].GetParameters()
                .Select(parameter => parameter.ParameterType)
                .ToArray());
        Assert.Equal(
            [
                typeof(bool),
                typeof(bool),
                typeof(int),
                typeof(int),
                typeof(long?),
                typeof(int),
                typeof(CancellationToken)
            ],
            mcp_methods[1].GetParameters()
                .Select(parameter => parameter.ParameterType)
                .ToArray());
        Assert.All(mcp_methods, method => Assert.Equal(typeof(Task<string>), method.ReturnType));

        IMcpHost host = DispatchProxy.Create<IMcpHost, EmptyMcpHostProxy>();
        var proxy = Assert.IsAssignableFrom<EmptyMcpHostProxy>(host);
        var server = new McpServer(
            host,
            9391,
            new McpConfig
            {
                Token = new string('b', 32),
                AllowEditor = false
            });
        FieldInfo tools_field = typeof(McpServer).GetField(
            "_tools",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        McpTool gifts = Assert.Single(
            (IReadOnlyList<McpTool>)tools_field.GetValue(server)!,
            tool => tool.Name == "get_gifts");
        using (JsonDocument schema = JsonDocument.Parse(
            JsonSerializer.Serialize(gifts.InputSchema)))
        {
            JsonElement properties = schema.RootElement.GetProperty("properties");
            Assert.True(properties.GetProperty("fetch").GetProperty("default").GetBoolean());
            Assert.False(properties.GetProperty("detail").GetProperty("default").GetBoolean());
            Assert.Equal(25, properties.GetProperty("limit").GetProperty("default").GetInt32());
            Assert.Equal(1, properties.GetProperty("limit").GetProperty("minimum").GetInt32());
            Assert.Equal(100, properties.GetProperty("limit").GetProperty("maximum").GetInt32());
            Assert.Equal(0, properties.GetProperty("offset").GetProperty("default").GetInt32());
            Assert.Equal(
                1,
                properties.GetProperty("snapshot_revision").GetProperty("minimum").GetInt32());
            Assert.False(properties.GetProperty("snapshot_revision").TryGetProperty(
                "default",
                out _));
            Assert.Equal(
                10000,
                properties.GetProperty("timeout_ms").GetProperty("default").GetInt32());
            Assert.Equal(
                120000,
                properties.GetProperty("timeout_ms").GetProperty("maximum").GetInt32());
        }

        using (JsonDocument arguments = JsonDocument.Parse("{}"))
        {
            _ = await gifts.Handler(arguments.RootElement, CancellationToken.None);
        }
        Assert.Equal(7, proxy.LastMethod!.GetParameters().Length);
        Assert.Equal(
            [true, false, 25, 0, null, 10000],
            proxy.LastArguments.Take(6).ToArray());
        using (JsonDocument arguments = JsonDocument.Parse(
            """{"fetch":true,"detail":true,"limit":3,"offset":6,"snapshot_revision":99,"timeout_ms":1234}"""))
        {
            _ = await gifts.Handler(arguments.RootElement, CancellationToken.None);
        }
        Assert.Equal(
            [true, true, 3, 6, 99L, 1234],
            proxy.LastArguments.Take(6).ToArray());
        using (JsonDocument invalid = JsonDocument.Parse("""{"snapshot_revision":0}"""))
        {
            await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() =>
                gifts.Handler(invalid.RootElement, CancellationToken.None));
        }

        string root = FindRepositoryRoot();
        string gifts_script = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.Gifts.cs"));
        Assert.DoesNotContain("SendToServer", gifts_script, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageKeys.", gifts_script, StringComparison.Ordinal);
        Assert.Contains("Gifts.Purchase(request)", gifts_script, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.GiftsNewUserOfferList", gifts_script,
            StringComparison.Ordinal);
        string gift_events = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.GiftEvents.cs"));
        Assert.Contains("Gifts.WrappingConfigurationChanged", gift_events,
            StringComparison.Ordinal);
        Assert.Contains("Gifts.NewUserOfferChanged", gift_events, StringComparison.Ordinal);
        Assert.DoesNotContain("GiftChanged", gift_events, StringComparison.Ordinal);
        string shop = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.Shop.cs"));
        Assert.Contains("ApplicationMemberIds.GiftsPurchase", shop, StringComparison.Ordinal);
        Assert.Contains("!anonymous", shop, StringComparison.Ordinal);
        Assert.DoesNotContain("GiftPurchaseForCurrentClient", shop, StringComparison.Ordinal);
        string actions = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.Actions.cs"));
        Assert.Contains("ApplicationMemberIds.GiftsPurchase", actions, StringComparison.Ordinal);
        Assert.DoesNotContain("GiftPurchaseForCurrentClient", actions, StringComparison.Ordinal);
    }

    [Fact]
    public async Task gifts_mcp_delegate_uses_core_tokens_zero_send_and_global_detail_budget()
    {
        var fetched_runtime = new GiftMcpRuntime();
        string fetched = await ReadGiftMcp(
            fetched_runtime,
            true,
            true,
            3,
            0,
            null,
            10000);
        Assert.Equal(1, fetched_runtime.ReadinessCount);
        Assert.Equal(1, fetched_runtime.RefreshCount);
        Assert.DoesNotContain(
            fetched_runtime.ClubRequests,
            request => request.Collection is GiftClubInfoCollection.Offers);
        using (JsonDocument document = JsonDocument.Parse(fetched))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            JsonElement metadata = root.GetProperty("metadata");
            Assert.Equal(77, metadata.GetProperty("snapshotRevision").GetInt64());
            Assert.True(metadata.GetProperty("truncated").GetBoolean());
            Assert.False(metadata.TryGetProperty("nextOffset", out _));
            JsonElement data = root.GetProperty("data");
            Assert.Equal(3, data.GetProperty("total").GetInt32());
            Assert.Equal(3, data.GetProperty("returned").GetInt32());
            JsonElement detail_metadata = data.GetProperty("detailMetadata");
            Assert.Equal(1201, detail_metadata.GetProperty("total").GetInt32());
            Assert.Equal(500, detail_metadata.GetProperty("returned").GetInt32());
            Assert.Equal(500, detail_metadata.GetProperty("maxItems").GetInt32());
            Assert.True(detail_metadata.GetProperty("truncated").GetBoolean());
            JsonElement details = data.GetProperty("details");
            int nested_returned = details.EnumerateArray().Sum(offer =>
                offer.GetProperty("products").GetArrayLength() +
                offer.GetProperty("unityProductReferences").GetArrayLength() +
                offer.GetProperty("unityProducts").GetArrayLength());
            Assert.Equal(500, nested_returned);
        }
        Assert.Equal(
            [
                GiftClubInfoCollection.Products,
                GiftClubInfoCollection.UnityProductReferences,
                GiftClubInfoCollection.UnityProducts
            ],
            fetched_runtime.ClubRequests
                .Select(request => request.Collection)
                .ToArray());
        Assert.All(
            fetched_runtime.ClubRequests,
            request => Assert.Equal(77, request.SnapshotRevision));

        var continuation_runtime = new GiftMcpRuntime();
        string continuation = await ReadGiftMcp(
            continuation_runtime,
            true,
            false,
            1,
            2,
            77,
            10000);
        Assert.Equal(0, continuation_runtime.ReadinessCount);
        Assert.Equal(0, continuation_runtime.RefreshCount);
        GiftClubInfoPageRequest offer_request = Assert.Single(
            continuation_runtime.ClubRequests,
            request => request.Collection is GiftClubInfoCollection.Offers);
        Assert.Equal((2, 1, 77L),
            (offer_request.Offset, offer_request.Limit, offer_request.SnapshotRevision));
        using (JsonDocument document = JsonDocument.Parse(continuation))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            Assert.Equal(77,
                root.GetProperty("metadata").GetProperty("snapshotRevision").GetInt64());
            Assert.False(root.GetProperty("metadata").TryGetProperty("nextOffset", out _));
            Assert.Equal(2, root.GetProperty("data").GetProperty("offset").GetInt32());
            Assert.Equal(1, root.GetProperty("data").GetProperty("returned").GetInt32());
        }

        await Assert.ThrowsAsync<ArgumentException>(() => ReadGiftMcp(
            new GiftMcpRuntime(),
            true,
            false,
            1,
            1,
            null,
            10000));
        var expired_runtime = new GiftMcpRuntime();
        string expired = await ReadGiftMcp(
            expired_runtime,
            true,
            false,
            1,
            1,
            999,
            10000);
        Assert.Equal(0, expired_runtime.ReadinessCount);
        Assert.Equal(0, expired_runtime.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(expired))
        {
            Assert.Equal(
                "unavailable",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

        var drift_runtime = new GiftMcpRuntime { StateSessionGeneration = 8 };
        string drift = await ReadGiftMcp(
            drift_runtime,
            false,
            false,
            1,
            0,
            null,
            10000);
        using (JsonDocument document = JsonDocument.Parse(drift))
        {
            Assert.Equal(
                "invalid_response",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

        var timeout_runtime = new GiftMcpRuntime
        {
            Readiness = token => Task.Delay(Timeout.Infinite, token)
        };
        string timeout = await ReadGiftMcp(
            timeout_runtime,
            true,
            false,
            1,
            0,
            null,
            20);
        Assert.Equal(1, timeout_runtime.ReadinessCount);
        Assert.Equal(0, timeout_runtime.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(timeout))
        {
            Assert.Equal(
                "timeout",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
            Assert.Equal(3,
                document.RootElement.GetProperty("data").GetProperty("total").GetInt32());
        }
        var error_runtime = new GiftMcpRuntime
        {
            RefreshOverride = (_, _) => ValueTask.FromException<GiftRefreshResult>(
                new TimeoutException("gift refresh timeout"))
        };
        string refresh_error = await ReadGiftMcp(
            error_runtime,
            true,
            false,
            1,
            0,
            null,
            10000);
        Assert.Equal(1, error_runtime.ReadinessCount);
        Assert.Equal(1, error_runtime.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(refresh_error))
        {
            Assert.Equal(
                "timeout",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
            Assert.Equal(3,
                document.RootElement.GetProperty("data").GetProperty("total").GetInt32());
        }

        string root_path = FindRepositoryRoot();
        string hosting = File.ReadAllText(Path.Combine(
            root_path,
            "src",
            "QX.Hosting",
            "Mcp",
            "McpHost.cs"));
        Assert.Contains("ApplicationMemberIds.GiftsRefresh", hosting, StringComparison.Ordinal);
        Assert.Contains("GiftDetailEntryLimit = 500", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("game.Gifts", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("gift_leases", hosting, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("GiftSnapshotLease", hosting, StringComparison.Ordinal);
    }

    [Fact]
    public void crafting_state_leases_descriptors_and_passive_payloads_are_stable()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.EnterRoom(400);

        (string id, ApplicationMemberKind kind, Type? request, Type result)[] expected =
        [
            ("crafting.state", ApplicationMemberKind.Query,
                typeof(CraftingStateRequest), typeof(CraftingStateView)),
            ("crafting.products.list", ApplicationMemberKind.Query,
                typeof(CraftingProductsPageRequest), typeof(CraftingProductsPage)),
            ("crafting.recipe.list", ApplicationMemberKind.Query,
                typeof(CraftingRecipePageRequest), typeof(CraftingRecipePage)),
            ("crafting.products.refresh", ApplicationMemberKind.Operation,
                typeof(CraftingProductsRefreshRequest), typeof(CraftingProductsRefreshResult)),
            ("crafting.recipe.refresh", ApplicationMemberKind.Operation,
                typeof(CraftingRecipeRefreshRequest), typeof(CraftingRecipeRefreshResult)),
            ("crafting.availability.refresh", ApplicationMemberKind.Operation,
                typeof(CraftingAvailabilityRefreshRequest), typeof(CraftingAvailabilityRefreshResult)),
            ("crafting.craft", ApplicationMemberKind.Operation,
                typeof(CraftingCraftRequest), typeof(CraftingCraftDispatchReceipt)),
            ("crafting.secret_craft", ApplicationMemberKind.Operation,
                typeof(CraftingSecretCraftRequest), typeof(CraftingSecretCraftDispatchReceipt)),
            ("crafting.changed", ApplicationMemberKind.Event,
                null, typeof(CraftingChanged))
        ];
        Assert.All(expected, value =>
        {
            ApplicationDescriptor descriptor = Assert.Single(
                fixture.Application.Members,
                candidate => candidate.Id == value.id);
            Assert.Equal(value.kind, descriptor.Kind);
            Assert.Equal(value.request, descriptor.RequestType);
            Assert.Equal(value.result, descriptor.ResultType);
            Assert.Equal(
                value.kind is ApplicationMemberKind.Event
                    ? ApplicationExposure.Ui | ApplicationExposure.Cli | ApplicationExposure.Scripting
                    : ApplicationExposure.All,
                descriptor.Exposure);
            Assert.Equal(
                value.kind is ApplicationMemberKind.Operation
                    ? [ApplicationStateKey.HotelConnected, ApplicationStateKey.RoomReady]
                    : [],
                descriptor.RequiredStates);
            ApplicationClientAvailability[] clients = fixture.Application
                .Describe(value.id)
                .Availability
                .Clients
                .ToArray();
            Assert.Equal(
                [ClientType.Flash, ClientType.Unity],
                clients.Select(candidate => candidate.Client).ToArray());
            Assert.All(clients, candidate => Assert.True(candidate.Supported));
        });
        CraftingProduct[] source_products =
        [
            new("recipe-1", "product-1", "chair-1"),
            new("recipe-2", "product-2", "chair-2")
        ];
        string[] source_usable = ["chair-1", "chair-2"];
        CraftingIngredient[] source_ingredients =
        [
            new(1, "chair-1"),
            new(2, "chair-2")
        ];
        var products = new CraftableProducts(source_products, source_usable);
        var recipe = new CraftingRecipe(source_ingredients);
        var result = new CraftingResult(true, source_products[0]);
        var availability = new CraftingRecipesAvailable(3, true);
        Assert.False(fixture.Receive(MessageContracts.Crafting.ProductsSnapshot, products));
        Assert.False(fixture.Receive(MessageContracts.Crafting.RecipeSnapshot, recipe));
        Assert.False(fixture.Receive(MessageContracts.Crafting.Result, result));
        Assert.False(fixture.Receive(MessageContracts.Crafting.AvailabilitySnapshot, availability));
        source_products[0] = new("mutated", "mutated", "mutated");
        source_usable[0] = "mutated";
        source_ingredients[0] = new(99, "mutated");

        CraftingStateView state = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest());
        Assert.True(state.Connected);
        Assert.Equal(ClientType.Flash, state.Client);
        Assert.Equal(2, state.Products!.ProductCount);
        Assert.Equal(2, state.Products.UsableInventoryFurnitureClassCount);
        Assert.Equal(2, state.Recipe!.IngredientCount);
        Assert.Equal(result, state.LastResult);
        Assert.Equal(availability, state.AvailableRecipes);
        Assert.True(state.SnapshotRevision > 0);

        CraftingProductsPage first = fixture.Application.Invoke<
            CraftingProductsPageRequest,
            CraftingProductsPage>(
            ApplicationMemberIds.CraftingProductsList,
            new CraftingProductsPageRequest(
                CraftingProductsCollection.Products,
                0,
                1,
                state.SnapshotRevision));
        Assert.Equal("recipe-1", Assert.Single(first.Products).RecipeCode);
        Assert.Equal(1, first.NextOffset);
        CraftingProductsPage usable = fixture.Application.Invoke<
            CraftingProductsPageRequest,
            CraftingProductsPage>(
            ApplicationMemberIds.CraftingProductsList,
            new CraftingProductsPageRequest(
                CraftingProductsCollection.UsableInventoryFurnitureClasses,
                0,
                2,
                state.SnapshotRevision));
        Assert.Equal(["chair-1", "chair-2"], usable.UsableInventoryFurnitureClasses);
        CraftingRecipePage ingredients = fixture.Application.Invoke<
            CraftingRecipePageRequest,
            CraftingRecipePage>(
            ApplicationMemberIds.CraftingRecipeList,
            new CraftingRecipePageRequest(0, 2, state.SnapshotRevision));
        Assert.Equal("chair-1", ingredients.Ingredients[0].FurnitureClassName);

        fixture.Receive(
            MessageContracts.Crafting.ProductsSnapshot,
            new CraftableProducts([new("new", "new", "new")], ["new"]));
        CraftingProductsPage retained = fixture.Application.Invoke<
            CraftingProductsPageRequest,
            CraftingProductsPage>(
            ApplicationMemberIds.CraftingProductsList,
            new CraftingProductsPageRequest(
                CraftingProductsCollection.Products,
                1,
                1,
                state.SnapshotRevision));
        Assert.Equal("recipe-2", Assert.Single(retained.Products).RecipeCode);

        long first_revision = state.SnapshotRevision;
        for (int index = 0; index < 5; index++)
        {
            fixture.Receive(
                MessageContracts.Crafting.AvailabilitySnapshot,
                new CraftingRecipesAvailable(index, false));
            _ = fixture.Application.Invoke<CraftingStateRequest, CraftingStateView>(
                ApplicationMemberIds.CraftingState,
                new CraftingStateRequest());
        }
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest(first_revision)));

        var isolated_changes = new List<CraftingChanged>();
        using IDisposable failing_observer = fixture.Application.Subscribe<CraftingChanged>(
            ApplicationMemberIds.CraftingChanged,
            _ => throw new InvalidOperationException("observer failure"));
        using IDisposable stable_observer = fixture.Application.Subscribe<CraftingChanged>(
            ApplicationMemberIds.CraftingChanged,
            isolated_changes.Add);
        fixture.Receive(
            MessageContracts.Crafting.AvailabilitySnapshot,
            new CraftingRecipesAvailable(99, true));
        Assert.Equal(CraftingChangeKind.Availability, Assert.Single(isolated_changes).Kind);
        CraftingStateView reset_state = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest());
        int legacy_resets = 0;
        fixture.Crafting.ResetCompleted += () => legacy_resets++;
        fixture.Disconnect();
        Assert.Equal(1, legacy_resets);
        Assert.Equal(CraftingChangeKind.Reset, isolated_changes[^1].Kind);
        Assert.Null(isolated_changes[^1].Client);
        CraftingStateView disconnected = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest());
        Assert.False(disconnected.Connected);
        Assert.Null(disconnected.Products);
        Assert.Null(disconnected.Recipe);
        Assert.Null(disconnected.LastResult);
        Assert.Null(disconnected.AvailableRecipes);
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest(reset_state.SnapshotRevision)));
    }

