    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.EnterRoom(401);
        using ScriptGlobals globals = fixture.CreateGlobals();

        Assert.Equal(
            typeof(CraftingManager),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.Crafting))!.PropertyType);
        Assert.Equal(
            typeof(CraftableProducts),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.CraftableProducts))!
                .PropertyType);
        Assert.Equal(
            typeof(CraftingRecipe),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.CurrentCraftingRecipe))!
                .PropertyType);
        Assert.Equal(
            typeof(CraftingResult),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.LastCraftingResult))!
                .PropertyType);
        Assert.Equal(
            typeof(CraftingRecipesAvailable),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.AvailableCraftingRecipes))!
                .PropertyType);
        (string name, Type[] parameters)[] manager_methods =
        [
            (nameof(CraftingManager.RequestProducts), [typeof(Id)]),
            (nameof(CraftingManager.RequestRecipe), [typeof(string)]),
            (nameof(CraftingManager.Craft), [typeof(Id), typeof(string)]),
            (nameof(CraftingManager.CraftSecret),
                [typeof(Id), typeof(IReadOnlyList<Id>)]),
            (nameof(CraftingManager.RequestAvailableRecipes),
                [typeof(Id), typeof(IReadOnlyList<Id>)])
        ];
        Assert.All(manager_methods, expected_method =>
        {
            MethodInfo method = Assert.Single(
                typeof(CraftingManager).GetMethods(),
                candidate => candidate.Name == expected_method.name);
            Assert.Equal(
                expected_method.parameters,
                method.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
            Assert.All(method.GetParameters(), parameter => Assert.False(parameter.IsOptional));
            Assert.Equal(typeof(void), method.ReturnType);
        });
        Assert.Equal(
            typeof(Action<CraftableProducts>),
            typeof(CraftingManager).GetEvent(nameof(CraftingManager.ProductsReceived))!
                .EventHandlerType);
        Assert.Equal(
            typeof(Action<CraftingRecipe>),
            typeof(CraftingManager).GetEvent(nameof(CraftingManager.RecipeReceived))!
                .EventHandlerType);
        Assert.Equal(
            typeof(Action<CraftingResult>),
            typeof(CraftingManager).GetEvent(nameof(CraftingManager.ResultReceived))!
                .EventHandlerType);
        Assert.Equal(
            typeof(Action<CraftingRecipesAvailable>),
            typeof(CraftingManager).GetEvent(nameof(CraftingManager.AvailableRecipesReceived))!
                .EventHandlerType);
        Assert.Equal(
            typeof(Action),
            typeof(CraftingManager).GetEvent(nameof(CraftingManager.ResetCompleted))!
                .EventHandlerType);
        Assert.Equal(
            [typeof(Id)],
            Assert.Single(typeof(ScriptGlobals).GetMethods(),
                    method => method.Name == nameof(ScriptGlobals.RequestCraftableProducts))
                .GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [typeof(string)],
            Assert.Single(typeof(ScriptGlobals).GetMethods(),
                    method => method.Name == nameof(ScriptGlobals.RequestCraftingRecipe))
                .GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [typeof(Id), typeof(string)],
            Assert.Single(typeof(ScriptGlobals).GetMethods(),
                    method => method.Name == nameof(ScriptGlobals.Craft))
                .GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        MethodInfo secret = Assert.Single(
            typeof(ScriptGlobals).GetMethods(),
            method => method.Name == nameof(ScriptGlobals.CraftSecret));
        Assert.Equal([typeof(Id), typeof(Id[])], secret.GetParameters()
            .Select(parameter => parameter.ParameterType).ToArray());
        Assert.NotNull(secret.GetParameters()[1].GetCustomAttribute<ParamArrayAttribute>());
        Assert.Equal(
            [typeof(Id), typeof(Id[])],
            Assert.Single(typeof(ScriptGlobals).GetMethods(),
                    method => method.Name == nameof(ScriptGlobals.RequestCraftingRecipesAvailable))
                .GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.All(
            new[]
            {
                nameof(ScriptGlobals.OnCraftableProducts),
                nameof(ScriptGlobals.OnCraftingRecipe),
                nameof(ScriptGlobals.OnCraftingResult),
                nameof(ScriptGlobals.OnCraftingRecipesAvailable),
                nameof(ScriptGlobals.OnCraftingReset)
            },
            name => Assert.Equal(
                typeof(IDisposable),
                Assert.Single(typeof(ScriptGlobals).GetMethods(), method => method.Name == name)
                    .ReturnType));
        Assert.Equal(
            typeof(Action<CraftableProducts>),
            Assert.Single(typeof(ScriptGlobals).GetMethod(
                nameof(ScriptGlobals.OnCraftableProducts))!.GetParameters()).ParameterType);
        Assert.Equal(
            typeof(Action<CraftingRecipe>),
            Assert.Single(typeof(ScriptGlobals).GetMethod(
                nameof(ScriptGlobals.OnCraftingRecipe))!.GetParameters()).ParameterType);
        Assert.Equal(
            typeof(Action<CraftingResult>),
            Assert.Single(typeof(ScriptGlobals).GetMethod(
                nameof(ScriptGlobals.OnCraftingResult))!.GetParameters()).ParameterType);
        Assert.Equal(
            typeof(Action<CraftingRecipesAvailable>),
            Assert.Single(typeof(ScriptGlobals).GetMethod(
                nameof(ScriptGlobals.OnCraftingRecipesAvailable))!.GetParameters()).ParameterType);
        Assert.Equal(
            typeof(Action),
            Assert.Single(typeof(ScriptGlobals).GetMethod(
                nameof(ScriptGlobals.OnCraftingReset))!.GetParameters()).ParameterType);
        Assert.All(
            typeof(ScriptGlobals).GetMethods()
                .Where(method => method.Name is
                    nameof(ScriptGlobals.RequestCraftableProducts) or
                    nameof(ScriptGlobals.RequestCraftingRecipe) or
                    nameof(ScriptGlobals.Craft) or
                    nameof(ScriptGlobals.CraftSecret) or
                    nameof(ScriptGlobals.RequestCraftingRecipesAvailable))
                .SelectMany(method => method.GetParameters()),
            parameter => Assert.False(parameter.IsOptional));

        globals.RequestCraftableProducts(0);
        globals.RequestCraftingRecipe("");
        globals.Craft(0, "");
        globals.CraftSecret(0);
        globals.RequestCraftingRecipesAvailable(0);
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.RecipeRequest));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.Craft));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.SecretCraft));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.AvailabilityRequest));
        Assert.Equal((Id)0, fixture.LastCraftingProductsRequest!.CraftingFurnitureId);
        Assert.Equal("", fixture.LastCraftingRecipeRequest!.RecipeCode);
        Assert.Equal(((Id)0, ""),
            (fixture.LastCraftRequest!.CraftingFurnitureId,
                fixture.LastCraftRequest.RecipeCode));
        Assert.Equal((Id)0, fixture.LastSecretCraftRequest!.CraftingFurnitureId);
        Assert.Empty(fixture.LastSecretCraftRequest.IngredientItemIds);
        Assert.Equal((Id)0, fixture.LastCraftingAvailabilityRequest!.CraftingFurnitureId);
        Assert.Empty(fixture.LastCraftingAvailabilityRequest.IngredientItemIds);

        CraftableProducts? observed_products = null;
        CraftingRecipe? observed_recipe = null;
        CraftingResult? observed_result = null;
        CraftingRecipesAvailable? observed_availability = null;
        using IDisposable products_subscription = globals.OnCraftableProducts(
            value => observed_products = value);
        using IDisposable recipe_subscription = globals.OnCraftingRecipe(
            value => observed_recipe = value);
        using IDisposable result_subscription = globals.OnCraftingResult(
            value => observed_result = value);
        using IDisposable availability_subscription = globals.OnCraftingRecipesAvailable(
            value => observed_availability = value);
        fixture.Receive(
            MessageContracts.Crafting.ProductsSnapshot,
            new CraftableProducts([new("r", "p", "f")], ["f"]));
        fixture.Receive(
            MessageContracts.Crafting.RecipeSnapshot,
            new CraftingRecipe([new CraftingIngredient(1, "f")]));
        fixture.Receive(
            MessageContracts.Crafting.Result,
            new CraftingResult(true, new CraftingProduct("r", "p", "f")));
        fixture.Receive(
            MessageContracts.Crafting.AvailabilitySnapshot,
            new CraftingRecipesAvailable(1, true));
        Assert.Same(globals.CraftableProducts, observed_products);
        Assert.Same(globals.CurrentCraftingRecipe, observed_recipe);
        Assert.Same(globals.LastCraftingResult, observed_result);
        Assert.Same(globals.AvailableCraftingRecipes, observed_availability);

        long reset_token = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest()).SnapshotRevision;
        int resets = 0;
        using IDisposable reset_subscription = globals.OnCraftingReset(() => resets++);
        int isolated_legacy_calls = 0;
        void failing_legacy(CraftableProducts _)
        {
            fixture.Disconnect();
            throw new InvalidOperationException("legacy observer failure");
        }
        void stable_legacy(CraftableProducts _) => isolated_legacy_calls++;
        fixture.Crafting.ProductsReceived += failing_legacy;
        fixture.Crafting.ProductsReceived += stable_legacy;
        Assert.False(fixture.Receive(
            MessageContracts.Crafting.ProductsSnapshot,
            new CraftableProducts([new("isolated", "isolated", "isolated")], [])));
        fixture.Crafting.ProductsReceived -= failing_legacy;
        fixture.Crafting.ProductsReceived -= stable_legacy;
        Assert.Equal(0, isolated_legacy_calls);
        Assert.Equal(1, resets);
        Assert.Null(globals.CraftableProducts);
        Assert.Null(globals.CurrentCraftingRecipe);
        Assert.Null(globals.LastCraftingResult);
        Assert.Null(globals.AvailableCraftingRecipes);
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest(reset_token)));
    }

    [Theory]
