            CraftingRecipeRefreshResult>(
            ApplicationMemberIds.CraftingRecipeRefresh,
            new CraftingRecipeRefreshRequest("fresh", 1));
        Assert.Equal("chair", Assert.Single(recipe.FirstPage.Ingredients).FurnitureClassName);
        CraftingAvailabilityRefreshResult availability = await fixture.Application.InvokeAsync<
            CraftingAvailabilityRefreshRequest,
            CraftingAvailabilityRefreshResult>(
            ApplicationMemberIds.CraftingAvailabilityRefresh,
            new CraftingAvailabilityRefreshRequest(9, [10, 11]));
        Assert.Equal(1, availability.AvailableRecipes.Count);
        CraftingCraftDispatchReceipt craft = await fixture.Application.InvokeAsync<
            CraftingCraftRequest,
            CraftingCraftDispatchReceipt>(
            ApplicationMemberIds.CraftingCraft,
            new CraftingCraftRequest(12, "craft-recipe"));
        CraftingSecretCraftDispatchReceipt secret = await fixture.Application.InvokeAsync<
            CraftingSecretCraftRequest,
            CraftingSecretCraftDispatchReceipt>(
            ApplicationMemberIds.CraftingSecretCraft,
            new CraftingSecretCraftRequest(13, [14, 15]));
        Assert.Equal(1, craft.MessagesDispatched);
        Assert.Equal(1, secret.MessagesDispatched);
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.RecipeRequest));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.AvailabilityRequest));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.Craft));
        Assert.Equal(1, fixture.CraftingRequestCount(MessageKeys.Crafting.SecretCraft));
        Assert.Equal((Id)7, fixture.LastCraftingProductsRequest!.CraftingFurnitureId);
        Assert.Equal("fresh", fixture.LastCraftingRecipeRequest!.RecipeCode);
        Assert.Equal((Id)9,
            fixture.LastCraftingAvailabilityRequest!.CraftingFurnitureId);
        Assert.Equal(
            new Id[] { 10, 11 },
