        Assert.Equal(((Id)12, "craft-recipe"),
            (fixture.LastCraftRequest!.CraftingFurnitureId,
                fixture.LastCraftRequest.RecipeCode));
        Assert.Equal((Id)13, fixture.LastSecretCraftRequest!.CraftingFurnitureId);
        Assert.Equal(new Id[] { 14, 15 }, fixture.LastSecretCraftRequest.IngredientItemIds);
    }

    [Fact]
    public async Task crafting_same_route_refreshes_are_serialized()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.EnterRoom(405);
        using var first_before_guard = new ManualResetEventSlim();
        using var release_first = new ManualResetEventSlim();
        const int request_timeout_ms = 10_000;
        TimeSpan synchronization_timeout = TimeSpan.FromSeconds(10);
        int dispatches = 0;
        fixture.BeforeCraftingDispatch = key =>
        {
            if (key != MessageKeys.Crafting.ProductsRequest ||
                Interlocked.Increment(ref dispatches) != 1)
            {
                return;
            }
            first_before_guard.Set();
            if (!release_first.Wait(synchronization_timeout))
                throw new TimeoutException("The first crafting dispatch was not released.");
        };
        Task<CraftingProductsRefreshResult> first = Task.Run(async () =>
            await fixture.Application.InvokeAsync<
                CraftingProductsRefreshRequest,
                CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(21, 1, request_timeout_ms)));
        Assert.True(first_before_guard.Wait(synchronization_timeout));
        using var queued_started = new ManualResetEventSlim();
        Thread? queued_thread = null;
        Task<CraftingProductsRefreshResult> queued;
        try
        {
            queued = Task.Run(() =>
            {
                queued_thread = Thread.CurrentThread;
                queued_started.Set();
                return fixture.Application.InvokeAsync<
                    CraftingProductsRefreshRequest,
                    CraftingProductsRefreshResult>(
                    ApplicationMemberIds.CraftingProductsRefresh,
                    new CraftingProductsRefreshRequest(22, 1, request_timeout_ms))
                    .AsTask()
                    .GetAwaiter()
                    .GetResult();
            });
            Assert.True(queued_started.Wait(synchronization_timeout));
            Assert.True(SpinWait.SpinUntil(
                () => queued_thread is not null &&
                    (queued_thread.ThreadState &
                        System.Threading.ThreadState.WaitSleepJoin) != 0,
                synchronization_timeout));
            Assert.Equal(0,
                fixture.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));
        }
        finally
        {
            release_first.Set();
        }
        Task first_sent = fixture.WaitForCraftingRequestCount(
            MessageKeys.Crafting.ProductsRequest,
            1);
        Task first_progress = await Task.WhenAny(first, first_sent)
            .WaitAsync(synchronization_timeout);
        if (ReferenceEquals(first_progress, first))
            _ = await first;
        await first_sent;

        fixture.Receive(
            MessageContracts.Crafting.ProductsSnapshot,
            new CraftableProducts([new("first", "first", "first")], []));
        CraftingProductsRefreshResult first_result = await first.WaitAsync(
            synchronization_timeout);
        Assert.Equal((Id)21, first_result.RequestedCraftingFurnitureId);
        Assert.Equal("first", Assert.Single(first_result.FirstPage.Products).RecipeCode);
        await fixture.WaitForCraftingRequestCount(
            MessageKeys.Crafting.ProductsRequest,
            2).WaitAsync(synchronization_timeout);
        fixture.Receive(
            MessageContracts.Crafting.ProductsSnapshot,
            new CraftableProducts([new("second", "second", "second")], []));
        CraftingProductsRefreshResult second_result = await queued.WaitAsync(
            synchronization_timeout);
        Assert.Equal((Id)22, second_result.RequestedCraftingFurnitureId);
        Assert.Equal("second", Assert.Single(second_result.FirstPage.Products).RecipeCode);
        Assert.Equal(2, fixture.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));
    }

    [Fact]
    public async Task crafting_dispatch_guards_reject_generation_and_actual_scope_drift()
    {
        using (var expected = new SurfaceFixture(ClientType.Flash))
        {
            expected.EnterRoom(406);
            CraftingStateView state = expected.Application.Invoke<
                CraftingStateRequest,
                CraftingStateView>(
                ApplicationMemberIds.CraftingState,
                new CraftingStateRequest());
            await Assert.ThrowsAsync<InvalidOperationException>(() => expected.Application
                .InvokeAsync<CraftingCraftRequest, CraftingCraftDispatchReceipt>(
                    ApplicationMemberIds.CraftingCraft,
                    new CraftingCraftRequest(
                        1,
                        "recipe",
                        state.SessionGeneration + 1,
                        expected.RoomGeneration))
                .AsTask());
            await Assert.ThrowsAsync<InvalidOperationException>(() => expected.Application
                .InvokeAsync<CraftingCraftRequest, CraftingCraftDispatchReceipt>(
                    ApplicationMemberIds.CraftingCraft,
                    new CraftingCraftRequest(
                        1,
                        "recipe",
                        state.SessionGeneration,
                        expected.RoomGeneration + 1))
                .AsTask());
            Assert.Equal(0, expected.CraftingRequestCount(MessageKeys.Crafting.Craft));
        }

        using (var session_drift = new SurfaceFixture(ClientType.Flash))
        {
            session_drift.EnterRoom(407);
            session_drift.BeforeCraftingDispatch = _ => session_drift.Disconnect();
            await Assert.ThrowsAsync<InvalidOperationException>(() => session_drift.Application
                .InvokeAsync<CraftingCraftRequest, CraftingCraftDispatchReceipt>(
                    ApplicationMemberIds.CraftingCraft,
                    new CraftingCraftRequest(1, "recipe"))
                .AsTask());
            Assert.Equal(0, session_drift.CraftingRequestCount(MessageKeys.Crafting.Craft));
        }

        using (var room_drift = new SurfaceFixture(ClientType.Unity))
        {
            room_drift.EnterRoom(408);
            long room_generation = room_drift.RoomGeneration;
            room_drift.BeforeCraftingDispatch = _ =>
                room_drift.AddFloorItem(CreateFloorItem(909, 1, 1, 1, 0));
            await Assert.ThrowsAsync<InvalidOperationException>(() => room_drift.Application
                .InvokeAsync<CraftingSecretCraftRequest, CraftingSecretCraftDispatchReceipt>(
                    ApplicationMemberIds.CraftingSecretCraft,
                    new CraftingSecretCraftRequest(1, [2]))
                .AsTask());
            Assert.Equal(room_generation, room_drift.RoomGeneration);
            Assert.Equal(0,
                room_drift.CraftingRequestCount(MessageKeys.Crafting.SecretCraft));
        }
    }

    [Fact]
    public async Task crafting_actions_share_result_epoch_without_waiting_for_results()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.EnterRoom(410);
        CraftingStateView before = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest());
        ValueTask<CraftingCraftDispatchReceipt> immediate = fixture.Application.InvokeAsync<
            CraftingCraftRequest,
            CraftingCraftDispatchReceipt>(
            ApplicationMemberIds.CraftingCraft,
            new CraftingCraftRequest(30, "known"));
        Assert.True(immediate.IsCompletedSuccessfully);
        CraftingCraftDispatchReceipt receipt = await immediate;
        Assert.Equal(1, receipt.MessagesDispatched);
        CraftingStateView after = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest());
        Assert.Equal(before.ResultRevision, after.ResultRevision);
        Assert.Null(after.LastResult);

        fixture.BeforeCraftingDispatch = key =>
        {
            if (key != MessageKeys.Crafting.SecretCraft)
                return;
            fixture.BeforeCraftingDispatch = null;
            fixture.Crafting.Craft(31, "foreign");
        };
        await Assert.ThrowsAsync<InvalidOperationException>(() => fixture.Application
            .InvokeAsync<CraftingSecretCraftRequest, CraftingSecretCraftDispatchReceipt>(
                ApplicationMemberIds.CraftingSecretCraft,
                new CraftingSecretCraftRequest(32, [33]))
            .AsTask());
        Assert.Equal(2, fixture.CraftingRequestCount(MessageKeys.Crafting.Craft));
        Assert.Equal(0, fixture.CraftingRequestCount(MessageKeys.Crafting.SecretCraft));
        fixture.Receive(
            MessageContracts.Crafting.Result,
            new CraftingResult(true, new CraftingProduct("r", "p", "f")));
        CraftingStateView observed = fixture.Application.Invoke<
            CraftingStateRequest,
            CraftingStateView>(
            ApplicationMemberIds.CraftingState,
            new CraftingStateRequest());
        Assert.Equal(before.ResultRevision + 1, observed.ResultRevision);
        Assert.NotNull(observed.LastResult);
    }

    [Fact]
    public async Task crafting_refresh_rejects_prearm_and_intervening_requests_without_retry()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.EnterRoom(403);
        fixture.BeforeCraftingDispatch = key =>
        {
            if (key != MessageKeys.Crafting.ProductsRequest)
                return;
            fixture.BeforeCraftingDispatch = null;
            fixture.Receive(
                MessageContracts.Crafting.ProductsSnapshot,
                new CraftableProducts([new("stale", "stale", "stale")], []));
        };
        fixture.AfterCraftingDispatch = key =>
        {
            if (key == MessageKeys.Crafting.ProductsRequest)
            {
                fixture.Receive(
                    MessageContracts.Crafting.ProductsSnapshot,
                    new CraftableProducts([new("fresh", "fresh", "fresh")], []));
            }
        };
        CraftingProductsRefreshResult fresh = await fixture.Application.InvokeAsync<
            CraftingProductsRefreshRequest,
            CraftingProductsRefreshResult>(
            ApplicationMemberIds.CraftingProductsRefresh,
            new CraftingProductsRefreshRequest(7, 1));
        Assert.Equal("fresh", Assert.Single(fresh.FirstPage.Products).RecipeCode);

        fixture.AfterCraftingDispatch = key =>
        {
            if (key != MessageKeys.Crafting.ProductsRequest)
                return;
            fixture.AfterCraftingDispatch = null;
            fixture.Crafting.RequestProducts(8);
            fixture.Receive(
                MessageContracts.Crafting.ProductsSnapshot,
                new CraftableProducts([new("foreign", "foreign", "foreign")], []));
        };
        Task<CraftingProductsRefreshResult> rejected = fixture.Application.InvokeAsync<
                CraftingProductsRefreshRequest,
                CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(
                    7,
                    1,
                    test_refusal_timeout_ms))
            .AsTask();
        await fixture.WaitForCraftingRequestCount(
            MessageKeys.Crafting.ProductsRequest,
            3).WaitAsync(test_synchronization_timeout);
        await Assert.ThrowsAsync<RequestTimeoutException>(() => rejected);
        Assert.Equal(3, fixture.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));

        using var no_room = new SurfaceFixture(ClientType.Flash);
        await Assert.ThrowsAsync<ApplicationUnavailableException>(() => no_room.Application.InvokeAsync<
                CraftingProductsRefreshRequest,
                CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(7))
            .AsTask());
        Assert.Throws<InvalidOperationException>(() => no_room.Crafting.RequestProducts(0));
        Assert.Equal(0, no_room.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));

        using var cancelled = new SurfaceFixture(ClientType.Flash);
        cancelled.EnterRoom(404);
        using var cancellation = new CancellationTokenSource();
        Task<CraftingProductsRefreshResult> pending = cancelled.Application.InvokeAsync<
                CraftingProductsRefreshRequest,
                CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(7, TimeoutMilliseconds: 10000),
                cancellation.Token)
            .AsTask();
        await cancelled.WaitForCraftingRequestCount(
            MessageKeys.Crafting.ProductsRequest,
            1).WaitAsync(test_synchronization_timeout);
        cancellation.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => pending);
        Assert.Equal(1, cancelled.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));

        using var disconnected = new SurfaceFixture(ClientType.Flash);
        disconnected.EnterRoom(411);
        Task<CraftingProductsRefreshResult> disconnected_first = disconnected.Application
            .InvokeAsync<CraftingProductsRefreshRequest, CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(7, TimeoutMilliseconds: 10000))
            .AsTask();
        await disconnected.WaitForCraftingRequestCount(
            MessageKeys.Crafting.ProductsRequest,
            1).WaitAsync(test_synchronization_timeout);
        Task<CraftingProductsRefreshResult> disconnected_queued = disconnected.Application
            .InvokeAsync<CraftingProductsRefreshRequest, CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(8, TimeoutMilliseconds: 10000))
            .AsTask();
        await Task.Yield();
        disconnected.Disconnect();
        await Assert.ThrowsAsync<RequestDisconnectedException>(() => disconnected_first.WaitAsync(
            test_synchronization_timeout));
        await Assert.ThrowsAsync<RequestDisconnectedException>(() => disconnected_queued.WaitAsync(
            test_synchronization_timeout));
        Assert.Equal(1,
            disconnected.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));

        using var disposed = new SurfaceFixture(ClientType.Flash);
        disposed.EnterRoom(412);
        Task<CraftingProductsRefreshResult> disposed_first = disposed.Application
            .InvokeAsync<CraftingProductsRefreshRequest, CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(7, TimeoutMilliseconds: 10000))
            .AsTask();
        await disposed.WaitForCraftingRequestCount(
            MessageKeys.Crafting.ProductsRequest,
            1).WaitAsync(test_synchronization_timeout);
        Task<CraftingProductsRefreshResult> disposed_queued = disposed.Application
            .InvokeAsync<CraftingProductsRefreshRequest, CraftingProductsRefreshResult>(
                ApplicationMemberIds.CraftingProductsRefresh,
                new CraftingProductsRefreshRequest(8, TimeoutMilliseconds: 10000))
            .AsTask();
        await Task.Yield();
        disposed.Application.Dispose();
        await Assert.ThrowsAsync<ObjectDisposedException>(() => disposed_first.WaitAsync(
            test_synchronization_timeout));
        await Assert.ThrowsAsync<ObjectDisposedException>(() => disposed_queued.WaitAsync(
            test_synchronization_timeout));
        Assert.Equal(1, disposed.CraftingRequestCount(MessageKeys.Crafting.ProductsRequest));
    }

    [Fact]
    public async Task crafting_mcp_abi_schema_and_application_only_helper_are_stable()
    {
        MethodInfo[] methods = typeof(IMcpHost).GetMethods()
            .Where(method => method.Name == nameof(IMcpHost.GetCraftingAsync))
            .OrderBy(method => method.GetParameters().Length)
            .ToArray();
        Assert.Equal(2, methods.Length);
        Assert.Equal(
            [
                typeof(bool),
                typeof(long),
                typeof(int),
                typeof(int),
                typeof(int),
                typeof(CancellationToken)
            ],
            methods[0].GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [
                typeof(bool),
                typeof(long),
                typeof(int),
                typeof(int),
                typeof(long?),
                typeof(int),
                typeof(CancellationToken)
            ],
            methods[1].GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.All(methods, method => Assert.Equal(typeof(Task<string>), method.ReturnType));

        IMcpHost host = DispatchProxy.Create<IMcpHost, EmptyMcpHostProxy>();
        var proxy = Assert.IsAssignableFrom<EmptyMcpHostProxy>(host);
        var server = new McpServer(
            host,
            9392,
            new McpConfig
            {
                Token = new string('c', 32),
                AllowEditor = false
            });
        FieldInfo tools_field = typeof(McpServer).GetField(
            "_tools",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        McpTool crafting = Assert.Single(
            (IReadOnlyList<McpTool>)tools_field.GetValue(server)!,
            tool => tool.Name == "get_crafting");
        Assert.Contains("latest observed recipe ingredients", crafting.Description,
            StringComparison.Ordinal);
        Assert.Contains("first fresh products-route response", crafting.Description,
            StringComparison.Ordinal);
        Assert.Contains("request metadata", crafting.Description, StringComparison.Ordinal);
        Assert.Contains("does not echo", crafting.Description, StringComparison.Ordinal);
        using (JsonDocument schema = JsonDocument.Parse(
            JsonSerializer.Serialize(crafting.InputSchema)))
        {
            JsonElement properties = schema.RootElement.GetProperty("properties");
            Assert.True(properties.GetProperty("fetch").GetProperty("default").GetBoolean());
            Assert.False(properties.GetProperty("furni_id").TryGetProperty("default", out _));
            Assert.Equal(50, properties.GetProperty("limit").GetProperty("default").GetInt32());
            Assert.Equal(1, properties.GetProperty("limit").GetProperty("minimum").GetInt32());
            Assert.Equal(200, properties.GetProperty("limit").GetProperty("maximum").GetInt32());
            Assert.Equal(0, properties.GetProperty("offset").GetProperty("default").GetInt32());
            Assert.Equal(
                1,
                properties.GetProperty("snapshot_revision").GetProperty("minimum").GetInt32());
            Assert.False(properties.GetProperty("snapshot_revision").TryGetProperty(
                "default",
                out _));
            Assert.Equal(
                10000,
                properties.GetProperty("timeout_ms").GetProperty("default").GetInt32());
            Assert.Equal(
                120000,
                properties.GetProperty("timeout_ms").GetProperty("maximum").GetInt32());
            Assert.Contains(
                "response does not echo",
                properties.GetProperty("furni_id").GetProperty("description").GetString(),
                StringComparison.Ordinal);
        }

        using (JsonDocument arguments = JsonDocument.Parse("{}"))
            _ = await crafting.Handler(arguments.RootElement, CancellationToken.None);
        Assert.Equal(7, proxy.LastMethod!.GetParameters().Length);
        Assert.Equal(
            [true, 0L, 50, 0, null, 10000],
            proxy.LastArguments.Take(6).ToArray());
        using (JsonDocument arguments = JsonDocument.Parse(
            """{"fetch":false,"furni_id":9,"limit":3,"offset":2,"snapshot_revision":77,"timeout_ms":1234}"""))
        {
            _ = await crafting.Handler(arguments.RootElement, CancellationToken.None);
        }
        Assert.Equal(
            [false, 9L, 3, 2, 77L, 1234],
            proxy.LastArguments.Take(6).ToArray());
        using (JsonDocument invalid = JsonDocument.Parse("""{"snapshot_revision":0}"""))
        {
            await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() =>
                crafting.Handler(invalid.RootElement, CancellationToken.None));
        }

        string root = FindRepositoryRoot();
        string hosting = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Hosting",
            "Mcp",
            "McpHost.cs"));
        Assert.Contains("ApplicationMemberIds.CraftingProductsRefresh", hosting,
            StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.CraftingState", hosting,
            StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.CraftingProductsList", hosting,
            StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.CraftingRecipeList", hosting,
            StringComparison.Ordinal);
        Assert.Contains("CraftingAncillaryEntryLimit = 500", hosting,
            StringComparison.Ordinal);
        Assert.DoesNotContain("game.Crafting", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("CraftingManager", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEventAsync<CraftableProducts>", hosting,
            StringComparison.Ordinal);
        Assert.DoesNotContain("McpCraftingState", hosting, StringComparison.Ordinal);
    }

    [Fact]
    public async Task crafting_mcp_uses_one_lease_product_paging_and_global_ancillary_budget()
    {
        var runtime = new CraftingMcpRuntime(3, 300, 300);
        string first = await ReadCraftingMcp(runtime, true, 55, 2, 0, null, 10000);
        Assert.Equal(1, runtime.ReadinessCount);
        Assert.Equal(1, runtime.RefreshCount);
        Assert.Equal((Id)55, runtime.LastRefreshRequest!.CraftingFurnitureId);
        Assert.Equal(2, runtime.LastRefreshRequest.Limit);
        Assert.InRange(runtime.LastRefreshRequest.TimeoutMilliseconds, 1, 10000);
        using (JsonDocument document = JsonDocument.Parse(first))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            JsonElement metadata = root.GetProperty("metadata");
            Assert.Equal(77, metadata.GetProperty("snapshotRevision").GetInt64());
            Assert.Equal(2, metadata.GetProperty("nextOffset").GetInt32());
            Assert.True(metadata.GetProperty("truncated").GetBoolean());
            JsonElement data = root.GetProperty("data");
            Assert.Equal(
                [
                    "total",
                    "returned",
                    "offset",
                    "maxItems",
                    "truncated",
                    "usableInventoryFurnitureClasses",
                    "currentRecipeIngredients",
                    "lastResult",
                    "availableRecipes",
                    "products",
                    "usableInventoryFurnitureClassesMetadata",
                    "currentRecipeIngredientsMetadata"
                ],
                data.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(3, data.GetProperty("total").GetInt32());
            Assert.Equal(2, data.GetProperty("returned").GetInt32());
            Assert.Equal(300,
                data.GetProperty("usableInventoryFurnitureClasses").GetArrayLength());
            Assert.Equal(200,
                data.GetProperty("currentRecipeIngredients").GetArrayLength());
            JsonElement usable = data.GetProperty(
                "usableInventoryFurnitureClassesMetadata");
            Assert.Equal(300, usable.GetProperty("total").GetInt32());
            Assert.Equal(300, usable.GetProperty("returned").GetInt32());
            Assert.Equal(500, usable.GetProperty("maxItems").GetInt32());
            Assert.False(usable.GetProperty("truncated").GetBoolean());
            Assert.False(usable.TryGetProperty("nextOffset", out _));
            JsonElement recipe = data.GetProperty("currentRecipeIngredientsMetadata");
            Assert.Equal(300, recipe.GetProperty("total").GetInt32());
            Assert.Equal(200, recipe.GetProperty("returned").GetInt32());
            Assert.Equal(200, recipe.GetProperty("maxItems").GetInt32());
            Assert.True(recipe.GetProperty("truncated").GetBoolean());
            Assert.False(recipe.TryGetProperty("nextOffset", out _));
            Assert.False(data.TryGetProperty("requestedCraftingFurnitureId", out _));
        }
        Assert.Equal(500,
            runtime.ProductRequests
                .Where(request => request.Collection is
                    CraftingProductsCollection.UsableInventoryFurnitureClasses)
                .Sum(request => request.Limit));
        Assert.Equal(200, Assert.Single(runtime.RecipeRequests).Limit);
        Assert.All(runtime.StateRequests, request => Assert.Equal(77, request.SnapshotRevision));
        Assert.All(runtime.ProductRequests,
            request => Assert.Equal(77, request.SnapshotRevision));
        Assert.All(runtime.RecipeRequests,
            request => Assert.Equal(77, request.SnapshotRevision));

        string continuation = await ReadCraftingMcp(
            runtime,
            true,
            999,
            2,
            2,
            77,
            10000);
        Assert.Equal(1, runtime.ReadinessCount);
        Assert.Equal(1, runtime.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(continuation))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            JsonElement metadata = root.GetProperty("metadata");
            Assert.Equal(77, metadata.GetProperty("snapshotRevision").GetInt64());
            Assert.False(metadata.TryGetProperty("nextOffset", out _));
            JsonElement data = root.GetProperty("data");
            Assert.Equal(2, data.GetProperty("offset").GetInt32());
            Assert.Equal(1, data.GetProperty("returned").GetInt32());
            Assert.Equal("recipe-2",
                data.GetProperty("products")[0].GetProperty("recipeCode").GetString());
        }
        Assert.All(runtime.StateRequests, request => Assert.Equal(77, request.SnapshotRevision));
        Assert.All(runtime.ProductRequests,
            request => Assert.Equal(77, request.SnapshotRevision));
        Assert.All(runtime.RecipeRequests,
            request => Assert.Equal(77, request.SnapshotRevision));

        await Assert.ThrowsAsync<ArgumentException>(() => ReadCraftingMcp(
            new CraftingMcpRuntime(),
            true,
            1,
            1,
            1,
            null,
            10000));
        var expired_runtime = new CraftingMcpRuntime();
        string expired = await ReadCraftingMcp(
            expired_runtime,
            true,
            1,
            1,
            1,
            999,
            10000);
        Assert.Equal(0, expired_runtime.ReadinessCount);
        Assert.Equal(0, expired_runtime.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(expired))
        {
            Assert.Equal(
                "unavailable",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

        var full_usable = new CraftingMcpRuntime(1, 500, 20);
        string bounded = await ReadCraftingMcp(
            full_usable,
            false,
            0,
            1,
            0,
            null,
            10000);
        using (JsonDocument document = JsonDocument.Parse(bounded))
        {
            JsonElement data = document.RootElement.GetProperty("data");
            Assert.Equal(500,
                data.GetProperty("usableInventoryFurnitureClasses").GetArrayLength());
            Assert.Empty(data.GetProperty("currentRecipeIngredients").EnumerateArray());
            Assert.Equal(0,
                data.GetProperty("currentRecipeIngredientsMetadata")
                    .GetProperty("maxItems")
                    .GetInt32());
            Assert.True(data.GetProperty("truncated").GetBoolean());
        }
        Assert.Empty(full_usable.RecipeRequests);
    }

    [Fact]
    public async Task crafting_mcp_preserves_timeout_errors_and_rejects_generation_drift()
    {
        var readiness_timeout = new CraftingMcpRuntime
        {
            Readiness = token => Task.Delay(Timeout.Infinite, token)
        };
        string readiness_error = await ReadCraftingMcp(
            readiness_timeout,
            true,
            1,
            1,
            0,
            null,
            20);
        Assert.Equal(1, readiness_timeout.ReadinessCount);
        Assert.Equal(0, readiness_timeout.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(readiness_error))
        {
            Assert.Equal(
                "timeout",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
            Assert.Equal(3,
                document.RootElement.GetProperty("data").GetProperty("total").GetInt32());
        }

        var refresh_timeout = new CraftingMcpRuntime
        {
            RefreshOverride = (_, _) =>
                ValueTask.FromException<CraftingProductsRefreshResult>(
                    new TimeoutException("crafting refresh timeout"))
        };
        string refresh_error = await ReadCraftingMcp(
            refresh_timeout,
            true,
            1,
            1,
            0,
            null,
            10000);
        Assert.Equal(1, refresh_timeout.ReadinessCount);
        Assert.Equal(1, refresh_timeout.RefreshCount);
        using (JsonDocument document = JsonDocument.Parse(refresh_error))
        {
            Assert.Equal(
                "timeout",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
            Assert.Equal(3,
                document.RootElement.GetProperty("data").GetProperty("total").GetInt32());
        }

        var refresh_failure = new CraftingMcpRuntime
        {
            RefreshOverride = (_, _) =>
                ValueTask.FromException<CraftingProductsRefreshResult>(
                    new InvalidOperationException("crafting unavailable"))
        };
        string unavailable = await ReadCraftingMcp(
            refresh_failure,
            true,
            1,
            1,
            0,
            null,
            10000);
        using (JsonDocument document = JsonDocument.Parse(unavailable))
        {
            Assert.Equal(
                "unavailable",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

        var drift = new CraftingMcpRuntime { StateSessionGeneration = 8 };
        string invalid = await ReadCraftingMcp(
            drift,
            true,
            1,
            1,
            0,
            null,
            10000);
        using (JsonDocument document = JsonDocument.Parse(invalid))
        {
            Assert.Equal(
                "invalid_response",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

    }

