            "Snapshots",
            "GameQueryService.Achievements.cs"));
        string query_badges = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Game",
            "Snapshots",
            "GameQueryService.Badges.cs"));
        Assert.DoesNotContain("game.Achievements", query_achievements, StringComparison.Ordinal);
        Assert.DoesNotContain("game.Badges", query_badges, StringComparison.Ordinal);
        string achievement_globals = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Scripting",
            "ScriptGlobals.Achievements.cs"));
        Assert.DoesNotContain("Flash only; a Unity session throws", achievement_globals,
            StringComparison.Ordinal);
        string interface_source = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Mcp",
            "IMcpHost.cs"));
        string server_source = File.ReadAllText(Path.Combine(
            root,
            "src",
            "QX.Mcp",
            "McpServer.cs"));
        string migrated_sources = string.Join('\n',
            requests,
            hosting,
            query_achievements,
            query_badges,
            interface_source,
            server_source);
        foreach (string bypass in new[]
                 {
                     "AchievementManager",
                     "BadgeInventoryManager",
                     "game.Achievements",
                     "game.Badges",
                     "MessageKeys.Achievements",
                     "MessageKeys.Badges",
                     "MessageContracts.Achievements",
                     "MessageContracts.Badges",
                     "RequestAsync<Achievements>",
                     "RequestAsync<BadgeInventory>",
                     "FetchAchievementsAsync",
                     "PageAchievements",
                     "PageBadges"
                 })
        {
            Assert.DoesNotContain(bypass, migrated_sources, StringComparison.Ordinal);
        }
        Assert.DoesNotContain("BadgeInventoryManager", achievement_globals,
            StringComparison.Ordinal);
        Assert.Single(System.Text.RegularExpressions.Regex.Matches(
            achievement_globals,
            "AchievementManager").Cast<System.Text.RegularExpressions.Match>());
        string migrated_script_requests = requests[
            requests.IndexOf("public async Task<BadgeInventory> GetBadgeInventory", StringComparison.Ordinal)..requests.IndexOf("public async Task<IReadOnlyList<GuildMembership>>", StringComparison.Ordinal)];
        Assert.DoesNotContain("across one retry", migrated_script_requests,
            StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEvent", migrated_script_requests, StringComparison.Ordinal);
        Assert.DoesNotContain("RequestBroker", migrated_script_requests, StringComparison.Ordinal);
        Assert.DoesNotContain("Requests.", migrated_script_requests, StringComparison.Ordinal);
        Assert.DoesNotContain("Send(", migrated_script_requests, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task achievement_badge_scripts_keep_raw_order_queries_sort_after_full_token(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        Achievement early = ConsumerAchievement(9000, "z", "z");
        fixture.Receive(MessageContracts.Achievements.Updated, new AchievementUpdate(early));
        AchievementStateView before = fixture.Application.Invoke<
            AchievementStateRequest,
            AchievementStateView>(
                ApplicationMemberIds.AchievementsState,
                new AchievementStateRequest());
        Assert.False(before.List.Loaded);
        Assert.Equal(0, before.BaselineRevision);

        Achievement[] achievement_source = Enumerable.Range(0, 1201)
            .Select(index => ConsumerAchievement(
                1200 - index,
                index % 3 == 0 ? "z" : index % 3 == 1 ? "a" : "m",
                index % 2 == 0 ? "two" : "one"))
            .ToArray();
        OwnedBadge[] badge_source = Enumerable.Range(0, 620)
            .Select(index => new OwnedBadge(
                index + 1,
                $"consumer-{619 - index:D4}",
                client is ClientType.Flash ? index + 10 : 0,
                client is ClientType.Flash ? index % 7 : 0,
                client is ClientType.Flash))
            .ToArray();
        OwnedBadge[] badge_first = badge_source.Take(310).ToArray();
        OwnedBadge[] badge_second = badge_source.Skip(310).ToArray();
        var limits = new BadgePointLimits([new BadgePointLimit("Consumer", 1, 42)]);
        fixture.AfterAchievementBadgeDispatch = key =>
        {
            if (key == MessageKeys.Achievements.Request)
            {
                fixture.Receive(
                    MessageContracts.Achievements.Snapshot,
                    new Achievements(achievement_source, "default"));
            }
            else if (key == MessageKeys.Badges.Request)
            {
                fixture.Receive(
                    MessageContracts.Badges.Snapshot,
                    new BadgeInventory(2, 1, badge_second));
                fixture.Receive(
                    MessageContracts.Badges.Snapshot,
                    new BadgeInventory(2, 0, badge_first));
            }
            else if (key == MessageKeys.Achievements.PointLimitsRequest)
            {
                fixture.Receive(MessageContracts.Achievements.PointLimits, limits);
            }
        };

        using ScriptGlobals globals = fixture.CreateGlobals();
        Achievements achievements = await globals.GetAchievements(test_request_timeout_ms);
        BadgeInventory badges = await globals.GetBadgeInventory(test_request_timeout_ms);
        BadgePointLimits received_limits = await globals.GetBadgePointLimits(test_request_timeout_ms);
        Assert.Equal(
            achievement_source.Select(achievement => achievement.Id),
            achievements.Items.Select(achievement => achievement.Id));
        Assert.Equal(
            JsonSerializer.Serialize(new Achievements(achievement_source, "default")),
            JsonSerializer.Serialize(achievements));
        Assert.Equal("default", achievements.DefaultCategory);
        Assert.Equal(1, badges.TotalPages);
        Assert.Equal(0, badges.CurrentPage);
        Assert.Equal(
            badge_source.Select(badge => badge.NativeBadgeId),
            badges.Badges.Select(badge => badge.NativeBadgeId));
        Assert.Equal(
            JsonSerializer.Serialize(new BadgeInventory(1, 0, badge_source)),
            JsonSerializer.Serialize(badges));
        Assert.Equal(client is ClientType.Flash, badges.Badges[0].HasRarityData);
        Assert.Equal(42, received_limits.Limit("Consumer", 1));
        Assert.Equal(1,
            fixture.AchievementBadgeRequestCount(MessageKeys.Achievements.Request));
        Assert.Equal(1, fixture.AchievementBadgeRequestCount(MessageKeys.Badges.Request));
        Assert.Equal(1, fixture.AchievementBadgeRequestCount(
            MessageKeys.Achievements.PointLimitsRequest));

        AchievementPage raw_achievements = fixture.Application.Invoke<
            AchievementPageRequest,
            AchievementPage>(
                ApplicationMemberIds.AchievementsList,
                new AchievementPageRequest(Limit: 500));
        Assert.Equal(
            achievement_source.Take(500).Select(achievement => achievement.Id),
            raw_achievements.Achievements.Select(achievement => achievement.Id));
        OwnedBadgePage raw_badges = fixture.Application.Invoke<
            OwnedBadgePageRequest,
            OwnedBadgePage>(
                ApplicationMemberIds.BadgesOwnedList,
                new OwnedBadgePageRequest(Limit: 500));
        Assert.Equal(
            badge_source.Take(500).Select(badge => badge.NativeBadgeId),
            raw_badges.Badges.Select(badge => badge.Id));

        AchievementSnapshot[] expected_achievements = achievement_source
            .OrderBy(achievement => achievement.Category, StringComparer.OrdinalIgnoreCase)
            .ThenBy(achievement => achievement.Subcategory, StringComparer.OrdinalIgnoreCase)
            .ThenBy(achievement => achievement.Id)
            .Take(700)
            .Select(ConsumerAchievementSnapshot)
            .ToArray();
        QueryEnvelope<AchievementCollectionSnapshot> achievement_query =
            fixture.Queries.Achievements(700);
        Assert.Equal(1201, achievement_query.Data!.Total);
        Assert.Equal(700, achievement_query.Data.Returned);
        Assert.True(achievement_query.Data.Truncated);
        Assert.Equal(
            expected_achievements.Select(achievement => achievement.Id),
            achievement_query.Data.Achievements.Select(achievement => achievement.Id));
        OwnedBadge[] expected_badges = badge_source
            .OrderBy(badge => badge.Code, StringComparer.OrdinalIgnoreCase)
            .ThenBy(badge => (long)badge.NativeBadgeId)
            .Take(300)
            .ToArray();
        QueryEnvelope<BadgeInventorySnapshot> badge_query = fixture.Queries.BadgeInventory(300);
        Assert.Equal(620, badge_query.Data!.Total);
        Assert.Equal(300, badge_query.Data.Returned);
        Assert.True(badge_query.Data.Truncated);
        Assert.Equal(
            expected_badges.Select(badge => badge.NativeBadgeId),
            badge_query.Data.Badges.Select(badge => badge.Id));
        Assert.Equal(0, fixture.Queries.Achievements(0).Data!.Returned);
        Assert.Equal(1201, fixture.Queries.Achievements(0).Data!.Total);
        Assert.Equal(0, fixture.Queries.BadgeInventory(0).Data!.Returned);
        Assert.Equal(620, fixture.Queries.BadgeInventory(0).Data!.Total);
        string legacy_achievements = InvokeLegacyMcpRead(fixture, "GetAchievements");
        string legacy_badges = InvokeLegacyMcpRead(fixture, "GetBadgeInventory");
        Assert.Equal(
            NormalizeCapturedAt(QueryJson.Serialize(fixture.Queries.Achievements())),
            NormalizeCapturedAt(legacy_achievements));
        Assert.Equal(
            NormalizeCapturedAt(QueryJson.Serialize(fixture.Queries.BadgeInventory())),
            NormalizeCapturedAt(legacy_badges));
        foreach (string json in new[] { legacy_achievements, legacy_badges })
        {
            using JsonDocument document = JsonDocument.Parse(json);
            Assert.Equal(
                ["ready", "loaded", "stale", "truncated", "capturedAtUtc", "pending"],
                document.RootElement.GetProperty("metadata").EnumerateObject()
                    .Select(property => property.Name).ToArray());
        }
        Assert.Equal(1,
            fixture.AchievementBadgeRequestCount(MessageKeys.Achievements.Request));
        Assert.Equal(1, fixture.AchievementBadgeRequestCount(MessageKeys.Badges.Request));

        long retained = raw_achievements.SnapshotRevision;
        for (int index = 0; index < 5; index++)
        {
            fixture.Receive(
                MessageContracts.Achievements.Snapshot,
                new Achievements(
                    [ConsumerAchievement(index + 1, "new", "new")],
                    "new"));
        }
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            AchievementPageRequest,
            AchievementPage>(
                ApplicationMemberIds.AchievementsList,
                new AchievementPageRequest(0, 1, retained)));
    }

    [Fact]
    public async Task achievement_badge_mcp_collects_one_raw_token_sorts_and_never_fetches_continuations()
    {
        var runtime = new AchievementBadgeMcpRuntime(1201, 620, loaded: false);
        string achievements = await ReadAchievementMcp(
            runtime,
            true,
            3,
            0,
            null,
            10000);
        Assert.Equal(1, runtime.AchievementReadinessCount);
        Assert.Equal(1, runtime.AchievementRefreshCount);
        Assert.Equal([0, 500, 1000],
            runtime.AchievementRequests.Select(request => request.Offset).ToArray());
        Assert.All(runtime.AchievementRequests.Skip(1),
            request => Assert.Equal(77, request.SnapshotRevision));
        using (JsonDocument document = JsonDocument.Parse(achievements))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            Assert.Equal(
                ["ready", "loaded", "stale", "truncated", "capturedAtUtc", "pending",
                    "snapshotRevision", "nextOffset"],
                root.GetProperty("metadata").EnumerateObject()
                    .Select(property => property.Name).ToArray());
            Assert.Equal(77,
                root.GetProperty("metadata").GetProperty("snapshotRevision").GetInt64());
            Assert.Equal(3,
                root.GetProperty("metadata").GetProperty("nextOffset").GetInt32());
            JsonElement data = root.GetProperty("data");
            Assert.Equal(
                ["defaultCategory", "total", "completed", "returned", "maxItems",
                    "truncated", "achievements"],
                data.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(1201, data.GetProperty("total").GetInt32());
            Assert.Equal(3, data.GetProperty("returned").GetInt32());
            JsonElement[] items = data.GetProperty("achievements").EnumerateArray().ToArray();
            Assert.Equal(3, items.Length);
            for (int index = 0; index < items.Length; index++)
                AssertMcpAchievement(runtime.SortedAchievements[index], items[index]);
        }

        string badges = await ReadBadgeMcp(runtime, true, 2, 0, null, 10000);
        Assert.Equal(1, runtime.BadgeReadinessCount);
        Assert.Equal(1, runtime.BadgeRefreshCount);
        using (JsonDocument document = JsonDocument.Parse(badges))
        {
            JsonElement data = document.RootElement.GetProperty("data");
            Assert.Equal(
                ["isLoading", "isStale", "generation", "expectedFragments",
                    "receivedFragments", "total", "returned", "maxBadges", "truncated",
                    "badges"],
                data.EnumerateObject().Select(property => property.Name).ToArray());
            JsonElement[] items = data.GetProperty("badges").EnumerateArray().ToArray();
            Assert.Equal(2, items.Length);
            for (int index = 0; index < items.Length; index++)
                AssertMcpBadge(runtime.SortedBadges[index], items[index]);
        }

        var continuation = new AchievementBadgeMcpRuntime(1201, 620, loaded: true);
        string continued = await ReadAchievementMcp(
            continuation,
            true,
            2,
            2,
            77,
            10000);
        Assert.Equal(0, continuation.AchievementReadinessCount);
        Assert.Equal(0, continuation.AchievementRefreshCount);
        Assert.Equal([0, 500, 1000],
            continuation.AchievementRequests.Select(request => request.Offset).ToArray());
        Assert.All(continuation.AchievementRequests,
            request => Assert.Equal(77, request.SnapshotRevision));
        using (JsonDocument document = JsonDocument.Parse(continued))
        {
            Assert.Equal(
                continuation.SortedAchievements.Skip(2).Take(2).Select(item => item.Id),
                document.RootElement.GetProperty("data").GetProperty("achievements")
                    .EnumerateArray().Select(item => item.GetProperty("id").GetInt32()));
        }

        string continued_badges = await ReadBadgeMcp(
            continuation,
            true,
            2,
            2,
            77,
            10000);
        Assert.Equal(0, continuation.BadgeReadinessCount);
        Assert.Equal(0, continuation.BadgeRefreshCount);
        Assert.All(continuation.BadgeRequests,
            request => Assert.Equal(77, request.SnapshotRevision));
        using (JsonDocument document = JsonDocument.Parse(continued_badges))
        {
            Assert.Equal(
                continuation.SortedBadges.Skip(2).Take(2).Select(item => (long)item.Id),
                document.RootElement.GetProperty("data").GetProperty("badges")
                    .EnumerateArray().Select(item => long.Parse(
                        item.GetProperty("id").GetString()!,
                        System.Globalization.CultureInfo.InvariantCulture)));
        }

        var loaded = new AchievementBadgeMcpRuntime(3, 3, loaded: true);
        _ = await ReadAchievementMcp(loaded, true, 2, 0, null, 10000);
        _ = await ReadBadgeMcp(loaded, true, 2, 0, null, 10000);
        Assert.Equal(1, loaded.AchievementReadinessCount);
        Assert.Equal(0, loaded.AchievementRefreshCount);
        Assert.Equal(1, loaded.BadgeReadinessCount);
        Assert.Equal(0, loaded.BadgeRefreshCount);

        var expired = new AchievementBadgeMcpRuntime();
        string expired_achievements = await ReadAchievementMcp(
            expired,
            true,
            1,
            1,
            999,
            10000);
        string expired_badges = await ReadBadgeMcp(
            expired,
            true,
            1,
            1,
            999,
            10000);
        Assert.Equal(0, expired.AchievementReadinessCount);
        Assert.Equal(0, expired.AchievementRefreshCount);
        Assert.Equal(0, expired.BadgeReadinessCount);
        Assert.Equal(0, expired.BadgeRefreshCount);
        using (JsonDocument document = JsonDocument.Parse(expired_achievements))
        {
            Assert.Equal(
                "unavailable",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }
        using (JsonDocument document = JsonDocument.Parse(expired_badges))
        {
            Assert.Equal(
                "unavailable",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

        await Assert.ThrowsAsync<ArgumentException>(() => ReadAchievementMcp(
            new AchievementBadgeMcpRuntime(),
            true,
            1,
            1,
            null,
            10000));
        await Assert.ThrowsAsync<ArgumentException>(() => ReadBadgeMcp(
            new AchievementBadgeMcpRuntime(),
            true,
            1,
            1,
            null,
            10000));

        var invalid_refresh = new AchievementBadgeMcpRuntime(3, 3, loaded: false)
        {
            BadgeRefreshStateRevisionOffset = 1
        };
        string invalid = await ReadBadgeMcp(
            invalid_refresh,
            true,
            1,
            0,
            null,
            10000);
        using (JsonDocument document = JsonDocument.Parse(invalid))
        {
            Assert.Equal(
                "invalid_response",
                document.RootElement.GetProperty("error").GetProperty("code").GetString());
        }

        foreach ((AchievementBadgeMcpRuntime invalid_runtime, bool achievement) in new[]
                 {
                     (new AchievementBadgeMcpRuntime(501, 501)
                     {
                         AchievementContinuationStateRevisionOffset = 1
                     }, true),
                     (new AchievementBadgeMcpRuntime(501, 501)
                     {
                         BadgeContinuationStateRevisionOffset = 1
                     }, false),
                     (new AchievementBadgeMcpRuntime(501, 501)
                     {
                         EmptyAchievementContinuation = true
                     }, true),
                     (new AchievementBadgeMcpRuntime(501, 501)
                     {
                         EmptyBadgeContinuation = true
                     }, false)
                 })
        {
            string response = achievement
                ? await ReadAchievementMcp(
                    invalid_runtime, false, 1, 0, null, 10000)
                : await ReadBadgeMcp(
                    invalid_runtime, false, 1, 0, null, 10000);
            AssertMcpError(response, "invalid_response");
        }

        var timed_out = new AchievementBadgeMcpRuntime(loaded: false)
        {
            AchievementReadiness = static token =>
                Task.Delay(Timeout.InfiniteTimeSpan, token)
        };
        AssertMcpError(
            await ReadAchievementMcp(timed_out, true, 1, 0, null, 25),
            "timeout");
        var cancelled = new AchievementBadgeMcpRuntime(loaded: false)
        {
            BadgeReadiness = static token => Task.Delay(Timeout.InfiniteTimeSpan, token)
        };
        using var cancellation = new CancellationTokenSource();
        Task<string> cancellation_read = ReadBadgeMcp(
            cancelled,
            true,
            1,
            0,
            null,
            10000,
            cancellation.Token);
        await Task.Delay(20);
        cancellation.Cancel();
        AssertMcpError(await cancellation_read, "cancelled");
    }

    [Fact]
    public async Task achievement_badge_consumers_reject_drift_and_zero_progress_and_propagate_failures()
    {
        foreach ((AchievementBadgeConsumerFailure failure, bool achievement) in new[]
                 {
                     (AchievementBadgeConsumerFailure.AchievementStateDrift, true),
                     (AchievementBadgeConsumerFailure.BadgeStateDrift, false),
                     (AchievementBadgeConsumerFailure.AchievementZeroProgress, true),
                     (AchievementBadgeConsumerFailure.BadgeZeroProgress, false)
                 })
        {
            var query_runtime = new AchievementBadgeScriptRuntime(failure);
            using var query_game = new GameState();
            var queries = new GameQueryService(
                query_game,
                query_runtime,
                static () => null);
            if (achievement)
                Assert.Throws<InvalidOperationException>(() => queries.Achievements(1));
            else
                Assert.Throws<InvalidOperationException>(() => queries.BadgeInventory(1));

            using var fixture = new SurfaceFixture(ClientType.Flash);
            using ScriptGlobals globals = fixture.CreateGlobals(
                new AchievementBadgeScriptRuntime(failure));
            if (achievement)
                await Assert.ThrowsAsync<InvalidOperationException>(() => globals.GetAchievements());
            else
                await Assert.ThrowsAsync<InvalidOperationException>(() => globals.GetBadgeInventory());
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        using (ScriptGlobals globals = fixture.CreateGlobals(
            new AchievementBadgeScriptRuntime(
                AchievementBadgeConsumerFailure.AchievementCancellation),
            cancellation.Token))
        {
            Task<Achievements> pending = globals.GetAchievements();
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => pending);
            Assert.Equal(cancellation.Token, error.CancellationToken);
        }

        using (var fixture = new SurfaceFixture(ClientType.Unity))
        using (ScriptGlobals globals = fixture.CreateGlobals(
            new AchievementBadgeScriptRuntime(
                AchievementBadgeConsumerFailure.BadgeTimeout)))
        {
            RequestTimeoutException error = await Assert.ThrowsAsync<RequestTimeoutException>(
                () => globals.GetBadgeInventory(47));
            Assert.Equal(47, error.TimeoutMs);
        }
    }

    [Fact]
    public async Task achievement_badge_refreshes_preserve_cancellation_timeout_and_disconnect()
    {
        using (var achievement_cancelled = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<AchievementRefreshResult> pending = achievement_cancelled.Application
                .InvokeAsync<AchievementRefreshRequest, AchievementRefreshResult>(
                    ApplicationMemberIds.AchievementsRefresh,
                    new AchievementRefreshRequest(TimeoutMilliseconds: 10000),
                    cancellation.Token)
                .AsTask();
            await achievement_cancelled.WaitForAchievementBadgeRequestCount(
                MessageKeys.Achievements.Request,
                1).WaitAsync(test_synchronization_timeout);
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => pending);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(1, achievement_cancelled.AchievementBadgeRequestCount(
                MessageKeys.Achievements.Request));
        }

        using (var badge_cancelled = new SurfaceFixture(ClientType.Unity))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<BadgeRefreshResult> pending = badge_cancelled.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000),
                    cancellation.Token)
                .AsTask();
            await badge_cancelled.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => pending);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(1,
                badge_cancelled.AchievementBadgeRequestCount(MessageKeys.Badges.Request));
        }

        using (var timed_out = new SurfaceFixture(ClientType.Flash))
        {
            await Assert.ThrowsAsync<RequestTimeoutException>(() => timed_out.Application
                .InvokeAsync<AchievementRefreshRequest, AchievementRefreshResult>(
                    ApplicationMemberIds.AchievementsRefresh,
                    new AchievementRefreshRequest(TimeoutMilliseconds: 50))
                .AsTask());
            Assert.Equal(1,
                timed_out.AchievementBadgeRequestCount(MessageKeys.Achievements.Request));
        }

        using (var disconnected = new SurfaceFixture(ClientType.Unity))
        {
            Task<BadgeRefreshResult> pending = disconnected.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await disconnected.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => pending.WaitAsync(
                test_synchronization_timeout));
            Assert.Equal(1,
                disconnected.AchievementBadgeRequestCount(MessageKeys.Badges.Request));
        }
    }

    [Fact]
    public async Task achievement_badge_refreshes_coalesce_waiters_and_disconnect_terminally()
    {
        using (var achievements = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<AchievementRefreshResult> first = achievements.Application
                .InvokeAsync<AchievementRefreshRequest, AchievementRefreshResult>(
                    ApplicationMemberIds.AchievementsRefresh,
                    new AchievementRefreshRequest(TimeoutMilliseconds: 10000),
                    cancellation.Token)
                .AsTask();
            await achievements.WaitForAchievementBadgeRequestCount(
                MessageKeys.Achievements.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task<AchievementRefreshResult> second = achievements.Application
                .InvokeAsync<AchievementRefreshRequest, AchievementRefreshResult>(
                    ApplicationMemberIds.AchievementsRefresh,
                    new AchievementRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => first);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.False(second.IsCompleted);
            achievements.Receive(
                MessageContracts.Achievements.Snapshot,
                new Achievements([ConsumerAchievement(1, "coalesced", "one")], "default"));
            AchievementRefreshResult refreshed = await second.WaitAsync(test_synchronization_timeout);
            Assert.True(refreshed.FirstPage.Loaded);
            Assert.Equal(1, achievements.AchievementBadgeRequestCount(
                MessageKeys.Achievements.Request));
        }

        using (var badges = new SurfaceFixture(ClientType.Unity))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<BadgeRefreshResult> first = badges.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000),
                    cancellation.Token)
                .AsTask();
            await badges.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task<BadgeRefreshResult> second = badges.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
                () => first);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.False(second.IsCompleted);
            badges.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(1, 0, [new OwnedBadge(1, "COALESCED", 0, 0, false)]));
            BadgeRefreshResult refreshed = await second.WaitAsync(test_synchronization_timeout);
            Assert.True(refreshed.FirstPage.Inventory.Loaded);
            Assert.Equal(1,
                badges.AchievementBadgeRequestCount(MessageKeys.Badges.Request));
        }

        using (var disconnected = new SurfaceFixture(ClientType.Flash))
        {
            Task<BadgeRefreshResult> first = disconnected.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await disconnected.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task<BadgeRefreshResult> second = disconnected.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(
                () => first.WaitAsync(test_synchronization_timeout));
            await Assert.ThrowsAsync<RequestDisconnectedException>(
                () => second.WaitAsync(test_synchronization_timeout));
            Assert.Equal(1,
                disconnected.AchievementBadgeRequestCount(MessageKeys.Badges.Request));
        }
    }

