    [Fact]
    public async Task achievement_badge_changed_callbacks_can_dispose_the_runtime()
    {
        using (var achievements = new SurfaceFixture(ClientType.Flash))
        {
            int received = 0;
            IDisposable subscription = achievements.Application.Subscribe<AchievementChanged>(
                ApplicationMemberIds.AchievementsChanged,
                changed =>
                {
                    if (changed.Kind is not AchievementChangeKind.Snapshot)
                        return;
                    Interlocked.Increment(ref received);
                    achievements.Application.Dispose();
                });
            Task<AchievementRefreshResult> refresh = achievements.Application
                .InvokeAsync<AchievementRefreshRequest, AchievementRefreshResult>(
                    ApplicationMemberIds.AchievementsRefresh,
                    new AchievementRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await achievements.WaitForAchievementBadgeRequestCount(
                MessageKeys.Achievements.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task<bool> publication = Task.Run(() => achievements.Receive(
                MessageContracts.Achievements.Snapshot,
                new Achievements(
                    [ConsumerAchievement(7, "dispose", "achievement")],
                    "dispose")));
            await publication.WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, received);
            Exception? refresh_error = await Record.ExceptionAsync(
                () => refresh.WaitAsync(test_synchronization_timeout));
            Assert.True(refresh_error is null or ObjectDisposedException,
                refresh_error?.ToString());
            Assert.Throws<ObjectDisposedException>(() => achievements.Application.Members);
            subscription.Dispose();
        }

        using (var badges = new SurfaceFixture(ClientType.Unity))
        {
            int received = 0;
            IDisposable subscription = badges.Application.Subscribe<BadgeChanged>(
                ApplicationMemberIds.BadgesChanged,
                changed =>
                {
                    if (changed.Kind is not BadgeChangeKind.Loaded)
                        return;
                    Interlocked.Increment(ref received);
                    badges.Application.Dispose();
                });
            Task<BadgeRefreshResult> refresh = badges.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await badges.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task<bool> publication = Task.Run(() => badges.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(
                    1,
                    0,
                    [new OwnedBadge(8, "DISPOSE", 0, 0, false)])));
            await publication.WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, received);
            Exception? refresh_error = await Record.ExceptionAsync(
                () => refresh.WaitAsync(test_synchronization_timeout));
            Assert.True(refresh_error is null or ObjectDisposedException,
                refresh_error?.ToString());
            Assert.Throws<ObjectDisposedException>(() => badges.Application.Members);
            subscription.Dispose();
        }
    }

    [Fact]
    public void achievement_badge_reset_retires_old_leases_without_new_lease_ghosts()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.Receive(
            MessageContracts.Achievements.Snapshot,
            new Achievements([ConsumerAchievement(9, "lease", "achievement")], "lease"));
        fixture.Receive(
            MessageContracts.Achievements.PointLimits,
            new BadgePointLimits([new BadgePointLimit("Lease", 1, 90)]));
        fixture.Receive(
            MessageContracts.Badges.Snapshot,
            new BadgeInventory(1, 0, [new OwnedBadge(9, "LEASE", 90, 9)]));
        long[] old_achievement_tokens = Enumerable.Range(0, 4)
            .Select(_ => fixture.Application.Invoke<
                AchievementStateRequest,
                AchievementStateView>(
                    ApplicationMemberIds.AchievementsState,
                    new AchievementStateRequest()).SnapshotRevision)
            .ToArray();
        long[] old_badge_tokens = Enumerable.Range(0, 4)
            .Select(_ => fixture.Application.Invoke<BadgeStateRequest, BadgeStateView>(
                ApplicationMemberIds.BadgesState,
                new BadgeStateRequest()).SnapshotRevision)
            .ToArray();

        fixture.Disconnect();
        fixture.Connect(new Session(
            "localhost",
            0,
            "smoke",
            "smoke",
            ClientType.Flash));

        Assert.All(old_achievement_tokens, token =>
            Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
                AchievementStateRequest,
                AchievementStateView>(
                    ApplicationMemberIds.AchievementsState,
                    new AchievementStateRequest(token))));
        Assert.All(old_badge_tokens, token =>
            Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
                BadgeStateRequest,
                BadgeStateView>(
                    ApplicationMemberIds.BadgesState,
                    new BadgeStateRequest(token))));

        long[] achievement_tokens = Enumerable.Range(0, 4)
            .Select(_ => fixture.Application.Invoke<
                AchievementStateRequest,
                AchievementStateView>(
                    ApplicationMemberIds.AchievementsState,
                    new AchievementStateRequest()).SnapshotRevision)
            .ToArray();
        long[] badge_tokens = Enumerable.Range(0, 4)
            .Select(_ => fixture.Application.Invoke<BadgeStateRequest, BadgeStateView>(
                ApplicationMemberIds.BadgesState,
                new BadgeStateRequest()).SnapshotRevision)
            .ToArray();
        Assert.All(achievement_tokens, token =>
        {
            Assert.Equal(token, fixture.Application.Invoke<
                AchievementStateRequest,
                AchievementStateView>(
                    ApplicationMemberIds.AchievementsState,
                    new AchievementStateRequest(token)).SnapshotRevision);
            Assert.Equal(token, fixture.Application.Invoke<
                AchievementPageRequest,
                AchievementPage>(
                    ApplicationMemberIds.AchievementsList,
                    new AchievementPageRequest(SnapshotRevision: token)).SnapshotRevision);
            Assert.Equal(token, fixture.Application.Invoke<
                AchievementPointLimitPageRequest,
                AchievementPointLimitPage>(
                    ApplicationMemberIds.AchievementPointLimitsList,
                    new AchievementPointLimitPageRequest(
                        SnapshotRevision: token)).SnapshotRevision);
        });
        Assert.All(badge_tokens, token =>
        {
            Assert.Equal(token, fixture.Application.Invoke<BadgeStateRequest, BadgeStateView>(
                ApplicationMemberIds.BadgesState,
                new BadgeStateRequest(token)).SnapshotRevision);
            Assert.Equal(token, fixture.Application.Invoke<
                OwnedBadgePageRequest,
                OwnedBadgePage>(
                    ApplicationMemberIds.BadgesOwnedList,
                    new OwnedBadgePageRequest(SnapshotRevision: token)).SnapshotRevision);
            Assert.Equal(token, fixture.Application.Invoke<
                BadgeSelectedSetPageRequest,
                BadgeSelectedSetPage>(
                    ApplicationMemberIds.BadgesSelectedSetsList,
                    new BadgeSelectedSetPageRequest(
                        SnapshotRevision: token)).SnapshotRevision);
            Assert.Equal(token, fixture.Application.Invoke<
                BadgeSelectedPageRequest,
                BadgeSelectedPage>(
                    ApplicationMemberIds.BadgesSelectedList,
                    new BadgeSelectedPageRequest(
                        (Id)1L,
                        SnapshotRevision: token)).SnapshotRevision);
        });
    }

    [Fact]
    public void achievement_badge_reentrant_reset_drops_stale_publication_leases()
    {
        using (var achievements = new SurfaceFixture(ClientType.Flash))
        {
            AchievementChanged? reset = null;
            using IDisposable subscription = achievements.Application
                .Subscribe<AchievementChanged>(
                    ApplicationMemberIds.AchievementsChanged,
                    changed =>
                    {
                        if (changed.Kind is AchievementChangeKind.Reset &&
                            changed.Client is ClientType.Unity)
                        {
                            reset = changed;
                        }
                    });
            int triggered = 0;
            PrependStateChanged(achievements.Achievements, () =>
            {
                if (Interlocked.Exchange(ref triggered, 1) != 0)
                    return;
                achievements.Disconnect();
                achievements.Connect(new Session(
                    "localhost",
                    0,
                    "smoke",
                    "smoke",
                    ClientType.Unity));
            });
            achievements.Receive(
                MessageContracts.Achievements.Snapshot,
                new Achievements(
                    [ConsumerAchievement(10, "stale", "achievement")],
                    "stale"));
            Assert.NotNull(reset);
            Assert.NotNull(reset!.SnapshotRevision);
            AssertSingleLease(
                AchievementFeature(achievements.Application),
                "achievement_leases",
                "achievement_lease_order",
                reset.SnapshotRevision.Value);
        }

        using (var badges = new SurfaceFixture(ClientType.Flash))
        {
            BadgeChanged? reset = null;
            using IDisposable subscription = badges.Application.Subscribe<BadgeChanged>(
                ApplicationMemberIds.BadgesChanged,
                changed =>
                {
                    if (changed.Kind is BadgeChangeKind.Reset &&
                        changed.Client is ClientType.Unity)
                    {
                        reset = changed;
                    }
                });
            int triggered = 0;
            PrependStateChanged(badges.Badges, () =>
            {
                if (Interlocked.Exchange(ref triggered, 1) != 0)
                    return;
                badges.Disconnect();
                badges.Connect(new Session(
                    "localhost",
                    0,
                    "smoke",
                    "smoke",
                    ClientType.Unity));
            });
            badges.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(1, 0, [new OwnedBadge(10, "STALE", 100, 10)]));
            Assert.NotNull(reset);
            Assert.NotNull(reset!.SnapshotRevision);
            AssertSingleLease(
                AchievementFeature(badges.Application),
                "badge_leases",
                "badge_lease_order",
                reset.SnapshotRevision.Value);
        }
    }

    [Fact]
    public async Task badge_journal_replays_prebaseline_and_orders_regrant()
    {
        using (var prebaseline = new SurfaceFixture(ClientType.Flash))
        {
            prebaseline.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(3, "C", 30, 3));
            Task<BadgeRefreshResult> refresh = prebaseline.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await prebaseline.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            prebaseline.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(1, 0,
                [
                    new OwnedBadge(1, "A", 10, 1),
                    new OwnedBadge(2, "B", 20, 2)
                ]));
            await refresh;
            Assert.Equal(
                ["A", "B", "C"],
                ReadOwnedBadges(prebaseline).Select(badge => badge.Code).ToArray());
        }

        using (var chronology = new SurfaceFixture(ClientType.Flash))
        {
            Task<BadgeRefreshResult> initial = chronology.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await chronology.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            BadgeInventory baseline = new(1, 0,
            [
                new OwnedBadge(1, "A", 10, 1),
                new OwnedBadge(2, "B", 20, 2)
            ]);
            chronology.Receive(MessageContracts.Badges.Snapshot, baseline);
            await initial;

            Task<BadgeRefreshResult> reload = chronology.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await chronology.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                2).WaitAsync(test_synchronization_timeout);
            chronology.Receive(
                MessageContracts.Achievements.Notification,
                BadgeMutationNotification("", "A", 0, 0, 0));
            chronology.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(3, "C", 30, 3));
            chronology.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(4, "D", 40, 4));
            chronology.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(3, "C", 31, 3));
            chronology.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(5, "A", 50, 5));
            chronology.Receive(MessageContracts.Badges.Snapshot, baseline);
            await reload;
            OwnedBadgeSnapshot[] badges = ReadOwnedBadges(chronology).ToArray();
            Assert.Equal(
                ["B", "C", "D", "A"],
                badges.Select(badge => badge.Code).ToArray());
            Assert.Equal(31, badges[1].OwnerCount);
        }
    }

    [Fact]
    public async Task badge_completed_generation_does_not_replay_and_unity_preserves_rarity()
    {
        using (var closed_generation = new SurfaceFixture(ClientType.Flash))
        {
            Task<BadgeRefreshResult> initial = closed_generation.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await closed_generation.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            closed_generation.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(1, 0, [new OwnedBadge(1, "A", 1, 1)]));
            await initial;
            closed_generation.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(2, "A", 2, 2));
            Assert.Equal(2, Assert.Single(ReadOwnedBadges(closed_generation)).OwnerCount);

            Task<BadgeRefreshResult> reload = closed_generation.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await closed_generation.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                2).WaitAsync(test_synchronization_timeout);
            closed_generation.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(1, 0, [new OwnedBadge(3, "A", 3, 3)]));
            await reload;
            OwnedBadgeSnapshot current = Assert.Single(ReadOwnedBadges(closed_generation));
            Assert.Equal(3, (long)current.Id);
            Assert.Equal(3, current.OwnerCount);
            Assert.Equal(3, current.RarityId);
        }

        using (var unity = new SurfaceFixture(ClientType.Unity))
        {
            Task<BadgeRefreshResult> initial = unity.Application
                .InvokeAsync<BadgeRefreshRequest, BadgeRefreshResult>(
                    ApplicationMemberIds.BadgesRefresh,
                    new BadgeRefreshRequest(TimeoutMilliseconds: 10000))
                .AsTask();
            await unity.WaitForAchievementBadgeRequestCount(
                MessageKeys.Badges.Request,
                1).WaitAsync(test_synchronization_timeout);
            unity.Receive(
                MessageContracts.Badges.Snapshot,
                new BadgeInventory(1, 0, [new OwnedBadge(1, "KEEP", 0, 0, false)]));
            await initial;
            unity.Receive(
                MessageContracts.Badges.Received,
                new BadgeReceived(1, "KEEP", 33, 7));
            OwnedBadgeSnapshot seeded = Assert.Single(ReadOwnedBadges(unity));
            Assert.Equal(33, seeded.OwnerCount);
            Assert.Equal(7, seeded.RarityId);
            Assert.True(seeded.HasRarityData);
            unity.Receive(
                MessageContracts.Achievements.Notification,
                BadgeMutationNotification("KEEP", "", 9, 0, 0));
            OwnedBadgeSnapshot badge = Assert.Single(ReadOwnedBadges(unity));
            Assert.Equal(9, (long)badge.Id);
            Assert.Equal("KEEP", badge.Code);
            Assert.Equal(33, badge.OwnerCount);
            Assert.Equal(7, badge.RarityId);
            Assert.True(badge.HasRarityData);
        }
    }

    [Fact]
    public async Task achievement_badge_game_data_loads_are_host_atomic_and_caller_scoped()
    {
        (GameData data, GameDataTransportProxy transport) = CreateGameData();
        int loaded_count = 0;
        data.Loaded += () => Interlocked.Increment(ref loaded_count);
        GameDataHostResponse first_host = transport.Configure(
            "www.habbo.com",
            "achievements.new=A");
        Task first = data.LoadAsync("game-us.habbo.com");
        await first_host.Requested.WaitAsync(test_synchronization_timeout);
        GameDataHostResponse second_host = transport.Configure(
            "www.habbo.de",
            "achievements.new=B");
        Task second = data.LoadAsync("game-de.habbo.com");
        await second_host.Requested.WaitAsync(test_synchronization_timeout);
        Assert.Equal(1, first_host.TransportCancellationCount);
        await first.WaitAsync(test_synchronization_timeout);
        second_host.Complete();
        await second.WaitAsync(test_synchronization_timeout);
        first_host.Complete();
        Assert.Equal(["B"], data.Variables!.List("achievements.new"));
        Assert.Equal(1, loaded_count);

        GameDataHostResponse without_variables = transport.Configure(
            "www.habbo.fr",
            null,
            variables_fail: true);
        Task third = data.LoadAsync("game-fr.habbo.com");
        await without_variables.Requested.WaitAsync(test_synchronization_timeout);
        without_variables.Complete();
        await third.WaitAsync(test_synchronization_timeout);
        Assert.True(data.IsLoaded);
        Assert.Null(data.Variables);
        Assert.Equal(2, loaded_count);

        var statuses = new List<string>();
        data.Status += statuses.Add;
        GameDataHostResponse failed_host = transport.Configure(
            "www.habbo.es",
            "achievements.new=FAILED");
        Task failed = data.LoadAsync("game-es.habbo.com");
        await failed_host.Requested.WaitAsync(test_synchronization_timeout);
        failed_host.Fail(new IOException("hashes unavailable"));
        await failed.WaitAsync(test_synchronization_timeout);
        Assert.False(data.IsLoaded);
        Assert.Contains(statuses, value => value.Contains(
            "hashes unavailable",
            StringComparison.Ordinal));
        Assert.Equal(2, loaded_count);

        (GameData coalesced, GameDataTransportProxy coalesced_transport) = CreateGameData();
        int coalesced_loaded = 0;
        coalesced.Loaded += () => Interlocked.Increment(ref coalesced_loaded);
        GameDataHostResponse shared_host = coalesced_transport.Configure(
            "www.habbo.de",
            "achievements.new=SHARED");
        using var cancellation = new CancellationTokenSource();
        Task cancelled = coalesced.LoadAsync("game-de.habbo.com", cancellation.Token);
        await shared_host.Requested.WaitAsync(test_synchronization_timeout);
        Task survivor = coalesced.LoadAsync("game-de.habbo.com");
        cancellation.Cancel();
        OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => cancelled);
        Assert.Equal(cancellation.Token, error.CancellationToken);
        Assert.False(survivor.IsCompleted);
        Assert.Equal(1, shared_host.RequestCount);
        Assert.Equal(0, shared_host.TransportCancellationCount);
        shared_host.Complete();
        await survivor.WaitAsync(test_synchronization_timeout);
        Assert.Equal(["SHARED"], coalesced.Variables!.List("achievements.new"));
        Assert.Equal(1, coalesced_loaded);
        Assert.Equal(1, shared_host.RequestCount);
        Assert.Equal(0, shared_host.TransportCancellationCount);
    }

    [Fact]
    public async Task achievement_badge_game_state_adopts_preload_once_and_clears_cross_host_scope()
    {
        using var game = new GameState();
        (object transport_object, GameDataTransportProxy transport) = CreateGameDataTransport();
        typeof(GameData).GetField("transport", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(game.GameData, transport_object);
        GameDataHostResponse first_host = transport.Configure(
            "www.habbo.com",
            "achievements.new=A,B\nhabbicons.enabled=true\n" +
            "games.highscores.viewSize=11\ngames.highscores.windowSize=22");
        first_host.Complete();
        await game.GameData.LoadAsync("game-us.habbo.com");

        MessageManager messages = MessageManager.CreateWithEmbeddedMap();
        var interceptor = new FakeInterceptor(messages);
        game.Attach(interceptor);
        var contracts = new MessageContractCatalog(messages.Registry, MessageContracts.All);
        using var application = new ApplicationRuntime(interceptor, game, contracts);
        AchievementStateView before = application.Invoke<AchievementStateRequest, AchievementStateView>(
            ApplicationMemberIds.AchievementsState,
            new AchievementStateRequest());
        var first_session = new Session(
            "game-us.habbo.com",
            0,
            "smoke",
            "smoke",
            ClientType.Flash);
        interceptor.Connect(first_session);
        AchievementStateView adopted = application.Invoke<AchievementStateRequest, AchievementStateView>(
            ApplicationMemberIds.AchievementsState,
            new AchievementStateRequest());
        Assert.Equal(["A", "B"], game.Achievements.NewAchievementCodes);
        Assert.Equal(before.NewCodesRevision + 2, adopted.NewCodesRevision);
        Assert.True(game.Habbicons.IsEnabled);
        Assert.Equal(11, game.Leaderboards.ViewSize);
        Assert.Equal(22, game.Leaderboards.WindowSize);
        int same_host_updates = 0;
        IDisposable same_host_subscription = application.Subscribe<AchievementChanged>(
            ApplicationMemberIds.AchievementsChanged,
            changed =>
            {
                if (changed.Kind is AchievementChangeKind.NewCodes)
                    Interlocked.Increment(ref same_host_updates);
            });
        interceptor.Disconnect();
        interceptor.Connect(new Session(
            "game-us.habbo.com",
            0,
            "smoke",
            "smoke",
            ClientType.Flash));
        Assert.Equal(["A", "B"], game.Achievements.NewAchievementCodes);
        Assert.Equal(1, same_host_updates);
        same_host_subscription.Dispose();
        AchievementStateView same_host = application.Invoke<
            AchievementStateRequest,
            AchievementStateView>(
                ApplicationMemberIds.AchievementsState,
                new AchievementStateRequest());
        long first_token = same_host.SnapshotRevision;

        AchievementChanged? second_reset = null;
        IDisposable reset_subscription = application.Subscribe<AchievementChanged>(
            ApplicationMemberIds.AchievementsChanged,
            changed =>
            {
                if (changed.Kind is AchievementChangeKind.Reset &&
                    changed.Client is ClientType.Unity)
                {
                    second_reset = changed;
                }
            });

        GameDataHostResponse second_host = transport.Configure(
            "www.habbo.de",
            "achievements.new=C\nhabbicons.enabled=true\n" +
            "games.highscores.viewSize=17\ngames.highscores.windowSize=34");
        Task external_load = game.GameData.LoadAsync("game-de.habbo.com");
        await second_host.Requested.WaitAsync(test_synchronization_timeout);
        interceptor.Disconnect();
        var second_session = new Session(
            "game-de.habbo.com",
            0,
            "smoke",
            "smoke",
            ClientType.Unity);
        interceptor.Connect(second_session);
        AchievementStateView pending = application.Invoke<AchievementStateRequest, AchievementStateView>(
            ApplicationMemberIds.AchievementsState,
            new AchievementStateRequest());
        Assert.Empty(game.Achievements.NewAchievementCodes);
        Assert.Equal(0, pending.NewCodeCount);
        Assert.False(game.Habbicons.IsEnabled);
        Assert.Equal(8, game.Leaderboards.ViewSize);
        Assert.Equal(50, game.Leaderboards.WindowSize);
        Assert.NotNull(second_reset);
        Assert.NotNull(second_reset!.SnapshotRevision);
        AchievementStateView reset_state = application.Invoke<
            AchievementStateRequest,
            AchievementStateView>(
                ApplicationMemberIds.AchievementsState,
                new AchievementStateRequest(second_reset.SnapshotRevision));
        Assert.Equal(0, reset_state.NewCodeCount);
        AchievementPage reset_page = application.Invoke<
            AchievementPageRequest,
            AchievementPage>(
                ApplicationMemberIds.AchievementsList,
                new AchievementPageRequest(
                    SnapshotRevision: second_reset.SnapshotRevision));
        Assert.All(reset_page.Achievements, achievement => Assert.False(achievement.IsNew));
        Assert.Throws<InvalidOperationException>(() => application.Invoke<
            AchievementPageRequest,
            AchievementPage>(
                ApplicationMemberIds.AchievementsList,
                new AchievementPageRequest(SnapshotRevision: first_token)));

        second_host.Complete();
        await external_load.WaitAsync(test_synchronization_timeout);
        Assert.Equal(["C"], game.Achievements.NewAchievementCodes);
        Assert.True(game.Habbicons.IsEnabled);
        Assert.Equal(17, game.Leaderboards.ViewSize);
        Assert.Equal(34, game.Leaderboards.WindowSize);
        Assert.Equal(1, second_host.RequestCount);
        reset_subscription.Dispose();
    }

    [Fact]
    public async Task achievement_badge_game_state_applies_synchronous_connect_load_once()
    {
        using var game = new GameState();
        (object transport_object, GameDataTransportProxy transport) = CreateGameDataTransport();
        typeof(GameData).GetField("transport", BindingFlags.Instance | BindingFlags.NonPublic)!
            .SetValue(game.GameData, transport_object);
        GameDataHostResponse response = transport.Configure(
            "www.habbo.com",
            "achievements.new=SYNCHRONOUS");
        response.Complete();
        Assert.False(game.GameData.IsLoaded);

        MessageManager messages = MessageManager.CreateWithEmbeddedMap();
        var interceptor = new FakeInterceptor(messages);
        game.Attach(interceptor);
        var contracts = new MessageContractCatalog(messages.Registry, MessageContracts.All);
        using var application = new ApplicationRuntime(interceptor, game, contracts);
        int updates = 0;
        var changed = new TaskCompletionSource<AchievementChanged>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        using IDisposable subscription = application.Subscribe<AchievementChanged>(
            ApplicationMemberIds.AchievementsChanged,
            value =>
            {
                if (value.Kind is not AchievementChangeKind.NewCodes)
                    return;
                Interlocked.Increment(ref updates);
                changed.TrySetResult(value);
            });
        interceptor.Connect(new Session(
            "game-us.habbo.com",
            0,
            "smoke",
            "smoke",
            ClientType.Flash));
        AchievementChanged applied = await changed.Task.WaitAsync(test_synchronization_timeout);
        Assert.True(game.GameData.IsLoaded);
        Assert.Equal(["SYNCHRONOUS"], game.Achievements.NewAchievementCodes);
        Assert.Equal(1, applied.NewCodeCount);
        Assert.Equal(1, updates);
        Assert.Equal(1, response.RequestCount);
    }

