            (nameof(ScriptGlobals.GetEarningsTotal), typeof(Task<EarningsLine>),
                [typeof(int)], [10000]),
            (nameof(ScriptGlobals.ClaimEarnings), typeof(void),
                [typeof(EarningCategory)], [DBNull.Value]),
            (nameof(ScriptGlobals.ClaimAllEarnings), typeof(void), [], []),
            (nameof(ScriptGlobals.ClaimEarningsPerCategory),
                typeof(Task<IReadOnlyList<EarningCategory>>), [typeof(int)], [10000]),
            (nameof(ScriptGlobals.RefreshEarnings), typeof(void), [], []),
            (nameof(ScriptGlobals.OnEarningsChanged), typeof(void),
                [typeof(Action<EarningStatus>)], [DBNull.Value]),
            (nameof(ScriptGlobals.OnEarningsClaimed), typeof(void),
