                [typeof(Action<EarningCategory>)], [DBNull.Value])
        ];
        Assert.All(methods, expected =>
        {
            Assert.Single(
                typeof(ScriptGlobals).GetMethods(BindingFlags.Instance | BindingFlags.Public),
                method => method.Name == expected.Name);
            MethodInfo method = typeof(ScriptGlobals).GetMethod(
                expected.Name,
                expected.Parameters)!;
            Assert.Equal(expected.ReturnType, method.ReturnType);
            Assert.Equal(
                expected.Defaults,
                method.GetParameters().Select(parameter => parameter.DefaultValue).ToArray());
        });
        Assert.Equal(
            ["timeoutMs"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.GetEarnings))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.Equal(
            ["timeoutMs"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.GetEarningsByCategory))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.Equal(
            ["timeoutMs"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.GetEarningsTotal))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.Equal(
            ["timeoutMs"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.ClaimEarningsPerCategory))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.Equal(
            ["category"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.ClaimEarnings))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.All(
            new[]
            {
                nameof(ScriptGlobals.OnEarningsChanged),
                nameof(ScriptGlobals.OnEarningsClaimed),
                nameof(ScriptGlobals.OnEarningAvailable)
            },
            name => Assert.Equal(
                ["handler"],
                typeof(ScriptGlobals).GetMethod(name)!
                    .GetParameters().Select(parameter => parameter.Name!).ToArray()));

        ConstructorInfo line_constructor = Assert.Single(typeof(EarningsLine).GetConstructors());
        Assert.Equal(
            [typeof(EarningCategory), typeof(int), typeof(int), typeof(int), typeof(bool)],
            line_constructor.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            ["Category", "Credits", "Duckets", "Products", "HasClaimable"],
            typeof(EarningsLine).GetProperties(BindingFlags.Instance | BindingFlags.Public)
                .Select(property => property.Name).ToArray());

        using var fixture = new SurfaceFixture(ClientType.Flash);
        (string Id, ApplicationMemberKind Kind, Type? Request, Type Result)[] members =
        [
            (ApplicationMemberIds.EarningsState, ApplicationMemberKind.Query,
                typeof(EarningStateRequest), typeof(EarningStateView)),
            (ApplicationMemberIds.EarningsEntriesList, ApplicationMemberKind.Query,
                typeof(EarningEntryPageRequest), typeof(EarningEntryPage)),
            (ApplicationMemberIds.EarningsRefresh, ApplicationMemberKind.Operation,
                typeof(EarningRefreshRequest), typeof(EarningRefreshResult)),
            (ApplicationMemberIds.EarningsClaim, ApplicationMemberKind.Operation,
                typeof(EarningClaimActionRequest), typeof(EarningClaimActionResult)),
            (ApplicationMemberIds.EarningsChanged, ApplicationMemberKind.Event,
                null, typeof(EarningChanged))
        ];
        Assert.All(members, expected =>
        {
            ApplicationDescriptor descriptor = Assert.Single(
                fixture.Application.Members,
                candidate => candidate.Id == expected.Id);
            Assert.Equal(expected.Kind, descriptor.Kind);
            Assert.Equal(expected.Request, descriptor.RequestType);
            Assert.Equal(expected.Result, descriptor.ResultType);
            Assert.Equal(
                expected.Kind is ApplicationMemberKind.Event
                    ? ApplicationExposure.Ui |
                        ApplicationExposure.Cli |
                        ApplicationExposure.Scripting
                    : ApplicationExposure.All,
                descriptor.Exposure);
            ApplicationClientAvailability[] clients = fixture.Application
                .Describe(expected.Id)
                .Availability
                .Clients
                .ToArray();
            Assert.Equal(
                [ClientType.Flash, ClientType.Unity],
                clients.Select(client => client.Client).ToArray());
            Assert.All(clients, client => Assert.True(client.Supported));
        });
        Assert.Equal(
            members.Select(member => member.Id).Order(StringComparer.Ordinal),
            fixture.Application.Members
                .Where(member => member.Id.StartsWith("earnings.", StringComparison.Ordinal))
                .Select(member => member.Id));

        ApplicationDescriptor entries_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.EarningsEntriesList);
        Assert.Equal(
            ["offset", "limit", "snapshot_revision"],
            entries_descriptor.Parameters.Select(parameter => parameter.Name).ToArray());
        Assert.Equal(
            [0, 100, null],
            entries_descriptor.Parameters.Select(parameter => parameter.DefaultValue).ToArray());
        Assert.Equal(0, entries_descriptor.Parameters[0].Constraints!.Minimum);
        Assert.Equal(1, entries_descriptor.Parameters[1].Constraints!.Minimum);
        Assert.Equal(500, entries_descriptor.Parameters[1].Constraints!.Maximum);
        Assert.Equal(1, entries_descriptor.Parameters[2].Constraints!.Minimum);
        ApplicationDescriptor refresh_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.EarningsRefresh);
        Assert.Equal(
            ["limit", "timeout_milliseconds", "expected_session_generation"],
            refresh_descriptor.Parameters.Select(parameter => parameter.Name).ToArray());
        Assert.Equal(
            [100, 10000, null],
            refresh_descriptor.Parameters.Select(parameter => parameter.DefaultValue).ToArray());
        Assert.Equal(120000, refresh_descriptor.Parameters[1].Constraints!.Maximum);
        ApplicationDescriptor claim_descriptor = fixture.Application.Members.Single(
            member => member.Id == ApplicationMemberIds.EarningsClaim);
        Assert.True(claim_descriptor.Parameters[0].Required);
        Assert.Equal(sbyte.MinValue, claim_descriptor.Parameters[0].Constraints!.Minimum);
        Assert.Equal(sbyte.MaxValue, claim_descriptor.Parameters[0].Constraints!.Maximum);

        using var unity = new SurfaceFixture(ClientType.Unity);
        ApplicationMessageAvailability unity_notification = fixture.Application
            .Describe(ApplicationMemberIds.EarningsChanged)
            .Availability
            .Clients
            .Single(client => client.Client == ClientType.Unity)
            .Messages
            .Single(message => message.Key == MessageKeys.Earnings.Notification);
        Assert.False(unity_notification.Required);
        Assert.False(unity_notification.Supported);
        Assert.True(unity.Application.Describe(ApplicationMemberIds.EarningsChanged)
            .Availability.Available);

        object? untyped_state = await fixture.Application.InvokeAsync(
            ApplicationMemberIds.EarningsState,
            new EarningStateRequest());
        Assert.IsType<EarningStateView>(untyped_state);
        EarningChanged? observed = null;
        using IDisposable subscription = fixture.Application.Subscribe(
            ApplicationMemberIds.EarningsChanged,
            value => observed = Assert.IsType<EarningChanged>(value));
        fixture.Receive(
            MessageContracts.Earnings.StatusSnapshot,
            new EarningStatus([new EarningEntry(
                EarningCategory.Tutorial,
                EarningRewardKind.Credits,
                1,
                "")]));
        Assert.Equal(EarningChangeKind.Snapshot, observed!.Kind);

        string source = File.ReadAllText(Path.Combine(
            FindRepositoryRoot(),
            "src",
            "QX.Scripting",
            "ScriptGlobals.Earnings.cs"));
        Assert.Contains("ApplicationMemberIds.EarningsState", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.EarningsEntriesList", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.EarningsRefresh", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.EarningsClaim", source, StringComparison.Ordinal);
        Assert.DoesNotContain("EnsureLoadedAsync", source, StringComparison.Ordinal);
        Assert.DoesNotContain("TaskCompletionSource", source, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEvent", source, StringComparison.Ordinal);
        Assert.DoesNotContain("RequestBroker", source, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageContracts", source, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageKeys", source, StringComparison.Ordinal);
        Assert.DoesNotContain(".Send(", source, StringComparison.Ordinal);

        using ScriptGlobals globals = fixture.CreateGlobals();
        foreach (Func<Task> call in new Func<Task>[]
                 {
                     async () => _ = await globals.GetEarnings(0),
                     async () => _ = await globals.GetEarningsByCategory(0),
                     async () => _ = await globals.GetEarningsTotal(0),
                     async () => _ = await globals.ClaimEarningsPerCategory(0)
                 })
        {
            ArgumentOutOfRangeException error =
                await Assert.ThrowsAsync<ArgumentOutOfRangeException>(call);
            Assert.Equal("timeoutMs", error.ParamName);
        }
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task earning_pages_and_script_reads_preserve_raw_order_and_exact_values(
        ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        EarningEntry[] expected = Enumerable.Range(0, 503)
            .Select(index => new EarningEntry(
                (EarningCategory)(sbyte)((index % 31) - 15),
                (EarningRewardKind)(sbyte)((index % 7) - 2),
                index - 250,
                index % 11 == 0 ? $"product-{index:D3}" : ""))
            .ToArray();
        expected[0] = new EarningEntry(
            (EarningCategory)sbyte.MinValue,
            EarningRewardKind.Credits,
            17,
            "");
        expected[1] = new EarningEntry(
            EarningCategory.Tutorial,
            EarningRewardKind.Duckets,
            9,
            "");
        expected[2] = new EarningEntry(
            (EarningCategory)sbyte.MinValue,
            (EarningRewardKind)sbyte.MaxValue,
            4,
            "rare-product");
        fixture.Receive(
            MessageContracts.Earnings.StatusSnapshot,
            new EarningStatus(expected));

        EarningStateView state = fixture.Application.Invoke<
            EarningStateRequest,
            EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest());
        Assert.True(state.Vault.Loaded);
        Assert.Equal(expected.Length, state.Vault.EntryCount);
        EarningEntryPage first = fixture.Application.Invoke<
            EarningEntryPageRequest,
            EarningEntryPage>(
                ApplicationMemberIds.EarningsEntriesList,
                new EarningEntryPageRequest(0, 500, state.SnapshotRevision));
        Assert.Equal(500, first.Entries.Count);
        Assert.Equal(500, first.NextOffset);
        EarningEntryPage second = fixture.Application.Invoke<
            EarningEntryPageRequest,
            EarningEntryPage>(
                ApplicationMemberIds.EarningsEntriesList,
                new EarningEntryPageRequest(500, 500, state.SnapshotRevision));
        Assert.Equal(3, second.Entries.Count);
        Assert.Null(second.NextOffset);
        Assert.Equal(state.SnapshotRevision, second.SnapshotRevision);
        Assert.Equal(
            expected.Select(entry => (int)(sbyte)(int)entry.Category),
            first.Entries.Concat(second.Entries).Select(entry => entry.Category));
        Assert.Equal(
            expected.Select(entry => (int)(sbyte)(int)entry.Kind),
            first.Entries.Concat(second.Entries).Select(entry => entry.Kind));
        Assert.Equal(
            Enumerable.Range(0, expected.Length),
            first.Entries.Concat(second.Entries).Select(entry => entry.Ordinal));
        Assert.Throws<ArgumentException>(() => fixture.Application.Invoke<
            EarningEntryPageRequest,
            EarningEntryPage>(
                ApplicationMemberIds.EarningsEntriesList,
                new EarningEntryPageRequest(500, 500)));

        using ScriptGlobals globals = fixture.CreateGlobals();
        EarningStatus status = await globals.GetEarnings();
        AssertEarningStatus(new EarningStatus(expected), status);
        IReadOnlyList<EarningsLine> lines = await globals.GetEarningsByCategory();
        Assert.Equal(status.Categories, lines.Select(line => line.Category).ToArray());
        Assert.All(lines, line =>
        {
            Assert.Equal(status.Credits(line.Category), line.Credits);
            Assert.Equal(status.Duckets(line.Category), line.Duckets);
            Assert.Equal(status.Products(line.Category), line.Products);
            Assert.Equal(status.HasClaimable(line.Category), line.HasClaimable);
        });
        EarningsLine total = await globals.GetEarningsTotal();
        Assert.Equal(EarningCategory.All, total.Category);
        Assert.Equal(status.Credits(), total.Credits);
        Assert.Equal(status.Duckets(), total.Duckets);
        Assert.Equal(status.Products(), total.Products);
        Assert.Equal(status.HasClaimable(), total.HasClaimable);
        Assert.Equal(0, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));

        var tokens = new List<long>();
        for (int index = 0; index < 5; index++)
        {
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    (EarningCategory)index,
                    EarningRewardKind.Credits,
                    index + 1,
                    "")]));
            tokens.Add(fixture.Application.Invoke<EarningStateRequest, EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest()).SnapshotRevision);
        }
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            EarningStateRequest,
            EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest(tokens[0])));
        EarningStateView retained = fixture.Application.Invoke<
            EarningStateRequest,
            EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest(tokens[^1]));
        Assert.Equal(tokens[^1], retained.SnapshotRevision);
    }

    [Fact]
    public async Task earning_script_refresh_claims_and_failures_preserve_legacy_behavior()
    {
        using (var unloaded = new SurfaceFixture(ClientType.Flash))
        using (ScriptGlobals globals = unloaded.CreateGlobals())
        {
            Task<EarningStatus> read = globals.GetEarnings(test_request_timeout_ms);
            await unloaded.WaitForEarningRequestCount(
                MessageKeys.Earnings.StatusRequest,
                1).WaitAsync(test_synchronization_timeout);
            unloaded.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    EarningCategory.Tutorial,
                    EarningRewardKind.Credits,
                    12,
                    "")]));
            Assert.Equal(12, (await read.WaitAsync(test_synchronization_timeout)).Credits());
        }

        using (var fixture = new SurfaceFixture(ClientType.Unity))
        using (ScriptGlobals globals = fixture.CreateGlobals())
        {
            EarningCategory first_category = (EarningCategory)(-17);
            EarningCategory second_category = (EarningCategory)99;
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus(
                [
                    new EarningEntry(first_category, EarningRewardKind.Credits, 2, ""),
                    new EarningEntry(EarningCategory.DailyGift, EarningRewardKind.Duckets, 50, ""),
                    new EarningEntry(second_category, (EarningRewardKind)7, 3, "item")
                ]));
            Task<IReadOnlyList<EarningCategory>> claims =
                globals.ClaimEarningsPerCategory(test_request_timeout_ms);
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.Claim,
                1).WaitAsync(test_synchronization_timeout);
            Assert.Equal(first_category, fixture.LastEarningClaim!.Category);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
            fixture.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(first_category, false));
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.Claim,
