                globals.ClaimEarningsPerCategory(test_request_timeout_ms);
            await disconnected.WaitForEarningRequestCount(
                MessageKeys.Earnings.Claim,
                1).WaitAsync(test_synchronization_timeout);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => claims);
