        using (var reconnected = new SurfaceFixture(ClientType.Flash))
        using (ScriptGlobals globals = reconnected.CreateGlobals())
        {
            reconnected.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus(
                [
                    new EarningEntry(EarningCategory.Tutorial,
                        EarningRewardKind.Credits, 1, ""),
                    new EarningEntry(EarningCategory.Achievements,
                        EarningRewardKind.Credits, 2, "")
                ]));
            var second_session = new Session(
                "game-de.habbo.com",
                0,
                "smoke",
                "smoke",
                ClientType.Flash);
            int dispatch_attempts = 0;
            reconnected.BeforeEarningDispatch = key =>
            {
                if (key == MessageKeys.Earnings.Claim &&
                    Interlocked.Increment(ref dispatch_attempts) == 2)
                {
                    reconnected.Connect(second_session);
                }
            };
            Task<IReadOnlyList<EarningCategory>> claims =
                globals.ClaimEarningsPerCategory(test_request_timeout_ms);
            await reconnected.WaitForEarningRequestCount(
                MessageKeys.Earnings.Claim,
                1).WaitAsync(test_synchronization_timeout);
            reconnected.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(EarningCategory.Tutorial, true));
            await Assert.ThrowsAnyAsync<InvalidOperationException>(() => claims);
            Assert.Equal(2, dispatch_attempts);
            Assert.Equal(1, reconnected.EarningRequestCount(MessageKeys.Earnings.Claim));
        }

        using (var legacy = new SurfaceFixture(ClientType.Flash))
        using (ScriptGlobals globals = legacy.CreateGlobals())
        {
            int changed = 0;
            int claimed = 0;
            int available = 0;
            var order = new List<string>();
            var sent_categories = new List<EarningCategory>();
            legacy.AfterEarningDispatch = key =>
            {
                if (key == MessageKeys.Earnings.Claim)
                    sent_categories.Add(legacy.LastEarningClaim!.Category);
            };
            globals.OnEarningsChanged(_ =>
            {
                changed++;
                order.Add("status");
            });
            globals.OnEarningsClaimed(_ =>
            {
                claimed++;
                order.Add("claimed");
            });
            globals.OnEarningAvailable(_ =>
            {
                available++;
                order.Add("available");
            });
            globals.RefreshEarnings();
            globals.RefreshEarnings();
            globals.ClaimEarnings((EarningCategory)255);
            globals.ClaimAllEarnings();
            Assert.Equal(2, legacy.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            Assert.Equal(2, legacy.EarningRequestCount(MessageKeys.Earnings.Claim));
            Assert.Equal(
                [EarningCategory.All, EarningCategory.All],
                sent_categories);
            Assert.Equal(EarningCategory.All, legacy.LastEarningClaim!.Category);
            legacy.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    EarningCategory.Tutorial,
                    EarningRewardKind.Credits,
                    1,
                    "")]));
            Assert.Equal(["status"], order);
            order.Clear();
            legacy.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(EarningCategory.All, true));
            Assert.Equal(["claimed", "status"], order);
            order.Clear();
            legacy.Receive(
                MessageContracts.Earnings.Notification,
                new EarningNotification(EarningCategory.Tutorial));
            Assert.Equal(["available"], order);
            order.Clear();
            legacy.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(EarningCategory.Tutorial, false));
            Assert.Equal(["claimed"], order);
            order.Clear();
            legacy.Connect(new Session(
                "game-de.habbo.com",
                0,
                "smoke",
                "smoke",
                ClientType.Flash));
            Assert.Empty(order);
            legacy.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(EarningCategory.Tutorial, true));
            Assert.Equal(["claimed"], order);
            order.Clear();
            legacy.Disconnect();
            Assert.Empty(order);
            Assert.Equal(2, changed);
            Assert.Equal(3, claimed);
            Assert.Equal(1, available);
        }
    }

    [Fact]
    public async Task earning_status_waiters_coalesce_and_detach_independently()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        using (var first_cancellation = new CancellationTokenSource())
        {
            Task<EarningRefreshResult> first = RefreshEarnings(
                fixture,
                test_request_timeout_ms,
                first_cancellation.Token);
            Task<EarningRefreshResult> second = RefreshEarnings(fixture, test_request_timeout_ms);
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.StatusRequest,
                1).WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            first_cancellation.Cancel();
            OperationCanceledException cancelled = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => first);
            Assert.Equal(first_cancellation.Token, cancelled.CancellationToken);
            Assert.False(second.IsCompleted);
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    EarningCategory.Tutorial,
                    EarningRewardKind.Credits,
                    7,
                    "")]));
            EarningRefreshResult result = await second.WaitAsync(test_synchronization_timeout);
            Assert.Equal(7, result.FirstPage.Vault.Credits);
            Assert.Equal(0, result.MessagesDispatched);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
        }

        using (var fixture = new SurfaceFixture(ClientType.Unity))
        {
            var entered = new TaskCompletionSource(
                TaskCreationOptions.RunContinuationsAsynchronously);
            using var release = new ManualResetEventSlim();
            fixture.BeforeEarningDispatch = key =>
            {
                if (key != MessageKeys.Earnings.StatusRequest)
                    return;
                entered.TrySetResult();
                if (!release.Wait(test_synchronization_timeout))
                    throw new TimeoutException("earning dispatch gate");
            };
            Task<EarningStatus> ensure = Task.Run(
                async () => await fixture.Earnings.EnsureLoadedAsync(test_request_timeout_ms));
            await entered.Task.WaitAsync(test_synchronization_timeout);
            Task<EarningRefreshResult> refresh = RefreshEarnings(fixture, test_request_timeout_ms);
            release.Set();
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.StatusRequest,
                1).WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    EarningCategory.DailyGift,
                    EarningRewardKind.Credits,
                    8,
                    "")]));
            Assert.Equal(8, (await ensure.WaitAsync(test_synchronization_timeout)).Credits());
            EarningRefreshResult promoted = await refresh.WaitAsync(test_synchronization_timeout);
            Assert.Equal(8, promoted.FirstPage.Vault.Credits);
            Assert.Equal(1, promoted.MessagesDispatched);
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            Task<EarningRefreshResult> timed_out = RefreshEarnings(fixture, 100);
            Task<EarningRefreshResult> survivor = RefreshEarnings(fixture, test_request_timeout_ms);
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.StatusRequest,
                1).WaitAsync(test_synchronization_timeout);
            await Assert.ThrowsAsync<RequestTimeoutException>(() => timed_out);
            Assert.False(survivor.IsCompleted);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([]));
            await survivor.WaitAsync(test_synchronization_timeout);
        }

        using (var fixture = new SurfaceFixture(ClientType.Unity))
        {
            Task<EarningRefreshResult> pending = RefreshEarnings(fixture, test_request_timeout_ms);
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.StatusRequest,
                1).WaitAsync(test_synchronization_timeout);
            fixture.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => pending);
        }
    }

