    [Fact]
    public async Task earning_claims_are_fifo_per_category_and_parallel_across_categories()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        using var first_cancellation = new CancellationTokenSource();
        int first_category = (int)EarningCategory.Tutorial;
        int second_category = (int)EarningCategory.Achievements;
        Task<EarningClaimActionResult> first = ClaimEarning(
            fixture,
            first_category,
            test_request_timeout_ms,
            first_cancellation.Token);
        await fixture.WaitForEarningRequestCount(
            MessageKeys.Earnings.Claim,
            1).WaitAsync(test_synchronization_timeout);
        Assert.Equal(EarningCategory.Tutorial, fixture.LastEarningClaim!.Category);
        Task<EarningClaimActionResult> queued = ClaimEarning(
            fixture,
            first_category,
            test_request_timeout_ms);
        Task<EarningClaimActionResult> parallel = ClaimEarning(
            fixture,
            second_category,
            test_request_timeout_ms);
        await fixture.WaitForEarningRequestCount(
            MessageKeys.Earnings.Claim,
            2).WaitAsync(test_synchronization_timeout);
        Assert.Equal(EarningCategory.Achievements, fixture.LastEarningClaim!.Category);
        first_cancellation.Cancel();
        OperationCanceledException cancelled = await Assert.ThrowsAnyAsync<
            OperationCanceledException>(() => first);
        Assert.Equal(first_cancellation.Token, cancelled.CancellationToken);
        Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));

        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Achievements, true));
        EarningClaimActionResult parallel_result =
            await parallel.WaitAsync(test_synchronization_timeout);
        Assert.True(parallel_result.Success);
        Assert.False(queued.IsCompleted);
        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Tutorial, false));
        await fixture.WaitForEarningRequestCount(
            MessageKeys.Earnings.Claim,
            3).WaitAsync(test_synchronization_timeout);
        Assert.Equal(EarningCategory.Tutorial, fixture.LastEarningClaim!.Category);
        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Tutorial, true));
        EarningClaimActionResult queued_result = await queued.WaitAsync(test_synchronization_timeout);
        Assert.True(queued_result.Success);
        Assert.Equal(1, queued_result.MessagesDispatched);
    }

    [Fact]
    public async Task earning_typed_claim_waits_for_all_passive_same_category_claims()
    {
        using var fixture = new SurfaceFixture(ClientType.Unity);
        fixture.Earnings.Claim(EarningCategory.Tutorial);
        fixture.Earnings.Claim(EarningCategory.Tutorial);
        Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
        Assert.Equal(2, EarningClaimOutstanding(
            fixture.Earnings,
            (int)EarningCategory.Tutorial));
        Task<EarningClaimActionResult> typed = ClaimEarning(
            fixture,
            (int)EarningCategory.Tutorial,
            test_request_timeout_ms);
        Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
        Assert.Equal(2, EarningClaimOutstanding(
            fixture.Earnings,
            (int)EarningCategory.Tutorial));
        Assert.False(typed.IsCompleted);
        var guard_entered = new TaskCompletionSource(
            TaskCreationOptions.RunContinuationsAsynchronously);
        using var guard_release = new ManualResetEventSlim();
        fixture.BeforeEarningDispatch = key =>
        {
            if (key != MessageKeys.Earnings.Claim)
                return;
            guard_entered.TrySetResult();
            if (!guard_release.Wait(test_synchronization_timeout))
                throw new TimeoutException("earning claim counter gate");
        };

        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Tutorial, false));
        Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
        Assert.Equal(1, EarningClaimOutstanding(
            fixture.Earnings,
            (int)EarningCategory.Tutorial));
        Assert.False(typed.IsCompleted);
        Task second_response = Task.Run(() => fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Tutorial, false)));
        try
        {
            await guard_entered.Task.WaitAsync(test_synchronization_timeout);
            Assert.Equal(0, EarningClaimOutstanding(
                fixture.Earnings,
                (int)EarningCategory.Tutorial));
            Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
        }
        finally
        {
            guard_release.Set();
        }
        await second_response.WaitAsync(test_synchronization_timeout);
        await fixture.WaitForEarningRequestCount(
            MessageKeys.Earnings.Claim,
            3).WaitAsync(test_synchronization_timeout);
        Assert.Equal(1, EarningClaimOutstanding(
            fixture.Earnings,
            (int)EarningCategory.Tutorial));
        Assert.False(typed.IsCompleted);
        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Achievements, true));
        Assert.Equal(1, EarningClaimOutstanding(
            fixture.Earnings,
            (int)EarningCategory.Tutorial));
        Assert.False(typed.IsCompleted);
        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Tutorial, true));
        EarningClaimActionResult result = await typed.WaitAsync(test_synchronization_timeout);
        Assert.True(result.Success);
        Assert.Equal((int)EarningCategory.Tutorial, result.Category);
        Assert.Equal(1, result.MessagesDispatched);
        Assert.Equal(0, EarningClaimOutstanding(
            fixture.Earnings,
            (int)EarningCategory.Tutorial));
    }

    [Fact]
