                queued_cancellation.Token);
            Task<EarningClaimActionResult> survivor = ClaimEarning(
                fixture,
                (int)EarningCategory.Tutorial,
                test_request_timeout_ms);
            queued_cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => cancelled);
            Assert.Equal(queued_cancellation.Token, error.CancellationToken);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
            fixture.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(EarningCategory.Tutorial, false));
            Assert.False((await head.WaitAsync(test_synchronization_timeout)).Success);
            await fixture.WaitForEarningRequestCount(
                MessageKeys.Earnings.Claim,
                2).WaitAsync(test_synchronization_timeout);
            Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
            fixture.Receive(
                MessageContracts.Earnings.Claimed,
                new EarningClaimResult(EarningCategory.Tutorial, true));
            Assert.True((await survivor.WaitAsync(test_synchronization_timeout)).Success);
        }
    }

    [Fact]
    public async Task earning_outstanding_requests_and_claim_journal_require_a_clean_cycle()
    {
        using var fixture = new SurfaceFixture(ClientType.Unity);
        EarningStatus baseline = new(
        [
            new EarningEntry(EarningCategory.Tutorial, EarningRewardKind.Credits, 1, ""),
            new EarningEntry(EarningCategory.DailyGift, EarningRewardKind.Credits, 2, ""),
            new EarningEntry(EarningCategory.Achievements, EarningRewardKind.Credits, 3, "")
        ]);
        fixture.Receive(MessageContracts.Earnings.StatusSnapshot, baseline);
        fixture.Earnings.Request();
        fixture.Earnings.Request();
        fixture.Earnings.Claim(EarningCategory.Tutorial);
        Assert.Equal(2, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
        Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.Claim));
        fixture.Receive(
            MessageContracts.Earnings.Claimed,
            new EarningClaimResult(EarningCategory.Tutorial, true));
        Assert.Equal(
            [EarningCategory.DailyGift, EarningCategory.Achievements],
