        fixture.Earnings.Request();
        Assert.Equal(3, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
        fixture.Receive(MessageContracts.Earnings.StatusSnapshot, baseline);
        Assert.DoesNotContain(
            EarningCategory.Tutorial,
            fixture.Earnings.Status.Categories);
        fixture.Receive(MessageContracts.Earnings.StatusSnapshot, baseline);
        Assert.DoesNotContain(
            EarningCategory.Tutorial,
            fixture.Earnings.Status.Categories);
        fixture.Receive(MessageContracts.Earnings.StatusSnapshot, baseline);
        Assert.DoesNotContain(
            EarningCategory.Tutorial,
            fixture.Earnings.Status.Categories);

        Task<EarningRefreshResult> refresh = RefreshEarnings(fixture, test_request_timeout_ms);
        await fixture.WaitForEarningRequestCount(
            MessageKeys.Earnings.StatusRequest,
            4).WaitAsync(test_synchronization_timeout);
        EarningStatus clean = new(
        [
            new EarningEntry(EarningCategory.DailyGift, EarningRewardKind.Credits, 20, ""),
            new EarningEntry(EarningCategory.Achievements, EarningRewardKind.Credits, 30, ""),
            new EarningEntry(EarningCategory.Marketplace, EarningRewardKind.Credits, 40, "")
        ]);
        fixture.Receive(MessageContracts.Earnings.StatusSnapshot, clean);
        EarningRefreshResult result = await refresh.WaitAsync(test_synchronization_timeout);
        Assert.Equal(90, result.FirstPage.Vault.Credits);
        AssertEarningStatus(clean, fixture.Earnings.Status);

        fixture.Receive(MessageContracts.Earnings.StatusSnapshot, baseline);
        AssertEarningStatus(baseline, fixture.Earnings.Status);
    }

    [Fact]
    public async Task earning_notifications_events_resets_and_disposal_are_session_safe()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    EarningCategory.Tutorial,
                    EarningRewardKind.Credits,
                    1,
                    "")]));
            int second_observer = 0;
            int changed_observer = 0;
            var order = new List<string>();
            fixture.AfterEarningDispatch = key =>
            {
                if (key == MessageKeys.Earnings.StatusRequest)
                    order.Add("request");
            };
            fixture.Earnings.RewardAvailable += _ => throw new InvalidOperationException("observer");
            fixture.Earnings.RewardAvailable += _ =>
            {
                second_observer++;
                order.Add("available");
            };
            using IDisposable changed_subscription = fixture.Application.Subscribe<EarningChanged>(
                ApplicationMemberIds.EarningsChanged,
                _ => throw new InvalidOperationException("application observer"));
            using IDisposable retained_subscription = fixture.Application.Subscribe<EarningChanged>(
                ApplicationMemberIds.EarningsChanged,
                changed =>
                {
                    if (changed.Kind is EarningChangeKind.Notification)
                    {
                        changed_observer++;
                        order.Add("changed");
                    }
                });
            fixture.Receive(
                MessageContracts.Earnings.Notification,
                new EarningNotification(EarningCategory.Tutorial));
            Assert.Equal(1, second_observer);
            Assert.Equal(1, changed_observer);
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            Assert.Equal(["changed", "available", "request"], order);
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                fixture.Earnings.Status);
            fixture.Earnings.RefreshOnNotification = false;
            order.Clear();
            fixture.Receive(
                MessageContracts.Earnings.Notification,
                new EarningNotification(EarningCategory.DailyGift));
            Assert.Equal(1, fixture.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            Assert.Equal(["changed", "available"], order);
        }

        using (var unloaded = new SurfaceFixture(ClientType.Flash))
        {
            unloaded.Receive(
                MessageContracts.Earnings.Notification,
                new EarningNotification(EarningCategory.Tutorial));
            Assert.Equal(0, unloaded.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
        }

        using (var drift = new SurfaceFixture(ClientType.Flash))
        {
            drift.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([new EarningEntry(
                    EarningCategory.Tutorial,
                    EarningRewardKind.Credits,
                    1,
                    "")]));
            var second_session = new Session(
                "game-de.habbo.com",
                0,
                "smoke",
                "smoke",
                ClientType.Flash);
            drift.Earnings.RewardAvailable += _ =>
            {
                drift.Connect(second_session);
                drift.Receive(
                    MessageContracts.Earnings.StatusSnapshot,
                    new EarningStatus([new EarningEntry(
                        EarningCategory.Achievements,
                        EarningRewardKind.Credits,
                        9,
                        "")]));
            };
            drift.Receive(
                MessageContracts.Earnings.Notification,
                new EarningNotification(EarningCategory.Tutorial));
            Assert.Equal(0, drift.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
            Assert.Equal([EarningCategory.Achievements], drift.Earnings.Status.Categories);
        }

        using (var fixture = new SurfaceFixture(ClientType.Unity))
        {
            var changes = new List<EarningChangeKind>();
            int legacy_status = 0;
            fixture.Earnings.StatusChanged += _ => legacy_status++;
            using IDisposable subscription = fixture.Application.Subscribe<EarningChanged>(
                ApplicationMemberIds.EarningsChanged,
                changed => changes.Add(changed.Kind));
            fixture.Receive(
                MessageContracts.Earnings.StatusSnapshot,
                new EarningStatus([]));
            fixture.Disconnect();
            Assert.Equal([EarningChangeKind.Snapshot, EarningChangeKind.Reset], changes);
            Assert.Equal(1, legacy_status);
        }

        var changed_dispose = new SurfaceFixture(ClientType.Flash);
        changed_dispose.Receive(
            MessageContracts.Earnings.StatusSnapshot,
            new EarningStatus([new EarningEntry(
                EarningCategory.Tutorial,
                EarningRewardKind.Credits,
                1,
                "")]));
        IDisposable changed_dispose_subscription =
            changed_dispose.Application.Subscribe<EarningChanged>(
                ApplicationMemberIds.EarningsChanged,
                changed =>
                {
                    if (changed.Kind is EarningChangeKind.Notification)
                        changed_dispose.Application.Dispose();
                });
        Task changed_notification = Task.Run(() => changed_dispose.Receive(
            MessageContracts.Earnings.Notification,
            new EarningNotification(EarningCategory.Tutorial)));
        await changed_notification.WaitAsync(test_synchronization_timeout);
        Assert.Equal(
            0,
            changed_dispose.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
        Assert.Throws<ObjectDisposedException>(() => changed_dispose.Application.Invoke<
            EarningStateRequest,
            EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest()));
        changed_dispose_subscription.Dispose();
        changed_dispose.Dispose();

        var reward_dispose = new SurfaceFixture(ClientType.Flash);
        reward_dispose.Receive(
            MessageContracts.Earnings.StatusSnapshot,
            new EarningStatus([new EarningEntry(
                EarningCategory.Tutorial,
                EarningRewardKind.Credits,
                1,
                "")]));
        reward_dispose.Earnings.RewardAvailable += _ =>
            reward_dispose.Application.Dispose();
        Task reward_notification = Task.Run(() => reward_dispose.Receive(
            MessageContracts.Earnings.Notification,
            new EarningNotification(EarningCategory.Tutorial)));
        await reward_notification.WaitAsync(test_synchronization_timeout);
        Assert.Equal(
            0,
            reward_dispose.EarningRequestCount(MessageKeys.Earnings.StatusRequest));
        Assert.Throws<ObjectDisposedException>(() => reward_dispose.Application.Invoke<
            EarningStateRequest,
            EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest()));
        reward_dispose.Dispose();

        var disposing = new SurfaceFixture(ClientType.Flash);
        IDisposable dispose_subscription = disposing.Application.Subscribe<EarningChanged>(
            ApplicationMemberIds.EarningsChanged,
            _ => disposing.Application.Dispose());
        Task receive = Task.Run(() => disposing.Receive(
            MessageContracts.Earnings.StatusSnapshot,
            new EarningStatus([])));
        await receive.WaitAsync(test_synchronization_timeout);
        Assert.Throws<ObjectDisposedException>(() => disposing.Application.Invoke<
            EarningStateRequest,
            EarningStateView>(
                ApplicationMemberIds.EarningsState,
                new EarningStateRequest()));
        dispose_subscription.Dispose();
        disposing.Dispose();
    }

    [Fact]
    public async Task earning_consumer_rejects_runtime_drift_and_invalid_pages()
    {
        foreach (EarningConsumerFailure failure in new[]
                 {
                     EarningConsumerFailure.ContinuationStateDrift,
                     EarningConsumerFailure.ZeroProgress,
                     EarningConsumerFailure.OrdinalDrift,
                     EarningConsumerFailure.SummaryDrift,
                     EarningConsumerFailure.Offline,
                     EarningConsumerFailure.RefreshSessionDrift
                 })
        {
            using var fixture = new SurfaceFixture(ClientType.Flash);
            var runtime = new EarningConsumerRuntime(failure);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            await Assert.ThrowsAsync<InvalidOperationException>(() => globals.GetEarnings(test_request_timeout_ms));
        }

        using (var fixture = new SurfaceFixture(ClientType.Unity))
        {
            var runtime = new EarningConsumerRuntime(EarningConsumerFailure.None);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            EarningStatus status = await globals.GetEarnings(test_request_timeout_ms);
            Assert.Equal(501, status.Entries.Count);
            Assert.Equal(
                [
                    ApplicationMemberIds.EarningsState,
                    ApplicationMemberIds.EarningsEntriesList,
                    ApplicationMemberIds.EarningsEntriesList
                ],
                runtime.Calls.Select(call => call.Id).ToArray());
            EarningEntryPageRequest[] pages = runtime.Calls
                .Where(call => call.Id == ApplicationMemberIds.EarningsEntriesList)
                .Select(call => Assert.IsType<EarningEntryPageRequest>(call.Request))
                .ToArray();
            Assert.Equal([0, 500], pages.Select(page => page.Offset).ToArray());
            Assert.All(pages, page =>
            {
                Assert.Equal(500, page.Limit);
                Assert.Equal(77, page.SnapshotRevision);
            });
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var runtime = new EarningConsumerRuntime(EarningConsumerFailure.Unloaded);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            Assert.False(fixture.Earnings.IsLoaded);
            EarningStatus status = await globals.GetEarnings(test_request_timeout_ms);
            Assert.Equal(501, status.Entries.Count);
            Assert.False(fixture.Earnings.IsLoaded);
            Assert.Empty(fixture.Earnings.Status.Entries);
            Assert.Equal(
                [
                    ApplicationMemberIds.EarningsState,
                    ApplicationMemberIds.EarningsRefresh,
                    ApplicationMemberIds.EarningsEntriesList
                ],
                runtime.Calls.Select(call => call.Id).ToArray());
            EarningRefreshRequest refresh = Assert.IsType<EarningRefreshRequest>(
                runtime.Calls[1].Request);
            Assert.Equal(7, refresh.ExpectedSessionGeneration);
            EarningEntryPageRequest continuation = Assert.IsType<EarningEntryPageRequest>(
                runtime.Calls[2].Request);
            Assert.Equal(500, continuation.Offset);
            Assert.Equal(77, continuation.SnapshotRevision);
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var runtime = new EarningConsumerRuntime(
                EarningConsumerFailure.ClaimMetadataDrift);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            await Assert.ThrowsAsync<InvalidOperationException>(() =>
                globals.ClaimEarningsPerCategory(test_request_timeout_ms));
            EarningClaimActionRequest request = Assert.IsType<EarningClaimActionRequest>(
                runtime.Calls.Single(call => call.Id == ApplicationMemberIds.EarningsClaim)
                    .Request);
            Assert.Equal(7, request.ExpectedSessionGeneration);
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var runtime = new EarningConsumerRuntime(
                EarningConsumerFailure.RefreshSessionDrift);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            await Assert.ThrowsAsync<InvalidOperationException>(() => globals.GetEarnings(test_request_timeout_ms));
            EarningRefreshRequest request = Assert.IsType<EarningRefreshRequest>(
                runtime.Calls.Single(call => call.Id == ApplicationMemberIds.EarningsRefresh)
                    .Request);
            Assert.Equal(7, request.ExpectedSessionGeneration);
        }
    }

    [Fact]
    public async Task daily_task_consumer_abi_descriptors_and_source_routes_are_stable()
    {
        PropertyInfo daily_tasks = typeof(ScriptGlobals).GetProperty(
            nameof(ScriptGlobals.DailyTasks))!;
        Assert.Equal(typeof(DailyTaskManager), daily_tasks.PropertyType);
        Assert.False(daily_tasks.CanWrite);

        (string Name, Type ReturnType, Type[] Parameters, object?[] Defaults)[] methods =
        [
            (nameof(ScriptGlobals.GetDailyTasks), typeof(Task<IReadOnlyList<DailyTask>>),
                [typeof(int)], [10000]),
            (nameof(ScriptGlobals.GetClaimableDailyTasks),
                typeof(Task<IReadOnlyList<DailyTask>>), [typeof(int)], [10000]),
            (nameof(ScriptGlobals.ClaimDailyTask), typeof(void), [typeof(long)], [DBNull.Value]),
            (nameof(ScriptGlobals.ClaimAllDailyTasks), typeof(Task<int>),
                [typeof(int)], [10000]),
            (nameof(ScriptGlobals.RefreshDailyTasks), typeof(bool), [], []),
            (nameof(ScriptGlobals.OnDailyTaskUpdated), typeof(void),
                [typeof(Action<DailyTask>)], [DBNull.Value]),
            (nameof(ScriptGlobals.OnDailyTaskCompleted), typeof(void),
                [typeof(Action<DailyTask>)], [DBNull.Value]),
            (nameof(ScriptGlobals.OnDailyTaskClaimed), typeof(void),
                [typeof(Action<DailyTask>)], [DBNull.Value])
        ];
        Assert.All(methods, expected =>
        {
            MethodInfo method = typeof(ScriptGlobals).GetMethod(
                expected.Name,
                expected.Parameters)!;
            Assert.Equal(expected.ReturnType, method.ReturnType);
            Assert.Equal(
                expected.Defaults,
                method.GetParameters().Select(parameter => parameter.DefaultValue).ToArray());
        });
        Assert.Equal(
            ["timeoutMs"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.GetDailyTasks))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.Equal(
            ["timeoutMs"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.GetClaimableDailyTasks))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());
        Assert.Equal(
            ["taskId"],
            typeof(ScriptGlobals).GetMethod(nameof(ScriptGlobals.ClaimDailyTask))!
                .GetParameters().Select(parameter => parameter.Name!).ToArray());

        ConstructorInfo manager_constructor = Assert.Single(
            typeof(DailyTaskManager).GetConstructors());
        Assert.Empty(manager_constructor.GetParameters());
        Assert.Equal(
            [typeof(int), typeof(CancellationToken)],
            typeof(DailyTaskManager).GetMethod(nameof(DailyTaskManager.EnsureLoadedAsync))!
                .GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [10000, null],
            typeof(DailyTaskManager).GetMethod(nameof(DailyTaskManager.EnsureLoadedAsync))!
                .GetParameters().Select(parameter => parameter.DefaultValue).ToArray());

        using var fixture = new SurfaceFixture(ClientType.Flash);
        (string Id, ApplicationMemberKind Kind, Type? Request, Type Result)[] members =
        [
            (ApplicationMemberIds.DailyTasksState, ApplicationMemberKind.Query,
                typeof(DailyTaskStateRequest), typeof(DailyTaskStateView)),
            (ApplicationMemberIds.DailyTasksEntriesList, ApplicationMemberKind.Query,
                typeof(DailyTaskPageRequest), typeof(DailyTaskPage)),
            (ApplicationMemberIds.DailyTasksRefresh, ApplicationMemberKind.Operation,
                typeof(DailyTaskRefreshRequest), typeof(DailyTaskRefreshResult)),
            (ApplicationMemberIds.DailyTasksClaim, ApplicationMemberKind.Operation,
                typeof(DailyTaskClaimActionRequest), typeof(DailyTaskClaimDispatchReceipt)),
            (ApplicationMemberIds.DailyTasksChanged, ApplicationMemberKind.Event,
                null, typeof(DailyTaskChanged))
        ];
        Assert.Equal(
            members.Select(member => member.Id).Order(StringComparer.Ordinal),
            fixture.Application.Members
                .Where(member => member.Id.StartsWith("daily_tasks.", StringComparison.Ordinal))
                .Select(member => member.Id));
        Assert.All(members, expected =>
        {
            ApplicationDescriptor descriptor = Assert.Single(
                fixture.Application.Members,
                member => member.Id == expected.Id);
            Assert.Equal(expected.Kind, descriptor.Kind);
            Assert.Equal(expected.Request, descriptor.RequestType);
            Assert.Equal(expected.Result, descriptor.ResultType);
            Assert.Equal(
                expected.Kind is ApplicationMemberKind.Event
                    ? ApplicationExposure.Ui |
                        ApplicationExposure.Cli |
                        ApplicationExposure.Scripting
                    : ApplicationExposure.All,
                descriptor.Exposure);
            Assert.Equal(
                expected.Kind is ApplicationMemberKind.Operation
                    ? [ApplicationStateKey.HotelConnected]
                    : [],
                descriptor.RequiredStates);
            ApplicationClientAvailability[] clients = fixture.Application
                .Describe(expected.Id)
                .Availability
                .Clients
                .ToArray();
            Assert.True(clients.Single(client => client.Client == ClientType.Flash).Supported);
            Assert.False(clients.Single(client => client.Client == ClientType.Unity).Supported);
        });
        Assert.Equal(
            ["offset", "limit", "snapshot_revision"],
            fixture.Application.Members.Single(
                member => member.Id == ApplicationMemberIds.DailyTasksEntriesList)
                .Parameters.Select(parameter => parameter.Name).ToArray());
        Assert.Equal(
            ["limit", "timeout_milliseconds", "expected_session_generation"],
            fixture.Application.Members.Single(
                member => member.Id == ApplicationMemberIds.DailyTasksRefresh)
                .Parameters.Select(parameter => parameter.Name).ToArray());
        Assert.Equal(
            ["task_id", "expected_session_generation"],
            fixture.Application.Members.Single(
                member => member.Id == ApplicationMemberIds.DailyTasksClaim)
                .Parameters.Select(parameter => parameter.Name).ToArray());
        Assert.True(fixture.DailyTasks.IsSupported);
        using var unity = new SurfaceFixture(ClientType.Unity);
        Assert.False(unity.DailyTasks.IsSupported);
        DailyTaskStateView unity_state = unity.Application.Invoke<
            DailyTaskStateRequest,
            DailyTaskStateView>(
                ApplicationMemberIds.DailyTasksState,
                new DailyTaskStateRequest());
        Assert.True(unity_state.Connected);
        Assert.Equal(ClientType.Unity, unity_state.Client);
        Assert.False(unity_state.Summary.Loaded);

        string source = File.ReadAllText(Path.Combine(
            FindRepositoryRoot(),
            "src",
            "QX.Scripting",
            "ScriptGlobals.DailyTasks.cs"));
        Assert.Contains("ApplicationMemberIds.DailyTasksState", source, StringComparison.Ordinal);
        Assert.Contains(
            "ApplicationMemberIds.DailyTasksEntriesList",
            source,
            StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.DailyTasksRefresh", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.DailyTasksClaim", source, StringComparison.Ordinal);
        Assert.DoesNotContain("EnsureLoadedAsync", source, StringComparison.Ordinal);
        Assert.DoesNotContain("RequestBroker", source, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageContracts", source, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageKeys", source, StringComparison.Ordinal);
        Assert.DoesNotContain(".Send(", source, StringComparison.Ordinal);

        using ScriptGlobals globals = fixture.CreateGlobals();
        foreach (Func<Task> call in new Func<Task>[]
                 {
                     async () => _ = await globals.GetDailyTasks(0),
                     async () => _ = await globals.GetClaimableDailyTasks(0),
                     async () => _ = await globals.ClaimAllDailyTasks(0)
                 })
        {
            ArgumentOutOfRangeException error =
                await Assert.ThrowsAsync<ArgumentOutOfRangeException>(call);
            Assert.Equal("timeoutMs", error.ParamName);
        }
    }

    [Fact]
    public async Task daily_task_pages_script_reads_and_claims_preserve_exact_values()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        DailyTask[] input = Enumerable.Range(0, 503)
            .Select(index => CreateDailyTask(
                index + 1,
                index % 127 == 0,
                index % 19 == 0 ? DailyTaskStatus.Completed : DailyTaskStatus.InProgress,
                index))
            .ToArray();
        DailyTask[] expected =
        [
            .. input.Where(task => !task.IsBonus),
            .. input.Where(task => task.IsBonus)
        ];
        fixture.Receive(
            MessageContracts.DailyTasks.Snapshot,
            new DailyTasksActiveList(input));

        DailyTaskStateView state = fixture.Application.Invoke<
            DailyTaskStateRequest,
            DailyTaskStateView>(
                ApplicationMemberIds.DailyTasksState,
                new DailyTaskStateRequest());
        Assert.True(state.Summary.Loaded);
        Assert.Equal(503, state.Summary.Total);
        DailyTaskPage first = fixture.Application.Invoke<
            DailyTaskPageRequest,
            DailyTaskPage>(
                ApplicationMemberIds.DailyTasksEntriesList,
                new DailyTaskPageRequest(0, 500, state.SnapshotRevision));
        DailyTaskPage second = fixture.Application.Invoke<
            DailyTaskPageRequest,
            DailyTaskPage>(
                ApplicationMemberIds.DailyTasksEntriesList,
                new DailyTaskPageRequest(500, 500, state.SnapshotRevision));
        Assert.Equal(500, first.Tasks.Count);
        Assert.Equal(500, first.NextOffset);
        Assert.Equal(3, second.Tasks.Count);
        Assert.Null(second.NextOffset);
        Assert.Equal(
            expected.Select(task => task.TaskId),
            first.Tasks.Concat(second.Tasks).Select(task => task.TaskId));
        Assert.Throws<ArgumentException>(() => fixture.Application.Invoke<
            DailyTaskPageRequest,
            DailyTaskPage>(
                ApplicationMemberIds.DailyTasksEntriesList,
                new DailyTaskPageRequest(1, 100)));

        using ScriptGlobals globals = fixture.CreateGlobals();
        IReadOnlyList<DailyTask> actual = await globals.GetDailyTasks(test_request_timeout_ms);
        Assert.Equal(0, fixture.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
        Assert.Equal(expected.Length, actual.Count);
        for (int index = 0; index < expected.Length; index++)
            AssertDailyTask(expected[index], actual[index]);
        IReadOnlyList<DailyTask> claimable = await globals.GetClaimableDailyTasks(test_request_timeout_ms);
        Assert.Equal(
            expected.Where(task => task.IsClaimable).Select(task => task.TaskId),
            claimable.Select(task => task.TaskId));

        using var claims = new SurfaceFixture(ClientType.Flash);
        DailyTask[] claim_input =
        [
            CreateDailyTask(11, false, DailyTaskStatus.Completed, 11),
            CreateDailyTask(12, false, DailyTaskStatus.InProgress, 12),
            CreateDailyTask(13, true, DailyTaskStatus.Completed, 13)
        ];
        claims.Receive(
            MessageContracts.DailyTasks.Snapshot,
            new DailyTasksActiveList(claim_input));
        using ScriptGlobals claim_globals = claims.CreateGlobals();
        Assert.Equal(2, await claim_globals.ClaimAllDailyTasks(test_request_timeout_ms));
        Assert.Equal(2, claims.DailyTaskRequestCount(MessageKeys.DailyTasks.Claim));
        Assert.Equal(13, claims.LastDailyTaskClaim!.TaskId);

        long wide_id = (long)uint.MaxValue + 2;
        DailyTaskClaimDispatchReceipt receipt = await claims.Application.InvokeAsync<
            DailyTaskClaimActionRequest,
            DailyTaskClaimDispatchReceipt>(
                ApplicationMemberIds.DailyTasksClaim,
                new DailyTaskClaimActionRequest(wide_id)).AsTask();
        Assert.Equal(wide_id, receipt.TaskId);
        Assert.Equal(1, receipt.MessagesDispatched);
        Assert.Equal(1, claims.LastDailyTaskClaim!.TaskId);
    }

    [Fact]
    public async Task daily_task_refresh_requires_a_fresh_uncontended_snapshot()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            Task<DailyTaskRefreshResult> refresh = RefreshDailyTasks(fixture, test_request_timeout_ms);
            await fixture.WaitForDailyTaskRequestCount(
                MessageKeys.DailyTasks.Request,
                1).WaitAsync(test_synchronization_timeout);
            fixture.Receive(
                MessageContracts.DailyTasks.Added,
                new DailyTasksTasksAdded([CreateDailyTask(
                    1,
                    false,
                    DailyTaskStatus.InProgress,
                    1)]));
            Assert.False(refresh.IsCompleted);
            DailyTasksActiveList snapshot = new(
            [
                CreateDailyTask(2, false, DailyTaskStatus.Completed, 2),
                CreateDailyTask(3, true, DailyTaskStatus.InProgress, 3)
            ]);
            fixture.Receive(MessageContracts.DailyTasks.Snapshot, snapshot);
            DailyTaskRefreshResult result = await refresh.WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, result.MessagesDispatched);
            Assert.Equal([2L, 3L], result.FirstPage.Tasks.Select(task => task.TaskId));
        }

        using (var overlap = new SurfaceFixture(ClientType.Flash))
        {
            Task<DailyTaskRefreshResult> refresh = RefreshDailyTasks(overlap, 400);
            await overlap.WaitForDailyTaskRequestCount(
                MessageKeys.DailyTasks.Request,
                1).WaitAsync(test_synchronization_timeout);
            Assert.True(overlap.DailyTasks.Request());
            Assert.Equal(2, overlap.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
            overlap.Receive(
                MessageContracts.DailyTasks.Snapshot,
                new DailyTasksActiveList([CreateDailyTask(
                    4,
                    false,
                    DailyTaskStatus.InProgress,
                    4)]));
            overlap.Receive(
                MessageContracts.DailyTasks.Snapshot,
                new DailyTasksActiveList([CreateDailyTask(
                    5,
                    false,
                    DailyTaskStatus.InProgress,
                    5)]));
            await Assert.ThrowsAsync<RequestTimeoutException>(() => refresh);
        }

        using (var canceled = new SurfaceFixture(ClientType.Flash))
        using (var entered = new ManualResetEventSlim())
        using (var release = new ManualResetEventSlim())
        using (var cancellation = new CancellationTokenSource())
        {
            canceled.BeforeDailyTaskDispatch = key =>
            {
                if (key == MessageKeys.DailyTasks.Request)
                {
                    entered.Set();
                    release.Wait(test_synchronization_timeout);
                }
            };
            Task<DailyTaskRefreshResult> refresh = Task.Run(() =>
                RefreshDailyTasks(canceled, test_request_timeout_ms, cancellation.Token));
            Assert.True(entered.Wait(test_synchronization_timeout));
            cancellation.Cancel();
            release.Set();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => refresh);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(0, canceled.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
        }

        using (var expired = new SurfaceFixture(ClientType.Flash))
        using (var entered = new ManualResetEventSlim())
        using (var release = new ManualResetEventSlim())
        {
            expired.BeforeDailyTaskDispatch = key =>
            {
                if (key == MessageKeys.DailyTasks.Request)
                {
                    entered.Set();
                    release.Wait(test_synchronization_timeout);
                }
            };
            Task<DailyTaskRefreshResult> refresh = Task.Run(() =>
                RefreshDailyTasks(expired, 100));
            Assert.True(entered.Wait(test_synchronization_timeout));
            await Task.Delay(150);
            release.Set();
            await Assert.ThrowsAsync<RequestTimeoutException>(() => refresh);
            Assert.Equal(0, expired.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
        }

        using (var canceled = new SurfaceFixture(ClientType.Flash))
        using (var entered = new ManualResetEventSlim())
        using (var release = new ManualResetEventSlim())
        using (var cancellation = new CancellationTokenSource())
        {
            canceled.BeforeDailyTaskDispatch = key =>
            {
                if (key == MessageKeys.DailyTasks.Claim)
                {
                    entered.Set();
                    release.Wait(test_synchronization_timeout);
                }
            };
            Task<DailyTaskClaimDispatchReceipt> claim = Task.Run(async () =>
                await canceled.Application.InvokeAsync<
                    DailyTaskClaimActionRequest,
                    DailyTaskClaimDispatchReceipt>(
                        ApplicationMemberIds.DailyTasksClaim,
                        new DailyTaskClaimActionRequest(17),
                        cancellation.Token));
            Assert.True(entered.Wait(test_synchronization_timeout));
            cancellation.Cancel();
            release.Set();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => claim);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(0, canceled.DailyTaskRequestCount(MessageKeys.DailyTasks.Claim));
        }

        using (var disconnected = new SurfaceFixture(ClientType.Flash))
        {
            Task<DailyTaskRefreshResult> refresh = RefreshDailyTasks(disconnected, test_request_timeout_ms);
            await disconnected.WaitForDailyTaskRequestCount(
                MessageKeys.DailyTasks.Request,
                1).WaitAsync(test_synchronization_timeout);
            disconnected.Disconnect();
            await Assert.ThrowsAsync<RequestDisconnectedException>(() =>
                refresh.WaitAsync(test_synchronization_timeout));
            Assert.Equal(1, disconnected.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
        }

        using (var coalesced = new SurfaceFixture(ClientType.Flash))
        {
            Task<IReadOnlyList<DailyTask>> first = coalesced.DailyTasks.EnsureLoadedAsync(test_request_timeout_ms);
            Task<IReadOnlyList<DailyTask>> second = coalesced.DailyTasks.EnsureLoadedAsync(test_request_timeout_ms);
            await coalesced.WaitForDailyTaskRequestCount(
                MessageKeys.DailyTasks.Request,
                1).WaitAsync(test_synchronization_timeout);
            coalesced.Receive(
                MessageContracts.DailyTasks.Snapshot,
                new DailyTasksActiveList([CreateDailyTask(
                    21,
                    false,
                    DailyTaskStatus.InProgress,
                    21)]));
            Assert.Equal(21, Assert.Single(await first).TaskId);
            Assert.Equal(21, Assert.Single(await second).TaskId);
            Assert.Equal(1, coalesced.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
        }
    }

    [Fact]
    public void daily_task_legacy_events_throttle_and_updates_remain_lossless()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        var order = new List<string>();
        fixture.DailyTasks.ListChanged += tasks =>
        {
            order.Add("list");
            Assert.Equal([1L, 2L], tasks.Select(task => task.TaskId));
        };
        fixture.DailyTasks.TaskUpdated += task => order.Add($"updated:{task.TaskId}");
        fixture.DailyTasks.TaskCompleted += task => order.Add($"completed:{task.TaskId}");
        fixture.DailyTasks.TaskClaimed += task => order.Add($"claimed:{task.TaskId}");
        fixture.Receive(
            MessageContracts.DailyTasks.Snapshot,
            new DailyTasksActiveList(
            [
                CreateDailyTask(2, true, DailyTaskStatus.InProgress, 2),
                CreateDailyTask(1, false, DailyTaskStatus.InProgress, 1)
            ]));
        fixture.Receive(
            MessageContracts.DailyTasks.Updated,
            new DailyTasksTaskUpdate(1, 5, DailyTaskStatus.Completed, 50));
        fixture.Receive(
            MessageContracts.DailyTasks.Updated,
            new DailyTasksTaskUpdate(1, 5, DailyTaskStatus.Claimed, 40));
        Assert.Equal(
            ["list", "updated:1", "completed:1", "updated:1", "claimed:1"],
            order);
        Assert.True(fixture.DailyTasks.Request());
        Assert.False(fixture.DailyTasks.Request());
        Assert.Equal(1, fixture.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
        fixture.DailyTasks.Claim((long)uint.MaxValue + 9);
        Assert.Equal(8, fixture.LastDailyTaskClaim!.TaskId);
        fixture.Receive(
            MessageContracts.DailyTasks.Updated,
            new DailyTasksTaskUpdate(999, 1, DailyTaskStatus.InProgress, 10));
        Assert.Equal(1, fixture.DailyTaskRequestCount(MessageKeys.DailyTasks.Request));
    }

