            Assert.Equal(200, schema_properties.GetProperty("limit").GetProperty("maximum").GetInt32());
            Assert.Equal(0, schema_properties.GetProperty("offset").GetProperty("default").GetInt32());
            Assert.Equal(0, schema_properties.GetProperty("offset").GetProperty("minimum").GetInt32());
            Assert.Equal(1000000, schema_properties.GetProperty("offset").GetProperty("maximum").GetInt32());
            Assert.Equal(1, schema_properties.GetProperty("snapshot_revision").GetProperty("minimum").GetInt32());
