            Assert.Equal(10000, schema_properties.GetProperty("timeout_ms").GetProperty("default").GetInt32());
            Assert.Equal(1, schema_properties.GetProperty("timeout_ms").GetProperty("minimum").GetInt32());
            Assert.Equal(120000, schema_properties.GetProperty("timeout_ms").GetProperty("maximum").GetInt32());
