        Assert.Contains("ApplicationMemberIds.QuestsState", hosting, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.QuestsEntriesList", hosting, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.QuestsAvailableRefresh", hosting, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.QuestsSeasonalRefresh", hosting, StringComparison.Ordinal);
        Assert.Contains("QuestCollection.Combined", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("game.Quests", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("QuestManager", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEventAsync<Quests>", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("McpQuestState", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("RequestAvailable()", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("RequestSeasonal()", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageContracts.Quests", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("MessageKeys.Quests", hosting, StringComparison.Ordinal);
    }

    [Fact]
    public async Task quest_script_collects_every_available_page_in_hotel_order()
    {
        QuestData[] quests = Enumerable.Range(0, 503)
            .Select(index => CreateQuestData(503 - index, false))
            .ToArray();
        using (var loaded = new SurfaceFixture(ClientType.Flash))
        {
            loaded.Receive(
                MessageContracts.Quests.Snapshot,
                new Quests(quests, true));
            using ScriptGlobals globals = loaded.CreateGlobals();
            IReadOnlyList<QuestData> actual = await globals.GetQuests(test_request_timeout_ms);
            Assert.Equal(0, loaded.QuestRequestCount(MessageKeys.Quests.Request));
            Assert.Equal(quests, actual);

            QuestStateView state = loaded.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest());
            QuestEntryPage first = loaded.Application.Invoke<
                QuestEntryPageRequest,
                QuestEntryPage>(
                    ApplicationMemberIds.QuestsEntriesList,
                    new QuestEntryPageRequest(
                        QuestCollection.Available,
                        0,
                        500,
                        state.SnapshotRevision));
            QuestEntryPage second = loaded.Application.Invoke<
                QuestEntryPageRequest,
                QuestEntryPage>(
                    ApplicationMemberIds.QuestsEntriesList,
                    new QuestEntryPageRequest(
                        QuestCollection.Available,
                        500,
                        500,
                        state.SnapshotRevision));
            Assert.Equal(500, first.Entries.Count);
            Assert.Equal(500, first.NextOffset);
            Assert.Equal(3, second.Entries.Count);
            Assert.Null(second.NextOffset);
            Assert.Equal(
                quests.Select(quest => quest.Id),
                first.Entries.Concat(second.Entries).Select(entry => entry.Quest.Id));
            Assert.Throws<ArgumentException>(() => loaded.Application.Invoke<
                QuestEntryPageRequest,
                QuestEntryPage>(
                    ApplicationMemberIds.QuestsEntriesList,
                    new QuestEntryPageRequest(QuestCollection.Available, 1, 100)));
        }

        using (var unloaded = new SurfaceFixture(ClientType.Unity))
        using (ScriptGlobals globals = unloaded.CreateGlobals())
        {
            Task<IReadOnlyList<QuestData>> pending = globals.GetQuests(test_request_timeout_ms);
            await unloaded.WaitForQuestRequestCount(
                MessageKeys.Quests.Request,
                1).WaitAsync(test_synchronization_timeout);
            unloaded.Receive(
                MessageContracts.Quests.Snapshot,
                new Quests(quests, false));
            IReadOnlyList<QuestData> actual = await pending.WaitAsync(test_synchronization_timeout);
            Assert.Equal(quests, actual);
            Assert.Equal(1, unloaded.QuestRequestCount(MessageKeys.Quests.Request));
        }
    }

    [Fact]
    public async Task quest_script_pins_refresh_and_continuation_metadata()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var runtime = new QuestScriptRuntime(QuestConsumerFailure.None);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            IReadOnlyList<QuestData> quests = await globals.GetQuests(test_request_timeout_ms);
            Assert.Equal(runtime.Quests, quests);
            Assert.Empty(fixture.Quests.Available);
            Assert.Equal(
                [ApplicationMemberIds.QuestsState, ApplicationMemberIds.QuestsEntriesList,
                    ApplicationMemberIds.QuestsEntriesList],
                runtime.Calls.Select(call => call.Id).ToArray());
            QuestEntryPageRequest first = Assert.IsType<QuestEntryPageRequest>(
                runtime.Calls[1].Request);
            QuestEntryPageRequest continuation = Assert.IsType<QuestEntryPageRequest>(
                runtime.Calls[2].Request);
            Assert.Equal(0, first.Offset);
            Assert.Equal(500, first.Limit);
            Assert.Equal(77, first.SnapshotRevision);
            Assert.Equal(500, continuation.Offset);
            Assert.Equal(500, continuation.Limit);
            Assert.Equal(77, continuation.SnapshotRevision);
            Assert.Equal(0, fixture.QuestRequestCount(MessageKeys.Quests.Request));
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var runtime = new QuestScriptRuntime(QuestConsumerFailure.Unloaded);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            IReadOnlyList<QuestData> quests = await globals.GetQuests(test_request_timeout_ms);
            Assert.Equal(runtime.Quests, quests);
            Assert.Empty(fixture.Quests.Available);
            Assert.Equal(
                [ApplicationMemberIds.QuestsState, ApplicationMemberIds.QuestsAvailableRefresh,
                    ApplicationMemberIds.QuestsEntriesList],
                runtime.Calls.Select(call => call.Id).ToArray());
            QuestAvailableRefreshRequest refresh = Assert.IsType<QuestAvailableRefreshRequest>(
                runtime.Calls[1].Request);
            Assert.Equal(7, refresh.ExpectedSessionGeneration);
            Assert.Equal(500, refresh.Limit);
            QuestEntryPageRequest continuation = Assert.IsType<QuestEntryPageRequest>(
                runtime.Calls[2].Request);
            Assert.Equal(500, continuation.Offset);
            Assert.Equal(77, continuation.SnapshotRevision);
        }

        foreach (QuestConsumerFailure failure in new[]
                 {
                     QuestConsumerFailure.ContinuationStateDrift,
                     QuestConsumerFailure.ZeroProgress,
                     QuestConsumerFailure.RefreshSessionDrift
                 })
        {
            using var fixture = new SurfaceFixture(ClientType.Flash);
            var runtime = new QuestScriptRuntime(failure);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            await Assert.ThrowsAsync<InvalidOperationException>(() => globals.GetQuests(test_request_timeout_ms));
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            var runtime = new QuestScriptRuntime(QuestConsumerFailure.Cancellation);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime, cancellation.Token);
            Task<IReadOnlyList<QuestData>> pending = globals.GetQuests(test_request_timeout_ms);
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => pending);
            Assert.Equal(cancellation.Token, error.CancellationToken);
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        {
            var runtime = new QuestScriptRuntime(QuestConsumerFailure.Timeout);
            using ScriptGlobals globals = fixture.CreateGlobals(runtime);
            RequestTimeoutException error = await Assert.ThrowsAsync<RequestTimeoutException>(
                () => globals.GetQuests(1234));
            Assert.Equal(1234, error.TimeoutMs);
        }
    }

    [Fact]
    public async Task quest_mcp_preserves_legacy_json_and_tokenized_combined_pages()
    {
        var runtime = new QuestMcpRuntime();
        string first = await ReadQuestMcp(
            runtime,
            true,
            false,
            2,
            0,
            null,
            10000);
        Assert.Equal(1, runtime.ReadinessCount);
        QuestAvailableRefreshRequest available_request = Assert.Single(runtime.AvailableRequests);
        QuestSeasonalRefreshRequest seasonal_request = Assert.Single(runtime.SeasonalRequests);
        Assert.Equal(500, available_request.Limit);
        Assert.Equal(500, seasonal_request.Limit);
        Assert.Equal(7, available_request.ExpectedSessionGeneration);
        Assert.Equal(7, seasonal_request.ExpectedSessionGeneration);
        Assert.InRange(available_request.TimeoutMilliseconds, 1, 10000);
        Assert.InRange(seasonal_request.TimeoutMilliseconds, 1, 10000);
        QuestEntryPageRequest first_request = Assert.Single(runtime.EntryRequests);
        Assert.Equal(QuestCollection.Combined, first_request.Collection);
        Assert.Equal(0, first_request.Offset);
        Assert.Equal(2, first_request.Limit);
        Assert.Equal(77, first_request.SnapshotRevision);
        Assert.Equal(2, runtime.StateRequests.Count);
        using (JsonDocument document = JsonDocument.Parse(first))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(
                ["query", "metadata", "data", "error"],
                root.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            Assert.Equal(
                ["ready", "loaded", "stale", "truncated", "capturedAtUtc", "pending",
                    "snapshotRevision", "nextOffset"],
                root.GetProperty("metadata").EnumerateObject()
                    .Select(property => property.Name).ToArray());
            Assert.Equal(77,
                root.GetProperty("metadata").GetProperty("snapshotRevision").GetInt64());
            Assert.Equal(2,
                root.GetProperty("metadata").GetProperty("nextOffset").GetInt32());
            JsonElement data = root.GetProperty("data");
            Assert.Equal(
                ["total", "returned", "offset", "maxItems", "truncated",
                    "availableCount", "seasonalCount", "current", "daily",
                    "lastCompleted", "lastCancelled", "quests"],
                data.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(3, data.GetProperty("total").GetInt32());
            Assert.Equal(2, data.GetProperty("returned").GetInt32());
            Assert.Equal(2, data.GetProperty("availableCount").GetInt32());
            Assert.Equal(1, data.GetProperty("seasonalCount").GetInt32());
            AssertMcpQuest(
                CreateQuestData(91, false),
                data.GetProperty("current"));
            JsonElement daily = data.GetProperty("daily");
            Assert.Equal(
                ["data", "easyQuestCount", "hardQuestCount", "hasQuest"],
                daily.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(3, daily.GetProperty("easyQuestCount").GetInt32());
            Assert.Equal(4, daily.GetProperty("hardQuestCount").GetInt32());
            Assert.True(daily.GetProperty("hasQuest").GetBoolean());
            JsonElement completed = data.GetProperty("lastCompleted");
            Assert.Equal(
                ["data", "showDialog"],
                completed.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.True(completed.GetProperty("showDialog").GetBoolean());
            JsonElement cancelled = data.GetProperty("lastCancelled");
            Assert.Equal(
                ["isExpired", "data"],
                cancelled.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.True(cancelled.GetProperty("isExpired").GetBoolean());
            JsonElement[] quests = data.GetProperty("quests").EnumerateArray().ToArray();
            Assert.Equal(2, quests.Length);
            AssertMcpQuest(runtime.Available[0], quests[0]);
            AssertMcpQuest(runtime.Available[1], quests[1]);
            Assert.False(data.TryGetProperty("details", out _));
        }

        var continuation = new QuestMcpRuntime();
        string second = await ReadQuestMcp(
            continuation,
            true,
            true,
            2,
            2,
            77,
            10000);
        Assert.Equal(0, continuation.ReadinessCount);
        Assert.Empty(continuation.AvailableRequests);
        Assert.Empty(continuation.SeasonalRequests);
        QuestStateRequest state_request = Assert.Single(continuation.StateRequests);
        Assert.Equal(77, state_request.SnapshotRevision);
        QuestEntryPageRequest continuation_request = Assert.Single(continuation.EntryRequests);
        Assert.Equal(77, continuation_request.SnapshotRevision);
        Assert.Equal(2, continuation_request.Offset);
        using (JsonDocument document = JsonDocument.Parse(second))
        {
            JsonElement metadata = document.RootElement.GetProperty("metadata");
            Assert.Equal(
                ["ready", "loaded", "stale", "truncated", "capturedAtUtc", "pending",
                    "snapshotRevision"],
                metadata.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.False(metadata.TryGetProperty("nextOffset", out _));
            JsonElement data = document.RootElement.GetProperty("data");
            JsonElement compact = Assert.Single(
                data.GetProperty("quests").EnumerateArray().ToArray());
            AssertMcpQuest(continuation.Seasonal[0], compact);
            JsonElement detail = Assert.Single(
                data.GetProperty("details").EnumerateArray().ToArray());
            Assert.Equal(
                ["campaignCode", "completedQuestsInCampaign", "questCountInCampaign",
                    "activityPointType", "id", "isAccepted", "type", "imageVersion",
                    "rewardCurrencyAmount", "localizationCode", "completedSteps", "totalSteps",
                    "sortOrder", "catalogPageName", "chainCode", "isEasy", "isSeasonal",
                    "seasonalSecondsLeft", "isCompleted", "isCampaignCompleted",
                    "isLastQuestInCampaign", "campaignChainCode"],
                detail.EnumerateObject().Select(property => property.Name).ToArray());
            Assert.Equal(continuation.Seasonal[0].Id, detail.GetProperty("id").GetInt32());
            Assert.Equal(continuation.Seasonal[0].ImageVersion,
                detail.GetProperty("imageVersion").GetString());
            Assert.Equal(continuation.Seasonal[0].SortOrder,
                detail.GetProperty("sortOrder").GetInt32());
            Assert.Equal(continuation.Seasonal[0].CampaignChainCode,
                detail.GetProperty("campaignChainCode").GetString());
        }

        var token_required = new QuestMcpRuntime();
        await Assert.ThrowsAsync<ArgumentException>(() => ReadQuestMcp(
            token_required,
            true,
            false,
            2,
            1,
            null,
            10000));
        Assert.Equal(0, token_required.ReadinessCount);
        Assert.Empty(token_required.AvailableRequests);
        Assert.Empty(token_required.SeasonalRequests);
        Assert.Empty(token_required.EntryRequests);

        var expired = new QuestMcpRuntime();
        string expired_json = await ReadQuestMcp(
            expired,
            true,
            false,
            2,
            0,
            78,
            10000);
        AssertMcpError(expired_json, "unavailable");
        Assert.Equal(0, expired.ReadinessCount);
        Assert.Empty(expired.AvailableRequests);
        Assert.Empty(expired.SeasonalRequests);
        Assert.Empty(expired.EntryRequests);

        await AssertConcreteQuestMcpOverloads();

        using var disconnected = new SurfaceFixture(ClientType.Flash);
        disconnected.Receive(
            MessageContracts.Quests.Snapshot,
            new Quests([CreateQuestData(61, false)], false));
        disconnected.Disconnect();
        QuestStateView disconnected_state = disconnected.Application.Invoke<
            QuestStateRequest,
            QuestStateView>(
                ApplicationMemberIds.QuestsState,
                new QuestStateRequest());
        Assert.False(disconnected_state.Connected);
        Assert.Null(disconnected_state.Client);
        Assert.True(disconnected_state.SessionGeneration > 0);
        string disconnected_json = await ReadLegacyQuestMcp(disconnected);
        using (JsonDocument document = JsonDocument.Parse(disconnected_json))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            Assert.False(root.GetProperty("metadata").GetProperty("loaded").GetBoolean());
            Assert.False(root.GetProperty("metadata").TryGetProperty(
                "snapshotRevision",
                out _));
            Assert.Equal(0, root.GetProperty("data").GetProperty("total").GetInt32());
        }
    }

    [Fact]
    public async Task quest_legacy_actions_and_actual_dispatch_guards_are_exact()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        using (ScriptGlobals globals = fixture.CreateGlobals())
