            globals.ActivateQuest(102);
            globals.RejectQuest(103);
            globals.CancelQuest();
            globals.OpenQuestTracker();
            globals.CompleteFriendRequestQuest();
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.Request));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.SeasonalRequest));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.DailyRequest));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.Accept));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.Activate));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.Reject));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.Cancel));
            Assert.Equal(1, fixture.QuestRequestCount(MessageKeys.Quests.TrackerOpen));
            Assert.Equal(1,
                fixture.QuestRequestCount(MessageKeys.Quests.FriendRequestCompleted));
            Assert.True(fixture.LastQuestDailyRequest!.IsEasy);
            Assert.Equal(-7, fixture.LastQuestDailyRequest.Index);
            Assert.Equal((Id)101, fixture.LastQuestAccept!.QuestId);
            Assert.Equal((Id)102, fixture.LastQuestActivate!.QuestId);
            Assert.Equal((Id)103, fixture.LastQuestReject!.QuestId);

            QuestSelectionDispatchReceipt accept = await fixture.Application.InvokeAsync<
                QuestSelectionActionRequest,
                QuestSelectionDispatchReceipt>(
                    ApplicationMemberIds.QuestsAccept,
                    new QuestSelectionActionRequest(201)).AsTask();
            QuestSelectionDispatchReceipt activate = await fixture.Application.InvokeAsync<
                QuestSelectionActionRequest,
                QuestSelectionDispatchReceipt>(
                    ApplicationMemberIds.QuestsActivate,
                    new QuestSelectionActionRequest(202)).AsTask();
            QuestSelectionDispatchReceipt reject = await fixture.Application.InvokeAsync<
                QuestSelectionActionRequest,
                QuestSelectionDispatchReceipt>(
                    ApplicationMemberIds.QuestsReject,
                    new QuestSelectionActionRequest(203)).AsTask();
            QuestDispatchReceipt cancel = await fixture.Application.InvokeAsync<
                QuestDispatchRequest,
                QuestDispatchReceipt>(
                    ApplicationMemberIds.QuestsCancel,
                    new QuestDispatchRequest()).AsTask();
            QuestDispatchReceipt tracker = await fixture.Application.InvokeAsync<
                QuestDispatchRequest,
                QuestDispatchReceipt>(
                    ApplicationMemberIds.QuestsTrackerOpen,
                    new QuestDispatchRequest()).AsTask();
            QuestDispatchReceipt friend = await fixture.Application.InvokeAsync<
                QuestDispatchRequest,
                QuestDispatchReceipt>(
                    ApplicationMemberIds.QuestsFriendRequestComplete,
                    new QuestDispatchRequest()).AsTask();
            Assert.All(
                new[] { accept, activate, reject },
                receipt => Assert.Equal(1, receipt.MessagesDispatched));
            Assert.All(
                new[] { cancel, tracker, friend },
                receipt => Assert.Equal(1, receipt.MessagesDispatched));
            Assert.Equal(2, fixture.QuestRequestCount(MessageKeys.Quests.Accept));
            Assert.Equal(2, fixture.QuestRequestCount(MessageKeys.Quests.Activate));
            Assert.Equal(2, fixture.QuestRequestCount(MessageKeys.Quests.Reject));
            Assert.Equal(2, fixture.QuestRequestCount(MessageKeys.Quests.Cancel));
            Assert.Equal(2, fixture.QuestRequestCount(MessageKeys.Quests.TrackerOpen));
            Assert.Equal(2,
                fixture.QuestRequestCount(MessageKeys.Quests.FriendRequestCompleted));
        }

        using (var unity = new SurfaceFixture(ClientType.Unity))
        {
