                QuestSelectionActionRequest,
                QuestSelectionDispatchReceipt>(
                    ApplicationMemberIds.QuestsAccept,
                    new QuestSelectionActionRequest(quest_id)).AsTask();
            Assert.Equal(quest_id, receipt.QuestId);
            Assert.Equal((Id)quest_id, unity.LastQuestAccept!.QuestId);
        }

        using (var canceled = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            canceled.BeforeQuestDispatch = key =>
            {
                if (key == MessageKeys.Quests.Accept)
                    cancellation.Cancel();
            };
            Task<QuestSelectionDispatchReceipt> pending = canceled.Application.InvokeAsync<
                QuestSelectionActionRequest,
                QuestSelectionDispatchReceipt>(
                    ApplicationMemberIds.QuestsAccept,
                    new QuestSelectionActionRequest(301),
                    cancellation.Token).AsTask();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => pending);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(0, canceled.QuestRequestCount(MessageKeys.Quests.Accept));
        }

        using (var expired = new SurfaceFixture(ClientType.Flash))
        using (var entered = new ManualResetEventSlim())
        using (var release = new ManualResetEventSlim())
        {
            expired.BeforeQuestDispatch = key =>
            {
                if (key == MessageKeys.Quests.Request)
                {
                    entered.Set();
                    release.Wait(test_synchronization_timeout);
                }
            };
            Task<QuestAvailableRefreshResult> pending = Task.Run(() =>
                RefreshAvailableQuests(expired, 100));
            try
            {
                Assert.True(entered.Wait(test_synchronization_timeout));
                await Task.Delay(150);
            }
            finally
            {
                release.Set();
            }
            await Assert.ThrowsAsync<RequestTimeoutException>(() => pending);
            Assert.Equal(0, expired.QuestRequestCount(MessageKeys.Quests.Request));
        }

        using (var canceled_refresh = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            canceled_refresh.BeforeQuestDispatch = key =>
            {
                if (key == MessageKeys.Quests.Request)
                    cancellation.Cancel();
            };
            Task<QuestAvailableRefreshResult> pending = RefreshAvailableQuests(
                canceled_refresh,
                test_request_timeout_ms,
                cancellation.Token);
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => pending);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(0,
                canceled_refresh.QuestRequestCount(MessageKeys.Quests.Request));
        }
    }

