                test_synchronization_timeout);
            Assert.Equal(1,
                same_first_result.MessagesDispatched + same_second_result.MessagesDispatched);

            Task<QuestDailyRefreshResult> first = RefreshDailyQuest(
                daily,
                false,
                2,
                test_request_timeout_ms);
            Task<QuestDailyRefreshResult> second = RefreshDailyQuest(
                daily,
                true,
                3,
                test_request_timeout_ms);
            await daily.WaitForQuestRequestCount(
                MessageKeys.Quests.DailyRequest,
                2).WaitAsync(test_synchronization_timeout);
            Assert.False(daily.LastQuestDailyRequest!.IsEasy);
            Assert.Equal(2, daily.LastQuestDailyRequest.Index);
            Assert.Equal(2, daily.QuestRequestCount(MessageKeys.Quests.DailyRequest));
            daily.Receive(
                MessageContracts.Quests.Daily,
                new QuestDaily(CreateQuestData(9, false), 4, 5));
            Assert.Equal(9, (await first.WaitAsync(test_synchronization_timeout)).Daily.Quest!.Id);
            await daily.WaitForQuestRequestCount(
                MessageKeys.Quests.DailyRequest,
                3).WaitAsync(test_synchronization_timeout);
            Assert.True(daily.LastQuestDailyRequest!.IsEasy);
            Assert.Equal(3, daily.LastQuestDailyRequest.Index);
            daily.Receive(
                MessageContracts.Quests.Daily,
                new QuestDaily(CreateQuestData(10, false), 6, 7));
            Assert.Equal(10, (await second.WaitAsync(test_synchronization_timeout)).Daily.Quest!.Id);
        }

        using (var queued = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            Task<QuestDailyRefreshResult> head = RefreshDailyQuest(
                queued,
                true,
                11,
                test_request_timeout_ms);
            await queued.WaitForQuestRequestCount(
                MessageKeys.Quests.DailyRequest,
                1).WaitAsync(test_synchronization_timeout);
            Task<QuestDailyRefreshResult> canceled = RefreshDailyQuest(
                queued,
                false,
                12,
                test_request_timeout_ms,
                cancellation.Token);
            Task<QuestDailyRefreshResult> survivor = RefreshDailyQuest(
                queued,
                true,
                13,
                test_request_timeout_ms);
            cancellation.Cancel();
            OperationCanceledException error = await Assert.ThrowsAnyAsync<
                OperationCanceledException>(() => canceled);
            Assert.Equal(cancellation.Token, error.CancellationToken);
            Assert.Equal(1, queued.QuestRequestCount(MessageKeys.Quests.DailyRequest));
            queued.Receive(
                MessageContracts.Quests.Daily,
                new QuestDaily(CreateQuestData(11, false), 1, 1));
            _ = await head.WaitAsync(test_synchronization_timeout);
            await queued.WaitForQuestRequestCount(
                MessageKeys.Quests.DailyRequest,
                2).WaitAsync(test_synchronization_timeout);
            Assert.True(queued.LastQuestDailyRequest!.IsEasy);
            Assert.Equal(13, queued.LastQuestDailyRequest.Index);
            queued.Receive(
                MessageContracts.Quests.Daily,
                new QuestDaily(CreateQuestData(13, false), 1, 1));
            Assert.Equal(13,
                (await survivor.WaitAsync(test_synchronization_timeout)).Daily.Quest!.Id);
            Assert.Equal(2, queued.QuestRequestCount(MessageKeys.Quests.DailyRequest));
        }
    }

    [Fact]
    public async Task quest_reset_publications_leases_and_daily_generations_are_terminal()
    {
        using (var publications = new SurfaceFixture(ClientType.Flash))
        {
            var legacy = new List<string>();
            var changed = new List<QuestChanged>();
            publications.Quests.AvailableChanged += value =>
                legacy.Add($"available:{value.Items.Count}");
            publications.Quests.SeasonalChanged += value =>
                legacy.Add($"seasonal:{value.Items.Count}");
            publications.Quests.CurrentChanged += value =>
                legacy.Add($"current:{value.Id}");
            publications.Quests.Completed += value =>
                legacy.Add($"completed:{value.Data.Id}:{value.ShowDialog}");
            publications.Quests.Cancelled += value =>
                legacy.Add($"cancelled:{value.Data.Id}:{value.IsExpired}");
            publications.Quests.DailyChanged += value =>
                legacy.Add($"daily:{value.Data!.Id}");
            publications.Quests.ResetCompleted += () => legacy.Add("reset");
            using IDisposable subscription = publications.Application.Subscribe<QuestChanged>(
                ApplicationMemberIds.QuestsChanged,
                changed.Add);

            publications.Receive(
                MessageContracts.Quests.Snapshot,
                new Quests([CreateQuestData(1, false), CreateQuestData(2, false)], true));
            publications.Receive(
                MessageContracts.Quests.SeasonalSnapshot,
                new QuestsSeasonal([CreateQuestData(3, true)]));
            publications.Receive(
                MessageContracts.Quests.Updated,
                new Quest(CreateQuestData(4, false)));
            publications.Receive(
                MessageContracts.Quests.Completed,
                new QuestCompleted(CreateQuestData(5, false), true));
            publications.Receive(
                MessageContracts.Quests.Cancelled,
                new QuestCancelled(true, CreateQuestData(6, false)));
            publications.Receive(
                MessageContracts.Quests.Daily,
                new QuestDaily(CreateQuestData(7, false), 8, 9));
            Assert.Equal(
                ["available:2", "seasonal:1", "current:4", "completed:5:True",
                    "cancelled:6:True", "daily:7"],
                legacy);
            Assert.Equal(
                [QuestChangeKind.Available, QuestChangeKind.Seasonal, QuestChangeKind.Current,
                    QuestChangeKind.Completed, QuestChangeKind.Cancelled, QuestChangeKind.Daily],
                changed.Select(value => value.Kind).ToArray());
            Assert.All(changed, value =>
            {
                Assert.Equal(ClientType.Flash, value.Client);
                Assert.True(value.SessionGeneration > 0);
                Assert.True(value.SnapshotRevision > 0);
            });
            Assert.Equal(4, changed[2].Quest!.Id);
            Assert.True(changed[3].ShowDialog);
            Assert.True(changed[4].IsExpired);
            Assert.Equal(7, changed[5].Daily!.Quest!.Id);

            QuestStateView retained = publications.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest());
            for (int index = 0; index < 5; index++)
            {
                publications.Receive(
                    MessageContracts.Quests.Updated,
                    new Quest(CreateQuestData(20 + index, false)));
            }
            Assert.Throws<InvalidOperationException>(() => publications.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest(retained.SnapshotRevision)));

            QuestStateView before_reset = publications.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest());
            publications.Disconnect();
            publications.Connect(new Session(
                "localhost",
                1,
                "smoke-b",
                "smoke-b",
                ClientType.Flash));
            Assert.Equal("reset", legacy[^2]);
            Assert.Equal("reset", legacy[^1]);
            Assert.Equal(
                [QuestChangeKind.Reset, QuestChangeKind.Reset],
                changed.TakeLast(2).Select(value => value.Kind).ToArray());
            Assert.Throws<InvalidOperationException>(() => publications.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest(before_reset.SnapshotRevision)));
            QuestStateView reset = publications.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest(changed[^1].SnapshotRevision));
            Assert.True(reset.Connected);
            Assert.Equal(ClientType.Flash, reset.Client);
            Assert.False(reset.Summary.AvailableLoaded);
            Assert.False(reset.Summary.SeasonalLoaded);
            Assert.False(reset.Summary.DailyLoaded);
            Assert.Equal(0, reset.Summary.AvailableCount);
            Assert.Equal(0, reset.Summary.SeasonalCount);
        }

        using (var generation = new SurfaceFixture(ClientType.Flash))
        using (var entered = new ManualResetEventSlim())
        using (var release = new ManualResetEventSlim())
        {
            object feature = QuestFeature(generation.Application);
            Type feature_type = feature.GetType();
            FieldInfo daily_queue = feature_type.GetField(
                "daily_queue",
                BindingFlags.Instance | BindingFlags.NonPublic)!;
            object old_queue = daily_queue.GetValue(feature)!;
            object old_signal = old_queue.GetType().GetProperty("Signal")!.GetValue(old_queue)!;
            int dispatches = 0;
            generation.BeforeQuestDispatch = key =>
            {
                if (key == MessageKeys.Quests.DailyRequest &&
                    Interlocked.Increment(ref dispatches) == 1)
                {
                    entered.Set();
                    release.Wait(test_synchronization_timeout);
                }
            };
            Task<QuestDailyRefreshResult> old = Task.Run(() => RefreshDailyQuest(
                generation,
                true,
                31,
                test_request_timeout_ms));
            try
            {
                Assert.True(entered.Wait(test_synchronization_timeout));
                generation.Disconnect();
                generation.Connect(new Session(
                    "localhost",
                    2,
                    "smoke-c",
                    "smoke-c",
                    ClientType.Flash));
                object new_queue = daily_queue.GetValue(feature)!;
                object new_signal = new_queue.GetType().GetProperty("Signal")!
                    .GetValue(new_queue)!;
                Assert.NotSame(old_queue, new_queue);
                Assert.NotSame(old_signal, new_signal);
                Assert.True((bool)old_queue.GetType().GetProperty("Retired")!
                    .GetValue(old_queue)!);
                Assert.False((bool)new_queue.GetType().GetProperty("Retired")!
                    .GetValue(new_queue)!);
                Task<QuestDailyRefreshResult> current = RefreshDailyQuest(
                    generation,
                    false,
                    32,
                    test_request_timeout_ms);
                await generation.WaitForQuestRequestCount(
                    MessageKeys.Quests.DailyRequest,
                    1).WaitAsync(test_synchronization_timeout);
                Assert.Same(new_queue, daily_queue.GetValue(feature));
                Assert.Equal(1, (int)new_queue.GetType().GetProperty("Operations")!
                    .PropertyType.GetProperty("Count")!.GetValue(
                        new_queue.GetType().GetProperty("Operations")!.GetValue(new_queue))!);
                MethodInfo stale_disconnect = Assert.Single(
                    feature_type.GetMethods(BindingFlags.Instance | BindingFlags.NonPublic),
                    method => method.Name == "DisconnectDailyUnsafe" &&
                        method.GetParameters().Length == 2);
                stale_disconnect.Invoke(
                    feature,
                    [old_queue, new InvalidOperationException("stale daily driver")]);
                Assert.Same(new_queue, daily_queue.GetValue(feature));
                Assert.Equal(1, (int)new_queue.GetType().GetProperty("Operations")!
                    .PropertyType.GetProperty("Count")!.GetValue(
                        new_queue.GetType().GetProperty("Operations")!.GetValue(new_queue))!);
                Assert.False(generation.LastQuestDailyRequest!.IsEasy);
                Assert.Equal(32, generation.LastQuestDailyRequest.Index);
                generation.Receive(
                    MessageContracts.Quests.Daily,
                    new QuestDaily(CreateQuestData(32, false), 1, 2));
                QuestDailyRefreshResult result = await current.WaitAsync(
                    test_synchronization_timeout);
                Assert.Equal(32, result.Daily.Quest!.Id);
                Assert.Equal(1,
                    generation.QuestRequestCount(MessageKeys.Quests.DailyRequest));
            }
            finally
            {
                release.Set();
            }
            await Assert.ThrowsAsync<RequestDisconnectedException>(() => old.WaitAsync(
                test_synchronization_timeout));
            Assert.Equal(1, generation.QuestRequestCount(MessageKeys.Quests.DailyRequest));
        }

        using (var disposed = new SurfaceFixture(ClientType.Flash))
        {
            int notifications = 0;
            IDisposable subscription = disposed.Application.Subscribe<QuestChanged>(
                ApplicationMemberIds.QuestsChanged,
                value =>
                {
                    if (value.Kind is QuestChangeKind.Available)
                    {
                        notifications++;
                        disposed.Application.Dispose();
                    }
                });
            Task<QuestAvailableRefreshResult> refresh = RefreshAvailableQuests(
                disposed,
                test_request_timeout_ms);
            await disposed.WaitForQuestRequestCount(
                MessageKeys.Quests.Request,
                1).WaitAsync(test_synchronization_timeout);
            Task receive = Task.Run(() => disposed.Receive(
                MessageContracts.Quests.Snapshot,
                new Quests([CreateQuestData(40, false)], false)));
            await receive.WaitAsync(test_synchronization_timeout);
            Assert.Equal(1, notifications);
            Exception? refresh_failure = await Record.ExceptionAsync(async () =>
            {
                QuestAvailableRefreshResult result = await refresh.WaitAsync(
                    test_synchronization_timeout);
                Assert.Equal(40, Assert.Single(result.FirstPage.Entries).Quest.Id);
            });
            Assert.True(refresh_failure is null or ObjectDisposedException);
            Assert.Throws<ObjectDisposedException>(() => disposed.Application.Invoke<
                QuestStateRequest,
                QuestStateView>(
                    ApplicationMemberIds.QuestsState,
                    new QuestStateRequest()));
            subscription.Dispose();
        }
    }

    [Fact]
    public void habbicon_abi_descriptors_and_client_availability_are_stable()
    {
        using var flash = new SurfaceFixture(ClientType.Flash);
        (string Id, ApplicationMemberKind Kind, Type? Request, Type Result, bool Unity)[] expected =
        [
            (ApplicationMemberIds.HabbiconsState, ApplicationMemberKind.Query,
                typeof(HabbiconStateRequest), typeof(HabbiconStateView), true),
            (ApplicationMemberIds.HabbiconCollectionsList, ApplicationMemberKind.Query,
                typeof(HabbiconCollectionPageRequest), typeof(HabbiconCollectionPage), true),
            (ApplicationMemberIds.HabbiconEntriesList, ApplicationMemberKind.Query,
                typeof(HabbiconEntryPageRequest), typeof(HabbiconEntryPage), true),
            (ApplicationMemberIds.HabbiconShopRefresh, ApplicationMemberKind.Operation,
                typeof(HabbiconShopRefreshRequest), typeof(HabbiconShopRefreshResult), true),
            (ApplicationMemberIds.HabbiconInfoRefresh, ApplicationMemberKind.Operation,
                typeof(HabbiconInfoRefreshRequest), typeof(HabbiconInfoRefreshResult), true),
            (ApplicationMemberIds.HabbiconBuy, ApplicationMemberKind.Operation,
                typeof(HabbiconBuyActionRequest), typeof(HabbiconDispatchResult), false),
            (ApplicationMemberIds.HabbiconCollectionBuy, ApplicationMemberKind.Operation,
                typeof(HabbiconCollectionBuyActionRequest), typeof(HabbiconDispatchResult), false),
            (ApplicationMemberIds.HabbiconClaim, ApplicationMemberKind.Operation,
                typeof(HabbiconClaimActionRequest), typeof(HabbiconDispatchResult), false),
            (ApplicationMemberIds.HabbiconFavorite, ApplicationMemberKind.Operation,
                typeof(HabbiconFavoriteActionRequest), typeof(HabbiconDispatchResult), false),
            (ApplicationMemberIds.HabbiconUnfavorite, ApplicationMemberKind.Operation,
                typeof(HabbiconUnfavoriteActionRequest), typeof(HabbiconDispatchResult), false),
            (ApplicationMemberIds.HabbiconsChanged, ApplicationMemberKind.Event,
                null, typeof(HabbiconChanged), true)
        ];
        Assert.Equal(
            expected.Select(value => value.Id).Order(StringComparer.Ordinal),
            flash.Application.Members
                .Where(member => member.Id.StartsWith("habbicons.", StringComparison.Ordinal))
                .Select(member => member.Id));
        using var unity = new SurfaceFixture(ClientType.Unity);
        Assert.All(expected, value =>
        {
            ApplicationDescriptor descriptor = flash.Application.Members.Single(
                member => member.Id == value.Id);
            Assert.Equal(value.Kind, descriptor.Kind);
            Assert.Equal(value.Request, descriptor.RequestType);
            Assert.Equal(value.Result, descriptor.ResultType);
            Assert.True(flash.Application.Describe(value.Id).Availability.Available);
            Assert.Equal(value.Unity, unity.Application.Describe(value.Id).Availability.Available);
        });

        Assert.Equal(typeof(HabbiconManager),
            typeof(ScriptGlobals).GetProperty(nameof(ScriptGlobals.Habbicons))!.PropertyType);
        foreach (string name in new[]
        {
            nameof(ScriptGlobals.GetHabbiconCollections),
            nameof(ScriptGlobals.GetHabbicons),
            nameof(ScriptGlobals.GetOwnedHabbicons),
            nameof(ScriptGlobals.GetClaimableHabbicons),
            nameof(ScriptGlobals.ClaimAllHabbicons)
        })
        {
            ParameterInfo parameter = Assert.Single(
                typeof(ScriptGlobals).GetMethod(name)!.GetParameters());
            Assert.Equal("timeoutMs", parameter.Name);
            Assert.Equal(10000, parameter.DefaultValue);
        }

        string source = File.ReadAllText(Path.Combine(
            FindRepositoryRoot(), "src", "QX.Scripting", "ScriptGlobals.Habbicons.cs"));
        Assert.Contains("ApplicationMemberIds.HabbiconsState", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.HabbiconCollectionsList", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.HabbiconEntriesList", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.HabbiconShopRefresh", source, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.HabbiconClaim", source, StringComparison.Ordinal);
        Assert.DoesNotContain("EnsureShopLoadedAsync", source, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(ClientType.Flash)]
    [InlineData(ClientType.Unity)]
    public async Task habbicon_pages_and_script_reads_are_lossless(ClientType client)
    {
        using var fixture = new SurfaceFixture(client);
        HabbiconCollection[] collections = Enumerable.Range(0, 503)
            .Select(index => new HabbiconCollection(
                2000 + index,
                $"Collection{index}",
                index % 3 == 0,
                7000 + index,
                index % 5 == 0 ? HabbiconState.Claimable : HabbiconState.Locked,
                index,
                index + 1,
                index + 2,
                [new Habbicon(
                    1000 + index,
                    $"Icon{index}",
                    2000 + index,
                    HabbiconState.Locked,
                    index + 3,
                    index + 4,
                    index + 5)]))
            .ToArray();
        fixture.Receive(
            MessageContracts.Habbicons.InventorySnapshot,
            new UserHabbicons(
            [
                new UserHabbiconState(1000, HabbiconState.Claimable),
                new UserHabbiconState(1001, HabbiconState.Favorite),
                new UserHabbiconState(1002, HabbiconState.Owned)
            ],
            [1002, 1001]));
        fixture.Receive(
            MessageContracts.Habbicons.ShopSnapshot,
            new HabbiconShopData(collections));

        HabbiconStateView state = fixture.Application.Invoke<
            HabbiconStateRequest,
            HabbiconStateView>(
                ApplicationMemberIds.HabbiconsState,
                new HabbiconStateRequest());
        Assert.True(state.Vault.ShopLoaded);
        Assert.True(state.Vault.UserLoaded);
        Assert.Equal(503, state.Vault.CollectionCount);
        Assert.Equal(503, state.Vault.IconCount);
        Assert.Equal(2, state.Vault.OwnedCount);
        Assert.Equal(1, state.Vault.ClaimableCount);

        HabbiconCollectionPage first = fixture.Application.Invoke<
            HabbiconCollectionPageRequest,
            HabbiconCollectionPage>(
                ApplicationMemberIds.HabbiconCollectionsList,
                new HabbiconCollectionPageRequest(0, 500, state.SnapshotRevision));
        HabbiconCollectionPage second = fixture.Application.Invoke<
            HabbiconCollectionPageRequest,
            HabbiconCollectionPage>(
                ApplicationMemberIds.HabbiconCollectionsList,
                new HabbiconCollectionPageRequest(500, 500, state.SnapshotRevision));
        Assert.Equal(500, first.Collections.Count);
        Assert.Equal(500, first.NextOffset);
        Assert.Equal(3, second.Collections.Count);
        Assert.Null(second.NextOffset);
        Assert.Throws<ArgumentException>(() => fixture.Application.Invoke<
            HabbiconEntryPageRequest,
            HabbiconEntryPage>(
                ApplicationMemberIds.HabbiconEntriesList,
                new HabbiconEntryPageRequest(1, 100)));

        using ScriptGlobals globals = fixture.CreateGlobals();
        IReadOnlyList<HabbiconCollection> script_collections =
            await globals.GetHabbiconCollections();
        IReadOnlyList<Habbicon> script_icons = await globals.GetHabbicons();
        Assert.Equal(503, script_collections.Count);
        Assert.Equal(503, script_icons.Count);
        Assert.Equal(collections.Select(value => value.CollectionId),
            script_collections.Select(value => value.CollectionId));
        Assert.Equal(Enumerable.Range(1000, 503),
            script_icons.Select(value => value.HabbiconId));
        Assert.Equal(HabbiconState.Claimable, script_icons[0].State);
        Assert.Equal(HabbiconState.Favorite, script_icons[1].State);
        Assert.Equal(HabbiconState.Owned, script_icons[2].State);
        Assert.Equal(0, fixture.HabbiconRequestCount(MessageKeys.Habbicons.ShopRequest));
    }

