    [Fact]
    public async Task leaderboard_refresh_scripts_and_snapshot_leases_are_correlated()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        Task<LeaderboardRefreshResult> refresh = fixture.Application
            .InvokeAsync<LeaderboardRefreshRequest, LeaderboardRefreshResult>(
                ApplicationMemberIds.LeaderboardsRefresh,
                new LeaderboardRefreshRequest(7, Limit: 500, TimeoutMilliseconds: test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForLeaderboardRequestCount(MessageKeys.Leaderboards.Total.Request, 1)
            .WaitAsync(test_synchronization_timeout);
        var expected = new Leaderboard(
            Enumerable.Range(0, 503)
                .Select(index => new LeaderboardEntry(
                    index + 1,
                    1000 - index,
                    index + 4,
                    $"User{index}",
                    $"hd-{index}",
                    index % 2 == 0 ? "M" : "F"))
                .ToArray(),
            509,
            7);
        fixture.Receive(
            MessageContracts.Leaderboards.TotalSnapshot,
            new TotalLeaderboard(expected));
        LeaderboardRefreshResult refreshed = await refresh.WaitAsync(test_synchronization_timeout);
        Assert.Equal(1, refreshed.MessagesDispatched);
        Assert.Equal(500, refreshed.FirstPage.Entries.Count);
        Assert.Equal(500, refreshed.FirstPage.NextOffset);
        Assert.True(refreshed.FirstPage.Board.HasMoreAbove);
        Assert.True(refreshed.FirstPage.Board.HasMoreBelow);

        LeaderboardEntryPage retained = await fixture.Application
            .InvokeAsync<LeaderboardEntryPageRequest, LeaderboardEntryPage>(
                ApplicationMemberIds.LeaderboardsEntriesList,
                new LeaderboardEntryPageRequest(
                    Limit: 500,
                    SnapshotRevision: refreshed.SnapshotRevision));
        Assert.Equal(500, retained.Entries.Count);
        Assert.Equal(500, retained.NextOffset);

        LeaderboardEntryPage continuation = await fixture.Application
            .InvokeAsync<LeaderboardEntryPageRequest, LeaderboardEntryPage>(
                ApplicationMemberIds.LeaderboardsEntriesList,
                new LeaderboardEntryPageRequest(
                    Offset: 500,
                    Limit: 500,
                    SnapshotRevision: refreshed.SnapshotRevision));
        Assert.Equal(3, continuation.Entries.Count);
        Assert.Null(continuation.NextOffset);

        ScriptGlobals globals = fixture.CreateGlobals();
        Task<Leaderboard?> next = globals.NextLeaderboardPage(timeoutMs: test_request_timeout_ms);
        await fixture.WaitForLeaderboardRequestCount(MessageKeys.Leaderboards.Total.Request, 2)
            .WaitAsync(test_synchronization_timeout);
        var next_board = new Leaderboard(
            [new LeaderboardEntry(3, 80, 6, "C", "hd-3", "M")],
            9,
            7);
        fixture.Receive(
            MessageContracts.Leaderboards.TotalSnapshot,
            new TotalLeaderboard(next_board));
        Leaderboard? next_result = await next.WaitAsync(test_synchronization_timeout);
        Assert.NotNull(next_result);
        Assert.Equal(6, Assert.Single(next_result.Entries).Rank);

        Task<Leaderboard> complete = globals.GetLeaderboard(7, timeoutMs: test_request_timeout_ms);
        await fixture.WaitForLeaderboardRequestCount(MessageKeys.Leaderboards.Total.Request, 3)
            .WaitAsync(test_synchronization_timeout);
        fixture.Receive(
            MessageContracts.Leaderboards.TotalSnapshot,
            new TotalLeaderboard(expected));
        Leaderboard complete_result = await complete.WaitAsync(test_synchronization_timeout);
        Assert.Equal(503, complete_result.Entries.Count);
        Assert.Equal(expected.Entries.ToArray(), complete_result.Entries.ToArray());

        fixture.Game.Leaderboards.Request(7, LeaderboardScope.Friends);
        await fixture.WaitForLeaderboardRequestCount(MessageKeys.Leaderboards.Friends.Request, 1)
            .WaitAsync(test_synchronization_timeout);
        fixture.Receive(
            MessageContracts.Leaderboards.FriendsSnapshot,
            new FriendsLeaderboard(expected));
        Leaderboard stored = Assert.IsType<Leaderboard>(
            fixture.Game.Leaderboards.Board(LeaderboardScope.Friends));
        Assert.Equal(expected.TotalListSize, stored.TotalListSize);
        Assert.Equal(expected.GameTypeId, stored.GameTypeId);
        Assert.Equal(expected.Entries.ToArray(), stored.Entries.ToArray());
    }

    [Fact]
    public async Task leaderboard_foreign_requests_disconnect_and_reset_are_terminal()
    {
