    [Fact]
    public async Task forum_abi_descriptors_schema_and_application_routes_are_stable()
    {
        MethodInfo[] forum_methods = typeof(IMcpHost).GetMethods()
            .Where(method => method.Name == nameof(IMcpHost.GetForumsAsync))
            .OrderBy(method => method.GetParameters().Length)
            .ToArray();
        MethodInfo[] thread_methods = typeof(IMcpHost).GetMethods()
            .Where(method => method.Name == nameof(IMcpHost.GetForumThreadsAsync))
            .OrderBy(method => method.GetParameters().Length)
            .ToArray();
        Assert.Equal([7, 8], forum_methods.Select(method => method.GetParameters().Length));
        Assert.Equal([7, 8], thread_methods.Select(method => method.GetParameters().Length));
        Assert.Equal(typeof(long?), forum_methods[1].GetParameters()[5].ParameterType);
        Assert.Equal("snapshotRevision", forum_methods[1].GetParameters()[5].Name);
        Assert.Equal(typeof(long?), thread_methods[1].GetParameters()[5].ParameterType);
        Assert.Equal("snapshotRevision", thread_methods[1].GetParameters()[5].Name);

        var legacy = new LegacyAchievementBadgeMcpHost();
        IMcpHost legacy_contract = legacy;
        Assert.Equal("legacy-forums", await legacy_contract.GetForumsAsync(
            false, false, "my", 20, 0, null, 10000, CancellationToken.None));
        Assert.Equal("legacy-threads", await legacy_contract.GetForumThreadsAsync(
            false, false, 7, 20, 0, null, 10000, CancellationToken.None));
        Assert.Equal(1, legacy.ForumCalls);
        Assert.Equal(1, legacy.ThreadCalls);
        await Assert.ThrowsAsync<NotSupportedException>(() => legacy_contract.GetForumsAsync(
            false, false, "my", 20, 1, null, 10000, CancellationToken.None));
        await Assert.ThrowsAsync<NotSupportedException>(() => legacy_contract.GetForumThreadsAsync(
            false, false, 7, 20, 0, 9, 10000, CancellationToken.None));

        using var fixture = new SurfaceFixture(ClientType.Flash);
        (string Id, ApplicationMemberKind Kind, Type? Request, Type Result, bool Unity)[] expected =
        [
            (ApplicationMemberIds.ForumsState, ApplicationMemberKind.Query,
                typeof(ForumStateRequest), typeof(ForumStateView), true),
            (ApplicationMemberIds.ForumDetailsRequest, ApplicationMemberKind.Operation,
                typeof(ForumDetailsRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumsListRequest, ApplicationMemberKind.Operation,
                typeof(ForumListRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumThreadsRequest, ApplicationMemberKind.Operation,
                typeof(ForumThreadsRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumMessagesRequest, ApplicationMemberKind.Operation,
                typeof(ForumMessagesRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumThreadRequest, ApplicationMemberKind.Operation,
                typeof(ForumThreadRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumsUnreadRequest, ApplicationMemberKind.Operation,
                typeof(ForumUnreadRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumsListRefresh, ApplicationMemberKind.Operation,
                typeof(ForumListRefreshRequest), typeof(ForumListRefreshResult), false),
            (ApplicationMemberIds.ForumThreadsRefresh, ApplicationMemberKind.Operation,
                typeof(ForumThreadsRefreshRequest), typeof(ForumThreadsRefreshResult), false),
            (ApplicationMemberIds.ForumMessagesRefresh, ApplicationMemberKind.Operation,
                typeof(ForumMessagesRefreshRequest), typeof(ForumMessagesRefreshResult), false),
            (ApplicationMemberIds.ForumDetailsRefresh, ApplicationMemberKind.Operation,
                typeof(ForumDetailsRefreshRequest), typeof(ForumDetailsRefreshResult), false),
            (ApplicationMemberIds.ForumThreadRefresh, ApplicationMemberKind.Operation,
                typeof(ForumThreadRefreshRequest), typeof(ForumThreadRefreshResult), false),
            (ApplicationMemberIds.ForumsUnreadRefresh, ApplicationMemberKind.Operation,
                typeof(ForumUnreadRefreshRequest), typeof(ForumUnreadRefreshResult), false),
            (ApplicationMemberIds.ForumsPost, ApplicationMemberKind.Operation,
                typeof(ForumPostActionRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumThreadModerate, ApplicationMemberKind.Operation,
                typeof(ForumThreadModerationRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumMessageModerate, ApplicationMemberKind.Operation,
                typeof(ForumMessageModerationRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumSettingsUpdate, ApplicationMemberKind.Operation,
                typeof(ForumSettingsUpdateRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumReadMarkersUpdate, ApplicationMemberKind.Operation,
                typeof(ForumReadMarkersUpdateRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumThreadUpdate, ApplicationMemberKind.Operation,
                typeof(ForumThreadUpdateRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumThreadReport, ApplicationMemberKind.Operation,
                typeof(ForumThreadReportRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumMessageReport, ApplicationMemberKind.Operation,
                typeof(ForumMessageReportRequest), typeof(ForumDispatchResult), true),
            (ApplicationMemberIds.ForumsChanged, ApplicationMemberKind.Event,
                null, typeof(ForumChanged), true)
        ];
        Assert.Equal(
            expected.Select(value => value.Id).Order(StringComparer.Ordinal),
            fixture.Application.Members
                .Where(member => member.Id.StartsWith("forums.", StringComparison.Ordinal))
                .Select(member => member.Id));
        Assert.All(expected, value =>
        {
            ApplicationDescriptor descriptor = fixture.Application.Members.Single(
                member => member.Id == value.Id);
            Assert.Equal(value.Kind, descriptor.Kind);
            Assert.Equal(value.Request, descriptor.RequestType);
            Assert.Equal(value.Result, descriptor.ResultType);
            Assert.True(fixture.Application.Describe(value.Id).Availability.Clients.Single(
                client => client.Client == ClientType.Flash).Supported);
            Assert.Equal(value.Unity, fixture.Application.Describe(value.Id).Availability.Clients.Single(
                client => client.Client == ClientType.Unity).Supported);
        });
        Assert.Equal(
            ["snapshot_revision"],
            fixture.Application.Members.Single(
                member => member.Id == ApplicationMemberIds.ForumsState)
                .Parameters.Select(parameter => parameter.Name).ToArray());

        IMcpHost proxy_contract = DispatchProxy.Create<IMcpHost, EmptyMcpHostProxy>();
        var proxy = Assert.IsAssignableFrom<EmptyMcpHostProxy>(proxy_contract);
        var server = new McpServer(
            proxy_contract,
            9395,
            new McpConfig { Token = new string('f', 32), AllowEditor = false });
        FieldInfo tools_field = typeof(McpServer).GetField(
            "_tools",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        IReadOnlyList<McpTool> tools =
            (IReadOnlyList<McpTool>)tools_field.GetValue(server)!;
        foreach (string name in new[] { "get_forums", "get_forum_threads" })
        {
            McpTool tool = tools.Single(candidate => candidate.Name == name);
            Assert.Contains("snapshot_revision", tool.Description, StringComparison.Ordinal);
            using JsonDocument schema = JsonDocument.Parse(JsonSerializer.Serialize(tool.InputSchema));
            Assert.Equal(1, schema.RootElement.GetProperty("properties")
                .GetProperty("snapshot_revision").GetProperty("minimum").GetInt32());
            using JsonDocument values = JsonDocument.Parse(
                name == "get_forums"
                    ? """{"offset":2,"snapshot_revision":91}"""
                    : """{"group_id":7,"offset":2,"snapshot_revision":91}""");
            _ = await tool.Handler(values.RootElement, CancellationToken.None);
            Assert.Contains(91L, proxy.LastArguments);
        }

        string root = FindRepositoryRoot();
        string script = File.ReadAllText(Path.Combine(
            root, "src", "QX.Scripting", "ScriptGlobals.Forums.cs"));
        string hosting = File.ReadAllText(Path.Combine(
            root, "src", "QX.Hosting", "Mcp", "McpHost.cs"));
        Assert.Contains("ApplicationMemberIds.ForumsListRequest", script, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.ForumsPost", script, StringComparison.Ordinal);
        Assert.DoesNotContain("Forums.Request", script, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.ForumsState", hosting, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.ForumsListRefresh", hosting, StringComparison.Ordinal);
        Assert.Contains("ApplicationMemberIds.ForumThreadsRefresh", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("game.Forums", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEventAsync<ForumsList>", hosting, StringComparison.Ordinal);
        Assert.DoesNotContain("AwaitEventAsync<ForumThreads>", hosting, StringComparison.Ordinal);
    }

    [Fact]
    public async Task forum_scripts_refreshes_actions_and_snapshot_leases_are_exact()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        using ScriptGlobals globals = fixture.CreateGlobals();
        globals.RequestForumStats(10);
        globals.RequestForums(ForumListCode.MyForums, 0, 20);
        globals.RequestForumThreads(10, 0, 20);
        globals.RequestForumMessages(10, 20, 0, 20);
        globals.RequestForumThread(10, 20);
        globals.RequestUnreadForumsCount();
        globals.PostForumMessage(10, 20, "subject", "message");
        globals.ModerateForumThread(10, 20, 1);
        globals.ModerateForumMessage(10, 20, 30, 10);
        globals.UpdateForumSettings(10, 0, 1, 2, 3);
        globals.UpdateForumReadMarkers(new ForumReadMarker(10, 30, true));
        globals.UpdateForumThread(10, 20, true, false);
        globals.ReportForumThread(10, 20, 4, "report");
        globals.ReportForumMessage(10, 20, 30, 4, "report");
        MessageKey[] requests =
        [
            MessageKeys.Forums.StatsRequest,
            MessageKeys.Forums.ListRequest,
            MessageKeys.Forums.ThreadsRequest,
            MessageKeys.Forums.MessagesRequest,
            MessageKeys.Forums.ThreadRequest,
            MessageKeys.Forums.UnreadCountRequest,
            MessageKeys.Forums.Post,
            MessageKeys.Forums.ThreadModerate,
            MessageKeys.Forums.MessageModerate,
            MessageKeys.Forums.SettingsUpdate,
            MessageKeys.Forums.ReadMarkersUpdate,
            MessageKeys.Forums.ThreadUpdate,
            MessageKeys.Forums.ThreadReport,
            MessageKeys.Forums.MessageReport
        ];
        Assert.All(requests, key => Assert.Equal(1, fixture.ForumRequestCount(key)));

        Task<ForumListRefreshResult> refresh = fixture.Application.InvokeAsync<
            ForumListRefreshRequest,
            ForumListRefreshResult>(
                ApplicationMemberIds.ForumsListRefresh,
                new ForumListRefreshRequest(ForumListCode.MyForums, 0, 20, test_request_timeout_ms))
            .AsTask();
        await fixture.WaitForForumRequestCount(MessageKeys.Forums.ListRequest, 2)
            .WaitAsync(test_synchronization_timeout);
        fixture.Receive(
            MessageContracts.Forums.List,
            new ForumsList(ForumListCode.Active, 1, 0, [ForumSummaryData(99)]));
        Assert.False(refresh.IsCompleted);
        ForumsList expected_page = new(
            ForumListCode.MyForums,
            2,
            0,
            [ForumSummaryData(10), ForumSummaryData(20)]);
        fixture.Receive(MessageContracts.Forums.List, expected_page);
        ForumsList refreshed = (await refresh).Page;
        Assert.Equal(expected_page.ListCode, refreshed.ListCode);
        Assert.Equal(expected_page.TotalAmount, refreshed.TotalAmount);
        Assert.Equal(expected_page.StartIndex, refreshed.StartIndex);
        Assert.Equal(expected_page.Forums, refreshed.Forums);

        ForumStateView first = fixture.Application.Invoke<ForumStateRequest, ForumStateView>(
            ApplicationMemberIds.ForumsState,
            new ForumStateRequest());
        Assert.Equal(3, first.Snapshot.KnownForums.Count);
        fixture.Receive(
            MessageContracts.Forums.List,
            new ForumsList(ForumListCode.Popular, 1, 0, [ForumSummaryData(30)]));
        ForumStateView retained = fixture.Application.Invoke<ForumStateRequest, ForumStateView>(
            ApplicationMemberIds.ForumsState,
            new ForumStateRequest(first.SnapshotRevision));
        ForumStateView current = fixture.Application.Invoke<ForumStateRequest, ForumStateView>(
            ApplicationMemberIds.ForumsState,
            new ForumStateRequest());
        Assert.Equal(3, retained.Snapshot.KnownForums.Count);
        Assert.Equal(4, current.Snapshot.KnownForums.Count);
        Assert.NotEqual(first.SnapshotRevision, current.SnapshotRevision);

        using var unity = new SurfaceFixture(ClientType.Unity);
        int before = unity.ForumRequestCount(MessageKeys.Forums.ThreadReport);
        Assert.Throws<NotSupportedException>(() => unity.Application.Invoke<
            ForumThreadReportRequest,
            ForumDispatchResult>(
                ApplicationMemberIds.ForumThreadReport,
                new ForumThreadReportRequest(10, 20, 4, "report", "context")));
        Assert.Equal(before, unity.ForumRequestCount(MessageKeys.Forums.ThreadReport));

        fixture.Disconnect();
        Assert.Throws<InvalidOperationException>(() => fixture.Application.Invoke<
            ForumStateRequest,
            ForumStateView>(
                ApplicationMemberIds.ForumsState,
                new ForumStateRequest(first.SnapshotRevision)));

        using var publications = new SurfaceFixture(ClientType.Flash);
        bool legacy_reached = false;
        ForumChanged? changed = null;
        publications.Game.Forums.ForumPageReceived += _ =>
            throw new InvalidOperationException("observer");
        publications.Game.Forums.ForumPageReceived += _ => legacy_reached = true;
        using IDisposable subscription = publications.Application.Subscribe<ForumChanged>(
            ApplicationMemberIds.ForumsChanged,
            value => changed = value);
        Assert.False(publications.Receive(
            MessageContracts.Forums.List,
            new ForumsList(ForumListCode.MyForums, 1, 0, [ForumSummaryData(40)])));
        Assert.True(legacy_reached);
        Assert.NotNull(changed);
        Assert.Equal(40, Assert.Single(changed.Snapshot.KnownForums).Key);
    }

    [Fact]
    public async Task forum_mcp_preserves_legacy_json_and_tokenized_pages()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        fixture.Receive(
            MessageContracts.Forums.List,
            new ForumsList(
                ForumListCode.MyForums,
                3,
                0,
                [ForumSummaryData(30), ForumSummaryData(10), ForumSummaryData(20)]));
        fixture.Receive(
            MessageContracts.Forums.Threads,
            new ForumThreads(
                10,
                0,
                [ForumThreadData(30), ForumThreadData(10), ForumThreadData(20)]));
        using var extension = new Qx.Interception.GEarth.GEarthExtension(
            new Qx.Interception.GEarth.GEarthOptions());
        Type host_type = typeof(ApplicationMcpTools).Assembly.GetType("Qx.Hosting.McpHost")!;
        var host = (IMcpHost)Activator.CreateInstance(
            host_type,
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
            null,
            [extension, fixture.Game, fixture.Queries, fixture.Application, null,
                Path.GetTempPath(), null],
            null)!;

        string legacy = await host.GetForumsAsync(
            false, false, "my", 2, 0, 10000, CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(legacy))
        {
            JsonElement metadata = document.RootElement.GetProperty("metadata");
            Assert.False(metadata.TryGetProperty("snapshotRevision", out _));
            Assert.Equal(2, metadata.GetProperty("nextOffset").GetInt32());
            Assert.Equal(
                ["unreadForumsCount", "total", "returned", "offset", "maxItems",
                    "truncated", "cachedForumDetails", "cachedThreads", "cachedMessages",
                    "forums"],
                document.RootElement.GetProperty("data").EnumerateObject()
                    .Select(property => property.Name).ToArray());
        }
        string legacy_offset = await host.GetForumsAsync(
            false, false, "my", 2, 2, 10000, CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(legacy_offset))
        {
            Assert.False(document.RootElement.GetProperty("metadata")
                .TryGetProperty("snapshotRevision", out _));
            Assert.Equal("30", document.RootElement.GetProperty("data")
                .GetProperty("forums")[0].GetProperty("groupId").GetString());
        }

        string first = await host.GetForumsAsync(
            false, false, "my", 2, 0, null, 10000, CancellationToken.None);
        long revision;
        using (JsonDocument document = JsonDocument.Parse(first))
        {
            revision = document.RootElement.GetProperty("metadata")
                .GetProperty("snapshotRevision").GetInt64();
            Assert.Equal(2, document.RootElement.GetProperty("metadata")
                .GetProperty("nextOffset").GetInt32());
        }
        fixture.Receive(
            MessageContracts.Forums.List,
            new ForumsList(ForumListCode.Popular, 1, 0, [ForumSummaryData(5)]));
        string continuation = await host.GetForumsAsync(
            true, false, "my", 2, 2, revision, 10000, CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(continuation))
        {
            Assert.Equal(revision, document.RootElement.GetProperty("metadata")
                .GetProperty("snapshotRevision").GetInt64());
            Assert.Equal("30", document.RootElement.GetProperty("data")
                .GetProperty("forums")[0].GetProperty("groupId").GetString());
        }

        string threads = await host.GetForumThreadsAsync(
            false, false, 10, 2, 0, null, 10000, CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(threads))
        {
            Assert.True(document.RootElement.GetProperty("metadata")
                .GetProperty("snapshotRevision").GetInt64() > 0);
            Assert.Equal(["10", "20"], document.RootElement.GetProperty("data")
                .GetProperty("threads").EnumerateArray()
                .Select(value => value.GetProperty("threadId").GetString()!).ToArray());
        }
        await Assert.ThrowsAsync<ArgumentException>(() => host.GetForumsAsync(
            false, false, "my", 2, 1, null, 10000, CancellationToken.None));
    }

    [Fact]
    public void script_event_abi_remains_action_only()
    {
        MethodInfo[] methods = typeof(ScriptGlobals).GetMethods(
                BindingFlags.Instance | BindingFlags.Public)
            .Where(method => method.Name.StartsWith("On", StringComparison.Ordinal))
            .ToArray();
        MethodInfo[] action_methods = methods.Where(method => method.GetParameters().Any(
                parameter => parameter.ParameterType == typeof(Action) ||
                    parameter.ParameterType.IsGenericType &&
                    parameter.ParameterType.GetGenericTypeDefinition().FullName?.StartsWith(
                        "System.Action`",
                        StringComparison.Ordinal) == true))
            .ToArray();
        MethodInfo[] task_delegate_methods = methods.Where(method => method.GetParameters().Any(
                parameter => parameter.ParameterType.IsGenericType &&
                    parameter.ParameterType.GetGenericTypeDefinition().FullName?.StartsWith(
                    "System.Func`",
                    StringComparison.Ordinal) == true &&
                    parameter.ParameterType.GenericTypeArguments.LastOrDefault() == typeof(Task)))
            .ToArray();

        Assert.Equal(198, action_methods.Length);
        Assert.Empty(task_delegate_methods);
        Assert.Single(
            typeof(ScriptGlobals).GetMethods(),
            method => method.Name == nameof(ScriptGlobals.OnCraftingResult));
        Assert.Single(
            typeof(ScriptGlobals).GetMethods(),
            method => method.Name == nameof(ScriptGlobals.OnPresentOpened));
        ConstructorInfo constructor = Assert.Single(typeof(ScriptGlobals).GetConstructors());
        Assert.Equal(
            [
                typeof(IInterceptor),
                typeof(GameState),
                typeof(IApplicationRuntime),
                typeof(Action<string>),
                typeof(CancellationToken),
                typeof(Action<Exception>)
            ],
            constructor.GetParameters().Select(parameter => parameter.ParameterType).ToArray());
    }

    [Fact]
    public async Task async_void_events_report_post_await_failures_and_drain()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        var error_reported = new TaskCompletionSource<Exception>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        using var globals = new ScriptGlobals(
            fixture.Interceptor,
            fixture.Game,
            fixture.Application,
            _ => { },
            CancellationToken.None,
            error => error_reported.TrySetResult(error));
        var release = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var expected = new InvalidOperationException("post-await-event-failure");

        _ = globals.OnBadgeInventoryLoaded(async () =>
        {
            await release.Task;
            throw expected;
        });
        fixture.Receive(
            MessageContracts.Badges.Snapshot,
            new BadgeInventory(1, 0, [new OwnedBadge(1, "ASYNC", 0, 0, false)]));

        Task<bool> drain = globals.WaitForBackgroundTasksAsync(test_request_timeout_ms);
        Assert.False(drain.IsCompleted);
        release.TrySetResult();

        Assert.Same(expected, await error_reported.Task.WaitAsync(test_synchronization_timeout));
        Assert.True(await drain.WaitAsync(test_synchronization_timeout));
    }

    [Fact]
    public async Task rewritten_event_work_uses_the_run_token_and_rejects_stale_callbacks()
    {
        using var fixture = new SurfaceFixture(ClientType.Flash);
        var output = new List<string>();
        var errors = new List<Exception>();
        using var globals = new ScriptGlobals(
            fixture.Interceptor,
            fixture.Game,
            fixture.Application,
            message => output.Add(message),
            CancellationToken.None,
            error => errors.Add(error));
        using var run = new CancellationTokenSource();
        ScriptProgram program = ScriptEngine.Prepare(
            """
            OnEnteredRoom(async () =>
            {
                Log("started");
                await Task.Delay(Timeout.Infinite);
                Log("after");
            });
            """);

        await program.RunAsync(globals, run.Token);
        fixture.EnterRoom(901);
        Assert.Equal(["started"], output);

        run.Cancel();
        Assert.True(await globals.WaitForBackgroundTasksAsync(test_request_timeout_ms));
        Assert.Throws<OperationCanceledException>(() => globals.OnEnteredRoom(() => { }));
        fixture.EnterRoom(902);

        Assert.Equal(["started"], output);
        Assert.Empty(errors);
    }

    [Fact]
    public async Task event_finish_completes_the_host_run_without_masking_stop()
    {
        using (var fixture = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            var ready = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var execution = new ScriptExecutionService(
                fixture.Interceptor,
                fixture.Game,
                fixture.Application);
            Task<ScriptExecutionResult> running = execution.RunAsync(new ScriptExecutionRequest
            {
                Code =
                    """
                    OnEnteredRoom(async () =>
                    {
                        await Task.Yield();
                        Finish();
                    });
                    Log("ready");
                    await Wait();
                    """,
                SourceIdentity = "event-finish",
                FileName = "event-finish.csx",
                BackgroundDrainTimeout = test_synchronization_timeout,
                OutputWritten = message =>
                {
                    if (message == "ready")
                        ready.TrySetResult();
                }
            }, cancellation.Token);

            try
            {
                await ready.Task.WaitAsync(test_script_startup_timeout);
                fixture.EnterRoom(903);
                ScriptExecutionResult result = await running.WaitAsync(test_synchronization_timeout);

                Assert.Equal(ScriptRunState.Finished, result.State);
                Assert.False(result.Faulted);
                Assert.False(result.TimedOut);
                Assert.Empty(result.Errors);
            }
            finally
            {
                await cancellation.CancelAsync();
                _ = await running.WaitAsync(test_script_startup_timeout);
            }
        }

        using (var fixture = new SurfaceFixture(ClientType.Flash))
        using (var cancellation = new CancellationTokenSource())
        {
            var ready = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            var execution = new ScriptExecutionService(
                fixture.Interceptor,
                fixture.Game,
                fixture.Application);
            Task<ScriptExecutionResult> running = execution.RunAsync(new ScriptExecutionRequest
            {
                Code =
                    """
                    OnEnteredRoom(async () =>
                    {
                        Log("entered");
                        try
                        {
                            await Task.Delay(Timeout.Infinite, Ct);
                        }
                        catch (OperationCanceledException)
                        {
                            Finish();
                        }
                    });
                    Log("ready");
                    await Wait();
                    """,
                SourceIdentity = "event-stop-finish-race",
                FileName = "event-stop-finish-race.csx",
                BackgroundDrainTimeout = test_synchronization_timeout,
                OutputWritten = message =>
                {
                    if (message == "ready")
                        ready.TrySetResult();
                    else if (message == "entered")
                        entered.TrySetResult();
                }
            }, cancellation.Token);

            try
            {
                await ready.Task.WaitAsync(test_script_startup_timeout);
                fixture.EnterRoom(904);
                await entered.Task.WaitAsync(test_synchronization_timeout);
                cancellation.Cancel();
                ScriptExecutionResult result = await running.WaitAsync(test_synchronization_timeout);

                Assert.Equal(ScriptRunState.Stopped, result.State);
                Assert.False(result.Faulted);
                Assert.False(result.TimedOut);
                Assert.Empty(result.Errors);
            }
            finally
            {
                await cancellation.CancelAsync();
                _ = await running.WaitAsync(test_script_startup_timeout);
            }
        }
    }

