    private static ClubGiftInfo GiftClubInfo(
        int value,
        int offer_count,
        ClientType client = ClientType.Flash)
    {
        CatalogPageOffer[] offers = Enumerable.Range(0, offer_count)
            .Select(ordinal => GiftClubOffer(value, ordinal))
            .ToArray();
        ClubGiftEligibility[] eligibility = offers
            .Select((offer, ordinal) => new ClubGiftEligibility(
                offer.OfferId,
                client is ClientType.Flash ? ordinal % 2 == 0 : null,
                value + ordinal,
                ordinal % 2 != 0))
            .ToArray();
        return new ClubGiftInfo(value, value + 1, offers, eligibility);
    }

