        Assert.Equal(expected.Id, actual.GetProperty("id").GetInt32());
        Assert.Equal(expected.CampaignCode, actual.GetProperty("campaignCode").GetString());
        Assert.Equal(expected.ChainCode, actual.GetProperty("chainCode").GetString());
        Assert.Equal(expected.LocalizationCode,
            actual.GetProperty("localizationCode").GetString());
        Assert.Equal(expected.Type, actual.GetProperty("type").GetString());
        Assert.Equal(expected.IsAccepted, actual.GetProperty("isAccepted").GetBoolean());
        Assert.Equal(expected.IsCompleted, actual.GetProperty("isCompleted").GetBoolean());
        Assert.Equal(expected.IsEasy, actual.GetProperty("isEasy").GetBoolean());
        Assert.Equal(expected.IsSeasonal, actual.GetProperty("isSeasonal").GetBoolean());
        Assert.Equal(expected.CompletedSteps,
            actual.GetProperty("completedSteps").GetInt32());
        Assert.Equal(expected.TotalSteps, actual.GetProperty("totalSteps").GetInt32());
        Assert.Equal(expected.CompletedQuestsInCampaign,
            actual.GetProperty("completedQuestsInCampaign").GetInt32());
        Assert.Equal(expected.QuestCountInCampaign,
            actual.GetProperty("questCountInCampaign").GetInt32());
        Assert.Equal(expected.RewardCurrencyAmount,
            actual.GetProperty("rewardCurrencyAmount").GetInt32());
        Assert.Equal(expected.ActivityPointType,
            actual.GetProperty("activityPointType").GetInt32());
        Assert.Equal(expected.CatalogPageName,
            actual.GetProperty("catalogPageName").GetString());
        if (expected.SeasonalSecondsLeft is int seconds)
            Assert.Equal(seconds, actual.GetProperty("seasonalSecondsLeft").GetInt32());
        else
            Assert.False(actual.TryGetProperty("seasonalSecondsLeft", out _));
    }

