    private static async Task AssertConcreteAchievementBadgeMcpOverloads()
    {
        var application = new AchievementBadgeScriptRuntime(
            AchievementBadgeConsumerFailure.None);
        using var game = new GameState();
        var queries = new GameQueryService(game, application, static () => null);
        using var extension = new Qx.Interception.GEarth.GEarthExtension(
            new Qx.Interception.GEarth.GEarthOptions());
        Type host_type = typeof(ApplicationMcpTools).Assembly.GetType("Qx.Hosting.McpHost")!;
        var host = (IMcpHost)Activator.CreateInstance(
            host_type,
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
            null,
            [extension, game, queries, application, null, Path.GetTempPath(), null],
            null)!;

        string badge_direct = await host.GetBadgeInventoryAsync(
            false, 10000, CancellationToken.None);
        string badge_limited = await host.GetBadgeInventoryAsync(
            false, 2, 10000, CancellationToken.None);
        string badge_offset = await host.GetBadgeInventoryAsync(
            false, 2, 2, 10000, CancellationToken.None);
        AssertLegacyMcpPage(badge_direct, 500, 500, false);
        AssertLegacyMcpPage(badge_limited, 2, 2, false);
        AssertLegacyMcpPage(badge_offset, 2, 4, false);
        using (JsonDocument document = JsonDocument.Parse(badge_offset))
        {
            JsonElement[] items = document.RootElement.GetProperty("data")
                .GetProperty("badges").EnumerateArray().ToArray();
            Assert.Equal(2, items.Length);
            AssertMcpBadge(application.SortedBadges[2], items[0]);
            AssertMcpBadge(application.SortedBadges[3], items[1]);
        }
        string badge_token = await host.GetBadgeInventoryAsync(
            false, 2, 2, 77, 10000, CancellationToken.None);
        AssertLegacyMcpPage(badge_token, 2, 4, true);

        string achievement_direct = await host.GetAchievementsAsync(
            false, 10000, CancellationToken.None);
        string achievement_limited = await host.GetAchievementsAsync(
            false, 2, 10000, CancellationToken.None);
        string achievement_offset = await host.GetAchievementsAsync(
            false, 2, 2, 10000, CancellationToken.None);
        AssertLegacyMcpPage(achievement_direct, 500, 500, false);
        AssertLegacyMcpPage(achievement_limited, 2, 2, false);
        AssertLegacyMcpPage(achievement_offset, 2, 4, false);
        using (JsonDocument document = JsonDocument.Parse(achievement_offset))
        {
            JsonElement[] items = document.RootElement.GetProperty("data")
                .GetProperty("achievements").EnumerateArray().ToArray();
            Assert.Equal(2, items.Length);
            AssertMcpAchievement(application.SortedAchievements[2], items[0]);
            AssertMcpAchievement(application.SortedAchievements[3], items[1]);
        }
        string achievement_token = await host.GetAchievementsAsync(
            false, 2, 2, 77, 10000, CancellationToken.None);
        AssertLegacyMcpPage(achievement_token, 2, 4, true);
    }

    private static async Task AssertConcreteQuestMcpOverloads()
    {
        var application = new QuestMcpRuntime();
        using var game = new GameState();
        var queries = new GameQueryService(game, application, static () => null);
        using var extension = new Qx.Interception.GEarth.GEarthExtension(
            new Qx.Interception.GEarth.GEarthOptions());
        Type host_type = typeof(ApplicationMcpTools).Assembly.GetType("Qx.Hosting.McpHost")!;
        var host = (IMcpHost)Activator.CreateInstance(
            host_type,
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
            null,
            [extension, game, queries, application, null, Path.GetTempPath(), null],
            null)!;

        string legacy_first = await host.GetQuestsAsync(
            false,
            false,
            2,
            0,
            10000,
            CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(legacy_first))
        {
            JsonElement metadata = document.RootElement.GetProperty("metadata");
            Assert.False(metadata.TryGetProperty("snapshotRevision", out _));
            Assert.Equal(2, metadata.GetProperty("nextOffset").GetInt32());
        }

        string legacy = await host.GetQuestsAsync(
            false,
            false,
            2,
            2,
            10000,
            CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(legacy))
        {
            JsonElement metadata = document.RootElement.GetProperty("metadata");
            Assert.False(metadata.TryGetProperty("snapshotRevision", out _));
            Assert.False(metadata.TryGetProperty("nextOffset", out _));
            JsonElement[] quests = document.RootElement.GetProperty("data")
                .GetProperty("quests").EnumerateArray().ToArray();
            AssertMcpQuest(application.Seasonal[0], Assert.Single(quests));
        }

        string tokenized = await host.GetQuestsAsync(
            false,
            false,
            2,
            0,
            77,
            10000,
            CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(tokenized))
        {
            JsonElement metadata = document.RootElement.GetProperty("metadata");
            Assert.Equal(77, metadata.GetProperty("snapshotRevision").GetInt64());
            Assert.Equal(2, metadata.GetProperty("nextOffset").GetInt32());
        }

        var offline_application = new QuestMcpRuntime(false);
        using var offline_game = new GameState();
        var offline_queries = new GameQueryService(
            offline_game,
            offline_application,
            static () => null);
        using var offline_extension = new Qx.Interception.GEarth.GEarthExtension(
            new Qx.Interception.GEarth.GEarthOptions());
        var offline_host = (IMcpHost)Activator.CreateInstance(
            host_type,
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
            null,
            [offline_extension, offline_game, offline_queries, offline_application, null,
                Path.GetTempPath(), null],
            null)!;
        string offline = await offline_host.GetQuestsAsync(
            false,
            false,
            2,
            0,
            10000,
            CancellationToken.None);
        using (JsonDocument document = JsonDocument.Parse(offline))
        {
            JsonElement root = document.RootElement;
            Assert.Equal(JsonValueKind.Null, root.GetProperty("error").ValueKind);
            JsonElement metadata = root.GetProperty("metadata");
            Assert.False(metadata.GetProperty("loaded").GetBoolean());
            Assert.Equal(["quests"], metadata.GetProperty("pending")
                .EnumerateArray().Select(value => value.GetString()!).ToArray());
            Assert.False(metadata.TryGetProperty("snapshotRevision", out _));
            Assert.Equal(0, root.GetProperty("data").GetProperty("total").GetInt32());
        }
    }

    private static void AssertLegacyMcpPage(
        string json,
        int returned,
        int next_offset,
        bool tokenized)
    {
        using JsonDocument document = JsonDocument.Parse(json);
        JsonElement metadata = document.RootElement.GetProperty("metadata");
        Assert.Equal(returned,
            document.RootElement.GetProperty("data").GetProperty("returned").GetInt32());
        Assert.Equal(next_offset, metadata.GetProperty("nextOffset").GetInt32());
        Assert.Equal(tokenized, metadata.TryGetProperty("snapshotRevision", out _));
        if (tokenized)
            Assert.Equal(77, metadata.GetProperty("snapshotRevision").GetInt64());
    }

