    private static (object Feature, object Operation, bool Dispatch)
        AcquireAchievementOperation(
            ApplicationRuntime application,
            bool ensure_only,
            string route_name = "List")
    {
        object feature = AchievementFeature(application);
        Type type = feature.GetType();
        object scope = type.GetMethod(
            "CaptureAchievementScope",
            BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(feature, [null, CancellationToken.None])!;
        string method_name = ensure_only
            ? "AcquireAchievementEnsure"
            : "AcquireAchievementOperation";
        MethodInfo method = type.GetMethod(
            method_name,
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        object route = Enum.Parse(method.GetParameters()[0].ParameterType, route_name);
        object result = method.Invoke(feature, [route, scope])!;
        object operation = result.GetType().GetField("Item1")!.GetValue(result)!;
        bool dispatch = (bool)result.GetType().GetField("Item2")!.GetValue(result)!;
        return (feature, operation, dispatch);
    }

    private static (object Feature, object Operation, bool Dispatch)
        AcquireBadgeOperation(ApplicationRuntime application, bool ensure_only)
    {
        object feature = AchievementFeature(application);
        Type type = feature.GetType();
        object scope = type.GetMethod(
            "CaptureBadgeScope",
            BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(feature, [null, CancellationToken.None])!;
        string method_name = ensure_only ? "AcquireBadgeEnsure" : "AcquireBadgeOperation";
        object result = type.GetMethod(
            method_name,
            BindingFlags.Instance | BindingFlags.NonPublic)!
            .Invoke(feature, [scope])!;
        object operation = result.GetType().GetField("Item1")!.GetValue(result)!;
        bool dispatch = (bool)result.GetType().GetField("Item2")!.GetValue(result)!;
        return (feature, operation, dispatch);
    }

