    private static void PrependStateChanged(object manager, Action callback)
    {
        FieldInfo field = manager.GetType().GetField(
            "StateChanged",
            BindingFlags.Instance | BindingFlags.NonPublic)!;
        Delegate listener = EventCallback(field.FieldType, callback);
        var current = (Delegate?)field.GetValue(manager);
        field.SetValue(manager, Delegate.Combine(listener, current));
    }

    private static Delegate EventCallback(Type event_type, Action callback)
    {
        Type argument = Assert.Single(event_type.GetGenericArguments());
        return (Delegate)typeof(ApplicationSurfaceTests).GetMethod(
            nameof(EventCallbackCore),
            BindingFlags.Static | BindingFlags.NonPublic)!
            .MakeGenericMethod(argument)
            .Invoke(null, [callback])!;
    }

    private static Action<T> EventCallbackCore<T>(Action callback) => _ => callback();

