    private static void AssertAchievementBadgeMcpOverloads(string name)
    {
        MethodInfo[] methods = typeof(IMcpHost).GetMethods()
            .Where(method => method.Name == name)
            .OrderBy(method => method.GetParameters().Length)
            .ToArray();
        Assert.Equal(4, methods.Length);
        Assert.Equal(
            [typeof(bool), typeof(int), typeof(CancellationToken)],
            methods[0].GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [typeof(bool), typeof(int), typeof(int), typeof(CancellationToken)],
            methods[1].GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [typeof(bool), typeof(int), typeof(int), typeof(int), typeof(CancellationToken)],
            methods[2].GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.Equal(
            [typeof(bool), typeof(int), typeof(int), typeof(long?), typeof(int),
                typeof(CancellationToken)],
            methods[3].GetParameters().Select(parameter => parameter.ParameterType).ToArray());
        Assert.All(methods, method => Assert.Equal(typeof(Task<string>), method.ReturnType));
    }

