    private static IReadOnlyList<T> ConsumerSlice<T>(
        IReadOnlyList<T> source,
        int offset,
        int limit)
    {
        int count = offset >= source.Count ? 0 : Math.Min(limit, source.Count - offset);
        var page = new T[count];
        for (int index = 0; index < count; index++)
            page[index] = source[offset + index];
        return Array.AsReadOnly(page);
    }

    private static T RoundtripPoll<T>(
        MessageContract<T> contract,
        T expected,
        ClientType client,
        Direction direction)
        where T : IParserComposer<T>
    {
        using var packet = new Packet(new Header(direction, 97), client);
        contract.Compose(expected, packet.Writer());
        packet.Position = 0;
        T parsed = contract.Parse(packet.Reader());
        Assert.Equal(0, packet.Available);
        packet.Position = packet.Length;
        packet.Writer().WriteByte(0x7f);
        packet.Position = 0;
        Assert.Throws<InvalidDataException>(() => contract.Parse(packet.Reader()));
        return parsed;
    }

