    private static string FindRepositoryRoot()
    {
        for (DirectoryInfo? directory = new(AppContext.BaseDirectory);
            directory is not null;
            directory = directory.Parent)
        {
            if (File.Exists(Path.Combine(directory.FullName, "QX.slnx")))
                return directory.FullName;
        }
        throw new DirectoryNotFoundException("The repository root was not found.");
    }

    private static string MethodSource(string source, string signature)
    {
        int start = source.IndexOf(signature, StringComparison.Ordinal);
        if (start < 0)
            throw new InvalidDataException($"Method signature '{signature}' was not found.");
        int body_start = source.IndexOf('{', start);
        if (body_start < 0)
            throw new InvalidDataException($"Method body '{signature}' was not found.");
        int depth = 0;
        for (int index = body_start; index < source.Length; index++)
        {
            if (source[index] == '{')
                depth++;
            else if (source[index] == '}' && --depth == 0)
                return source[start..(index + 1)];
        }
        throw new InvalidDataException($"Method body '{signature}' was incomplete.");
    }

