        {
            Context = new ParserContext(
                MessageManager.CreateWithEmbeddedMap(),
                new MessageWireProfile(
                    MessageWiredContextLayout.None,
                    false,
                    UnityRoomSettingsLayout: layout))
        };
        PacketWriter writer = packet.Writer();
        writer.WriteLong(9_000_000_042);
        writer.WriteString("room");
        writer.WriteString("description");
        writer.WriteInt((int)RoomDoorMode.Password);
        writer.WriteInt(7);
        writer.WriteInt(1);
        writer.WriteBool(true);
        writer.WriteInt(3);
        writer.WriteBool(true);
        writer.WriteInt((int)RoomModerationPermission.RightsHolders);
        writer.WriteInt((int)RoomModerationPermission.Everyone);
        writer.WriteInt((int)RoomModerationPermission.GroupAdmins);
        writer.WriteLength((Length)1);
        writer.WriteLong(9_000_000_043);
        if (visitor_fields >= 1)
            writer.WriteBool(true);
        if (visitor_fields >= 2)
            writer.WriteInt(33);
        if (visitor_fields >= 3)
            writer.WriteInt(44);
        if (visitor_fields >= 4)
