    private static OutgoingMessageSchema CreateUnityRoomSettingsSaveSchema(
        bool modern,
        bool invalid_array = false)
    {
        OutgoingWireType[] common =
        [
            OutgoingWireType.Int64,
            OutgoingWireType.String,
            OutgoingWireType.String,
            OutgoingWireType.Int32,
            OutgoingWireType.String,
            OutgoingWireType.Int32,
            OutgoingWireType.Boolean,
            OutgoingWireType.Int32,
            OutgoingWireType.Int32,
            OutgoingWireType.Int32,
            OutgoingWireType.Int32
        ];
        List<OutgoingParameterSchema> parameters = common
            .Select((wire_type, position) => Scalar(position, wire_type))
            .ToList();
        if (modern)
        {
            parameters.Add(Scalar(11, OutgoingWireType.Int32));
            parameters.Add(Scalar(12, OutgoingWireType.Int32));
            parameters.Add(Scalar(13, OutgoingWireType.Int32));
        }
        int array_position = modern ? 14 : 11;
        parameters.Add(new OutgoingParameterSchema(
            array_position,
            "long[]",
            "nft_group_ids",
            null,
            OutgoingWireType.Int64,
            invalid_array ? OutgoingCollectionKind.List : OutgoingCollectionKind.Array));
        return new OutgoingMessageSchema("SaveRoomSettings", parameters);
    }

