        return (messages, new Header(Direction.Out, 91));
    }

    private static void AssertCompleteSchema(JsonElement schema, string path)
    {
        if (schema.TryGetProperty("anyOf", out JsonElement alternatives))
        {
            int index = 0;
            foreach (JsonElement alternative in alternatives.EnumerateArray())
                AssertCompleteSchema(alternative, $"{path}.anyOf[{index++}]");
            return;
        }

        if (!schema.TryGetProperty("type", out JsonElement type))
            return;
        if (type.GetString() == "array")
        {
            AssertCompleteSchema(schema.GetProperty("items"), path + "[]");
            return;
        }
        if (type.GetString() != "object")
            return;

        bool has_properties = schema.TryGetProperty("properties", out JsonElement properties);
        bool has_dictionary_values = schema.TryGetProperty(
            "additionalProperties",
            out JsonElement additional_properties) &&
            additional_properties.ValueKind is JsonValueKind.Object;
        Assert.True(
            has_properties || has_dictionary_values,
            $"Schema '{path}' contains an unspecified object.");
        if (has_properties)
        {
            foreach (JsonProperty property in properties.EnumerateObject())
                AssertCompleteSchema(property.Value, path + "." + property.Name);
        }
        if (has_dictionary_values)
            AssertCompleteSchema(additional_properties, path + ".*");
    }

    private sealed class ClubOffersScriptRuntime(
        params SubscriptionClubOffersPage[] pages) : IApplicationRuntime
    {
        private int page_index;

        public IReadOnlyList<ApplicationDescriptor> Members => [];
        public int PagesRead => page_index;

        public ApplicationMemberDescription Describe(string id) =>
            throw new NotSupportedException(id);

        public TResult Invoke<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            if (id != ApplicationMemberIds.SubscriptionsClubOffersList ||
                request is not SubscriptionClubOffersPageRequest)
            {
                throw new InvalidOperationException(id);
            }
            return Result<TResult>();
        }

        public ValueTask<TResult> InvokeAsync<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            if (id != ApplicationMemberIds.SubscriptionsClubOffersRefresh ||
                request is not SubscriptionClubOffersRefreshRequest)
            {
                throw new InvalidOperationException(id);
            }
            return ValueTask.FromResult(Result<TResult>());
        }

        public ValueTask<object?> InvokeAsync(
            string id,
            object? request,
            CancellationToken cancellation_token = default) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe<TEvent>(string id, Action<TEvent> receiver) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe(string id, Action<object?> receiver) =>
            throw new NotSupportedException(id);

        private TResult Result<TResult>()
        {
            if (page_index >= pages.Length)
                throw new InvalidOperationException("No club-offer page remains.");
            object page = pages[page_index++];
            return page is TResult result
                ? result
                : throw new InvalidOperationException("Unexpected club-offer result type.");
        }
    }

    private sealed class SubscriptionMcpRuntime
    {
        private int refresh_count;
        private int last_timeout_milliseconds;
        private string? last_product_name;

        public required SubscriptionStateView State { get; set; }
        public required Func<
            SubscriptionUserInfoRefreshRequest,
            CancellationToken,
            ValueTask<SubscriptionUserInfoRefreshResult>> Refresh
        { get; set; }
        public int RefreshCount => Volatile.Read(ref refresh_count);
        public int LastTimeoutMilliseconds => Volatile.Read(ref last_timeout_milliseconds);
        public string? LastProductName => Volatile.Read(ref last_product_name);

        public async Task<SubscriptionUserInfoRefreshResult> RefreshAsync(
            string product_name,
            int timeout_ms,
            CancellationToken cancellation_token)
        {
            Interlocked.Increment(ref refresh_count);
            Volatile.Write(ref last_product_name, product_name);
            Volatile.Write(ref last_timeout_milliseconds, timeout_ms);
            return await Refresh(
                new SubscriptionUserInfoRefreshRequest(
                    product_name,
                    timeout_ms),
                cancellation_token).ConfigureAwait(false);
        }
    }

