    {
        None,
        ContinuationStateDrift,
        ZeroProgress,
        OrdinalDrift,
        SummaryDrift,
        Offline,
        Unloaded,
        RefreshSessionDrift,
        ClaimMetadataDrift
    }

    private sealed class EarningConsumerRuntime : IApplicationRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long state_revision = 20;
        private const long status_revision = 21;
        private const long baseline_revision = 22;
        private readonly EarningConsumerFailure failure;
        private readonly IReadOnlyList<EarningEntry> entries;
        private readonly List<(string Id, object Request)> calls = [];

        public EarningConsumerRuntime(EarningConsumerFailure failure)
        {
            this.failure = failure;
            entries = Array.AsReadOnly(Enumerable.Range(0, 501)
                .Select(index => new EarningEntry(
                    index == 0
                        ? (EarningCategory)sbyte.MinValue
                        : (EarningCategory)(index % 12),
                    index % 5 == 0
                        ? (EarningRewardKind)sbyte.MaxValue
                        : index % 2 == 0
                            ? EarningRewardKind.Credits
                            : EarningRewardKind.Duckets,
                    index + 1,
                    index % 17 == 0 ? $"runtime-{index:D3}" : ""))
                .ToArray());
        }

        public IReadOnlyList<ApplicationDescriptor> Members => [];
        public IReadOnlyList<(string Id, object Request)> Calls
        {
            get
            {
                lock (calls)
                    return calls.ToArray();
            }
        }

        public ApplicationMemberDescription Describe(string id) =>
            throw new NotSupportedException(id);

        public TResult Invoke<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            return (TResult)Read(id, request!);
        }

        public ValueTask<TResult> InvokeAsync<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            return ValueTask.FromResult((TResult)Read(id, request!));
        }

        public ValueTask<object?> InvokeAsync(
            string id,
            object? request,
            CancellationToken cancellation_token = default) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe<TEvent>(string id, Action<TEvent> receiver) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe(string id, Action<object?> receiver) =>
            throw new NotSupportedException(id);

        private object Read(string id, object request)
        {
            lock (calls)
                calls.Add((id, request));
            return id switch
            {
                ApplicationMemberIds.EarningsState => State(),
                ApplicationMemberIds.EarningsEntriesList =>
                    Page((EarningEntryPageRequest)request),
                ApplicationMemberIds.EarningsRefresh =>
                    Refresh((EarningRefreshRequest)request),
                ApplicationMemberIds.EarningsClaim =>
                    Claim((EarningClaimActionRequest)request),
                _ => throw new NotSupportedException(id)
            };
        }

        private EarningStateView State()
        {
            bool loaded = failure is not (
                EarningConsumerFailure.Unloaded or
                EarningConsumerFailure.RefreshSessionDrift);
            bool connected = failure is not EarningConsumerFailure.Offline;
            return new EarningStateView(
                connected,
                connected ? ClientType.Flash : null,
                connected ? session_generation : 0,
                state_revision,
                status_revision,
                baseline_revision,
                23,
                24,
                snapshot_revision,
                loaded ? Summary() : new EarningVaultSummary(
                    false,
                    0,
                    0,
                    0,
                    0,
                    0,
                    false));
        }

        private EarningEntryPage Page(EarningEntryPageRequest request)
        {
            bool continuation = request.Offset > 0;
            IReadOnlyList<EarningEntry> source = continuation &&
                failure is EarningConsumerFailure.ZeroProgress
                    ? []
                    : ConsumerSlice(entries, request.Offset, request.Limit);
            EarningEntryView[] page = source
                .Select((entry, index) => new EarningEntryView(
                    request.Offset + index +
                        (failure is EarningConsumerFailure.OrdinalDrift ? 1 : 0),
                    unchecked((sbyte)(int)entry.Category),
                    unchecked((sbyte)(int)entry.Kind),
                    entry.Amount,
                    entry.ProductCode,
                    entry.IsProduct))
                .ToArray();
            int consumed = checked(request.Offset + page.Length);
            return new EarningEntryPage(
                true,
                ClientType.Flash,
                session_generation,
                state_revision + (continuation &&
                    failure is EarningConsumerFailure.ContinuationStateDrift ? 1 : 0),
                status_revision,
                baseline_revision,
                snapshot_revision,
                Summary(),
                entries.Count,
                request.Offset,
                consumed < entries.Count ? consumed : null,
                Array.AsReadOnly(page));
        }

        private EarningRefreshResult Refresh(EarningRefreshRequest request)
        {
            EarningEntryPage page = Page(new EarningEntryPageRequest(
                Limit: request.Limit,
                SnapshotRevision: snapshot_revision));
            long generation = failure is EarningConsumerFailure.RefreshSessionDrift
                ? session_generation + 1
                : session_generation;
            page = page with { SessionGeneration = generation };
            return new EarningRefreshResult(
                ClientType.Flash,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                generation,
                page.StateRevision,
                page.StatusRevision,
                page.BaselineRevision,
                snapshot_revision,
                1,
                page);
        }

        private EarningClaimActionResult Claim(EarningClaimActionRequest request) => new(
            ClientType.Flash,
            DateTimeOffset.UnixEpoch,
            DateTimeOffset.UnixEpoch,
            session_generation,
            state_revision,
            status_revision,
            baseline_revision,
            23,
            snapshot_revision,
            failure is EarningConsumerFailure.ClaimMetadataDrift
                ? request.Category + 1
                : request.Category,
            true,
            1,
            Summary());

        private EarningVaultSummary Summary()
        {
            var status = new EarningStatus(entries);
            return new EarningVaultSummary(
                true,
                entries.Count,
                status.Categories.Count,
                status.Credits() +
                    (failure is EarningConsumerFailure.SummaryDrift ? 1 : 0),
                status.Duckets(),
                status.Products(),
                status.HasClaimable());
        }
    }

    private enum QuestConsumerFailure
    {
        None,
        Unloaded,
        ContinuationStateDrift,
        ZeroProgress,
        RefreshSessionDrift,
        Cancellation,
        Timeout
    }

    private sealed class QuestScriptRuntime : IApplicationRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long state_revision = 20;
        private const long available_revision = 21;
        private const long seasonal_revision = 22;
        private readonly QuestConsumerFailure failure;
        private readonly IReadOnlyList<QuestData> quests;
        private readonly List<(string Id, object Request)> calls = [];

        public QuestScriptRuntime(QuestConsumerFailure failure)
        {
            this.failure = failure;
            quests = Array.AsReadOnly(Enumerable.Range(0, 501)
                .Select(index => CreateQuestData(501 - index, false))
                .ToArray());
        }

        public IReadOnlyList<ApplicationDescriptor> Members => [];
        public IReadOnlyList<QuestData> Quests => quests;
        public IReadOnlyList<(string Id, object Request)> Calls => calls.ToArray();

        public ApplicationMemberDescription Describe(string id) =>
            throw new NotSupportedException(id);

        public TResult Invoke<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            return (TResult)Read(id, request!);
        }

        public ValueTask<TResult> InvokeAsync<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            if (id == ApplicationMemberIds.QuestsAvailableRefresh)
            {
                if (failure is QuestConsumerFailure.Cancellation)
                {
                    return new ValueTask<TResult>(WaitForCancellation<TResult>(
                        cancellation_token));
                }
                if (failure is QuestConsumerFailure.Timeout)
                {
                    int timeout = ((QuestAvailableRefreshRequest)(object)request!)
                        .TimeoutMilliseconds;
                    return ValueTask.FromException<TResult>(new RequestTimeoutException(
                        "quests.request",
                        "quests.snapshot",
                        timeout));
                }
            }
            return ValueTask.FromResult((TResult)Read(id, request!));
        }

        public ValueTask<object?> InvokeAsync(
            string id,
            object? request,
            CancellationToken cancellation_token = default) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe<TEvent>(string id, Action<TEvent> receiver) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe(string id, Action<object?> receiver) =>
            throw new NotSupportedException(id);

        private object Read(string id, object request)
        {
            calls.Add((id, request));
            return id switch
            {
                ApplicationMemberIds.QuestsState => State(),
                ApplicationMemberIds.QuestsEntriesList =>
                    Page((QuestEntryPageRequest)request),
                ApplicationMemberIds.QuestsAvailableRefresh =>
                    Refresh((QuestAvailableRefreshRequest)request),
                _ => throw new NotSupportedException(id)
            };
        }

        private QuestStateView State()
        {
            bool loaded = failure is not (
                QuestConsumerFailure.Unloaded or
                QuestConsumerFailure.RefreshSessionDrift or
                QuestConsumerFailure.Cancellation or
                QuestConsumerFailure.Timeout);
            QuestSummary summary = loaded
                ? Summary()
                : new QuestSummary(false, false, false, false, 0, 0, false, false, false, false);
            return new QuestStateView(
                true,
                ClientType.Flash,
                session_generation,
                state_revision,
                available_revision,
                seasonal_revision,
                23,
                24,
                25,
                26,
                snapshot_revision,
                summary,
                null,
                null,
                null,
                null);
        }

        private QuestEntryPage Page(QuestEntryPageRequest request)
        {
            bool continuation = request.Offset > 0;
            IReadOnlyList<QuestData> source = continuation &&
                failure is QuestConsumerFailure.ZeroProgress
                    ? []
                    : ConsumerSlice(quests, request.Offset, request.Limit);
            QuestEntryView[] entries = source
                .Select((quest, index) => new QuestEntryView(
                    request.Offset + index,
                    QuestCollection.Available,
                    request.Offset + index,
                    QuestViewOf(quest)))
                .ToArray();
            int consumed = checked(request.Offset + entries.Length);
            return new QuestEntryPage(
                true,
                ClientType.Flash,
                session_generation,
                state_revision + (continuation &&
                    failure is QuestConsumerFailure.ContinuationStateDrift ? 1 : 0),
                available_revision,
                seasonal_revision,
                snapshot_revision,
                Summary(),
                QuestCollection.Available,
                quests.Count,
                request.Offset,
                consumed < quests.Count ? consumed : null,
                Array.AsReadOnly(entries));
        }

        private QuestAvailableRefreshResult Refresh(QuestAvailableRefreshRequest request)
        {
            QuestEntryPage page = Page(new QuestEntryPageRequest(
                QuestCollection.Available,
                0,
                request.Limit,
                snapshot_revision));
            long generation = failure is QuestConsumerFailure.RefreshSessionDrift
                ? session_generation + 1
                : session_generation;
            page = page with { SessionGeneration = generation };
            return new QuestAvailableRefreshResult(
                ClientType.Flash,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                generation,
                page.StateRevision,
                page.AvailableRevision,
                page.SnapshotRevision,
                1,
                page);
        }

        private QuestSummary Summary() => new(
            true,
            false,
            false,
            true,
            quests.Count,
            0,
            false,
            false,
            false,
            false);

        private static async Task<TResult> WaitForCancellation<TResult>(
            CancellationToken cancellation_token)
        {
            await Task.Delay(Timeout.InfiniteTimeSpan, cancellation_token).ConfigureAwait(false);
            throw new InvalidOperationException();
        }
    }

    private sealed class QuestMcpRuntime : IApplicationRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long state_revision = 20;
        private const long available_revision = 21;
        private const long seasonal_revision = 22;
        private readonly IReadOnlyList<QuestData> available;
        private readonly IReadOnlyList<QuestData> seasonal;
        private readonly bool connected;
        private readonly List<QuestStateRequest> state_requests = [];
        private readonly List<QuestEntryPageRequest> entry_requests = [];
        private readonly List<QuestAvailableRefreshRequest> available_requests = [];
        private readonly List<QuestSeasonalRefreshRequest> seasonal_requests = [];
        private int readiness_count;

        public QuestMcpRuntime(bool connected = true)
        {
            this.connected = connected;
            available = connected
                ? Array.AsReadOnly<QuestData>(
                [
                    CreateQuestData(41, false),
                    CreateQuestData(7, false)
                ])
                : Array.AsReadOnly(Array.Empty<QuestData>());
            seasonal = connected
                ? Array.AsReadOnly<QuestData>([CreateQuestData(23, true)])
                : Array.AsReadOnly(Array.Empty<QuestData>());
        }

        public IReadOnlyList<ApplicationDescriptor> Members => [];
        public IReadOnlyList<QuestData> Available => available;
        public IReadOnlyList<QuestData> Seasonal => seasonal;
        public IReadOnlyList<QuestStateRequest> StateRequests => state_requests.ToArray();
        public IReadOnlyList<QuestEntryPageRequest> EntryRequests => entry_requests.ToArray();
        public IReadOnlyList<QuestAvailableRefreshRequest> AvailableRequests =>
            available_requests.ToArray();
        public IReadOnlyList<QuestSeasonalRefreshRequest> SeasonalRequests =>
            seasonal_requests.ToArray();
        public int ReadinessCount => Volatile.Read(ref readiness_count);

        public ApplicationMemberDescription Describe(string id) =>
            throw new NotSupportedException(id);

        public TResult Invoke<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            object result = id switch
            {
                ApplicationMemberIds.QuestsState =>
                    ReadState((QuestStateRequest)(object)request!, cancellation_token),
                ApplicationMemberIds.QuestsEntriesList =>
                    ReadPage((QuestEntryPageRequest)(object)request!, cancellation_token),
                _ => throw new NotSupportedException(id)
            };
            return (TResult)result;
        }

        public ValueTask<TResult> InvokeAsync<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            object result = id switch
            {
                ApplicationMemberIds.QuestsState =>
                    ReadState((QuestStateRequest)(object)request!, cancellation_token),
                ApplicationMemberIds.QuestsEntriesList =>
                    ReadPage((QuestEntryPageRequest)(object)request!, cancellation_token),
                ApplicationMemberIds.QuestsAvailableRefresh =>
                    AvailableRefresh((QuestAvailableRefreshRequest)(object)request!),
                ApplicationMemberIds.QuestsSeasonalRefresh =>
                    SeasonalRefresh((QuestSeasonalRefreshRequest)(object)request!),
                _ => throw new NotSupportedException(id)
            };
            return ValueTask.FromResult((TResult)result);
        }

        public ValueTask<object?> InvokeAsync(
            string id,
            object? request,
            CancellationToken cancellation_token = default) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe<TEvent>(string id, Action<TEvent> receiver) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe(string id, Action<object?> receiver) =>
            throw new NotSupportedException(id);

        public Task AwaitReadiness(CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            Interlocked.Increment(ref readiness_count);
            return Task.CompletedTask;
        }

        public QuestStateView ReadState(
            QuestStateRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            state_requests.Add(request);
            if (request.SnapshotRevision is long revision && revision != snapshot_revision)
                throw new InvalidOperationException("The quest snapshot expired.");
            QuestSummary summary = Summary();
            if (!connected)
            {
                return new QuestStateView(
                    false,
                    null,
                    0,
                    state_revision,
                    available_revision,
                    seasonal_revision,
                    23,
                    24,
                    25,
                    26,
                    snapshot_revision,
                    summary,
                    null,
                    null,
                    null,
                    null);
            }
            QuestView current = QuestViewOf(CreateQuestData(91, false));
            QuestView daily = QuestViewOf(CreateQuestData(92, false));
            QuestView completed = QuestViewOf(CreateQuestData(93, false));
            QuestView cancelled = QuestViewOf(CreateQuestData(94, false));
            return new QuestStateView(
                true,
                ClientType.Flash,
                session_generation,
                state_revision,
                available_revision,
                seasonal_revision,
                23,
                24,
                25,
                26,
                snapshot_revision,
                summary,
                current,
                new QuestCompletionView(completed, true),
                new QuestCancellationView(true, cancelled),
                new QuestDailyView(daily, 3, 4, true));
        }

        public ValueTask<QuestAvailableRefreshResult> RefreshAvailable(
            QuestAvailableRefreshRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            return ValueTask.FromResult(AvailableRefresh(request));
        }

        public ValueTask<QuestSeasonalRefreshResult> RefreshSeasonal(
            QuestSeasonalRefreshRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            return ValueTask.FromResult(SeasonalRefresh(request));
        }

        public QuestEntryPage ReadPage(
            QuestEntryPageRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            entry_requests.Add(request);
            if (request.SnapshotRevision != snapshot_revision)
                throw new InvalidOperationException("The quest snapshot expired.");
            return Page(request.Collection, request.Offset, request.Limit, snapshot_revision);
        }

        private QuestAvailableRefreshResult AvailableRefresh(
            QuestAvailableRefreshRequest request)
        {
            available_requests.Add(request);
            QuestEntryPage page = Page(QuestCollection.Available, 0, request.Limit, 75);
            return new QuestAvailableRefreshResult(
                ClientType.Flash,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                state_revision,
                available_revision,
                75,
                1,
                page);
        }

        private QuestSeasonalRefreshResult SeasonalRefresh(
            QuestSeasonalRefreshRequest request)
        {
            seasonal_requests.Add(request);
            QuestEntryPage page = Page(QuestCollection.Seasonal, 0, request.Limit, 76);
            return new QuestSeasonalRefreshResult(
                ClientType.Flash,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                state_revision,
                seasonal_revision,
                76,
                1,
                page);
        }

        private QuestEntryPage Page(
            QuestCollection collection,
            int offset,
            int limit,
            long revision)
        {
            IReadOnlyList<QuestData> source = collection switch
            {
                QuestCollection.Available => available,
                QuestCollection.Seasonal => seasonal,
                QuestCollection.Combined => [.. available, .. seasonal],
                _ => throw new ArgumentOutOfRangeException(nameof(collection))
            };
            IReadOnlyList<QuestData> values = ConsumerSlice(source, offset, limit);
            QuestEntryView[] entries = values.Select((quest, index) =>
            {
                int ordinal = checked(offset + index);
                QuestCollection entry_collection = collection is QuestCollection.Combined
                    ? ordinal < available.Count
                        ? QuestCollection.Available
                        : QuestCollection.Seasonal
                    : collection;
                int collection_ordinal = collection is QuestCollection.Combined &&
                    entry_collection is QuestCollection.Seasonal
                        ? ordinal - available.Count
                        : ordinal;
                return new QuestEntryView(
                    ordinal,
                    entry_collection,
                    collection_ordinal,
                    QuestViewOf(quest));
            }).ToArray();
            int consumed = checked(offset + entries.Length);
            return new QuestEntryPage(
                connected,
                connected ? ClientType.Flash : null,
                connected ? session_generation : 0,
                state_revision,
                available_revision,
                seasonal_revision,
                revision,
                Summary(),
                collection,
                source.Count,
                offset,
                consumed < source.Count ? consumed : null,
                Array.AsReadOnly(entries));
        }

        private QuestSummary Summary() => new(
            connected,
            connected,
            connected,
            connected,
            available.Count,
            seasonal.Count,
            connected,
            connected,
            connected,
            connected);
    }

    private enum AchievementBadgeConsumerFailure
    {
        None,
        AchievementStateDrift,
        BadgeStateDrift,
        AchievementZeroProgress,
        BadgeZeroProgress,
        AchievementCancellation,
        BadgeTimeout
    }

    private sealed class AchievementBadgeScriptRuntime : IApplicationRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long state_revision = 20;
        private const long achievement_list_revision = 21;
        private const long achievement_baseline_revision = 22;
        private const long achievement_new_codes_revision = 23;
        private const long badge_inventory_revision = 24;
        private const long badge_baseline_revision = 25;
        private readonly AchievementBadgeConsumerFailure failure;
        private readonly IReadOnlyList<AchievementApplicationItem> achievements;
        private readonly IReadOnlyList<OwnedBadgeSnapshot> badges;

        public AchievementBadgeScriptRuntime(AchievementBadgeConsumerFailure failure)
        {
            this.failure = failure;
            achievements = Array.AsReadOnly(Enumerable.Range(0, 501)
                .Select(index =>
                {
                    Achievement achievement = ConsumerAchievement(
                        501 - index,
                        index % 2 == 0 ? "z" : "a",
                        index % 3 == 0 ? "three" : "one");
                    return new AchievementApplicationItem(
                        achievement.Id,
                        achievement.Level,
                        achievement.BadgeCode,
                        achievement.BaseProgress,
                        achievement.MaxProgress,
                        achievement.LevelRewardPoints,
                        achievement.LevelRewardPointType,
                        achievement.CurrentProgress,
                        achievement.IsComplete,
                        achievement.Category,
                        achievement.Subcategory,
                        achievement.MaxLevel,
                        achievement.DisplayMethod,
                        achievement.State,
                        index % 5 == 0);
                })
                .ToArray());
            badges = Array.AsReadOnly(Enumerable.Range(0, 501)
                .Select(index => new OwnedBadgeSnapshot(
                    index + 1,
                    $"script-badge-{500 - index:D4}",
                    index + 20,
                    index % 9,
                    true))
                .ToArray());
            SortedAchievements = Array.AsReadOnly(achievements
                .OrderBy(item => item.Category, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.Subcategory, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.Id)
                .ToArray());
            SortedBadges = Array.AsReadOnly(badges
                .OrderBy(item => item.Code, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => (long)item.Id)
                .ToArray());
        }

        public IReadOnlyList<ApplicationDescriptor> Members => [];
        public IReadOnlyList<AchievementApplicationItem> SortedAchievements { get; }
        public IReadOnlyList<OwnedBadgeSnapshot> SortedBadges { get; }

        public ApplicationMemberDescription Describe(string id) =>
            throw new NotSupportedException(id);

        public TResult Invoke<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            return (TResult)Read(id, request!);
        }

        public ValueTask<TResult> InvokeAsync<TRequest, TResult>(
            string id,
            TRequest request,
            CancellationToken cancellation_token = default)
        {
            cancellation_token.ThrowIfCancellationRequested();
            if (failure is AchievementBadgeConsumerFailure.AchievementCancellation &&
                id == ApplicationMemberIds.AchievementsRefresh)
            {
                return new ValueTask<TResult>(WaitForCancellation<TResult>(cancellation_token));
            }
            if (failure is AchievementBadgeConsumerFailure.BadgeTimeout &&
                id == ApplicationMemberIds.BadgesRefresh)
            {
                int timeout = ((BadgeRefreshRequest)(object)request!).TimeoutMilliseconds;
                return ValueTask.FromException<TResult>(new RequestTimeoutException(
                    "badges.request",
                    "badges.snapshot",
                    timeout));
            }
            return ValueTask.FromResult((TResult)Read(id, request!));
        }

        public ValueTask<object?> InvokeAsync(
            string id,
            object? request,
            CancellationToken cancellation_token = default) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe<TEvent>(string id, Action<TEvent> receiver) =>
            throw new NotSupportedException(id);

        public IDisposable Subscribe(string id, Action<object?> receiver) =>
            throw new NotSupportedException(id);

        private object Read(string id, object request) => id switch
        {
            ApplicationMemberIds.AchievementsList =>
                AchievementPage((AchievementPageRequest)request),
            ApplicationMemberIds.BadgesOwnedList =>
                BadgePage((OwnedBadgePageRequest)request),
            ApplicationMemberIds.AchievementsRefresh =>
                AchievementRefresh((AchievementRefreshRequest)request),
            ApplicationMemberIds.BadgesRefresh => BadgeRefresh((BadgeRefreshRequest)request),
            _ => throw new NotSupportedException(id)
        };

        private AchievementRefreshResult AchievementRefresh(AchievementRefreshRequest request)
        {
            AchievementPage first = AchievementPage(new AchievementPageRequest(
                Limit: request.Limit,
                SnapshotRevision: snapshot_revision));
            return new AchievementRefreshResult(
                ClientType.Flash,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                state_revision,
                achievement_list_revision,
                achievement_baseline_revision,
                snapshot_revision,
                1,
                first);
        }

        private BadgeRefreshResult BadgeRefresh(BadgeRefreshRequest request)
        {
            OwnedBadgePage first = BadgePage(new OwnedBadgePageRequest(
                Limit: request.Limit,
                SnapshotRevision: snapshot_revision));
            return new BadgeRefreshResult(
                ClientType.Flash,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                state_revision,
                badge_inventory_revision,
                badge_baseline_revision,
                snapshot_revision,
                1,
                first);
        }

        private AchievementPage AchievementPage(AchievementPageRequest request)
        {
            bool continuation = request.Offset > 0;
            IReadOnlyList<AchievementApplicationItem> page = continuation &&
                failure is AchievementBadgeConsumerFailure.AchievementZeroProgress
                    ? []
                    : ConsumerSlice(achievements, request.Offset, request.Limit);
            int consumed = checked(request.Offset + page.Count);
            return new AchievementPage(
                true,
                ClientType.Flash,
                session_generation,
                state_revision + (continuation &&
                    failure is AchievementBadgeConsumerFailure.AchievementStateDrift ? 1 : 0),
                achievement_list_revision,
                achievement_baseline_revision,
                achievement_new_codes_revision,
                snapshot_revision,
                true,
                "default",
                achievements.Count,
                achievements.Count(item => item.IsComplete),
                request.Offset,
                consumed < achievements.Count ? consumed : null,
                page);
        }

        private OwnedBadgePage BadgePage(OwnedBadgePageRequest request)
        {
            bool continuation = request.Offset > 0;
            IReadOnlyList<OwnedBadgeSnapshot> page = continuation &&
                failure is AchievementBadgeConsumerFailure.BadgeZeroProgress
                    ? []
                    : ConsumerSlice(badges, request.Offset, request.Limit);
            int consumed = checked(request.Offset + page.Count);
            var inventory = new BadgeInventorySummary(
                true,
                false,
                false,
                false,
                4,
                1,
                1,
                badges.Count,
                0,
                0,
                null,
                null);
            return new OwnedBadgePage(
                true,
                ClientType.Flash,
                session_generation,
                state_revision + (continuation &&
                    failure is AchievementBadgeConsumerFailure.BadgeStateDrift ? 1 : 0),
                badge_inventory_revision,
                badge_baseline_revision,
                snapshot_revision,
                inventory,
                badges.Count,
                request.Offset,
                consumed < badges.Count ? consumed : null,
                page);
        }

        private static async Task<TResult> WaitForCancellation<TResult>(
            CancellationToken cancellation_token)
        {
            await Task.Delay(Timeout.InfiniteTimeSpan, cancellation_token).ConfigureAwait(false);
            throw new InvalidOperationException();
        }
    }

    private sealed class AchievementBadgeMcpRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long state_revision = 20;
        private const long achievement_list_revision = 21;
        private const long achievement_baseline_revision = 22;
        private const long achievement_new_codes_revision = 23;
        private const long badge_inventory_revision = 24;
        private const long badge_baseline_revision = 25;
        private readonly IReadOnlyList<AchievementApplicationItem> achievements;
        private readonly IReadOnlyList<OwnedBadgeSnapshot> badges;
        private bool achievement_loaded;
        private bool badge_loaded;
        private int achievement_readiness_count;
        private int achievement_refresh_count;
        private int badge_readiness_count;
        private int badge_refresh_count;

        public AchievementBadgeMcpRuntime(
            int achievement_count = 3,
            int badge_count = 3,
            bool loaded = true)
        {
            achievements = Array.AsReadOnly(Enumerable.Range(0, achievement_count)
                .Select(index =>
                {
                    Achievement achievement = ConsumerAchievement(
                        achievement_count - index,
                        index % 3 == 0 ? "z" : index % 3 == 1 ? "a" : "m",
                        index % 2 == 0 ? "two" : "one");
                    return new AchievementApplicationItem(
                        achievement.Id,
                        achievement.Level,
                        achievement.BadgeCode,
                        achievement.BaseProgress,
                        achievement.MaxProgress,
                        achievement.LevelRewardPoints,
                        achievement.LevelRewardPointType,
                        achievement.CurrentProgress,
                        achievement.IsComplete,
                        achievement.Category,
                        achievement.Subcategory,
                        achievement.MaxLevel,
                        achievement.DisplayMethod,
                        achievement.State,
                        index % 5 == 0);
                })
                .ToArray());
            badges = Array.AsReadOnly(Enumerable.Range(0, badge_count)
                .Select(index => new OwnedBadgeSnapshot(
                    index + 1,
                    $"mcp-badge-{badge_count - index:D4}",
                    index + 10,
                    index % 7,
                    true))
                .ToArray());
            SortedAchievements = Array.AsReadOnly(achievements
                .OrderBy(item => item.Category, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.Subcategory, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.Id)
                .ToArray());
            SortedBadges = Array.AsReadOnly(badges
                .OrderBy(item => item.Code, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => (long)item.Id)
                .ToArray());
            achievement_loaded = loaded;
            badge_loaded = loaded;
        }

        public IReadOnlyList<AchievementApplicationItem> SortedAchievements { get; }
        public IReadOnlyList<OwnedBadgeSnapshot> SortedBadges { get; }
        public int AchievementReadinessCount => Volatile.Read(ref achievement_readiness_count);
        public int AchievementRefreshCount => Volatile.Read(ref achievement_refresh_count);
        public int BadgeReadinessCount => Volatile.Read(ref badge_readiness_count);
        public int BadgeRefreshCount => Volatile.Read(ref badge_refresh_count);
        public int BadgeRefreshStateRevisionOffset { get; init; }
        public int AchievementContinuationStateRevisionOffset { get; init; }
        public int BadgeContinuationStateRevisionOffset { get; init; }
        public bool EmptyAchievementContinuation { get; init; }
        public bool EmptyBadgeContinuation { get; init; }
        public Func<CancellationToken, Task>? AchievementReadiness { get; init; }
        public Func<CancellationToken, Task>? BadgeReadiness { get; init; }
        public List<AchievementPageRequest> AchievementRequests { get; } = [];
        public List<OwnedBadgePageRequest> BadgeRequests { get; } = [];

        public Task AwaitAchievementReadiness(CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            Interlocked.Increment(ref achievement_readiness_count);
            return AchievementReadiness?.Invoke(cancellation_token) ?? Task.CompletedTask;
        }

        public Task AwaitBadgeReadiness(CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            Interlocked.Increment(ref badge_readiness_count);
            return BadgeReadiness?.Invoke(cancellation_token) ?? Task.CompletedTask;
        }

        public ValueTask<AchievementRefreshResult> RefreshAchievements(
            AchievementRefreshRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            Interlocked.Increment(ref achievement_refresh_count);
            achievement_loaded = true;
            AchievementPage first = AchievementPage(new AchievementPageRequest(
                Limit: request.Limit,
                SnapshotRevision: snapshot_revision));
            return ValueTask.FromResult(new AchievementRefreshResult(
                ClientType.Unity,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                state_revision,
                achievement_list_revision,
                achievement_baseline_revision,
                snapshot_revision,
                1,
                first));
        }

        public ValueTask<BadgeRefreshResult> RefreshBadges(
            BadgeRefreshRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            Interlocked.Increment(ref badge_refresh_count);
            badge_loaded = true;
            OwnedBadgePage first = BadgePage(new OwnedBadgePageRequest(
                Limit: request.Limit,
                SnapshotRevision: snapshot_revision));
            return ValueTask.FromResult(new BadgeRefreshResult(
                ClientType.Unity,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                state_revision + BadgeRefreshStateRevisionOffset,
                badge_inventory_revision,
                badge_baseline_revision,
                snapshot_revision,
                1,
                first));
        }

        public AchievementPage ReadAchievements(
            AchievementPageRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            AchievementRequests.Add(request);
            RequireRevision(request.SnapshotRevision);
            return AchievementPage(request);
        }

        public OwnedBadgePage ReadBadges(
            OwnedBadgePageRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            BadgeRequests.Add(request);
            RequireRevision(request.SnapshotRevision);
            return BadgePage(request);
        }

        private AchievementPage AchievementPage(AchievementPageRequest request)
        {
            IReadOnlyList<AchievementApplicationItem> page =
                request.Offset > 0 && EmptyAchievementContinuation
                    ? []
                    : ConsumerSlice(achievements, request.Offset, request.Limit);
            int consumed = checked(request.Offset + page.Count);
            return new AchievementPage(
                true,
                ClientType.Unity,
                session_generation,
                state_revision + (request.Offset > 0
                    ? AchievementContinuationStateRevisionOffset
                    : 0),
                achievement_list_revision,
                achievement_baseline_revision,
                achievement_new_codes_revision,
                snapshot_revision,
                achievement_loaded,
                "default",
                achievements.Count,
                achievements.Count(item => item.IsComplete),
                request.Offset,
                consumed < achievements.Count ? consumed : null,
                page);
        }

        private OwnedBadgePage BadgePage(OwnedBadgePageRequest request)
        {
            IReadOnlyList<OwnedBadgeSnapshot> page = request.Offset > 0 && EmptyBadgeContinuation
                ? []
                : ConsumerSlice(badges, request.Offset, request.Limit);
            int consumed = checked(request.Offset + page.Count);
            var inventory = new BadgeInventorySummary(
                badge_loaded,
                false,
                !badge_loaded && badges.Count > 0,
                false,
                4,
                badge_loaded ? 1 : -1,
                badge_loaded ? 1 : 0,
                badges.Count,
                0,
                0,
                null,
                null);
            return new OwnedBadgePage(
                true,
                ClientType.Unity,
                session_generation,
                state_revision + (request.Offset > 0 ? BadgeContinuationStateRevisionOffset : 0),
                badge_inventory_revision,
                badge_baseline_revision,
                snapshot_revision,
                inventory,
                badges.Count,
                request.Offset,
                consumed < badges.Count ? consumed : null,
                page);
        }

        private static void RequireRevision(long? revision)
        {
            if (revision is not null && revision != snapshot_revision)
                throw new InvalidOperationException("The snapshot revision expired.");
        }
    }

    private sealed class CraftingMcpRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long state_revision = 20;
        private const long products_revision = 21;
        private const long recipe_revision = 22;
        private const long result_revision = 23;
        private const long availability_revision = 24;
        private readonly IReadOnlyList<CraftingProduct> products;
        private readonly IReadOnlyList<string> usable_classes;
        private readonly IReadOnlyList<CraftingIngredient> ingredients;
        private int readiness_count;
        private int refresh_count;

        public CraftingMcpRuntime(
            int product_count = 3,
            int usable_count = 3,
            int ingredient_count = 3)
        {
            products = Array.AsReadOnly(Enumerable.Range(0, product_count)
                .Select(index => new CraftingProduct(
                    $"recipe-{index}",
                    $"product-{index}",
                    $"class-{index}"))
                .ToArray());
            usable_classes = Array.AsReadOnly(Enumerable.Range(0, usable_count)
                .Select(index => $"usable-{index}")
                .ToArray());
            ingredients = Array.AsReadOnly(Enumerable.Range(0, ingredient_count)
                .Select(index => new CraftingIngredient(index + 1, $"ingredient-{index}"))
                .ToArray());
        }

        public int ReadinessCount => Volatile.Read(ref readiness_count);
        public int RefreshCount => Volatile.Read(ref refresh_count);
        public long StateSessionGeneration { get; set; } = session_generation;
        public Func<CancellationToken, Task>? Readiness { get; set; }
        public Func<
            CraftingProductsRefreshRequest,
            CancellationToken,
            ValueTask<CraftingProductsRefreshResult>>? RefreshOverride
        { get; set; }
        public CraftingProductsRefreshRequest? LastRefreshRequest { get; private set; }
        public List<CraftingStateRequest> StateRequests { get; } = [];
        public List<CraftingProductsPageRequest> ProductRequests { get; } = [];
        public List<CraftingRecipePageRequest> RecipeRequests { get; } = [];

        public Task AwaitReadiness(CancellationToken cancellation_token)
        {
            Interlocked.Increment(ref readiness_count);
            return Readiness?.Invoke(cancellation_token) ?? Task.CompletedTask;
        }

        public ValueTask<CraftingProductsRefreshResult> Refresh(
            CraftingProductsRefreshRequest request,
            CancellationToken cancellation_token)
        {
            Interlocked.Increment(ref refresh_count);
            LastRefreshRequest = request;
            if (RefreshOverride is not null)
                return RefreshOverride(request, cancellation_token);
            cancellation_token.ThrowIfCancellationRequested();
            CraftingProductsPage first_page = ProductsPage(
                new CraftingProductsPageRequest(
                    CraftingProductsCollection.Products,
                    0,
                    request.Limit,
                    snapshot_revision),
                session_generation);
            return ValueTask.FromResult(new CraftingProductsRefreshResult(
                ClientType.Unity,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                session_generation,
                500,
                5,
                6,
                state_revision,
                products_revision,
                snapshot_revision,
                request.CraftingFurnitureId,
                1,
                first_page));
        }

        public CraftingStateView ReadState(
            CraftingStateRequest request,
            CancellationToken cancellation_token)
        {
            ArgumentNullException.ThrowIfNull(request);
            cancellation_token.ThrowIfCancellationRequested();
            StateRequests.Add(request);
            RequireRevision(request.SnapshotRevision);
            return new CraftingStateView(
                true,
                ClientType.Unity,
                StateSessionGeneration,
                state_revision,
                products_revision,
                recipe_revision,
                result_revision,
                availability_revision,
                snapshot_revision,
                new CraftingProductsSummary(products.Count, usable_classes.Count),
                new CraftingRecipeSummary(ingredients.Count),
                new CraftingResult(
                    false,
                    new CraftingProduct("last-recipe", "last-product", "last-class")),
                new CraftingRecipesAvailable(4, false));
        }

        public CraftingProductsPage ReadProducts(
            CraftingProductsPageRequest request,
            CancellationToken cancellation_token)
        {
            ArgumentNullException.ThrowIfNull(request);
            cancellation_token.ThrowIfCancellationRequested();
            ProductRequests.Add(request);
            RequireRevision(request.SnapshotRevision);
            return ProductsPage(request, StateSessionGeneration);
        }

        public CraftingRecipePage ReadRecipe(
            CraftingRecipePageRequest request,
            CancellationToken cancellation_token)
        {
            ArgumentNullException.ThrowIfNull(request);
            cancellation_token.ThrowIfCancellationRequested();
            RecipeRequests.Add(request);
            RequireRevision(request.SnapshotRevision);
            IReadOnlyList<CraftingIngredient> page = Slice(
                ingredients,
                request.Offset,
                request.Limit);
            int consumed = checked(request.Offset + page.Count);
            return new CraftingRecipePage(
                true,
                ClientType.Unity,
                StateSessionGeneration,
                state_revision,
                recipe_revision,
                snapshot_revision,
                true,
                ingredients.Count,
                request.Offset,
                consumed < ingredients.Count ? consumed : null,
                page);
        }

        private CraftingProductsPage ProductsPage(
            CraftingProductsPageRequest request,
            long current_session_generation)
        {
            IReadOnlyList<CraftingProduct> product_page =
                Array.AsReadOnly(Array.Empty<CraftingProduct>());
            IReadOnlyList<string> usable_page = Array.AsReadOnly(Array.Empty<string>());
            int total;
            int returned;
            if (request.Collection is CraftingProductsCollection.Products)
            {
                product_page = Slice(products, request.Offset, request.Limit);
                total = products.Count;
                returned = product_page.Count;
            }
            else if (request.Collection is
                CraftingProductsCollection.UsableInventoryFurnitureClasses)
            {
                usable_page = Slice(usable_classes, request.Offset, request.Limit);
                total = usable_classes.Count;
                returned = usable_page.Count;
            }
            else
            {
                throw new ArgumentOutOfRangeException(nameof(request.Collection));
            }
            int consumed = checked(request.Offset + returned);
            return new CraftingProductsPage(
                true,
                ClientType.Unity,
                current_session_generation,
                state_revision,
                products_revision,
                snapshot_revision,
                true,
                products.Count,
                usable_classes.Count,
                request.Collection,
                total,
                request.Offset,
                consumed < total ? consumed : null,
                product_page,
                usable_page);
        }

        private static void RequireRevision(long? requested_revision)
        {
            if (requested_revision is long revision && revision != snapshot_revision)
                throw new InvalidOperationException("The crafting snapshot lease expired.");
        }

        private static IReadOnlyList<T> Slice<T>(
            IReadOnlyList<T> source,
            int offset,
            int limit)
        {
            int count = offset >= source.Count ? 0 : Math.Min(limit, source.Count - offset);
            var page = new T[count];
            for (int index = 0; index < count; index++)
                page[index] = source[offset + index];
            return Array.AsReadOnly(page);
        }
    }

    private sealed class GiftMcpRuntime
    {
        private const long snapshot_revision = 77;
        private const long session_generation = 7;
        private const long wrapping_revision = 11;
        private const long club_revision = 12;
        private readonly GiftWrappingConfiguration wrapping = new(
            true,
            5,
            [1, 2],
            [3, 4],
            [5],
            [6]);
        private readonly IReadOnlyList<GiftClubOfferView> offers;
        private readonly IReadOnlyList<GiftClubProductView> products;
        private readonly IReadOnlyList<GiftClubUnityProductReferenceView> references;
        private readonly IReadOnlyList<GiftClubUnityProductView> unity_products;
        private int readiness_count;
        private int refresh_count;

        public GiftMcpRuntime()
        {
            offers =
            [
                GiftOfferView(0, 200, 200, 200),
                GiftOfferView(1, 200, 200, 200),
                GiftOfferView(2, 1, 0, 0)
            ];
            products = Array.AsReadOnly(offers
                .SelectMany(offer => Enumerable.Range(0, offer.ProductCount)
                    .Select(ordinal => new GiftClubProductView(
                        offer.OfferOrdinal,
                        ordinal,
                        new CatalogProduct(
                            CatalogProduct.TypeStuff,
                            offer.OfferId * 1000 + ordinal,
                            $"product-{offer.OfferOrdinal}-{ordinal}",
                            1,
                            false,
                            0,
                            0,
                            1))))
                .ToArray());
            references = Array.AsReadOnly(offers
                .SelectMany(offer => Enumerable.Range(0, offer.UnityProductReferenceCount)
                    .Select(ordinal => new GiftClubUnityProductReferenceView(
                        offer.OfferOrdinal,
                        ordinal,
                        new CatalogPageProductReference(
                            1,
                            $"reference-{offer.OfferOrdinal}-{ordinal}"))))
                .ToArray());
            unity_products = Array.AsReadOnly(offers
                .SelectMany(offer => Enumerable.Range(0, offer.UnityProductCount)
                    .Select(ordinal => new GiftClubUnityProductView(
                        offer.OfferOrdinal,
                        ordinal,
                        new CatalogPageProduct(1, offer.OfferId * 1000 + ordinal, "", 1,
                            false, 0, 0))))
                .ToArray());
        }

        public int ReadinessCount => Volatile.Read(ref readiness_count);
        public int RefreshCount => Volatile.Read(ref refresh_count);
        public long StateSessionGeneration { get; set; } = session_generation;
        public Func<CancellationToken, Task>? Readiness { get; set; }
        public Func<
            GiftRefreshRequest,
            CancellationToken,
            ValueTask<GiftRefreshResult>>? RefreshOverride
        { get; set; }
        public List<GiftClubInfoPageRequest> ClubRequests { get; } = [];

        public Task AwaitReadiness(CancellationToken cancellation_token)
        {
            Interlocked.Increment(ref readiness_count);
            return Readiness?.Invoke(cancellation_token) ?? Task.CompletedTask;
        }

        public ValueTask<GiftRefreshResult> Refresh(
            GiftRefreshRequest request,
            CancellationToken cancellation_token)
        {
            Interlocked.Increment(ref refresh_count);
            if (RefreshOverride is not null)
                return RefreshOverride(request, cancellation_token);
            cancellation_token.ThrowIfCancellationRequested();
            GiftClubInfoPage first_page = ClubPage(
                new GiftClubInfoPageRequest(
                    GiftClubInfoCollection.Offers,
                    0,
                    request.Limit,
                    snapshot_revision));
            return ValueTask.FromResult(new GiftRefreshResult(
                ClientType.Unity,
                session_generation,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                DateTimeOffset.UnixEpoch,
                snapshot_revision,
                wrapping_revision,
                club_revision,
                new GiftWrappingSummaryView(
                    wrapping.IsWrappingEnabled,
                    wrapping.WrappingPrice,
                    wrapping.StuffTypes.Count,
                    wrapping.BoxTypes.Count,
                    wrapping.RibbonTypes.Count,
                    wrapping.DefaultStuffTypes.Count),
                ClubSummary(),
                first_page));
        }

        public GiftStateView ReadState(
            GiftStateRequest request,
            CancellationToken cancellation_token)
        {
            ArgumentNullException.ThrowIfNull(request);
            cancellation_token.ThrowIfCancellationRequested();
            return new GiftStateView(
                true,
                ClientType.Unity,
                StateSessionGeneration,
                20,
                wrapping_revision,
                club_revision,
                13,
                14,
                15,
                16,
                17,
                18,
                19,
                new GiftWrappingSummaryView(true, 5, 2, 2, 1, 1),
                ClubSummary(),
                new GiftClubSelectedSummaryView("selected", 1, 1),
                new PresentOpened("s", 1, "opened", 2, "s", true, ""),
                new ClubGiftNotification(2),
                new GiftNewUserOfferSummaryView(3, 3, 3),
                false,
                new Dictionary<int, bool> { [1] = true });
        }

        public GiftClubInfoPage ReadClubInfo(
            GiftClubInfoPageRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            ClubRequests.Add(request);
            if (request.SnapshotRevision is long revision && revision != snapshot_revision)
                throw new InvalidOperationException("The gift snapshot lease expired.");
            if (request.Offset != 0 && request.SnapshotRevision is null)
                throw new ArgumentException("Continuation requires a snapshot revision.");
            return ClubPage(request with { SnapshotRevision = snapshot_revision });
        }

        public GiftWrappingPage ReadWrapping(
            GiftWrappingPageRequest request,
            CancellationToken cancellation_token)
        {
            cancellation_token.ThrowIfCancellationRequested();
            if (request.SnapshotRevision != snapshot_revision)
                throw new InvalidOperationException("The gift snapshot lease expired.");
            IReadOnlyList<int> source = request.Collection switch
            {
                GiftWrappingCollection.StuffTypes => wrapping.StuffTypes,
                GiftWrappingCollection.BoxTypes => wrapping.BoxTypes,
                GiftWrappingCollection.RibbonTypes => wrapping.RibbonTypes,
                GiftWrappingCollection.DefaultStuffTypes => wrapping.DefaultStuffTypes,
                _ => throw new ArgumentOutOfRangeException(nameof(request.Collection))
            };
            IReadOnlyList<int> page = Slice(source, request.Offset, request.Limit);
            int consumed = checked(request.Offset + page.Count);
            return new GiftWrappingPage(
                true,
                ClientType.Unity,
                session_generation,
                wrapping_revision,
                snapshot_revision,
                true,
                wrapping.IsWrappingEnabled,
                wrapping.WrappingPrice,
                request.Collection,
                source.Count,
                request.Offset,
                consumed < source.Count ? consumed : null,
                page);
        }

        private GiftClubInfoPage ClubPage(GiftClubInfoPageRequest request)
        {
            IReadOnlyList<GiftClubOfferView> offer_page = [];
            IReadOnlyList<GiftClubProductView> product_page = [];
            IReadOnlyList<GiftClubUnityProductReferenceView> reference_page = [];
            IReadOnlyList<GiftClubUnityProductView> unity_product_page = [];
            int total;
            int returned;
            switch (request.Collection)
            {
                case GiftClubInfoCollection.Offers:
                    offer_page = Slice(offers, request.Offset, request.Limit);
                    total = offers.Count;
                    returned = offer_page.Count;
                    break;
                case GiftClubInfoCollection.Eligibility:
                    total = 0;
                    returned = 0;
                    break;
                case GiftClubInfoCollection.Products:
                    product_page = Slice(products, request.Offset, request.Limit);
                    total = products.Count;
                    returned = product_page.Count;
                    break;
                case GiftClubInfoCollection.UnityProductReferences:
                    reference_page = Slice(references, request.Offset, request.Limit);
                    total = references.Count;
                    returned = reference_page.Count;
                    break;
                case GiftClubInfoCollection.UnityProducts:
                    unity_product_page = Slice(unity_products, request.Offset, request.Limit);
                    total = unity_products.Count;
                    returned = unity_product_page.Count;
                    break;
                default:
                    throw new ArgumentOutOfRangeException(nameof(request.Collection));
            }
            int consumed = checked(request.Offset + returned);
            return new GiftClubInfoPage(
                true,
                ClientType.Unity,
                session_generation,
                club_revision,
                snapshot_revision,
                true,
                2,
                3,
                offers.Count,
                0,
                products.Count,
                references.Count,
                unity_products.Count,
                request.Collection,
                total,
                request.Offset,
                consumed < total ? consumed : null,
                offer_page,
                [],
                product_page,
                reference_page,
                unity_product_page);
        }

        private GiftClubInfoSummaryView ClubSummary() => new(
            2,
            3,
            offers.Count,
            0,
            products.Count,
            references.Count,
            unity_products.Count);

        private static GiftClubOfferView GiftOfferView(
            int ordinal,
            int product_count,
            int reference_count,
            int unity_product_count) => new(
            ordinal,
            100 + ordinal,
            $"mcp-gift-{ordinal}",
            false,
            ordinal + 1,
            ordinal + 2,
            ordinal + 3,
            ordinal + 4,
            true,
            ordinal % 2,
            true,
            false,
            $"mcp-gift-{ordinal}.png",
            product_count,
            reference_count,
            unity_product_count);

        private static IReadOnlyList<T> Slice<T>(
            IReadOnlyList<T> source,
            int offset,
            int limit)
        {
            int count = offset >= source.Count ? 0 : Math.Min(limit, source.Count - offset);
            var page = new T[count];
            for (int index = 0; index < count; index++)
                page[index] = source[offset + index];
            return Array.AsReadOnly(page);
        }
    }

    private class EmptyMcpHostProxy : DispatchProxy
    {
        public MethodInfo? LastMethod { get; private set; }
        public object?[] LastArguments { get; private set; } = [];

        protected override object? Invoke(MethodInfo? target_method, object?[]? arguments)
        {
            LastMethod = target_method;
            LastArguments = arguments ?? [];
            Type return_type = target_method?.ReturnType ?? typeof(void);
            if (return_type == typeof(string))
                return "";
            if (return_type == typeof(Task<string>))
                return Task.FromResult("");
            if (return_type == typeof(IReadOnlyList<string>))
                return Array.Empty<string>();
            if (return_type.IsValueType)
                return Activator.CreateInstance(return_type);
            return null;
        }
    }

    private static (GameData Data, GameDataTransportProxy Transport) CreateGameData()
    {
        (object transport, GameDataTransportProxy controller) = CreateGameDataTransport();
        var data = (GameData)Activator.CreateInstance(
            typeof(GameData),
            BindingFlags.Instance | BindingFlags.NonPublic,
            null,
            [transport],
            null)!;
        return (data, controller);
    }

    private static (object Transport, GameDataTransportProxy Controller)
        CreateGameDataTransport()
    {
        Type contract = typeof(GameData).Assembly.GetType("Qx.Game.IGameDataTransport")!;
        object transport = DispatchProxy.Create(contract, typeof(GameDataTransportProxy));
        return (transport, (GameDataTransportProxy)transport);
    }

    private class GameDataTransportProxy : DispatchProxy
    {
        private readonly object sync = new();
        private readonly Dictionary<string, GameDataHostResponse> hosts =
            new(StringComparer.OrdinalIgnoreCase);

        public GameDataHostResponse Configure(
            string web_host,
            string? variables,
            bool variables_fail = false,
            string? furnidata_json = null)
        {
            var response = new GameDataHostResponse(
                variables,
                variables_fail,
                furnidata_json);
            lock (sync)
                hosts[web_host] = response;
            return response;
        }

        protected override object? Invoke(MethodInfo? target_method, object?[]? arguments)
        {
            string web_host = (string)arguments![0]!;
            GameDataHostResponse response;
            lock (sync)
                response = hosts[web_host];
            return target_method!.Name switch
            {
                "LoadHashesAsync" => response.LoadHashes(
                    (CancellationToken)arguments[1]!),
                "FetchAsync" => response.Fetch(
                    (string)arguments[1]!,
                    (CancellationToken)arguments[5]!),
                _ => throw new NotSupportedException(target_method.Name)
            };
        }
    }

    private sealed class GameDataHostResponse(
        string? variables,
        bool variables_fail,
        string? furnidata_json)
    {
        private static readonly IReadOnlyDictionary<string, string> hashes =
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                ["furnidata"] = "1",
                ["productdata"] = "1",
                ["external_texts"] = "1",
                ["external_variables"] = "1"
            };
        private readonly TaskCompletionSource<IReadOnlyDictionary<string, string>> completion =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource requested =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private int request_count;
        private int transport_cancellation_count;

        public Task Requested => requested.Task;
        public int RequestCount => Volatile.Read(ref request_count);
        public int TransportCancellationCount =>
            Volatile.Read(ref transport_cancellation_count);

        public Task<IReadOnlyDictionary<string, string>> LoadHashes(
            CancellationToken cancellation_token)
        {
            Interlocked.Increment(ref request_count);
            requested.TrySetResult();
            cancellation_token.Register(
                () => Interlocked.Increment(ref transport_cancellation_count));
            return completion.Task.WaitAsync(cancellation_token);
        }

        public Task<string> Fetch(string path, CancellationToken cancellation_token) =>
            (path switch
            {
                "furnidata_json" => Task.FromResult(
                    furnidata_json ??
                    "{\"roomitemtypes\":{\"furnitype\":[]}," +
                    "\"wallitemtypes\":{\"furnitype\":[]}}"),
                "productdata_json" => Task.FromResult(
                    "{\"productdata\":{\"product\":[]}}"),
                "external_flash_texts" => Task.FromResult(""),
                "external_variables" when variables_fail =>
                    Task.FromException<string>(new IOException("variables unavailable")),
                "external_variables" => Task.FromResult(variables ?? ""),
                _ => Task.FromException<string>(new InvalidOperationException(path))
            }).WaitAsync(cancellation_token);

        public void Complete() => completion.TrySetResult(hashes);

        public void Fail(Exception error) => completion.TrySetException(error);
    }

