                AddRoute(catalog, client, MessageKeys.Room.WallItem.PostItPlace, 213);
                AddRoute(catalog, client, MessageKeys.Room.WallItem.SpamPostItAdd, 214);
                AddRoute(catalog, client, MessageKeys.Room.Access.OpenRequest, 215);
                AddRoute(catalog, client, MessageKeys.Room.Lifecycle.Quit, 216);
                AddRoute(catalog, client, MessageKeys.Room.Access.DoorbellAnswer, 217);
                AddRoute(catalog, client, MessageKeys.Room.RatingRequest, 220);
                AddRoute(catalog, client, MessageKeys.Room.StaffPickUpdateRequest, 221);
                AddRoute(catalog, client, MessageKeys.Room.Occupants.RespectRequest, 222);
                AddRoute(catalog, client, MessageKeys.Room.Authority.ControllerGrantRequest, 223);
                AddRoute(catalog, client, MessageKeys.Room.Occupants.Pet.RespectRequest, 224);
                AddRoute(catalog, client, MessageKeys.Room.Occupants.Pet.MountRequest, 225);
                AddRoute(catalog, client, MessageKeys.Room.Occupants.Pet.RemoveRequest, 226);
                AddRoute(catalog, client, MessageKeys.Room.Occupants.Bot.RemoveRequest, 227);
                AddRoute(catalog, client, MessageKeys.Navigator.RoomCreate, 228);
                AddRoute(catalog, client, MessageKeys.Navigator.RoomDelete, 229);
                AddRoute(catalog, client, MessageKeys.Navigator.HomeRoomUpdate, 230);
                AddRoute(catalog, client, MessageKeys.Friends.Follow, 231);
                AddRoute(catalog, client, MessageKeys.Friends.FriendRequestReceived, 232);
                AddRoute(catalog, client, MessageKeys.Friends.FriendRequestAccept, 233);
                AddRoute(catalog, client, MessageKeys.Navigator.Search.Text, 234);
                AddRoute(catalog, client, MessageKeys.Navigator.Search.LegacyResult, 235);
                AddRoute(catalog, client, MessageKeys.Wired.Trade.ItemsUpdate, 236);
                if (include_wired_chest_deposit)
                {
                    AddRoute(catalog, client, MessageKeys.Wired.Chests.OpenRequest, 237);
                    AddRoute(catalog, client, MessageKeys.Wired.Chests.ItemsChunk, 238);
                    AddRoute(catalog, client, MessageKeys.Wired.Chests.StartAdding, 239);
                    AddRoute(catalog, client, MessageKeys.Wired.Trade.Initiated, 240);
                    AddRoute(catalog, client, MessageKeys.Wired.Trade.ItemsUpdated, 241);
                    AddRoute(catalog, client, MessageKeys.Wired.Trade.Confirm, 242);
                    AddRoute(catalog, client, MessageKeys.Wired.Trade.Completed, 243);
                    AddRoute(catalog, client, MessageKeys.Wired.Trade.Cancelled, 244);
                    AddRoute(catalog, client, MessageKeys.Wired.Transaction.Failed, 245);
                    AddRoute(catalog, client, MessageKeys.Wired.Chests.ItemsUpdated, 246);
                    AddRoute(catalog, client, MessageKeys.Wired.Trade.Cancel, 247);
                }
                if (client is ClientType.Unity)
                {
                    catalog.AddOutgoingSchema(
                        75,
                        invalid_builders_club_wall_schema
                            ? new OutgoingMessageSchema(
                                Msg.Out.BuildersClubPlaceWallItem,
                                [Scalar(0, OutgoingWireType.Int64)])
                            : CreateBuildersClubWallPlacementSchema());
                    catalog.AddOutgoingSchema(
                        62,
                        new OutgoingMessageSchema(
                            Msg.Out.PurchaseFromCatalogAsGift,
                            [
                                Scalar(0, OutgoingWireType.Int32),
                                Scalar(1, OutgoingWireType.Int32),
                                Scalar(2, OutgoingWireType.String),
                                Scalar(3, OutgoingWireType.String),
                                Scalar(4, OutgoingWireType.String),
                                Scalar(5, OutgoingWireType.Int32),
                                Scalar(6, OutgoingWireType.Int32),
                                Scalar(7, OutgoingWireType.Int32),
                                Scalar(8, OutgoingWireType.Boolean),
                                Scalar(9, OutgoingWireType.Int32)
                            ]));
                    catalog.AddOutgoingSchema(
                        63,
                        new OutgoingMessageSchema(
                            Msg.Out.PurchaseRoomAd,
                            [
                                Scalar(0, OutgoingWireType.Int32),
                                Scalar(1, OutgoingWireType.Int32),
                                Scalar(2, OutgoingWireType.Int64),
                                Scalar(3, OutgoingWireType.String),
                                Scalar(4, OutgoingWireType.Boolean),
                                Scalar(5, OutgoingWireType.String),
                                Scalar(6, OutgoingWireType.Int32)
                            ]));
                }
                if (include_unignore)
                {
                    AddRoute(catalog, client, MessageKeys.Users.Ignore.Remove, 6);
                    if (client is ClientType.Unity && unity_unignore_schema is OutgoingWireType wire_type)
                    {
                        catalog.AddOutgoingSchema(
                            6,
                            new OutgoingMessageSchema(
                                "UnignoreUser",
                                [
                                    new OutgoingParameterSchema(
                                        0,
                                        wire_type is OutgoingWireType.Int64 ? "System.Int64" : "System.String",
                                        "identity",
                                        null,
                                        wire_type,
                                        OutgoingCollectionKind.None)
                                ]));
                    }
                }
                Messages.BindSessionCatalog(new SessionCatalogBinding(
                    client,
                    catalog,
                    new CatalogProvenance(
                        CatalogOrigin.EmbeddedReference,
                        client,
                        "application-surface-smoke")));
            }
            _interceptor = new FakeInterceptor(Messages, session);
            _game = new GameState();
            if (session is not null)
                _game.Attach(_interceptor);
            var contracts = new MessageContractCatalog(Messages.Registry, MessageContracts.All);
            Application = new ApplicationRuntime(_interceptor, _game, contracts);
            Queries = new GameQueryService(_game, Application, () => _interceptor.Session);
        }

