        public async Task LoadRoomGameDataAsync(
            string furnidata_json,
            string game_host = "localhost")
        {
            (GameData data, GameDataTransportProxy transport) = CreateGameData();
            GameDataHostResponse response = transport.Configure(
                GameData.WebHostFor(game_host),
                "",
                furnidata_json: furnidata_json);
            response.Complete();
            await data.LoadAsync(game_host);
            _game.Room.GameData = data;
        }

        public void EnterRoom(Id room_id)
        {
            Receive(MessageContracts.Room.Lifecycle.Ready, new RoomReady("private", room_id));
            Receive(MessageContracts.Room.Lifecycle.Entry, new RoomEntryInfo(room_id, true));
        }

        public void LoadFurni(params InventoryItem[] items) =>
            Receive(MessageContracts.Inventory.Furni.Snapshot, new FurniList(1, 0, items));

        public void AddFloorItem(FloorItem item) =>
            Receive(MessageContracts.Room.FloorItem.Added, new FloorItemAdd(item));

        public void UpdateFloorItem(FloorItem item) =>
            Receive(MessageContracts.Room.FloorItem.Updated, new FloorItemUpdate(item));

        public void RemoveFloorItem(Id item_id) =>
            Receive(MessageContracts.Room.FloorItem.Removed, new FloorItemRemove(item_id, false, 1, 0));

        public void AddWallItem(WallItem item) =>
            Receive(MessageContracts.Room.WallItem.Added, new WallItemAdd(item));

        public void UpdateWallItem(WallItem item) =>
            Receive(MessageContracts.Room.WallItem.Updated, new WallItemUpdate(item));

        public void RemoveWallItem(Id item_id) =>
            Receive(MessageContracts.Room.WallItem.Removed, new WallItemRemove(item_id, 1));

        public Task<RoomSettingsStateView> GetRoomSettings(
            Id room_id,
            int timeout,
            long? expected_session_generation = null,
            long? expected_room_generation = null) => Application
            .InvokeAsync<RoomSettingsGetRequest, RoomSettingsStateView>(
                ApplicationMemberIds.RoomSettingsGet,
                new RoomSettingsGetRequest(
                    room_id,
                    timeout,
                    expected_session_generation,
                    expected_room_generation))
            .AsTask();

        public Task<RoomSettingsSaveReceipt> SaveRoomSettings(
            RoomSettingsValues values,
            string password,
            int timeout,
            long? expected_operation_revision = null,
            long? expected_snapshot_revision = null) => Application
            .InvokeAsync<RoomSettingsSaveRequest, RoomSettingsSaveReceipt>(
                ApplicationMemberIds.RoomSettingsSave,
                new RoomSettingsSaveRequest(
                    values,
                    password,
                    timeout,
                    ExpectedOperationRevision: expected_operation_revision,
                    ExpectedSnapshotRevision: expected_snapshot_revision))
            .AsTask();

