            .InvokeAsync<RoomSettingsStateRequest, RoomSettingsStateView>(
                ApplicationMemberIds.RoomSettingsState,
                new RoomSettingsStateRequest(room_id));

        public void Disconnect() => _interceptor.Disconnect();

        public void Connect(Session session) => _interceptor.Connect(session);

        public bool Receive<T>(MessageContract<T> contract, T message)
            where T : IParserComposer<T> =>
            _interceptor.Receive(contract, message);

        public void Dispose()
        {
            Application.Dispose();
            _game.Dispose();
        }

        private void AddRoute(
            MessageCatalog catalog,
            ClientType client,
            MessageKey key,
            int id)
        {
            Assert.True(Messages.Registry.TryGet(key, out MessageDescriptor descriptor));
            IReadOnlyList<string> names = descriptor.NamesFor(client);
            Assert.NotEmpty(names);
            catalog.Add(descriptor.Direction, id, names[0]);
            foreach (string name in names.Skip(1))
                catalog.AddAlias(descriptor.Direction, id, name);
        }
    }

