        public event Action<Session>? Connected
        {
            add => connected += value;
            remove => connected -= value;
        }

        public event Action? Disconnected;

        public event Action<Intercept>? Intercepted
        {
            add { }
            remove { }
        }

        public InterceptorSessionCatalog CaptureSessionCatalog() =>
            new(Session, Messages.ActiveCatalogBinding);

        public void Send(IPacket packet) =>
            Send(packet, Session, Messages.ActiveCatalogBinding, null);

        public void Send(
            IPacket packet,
            Session? expected_session,
            SessionCatalogBinding? expected_catalog) =>
            Send(packet, expected_session, expected_catalog, null);

        public void Send(
            IPacket packet,
            Session? expected_session,
            SessionCatalogBinding? expected_catalog,
            Action? dispatch_guard)
        {
            if (expected_session is null || !ReferenceEquals(Session, expected_session))
                throw new InvalidOperationException("The connection session changed before dispatch.");
            if (!ReferenceEquals(Messages.ActiveCatalogBinding, expected_catalog))
                throw new InvalidOperationException("The message catalog changed before dispatch.");
            MessageKey subscription_request = SubscriptionRequestKey(packet.Header);
            if (!subscription_request.IsEmpty)
                BeforeSubscriptionDispatch?.Invoke(subscription_request);
            MessageKey gift_request = GiftRequestKey(packet.Header);
            if (!gift_request.IsEmpty)
                BeforeGiftDispatch?.Invoke(gift_request);
            MessageKey crafting_request = CraftingRequestKey(packet.Header);
            if (!crafting_request.IsEmpty)
                BeforeCraftingDispatch?.Invoke(crafting_request);
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_read_request) &&
                (room_read_request == MessageKeys.Room.SnapshotRequest ||
                    room_read_request == MessageKeys.Room.Authority.ControllersRequest ||
                    room_read_request == MessageKeys.Room.Occupants.Pet.InfoRequest ||
                    room_read_request == MessageKeys.Room.WallItem.StickyDataRequest ||
                    room_read_request == MessageKeys.Catalog.RoomAdInfoRequest))
            {
                BeforeRoomReadDispatch?.Invoke(room_read_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_chat_request) &&
                (room_chat_request == MessageKeys.Room.Chat.TalkSend ||
                    room_chat_request == MessageKeys.Room.Chat.ShoutSend))
            {
                BeforeRoomChatDispatch?.Invoke(room_chat_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_avatar_request) &&
                (room_avatar_request == MessageKeys.Room.Movement.Walk ||
                    room_avatar_request == MessageKeys.Room.Movement.LookTo ||
                    room_avatar_request == MessageKeys.Room.Occupants.Action.DanceRequest ||
                    room_avatar_request == MessageKeys.Room.Occupants.Action.ExpressionRequest ||
                    room_avatar_request == MessageKeys.Room.Occupants.Action.SignRequest ||
                    room_avatar_request == MessageKeys.Room.Occupants.Action.EffectSelectionRequest ||
                    room_avatar_request == MessageKeys.Room.Occupants.Action.PostureRequest ||
                    room_avatar_request == MessageKeys.Room.Typing.Start ||
                    room_avatar_request == MessageKeys.Room.Typing.Cancel))
            {
                BeforeRoomAvatarDispatch?.Invoke(room_avatar_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_item_request) &&
                (room_item_request == MessageKeys.Room.FloorItem.Use ||
                    room_item_request == MessageKeys.Room.WallItem.Use ||
                    room_item_request == MessageKeys.Room.FloorItem.OneWayDoorEnter ||
                    room_item_request == MessageKeys.Room.FloorItem.ThrowDice ||
                    room_item_request == MessageKeys.Room.FloorItem.DiceOff ||
                    room_item_request == MessageKeys.Room.WallItem.Remove ||
                    room_item_request == MessageKeys.Room.WallItem.StickyDataSet ||
                    room_item_request == MessageKeys.Room.WallItem.PostItPlace ||
                    room_item_request == MessageKeys.Room.WallItem.SpamPostItAdd))
            {
                BeforeRoomItemDispatch?.Invoke(room_item_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_lifecycle_request) &&
                (room_lifecycle_request == MessageKeys.Room.Access.OpenRequest ||
                    room_lifecycle_request == MessageKeys.Room.Lifecycle.Quit))
            {
                BeforeRoomLifecycleDispatch?.Invoke(room_lifecycle_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_control_request) &&
                (room_control_request == MessageKeys.Room.Access.DoorbellAnswer ||
                    room_control_request == MessageKeys.Room.HandItem.Drop ||
                    room_control_request == MessageKeys.Room.HandItem.Pass ||
                    room_control_request == MessageKeys.Room.RatingRequest ||
                    room_control_request == MessageKeys.Room.StaffPickUpdateRequest))
            {
                BeforeRoomControlDispatch?.Invoke(room_control_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey room_people_request) &&
                (room_people_request == MessageKeys.Room.Occupants.RespectRequest ||
                    room_people_request == MessageKeys.Room.Authority.ControllerGrantRequest ||
                    room_people_request == MessageKeys.Room.Occupants.Pet.RespectRequest ||
                    room_people_request == MessageKeys.Room.Occupants.Pet.MountRequest ||
                    room_people_request == MessageKeys.Room.Occupants.Pet.RemoveRequest ||
                    room_people_request == MessageKeys.Room.Occupants.Bot.RemoveRequest))
            {
                BeforeRoomPeopleDispatch?.Invoke(room_people_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey navigator_room_request) &&
                (navigator_room_request == MessageKeys.Navigator.RoomCreate ||
                    navigator_room_request == MessageKeys.Navigator.RoomDelete ||
                    navigator_room_request == MessageKeys.Navigator.HomeRoomUpdate))
            {
                BeforeNavigatorRoomDispatch?.Invoke(navigator_room_request);
            }
            if (TryGetPeopleGroupRequestKey(packet.Header, out MessageKey friend_request) &&
                (friend_request == MessageKeys.Friends.Follow ||
                    friend_request == MessageKeys.Friends.FriendRequestAccept))
            {
                BeforeFriendDispatch?.Invoke(friend_request);
            }
            MessageKey achievement_badge_request = AchievementBadgeRequestKey(packet.Header);
            MessageKey earning_request = EarningRequestKey(packet.Header);
            if (!earning_request.IsEmpty)
                BeforeEarningDispatch?.Invoke(earning_request);
            MessageKey daily_task_request = DailyTaskRequestKey(packet.Header);
            if (!daily_task_request.IsEmpty)
                BeforeDailyTaskDispatch?.Invoke(daily_task_request);
            MessageKey quest_request = QuestRequestKey(packet.Header);
            if (!quest_request.IsEmpty)
                BeforeQuestDispatch?.Invoke(quest_request);
            MessageKey forum_request = ForumRequestKey(packet.Header);
            MessageKey leaderboard_request = LeaderboardRequestKey(packet.Header);
            MessageKey habbicon_request = HabbiconRequestKey(packet.Header);
            if (!habbicon_request.IsEmpty)
                BeforeHabbiconDispatch?.Invoke(habbicon_request);
            dispatch_guard?.Invoke();
            if (!crafting_request.IsEmpty)
                CaptureCraftingRequest(packet, crafting_request);
            if (!subscription_request.IsEmpty)
                AfterSubscriptionDispatch?.Invoke(subscription_request);
            if (!gift_request.IsEmpty)
                AfterGiftDispatch?.Invoke(gift_request);
            if (!crafting_request.IsEmpty)
                AfterCraftingDispatch?.Invoke(crafting_request);
            if (!achievement_badge_request.IsEmpty)
                AfterAchievementBadgeDispatch?.Invoke(achievement_badge_request);
            if (!earning_request.IsEmpty)
            {
