                AfterEarningDispatch?.Invoke(earning_request);
            }
            if (!daily_task_request.IsEmpty)
            {
                CaptureDailyTaskRequest(packet, daily_task_request);
                AfterDailyTaskDispatch?.Invoke(daily_task_request);
