                CaptureQuestRequest(packet, quest_request);
                AfterQuestDispatch?.Invoke(quest_request);
            }
            if (!habbicon_request.IsEmpty)
                AfterHabbiconDispatch?.Invoke(habbicon_request);
            if (Messages.TryGetHeader(MessageKeys.Wallet.CreditsRequest, out Header header) &&
                packet.Header == header)
            {
                Interlocked.Increment(ref wallet_request_count);
                wallet_request_sent.TrySetResult();
            }
            if (Messages.TryGetHeader(MessageKeys.Room.Settings.Request, out header) &&
