        public Task WaitForRoomSettingsRequestCount(int count) => WaitForRoomSettingsCount(
            room_settings_request_sent,
            () => RoomSettingsRequestCount,
            count);

        public Task WaitForRoomSettingsSaveCount(int count) => WaitForRoomSettingsCount(
            room_settings_save_sent,
            () => RoomSettingsSaveCount,
            count);

        public Task WaitForPlacementSendCount(int count) => WaitForRoomSettingsCount(
            placement_sent,
            () => PlacementSendCount,
            count);

        public Task WaitForPollStartCount(int count) => WaitForRoomSettingsCount(
            poll_start_sent,
            () => PollStartSendCount,
            count);

        public Task WaitForPeopleGroupRequestCount(MessageKey key, int count) =>
            WaitForRoomSettingsCount(
                people_group_request_sent,
                () => PeopleGroupRequestCount(key),
                count);

        public Task WaitForCatalogIndexRequestCount(int count) => WaitForRoomSettingsCount(
            catalog_index_request_sent,
            () => CatalogIndexRequestCount,
            count);

        public Task WaitForCatalogPageRequestCount(int count) => WaitForRoomSettingsCount(
            catalog_page_request_sent,
            () => CatalogPageRequestCount,
            count);

        public Task WaitForSubscriptionRequestCount(MessageKey key, int count) => key switch
        {
            var value when value == MessageKeys.Subscriptions.UserInfoRequest =>
                WaitForRoomSettingsCount(
                    subscription_user_info_request_sent,
                    () => SubscriptionUserInfoRequestCount,
                    count),
            var value when value == MessageKeys.Subscriptions.KickbackInfoRequest =>
                WaitForRoomSettingsCount(
                    subscription_kickback_request_sent,
                    () => SubscriptionKickbackRequestCount,
                    count),
            var value when value == MessageKeys.Subscriptions.BuildersClubFurniCountRequest =>
                WaitForRoomSettingsCount(
                    subscription_furni_count_request_sent,
                    () => SubscriptionFurniCountRequestCount,
                    count),
            var value when value == MessageKeys.Subscriptions.ClubOffersRequest =>
                WaitForRoomSettingsCount(
                    club_offers_request_sent,
                    () => ClubOffersRequestCount,
                    count),
            _ => throw new ArgumentOutOfRangeException(nameof(key))
        };

        public Task WaitForGiftRequestCount(MessageKey key, int count) =>
            WaitForRoomSettingsCount(
                gift_request_sent,
                () => GiftRequestCount(key),
                count);

        public Task WaitForCraftingRequestCount(MessageKey key, int count) =>
            WaitForRoomSettingsCount(
