        public void Disconnect()
        {
            if (Session is null)
                return;
            Session = null;
            Disconnected?.Invoke();
            dispatcher.Rebind(Messages, false);
        }

        public void Connect(Session session)
        {
            Session = session;
            dispatcher.Rebind(Messages, true);
            connected?.Invoke(session);
        }

        public IDisposable Intercept(Header header, Action<Intercept> callback) =>
            dispatcher.Add(header, callback);

        public IDisposable Intercept(Identifier identifier, Action<Intercept> callback) =>
            dispatcher.Add(identifier, callback, Messages);

        public bool Receive<T>(MessageContract<T> contract, T message)
            where T : IParserComposer<T>
        {
            if (Session is not { } session)
                throw new InvalidOperationException("The interceptor is not connected.");
            if (!Messages.TryGetHeader(contract.Key, out Header header))
                throw new InvalidOperationException($"The message '{contract.Key}' is not routed.");
            using var packet = new Packet(header, session.Client)
            {
                Context = new ParserContext(
                    Messages,
                    Messages.GetWireProfile(session.Client))
            };
            PacketWriter writer = packet.Writer();
            contract.Compose(message, in writer);
            packet.Position = 0;
            var intercept = new Intercept { Packet = packet };
            dispatcher.Dispatch(intercept);
            return intercept.IsBlocked;
        }

        private static async Task WaitForRoomSettingsCount(
            SemaphoreSlim sent,
            Func<int> read_count,
            int count)
        {
            ArgumentOutOfRangeException.ThrowIfNegativeOrZero(count);
            while (read_count() < count)
                await sent.WaitAsync().ConfigureAwait(false);
        }

        private bool IsPlacementHeader(Header header) =>
            MatchesHeader(MessageKeys.Room.Item.Place, header) ||
            MatchesHeader(MessageKeys.Room.FloorItem.Move, header) ||
            MatchesHeader(MessageKeys.Room.WallItem.Move, header) ||
            MatchesHeader(MessageKeys.Room.Item.Pickup, header);

