        private void CaptureEarningRequest(IPacket packet, MessageKey key)
        {
            if (key != MessageKeys.Earnings.Claim)
                return;
            packet.Position = 0;
            Volatile.Write(
                ref last_earning_claim,
                MessageContracts.Earnings.Claim.Parse(packet.Reader()));
        }

        private void CaptureDailyTaskRequest(IPacket packet, MessageKey key)
        {
            if (key != MessageKeys.DailyTasks.Claim)
                return;
            packet.Position = 0;
            Volatile.Write(
                ref last_daily_task_claim,
                MessageContracts.DailyTasks.Claim.Parse(packet.Reader()));
        }

        private void CaptureQuestRequest(IPacket packet, MessageKey key)
        {
            packet.Position = 0;
            if (key == MessageKeys.Quests.DailyRequest)
            {
                Volatile.Write(
                    ref last_quest_daily_request,
                    MessageContracts.Quests.DailyRequest.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Quests.Accept)
            {
                Volatile.Write(
                    ref last_quest_accept,
                    MessageContracts.Quests.Accept.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Quests.Activate)
            {
                Volatile.Write(
                    ref last_quest_activate,
                    MessageContracts.Quests.Activate.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Quests.Reject)
            {
                Volatile.Write(
                    ref last_quest_reject,
                    MessageContracts.Quests.Reject.Parse(packet.Reader()));
            }
        }

        private void CaptureCraftingRequest(IPacket packet, MessageKey key)
        {
            packet.Position = 0;
            if (key == MessageKeys.Crafting.ProductsRequest)
            {
                Volatile.Write(
                    ref last_crafting_products_request,
                    MessageContracts.Crafting.ProductsRequest.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Crafting.RecipeRequest)
            {
                Volatile.Write(
                    ref last_crafting_recipe_request,
                    MessageContracts.Crafting.RecipeRequest.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Crafting.Craft)
            {
                Volatile.Write(
                    ref last_craft_request,
                    MessageContracts.Crafting.Craft.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Crafting.SecretCraft)
            {
                Volatile.Write(
                    ref last_secret_craft_request,
                    MessageContracts.Crafting.SecretCraft.Parse(packet.Reader()));
            }
            else if (key == MessageKeys.Crafting.AvailabilityRequest)
            {
                Volatile.Write(
                    ref last_crafting_availability_request,
                    MessageContracts.Crafting.AvailabilityRequest.Parse(packet.Reader()));
            }
        }

        private bool TryGetPeopleGroupRequestKey(Header header, out MessageKey key)
        {
            foreach (MessageKey candidate in people_group_request_keys)
            {
                if (!MatchesHeader(candidate, header))
                    continue;
                key = candidate;
                return true;
            }
            key = default;
            return false;
        }

        private bool MatchesHeader(MessageKey key, Header header) =>
            Messages.TryGetHeaders(key, out IReadOnlyList<Header> headers) &&
            headers.Contains(header);

        private bool MatchesHeader(string name, Direction direction, Header header) =>
            Messages.TryGetHeaders(
                new Identifier(Messages.ActiveClient, direction, name),
                out IReadOnlyList<Header> headers) &&
            headers.Contains(header);
    }

